// Dati QUANTO VALE
var QUANTO_VALE_DATA=[
 {q:"Quanti neonati nascono ogni giorno nel mondo?",min:0,max:500000,risposta:385000,unit:"neonati",curiosita:"Ogni giorno nascono circa 385.000 bambini — uno ogni 0,2 secondi. In un anno sono oltre 140 milioni."},
 {q:"Quanti chilometri percorre la luce in un secondo?",min:0,max:500000,risposta:299792,unit:"km",curiosita:"299.792 km al secondo. In un anno la luce percorre circa 9.461 miliardi di km — una distanza che chiamiamo anno luce."},
 {q:"Quanti anni fa è vissuto l'ultimo Tirannosauro Rex?",min:0,max:200000000,risposta:66000000,unit:"anni fa",curiosita:"Il T-Rex si è estinto 66 milioni di anni fa. Il Cleopatra vissuto 2.000 anni fa è temporalmente più vicino a noi che al T-Rex."},
 {q:"Quante parole contiene mediamente il vocabolario italiano?",min:0,max:500000,risposta:270000,unit:"parole",curiosita:"Il vocabolario italiano contiene circa 270.000 parole. Un italiano medio ne usa attivamente circa 2.000-5.000."},
 {q:"Quanti kg di plastica finiscono negli oceani ogni anno?",min:0,max:20000000,risposta:8000000,unit:"tonnellate",curiosita:"Circa 8 milioni di tonnellate ogni anno. Entro il 2050 ci sarà più plastica che pesce negli oceani in termini di peso."},
 {q:"Quante volte al giorno batte il cuore umano?",min:0,max:200000,risposta:100000,unit:"battiti",curiosita:"Il cuore batte circa 100.000 volte al giorno — 35 milioni di volte l'anno. In una vita media compie circa 2,5 miliardi di battiti."},
 {q:"Quanti pizze vengono mangiate ogni anno in Italia?",min:0,max:5000000000,risposta:2500000000,unit:"pizze",curiosita:"Circa 2,5 miliardi di pizze l'anno solo in Italia. La margherita è la più consumata. Il mercato mondiale della pizza vale oltre 140 miliardi di euro."},
 {q:"A quanti gradi celsius bolle l'acqua sulla cima dell'Everest?",min:0,max:100,risposta:70,unit:"°C",curiosita:"A 8.849 metri di altitudine l'acqua bolle a circa 70°C per via della bassa pressione atmosferica. Impossibile fare un buon tè lassù."},
 {q:"Quanti abitanti ha Tokyo?",min:0,max:50000000,risposta:37400000,unit:"abitanti",curiosita:"Tokyo con la sua area metropolitana conta circa 37,4 milioni di persone — più dell'intera popolazione del Canada."},
 {q:"Quanti anni ci vuole a una bottiglia di plastica per decomporsi?",min:0,max:1000,risposta:450,unit:"anni",curiosita:"Una bottiglia di plastica impiega circa 450 anni a decomporsi. Le prime bottiglie in PET prodotte negli anni '70 esistono ancora tutte."},
 {q:"Quanti grammi pesa il cuore umano?",min:0,max:1000,risposta:300,unit:"grammi",curiosita:"Il cuore pesa circa 300 grammi — quanto una lattina di bevanda. Nonostante le dimensioni ridotte, pompa circa 7.500 litri di sangue al giorno."},
 {q:"Quante lingue vengono parlate nel mondo oggi?",min:0,max:10000,risposta:7000,unit:"lingue",curiosita:"Esistono circa 7.000 lingue nel mondo. Il 40% rischia di estinguersi entro fine secolo. La Papua Nuova Guinea da sola ne ha oltre 800."},
 {q:"Quanti messaggi WhatsApp vengono inviati ogni giorno nel mondo?",min:0,max:200000000000,risposta:100000000000,unit:"messaggi",curiosita:"Circa 100 miliardi di messaggi al giorno. WhatsApp ha oltre 2 miliardi di utenti attivi mensili in 180 paesi."},
 {q:"A quanti anni in media gli italiani vanno in pensione?",min:0,max:100,risposta:62,unit:"anni",curiosita:"L'età media effettiva di pensionamento in Italia è circa 62 anni — tra le più basse d'Europa, ma con una delle aspettative di vita più alte."},
 {q:"Quante ore di video vengono caricate su YouTube ogni minuto?",min:0,max:1000,risposta:500,unit:"ore/minuto",curiosita:"Ogni minuto vengono caricate 500 ore di video su YouTube. Per vedere tutto il contenuto caricato in un solo giorno ci vorrebbero 82.000 anni."},
 {q:"Quanti neuroni ha il cervello umano?",min:0,max:200000000000,risposta:86000000000,unit:"neuroni",curiosita:"Il cervello contiene circa 86 miliardi di neuroni — quasi tanti quante le stelle della Via Lattea. Le connessioni tra neuroni sono nell'ordine dei quadrilioni."},
 {q:"Quanti chilometri di nervi ha il corpo umano?",min:0,max:200000,risposta:75000,unit:"km",curiosita:"Il sistema nervoso del corpo umano si estende per circa 75.000 km — quasi due volte la circonferenza della Terra."},
 {q:"Quante calorie ha una pizza margherita intera?",min:0,max:3000,risposta:800,unit:"kcal",curiosita:"Una pizza margherita da pizzeria contiene circa 800 calorie. Una pizza in teglia fatta in casa può arrivare a 1.200 calorie."},
 {q:"Quanti anni aveva il Re Luigi XIV quando salì al trono di Francia?",min:0,max:70,risposta:4,unit:"anni",curiosita:"Luigi XIV divenne Re di Francia a 4 anni nel 1643. Regnò per 72 anni — il regno più lungo di qualsiasi monarca europeo della storia."},
 {q:"Quante ore dorme in media un gatto al giorno?",min:0,max:24,risposta:15,unit:"ore",curiosita:"I gatti dormono tra 12 e 16 ore al giorno — in media 15. Sono predatori che conservano energia per la caccia. I ghepardi invece dormono solo 12 ore."},
 {q:"Quanti km di capillari ha il corpo umano?",min:0,max:200000,risposta:100000,unit:"km",curiosita:"Il sistema circolatorio umano si estende per circa 100.000 km — abbastanza per girare due volte e mezzo intorno alla Terra."},
 {q:"Quanti anni ci ha messo Leonardo da Vinci a dipingere La Gioconda?",min:0,max:30,risposta:16,unit:"anni",curiosita:"Da Vinci lavorò alla Gioconda intermittentemente per circa 16 anni, dal 1503 al 1519. Non la consegnò mai al committente — la tenne con sé fino alla morte."},
 {q:"Quante volte al giorno sbattiamo le palpebre?",min:0,max:50000,risposta:15000,unit:"volte",curiosita:"Sbattiamo le palpebre circa 15.000 volte al giorno — ogni 4-6 secondi. In totale passiamo circa 30 minuti al giorno con gli occhi chiusi per i soli battiti."},
 {q:"Quanti kg di cibo mangia in media un italiano all'anno?",min:0,max:2000,risposta:800,unit:"kg",curiosita:"Un italiano consuma circa 800 kg di cibo all'anno — oltre 2 kg al giorno. Siamo tra i maggiori consumatori di pasta, olio d'oliva e vino al mondo."},
 {q:"Quanti anni ha il Colosseo?",min:0,max:3000,risposta:1953,unit:"anni",curiosita:"Il Colosseo fu completato nell'80 d.C. e ha circa 1.953 anni. Poteva contenere tra 50.000 e 80.000 spettatori — più di molti stadi moderni."},
 {q:"Quanti km/h raggiunge un fulmine?",min:0,max:1000000,risposta:440000,unit:"km/h",curiosita:"Un fulmine scende a circa 440.000 km/h — ma il calore che genera (30.000°C) è 5 volte la temperatura della superficie del sole."},
 {q:"Quante app ci sono sull'App Store di Apple?",min:0,max:5000000,risposta:1800000,unit:"app",curiosita:"L'App Store contiene circa 1,8 milioni di app. Ogni giorno ne vengono aggiunte circa 1.000. Solo il 25% viene scaricata almeno una volta."},
 {q:"Quante monetine da 1 centesimo ci vogliono per fare 1 milione di euro?",min:0,max:200000000,risposta:100000000,unit:"monete",curiosita:"Ci vogliono 100 milioni di monete da 1 centesimo. Se le impilassi, raggiungerebbero un'altezza di circa 150 km — oltre la linea di Karman che segna l'inizio dello spazio."},
 {q:"Quanti litri di sangue pompa il cuore ogni giorno?",min:0,max:20000,risposta:7500,unit:"litri",curiosita:"Il cuore pompa circa 7.500 litri di sangue al giorno — quasi 3 milioni di litri all'anno. In una vita media, è abbastanza da riempire un piccolo serbatoio."},
 {q:"Quanti anni ci vorrà prima che il sole si spenga?",min:0,max:10000000000,risposta:5000000000,unit:"anni",curiosita:"Il sole ha circa 4,6 miliardi di anni e ne ha altri 5 miliardi davanti. Quando si spegnerà si espanderà inglobando la Terra — ma la vita sulla Terra sarà impossibile già tra 1-2 miliardi di anni."},
 {q:"Quante stelle ci sono nella Via Lattea?",min:0,max:1000000000000,risposta:200000000000,unit:"stelle",curiosita:"La Via Lattea contiene circa 200-400 miliardi di stelle. Il nostro sole è una stella assolutamente normale — né grande né piccola — nella periferia della galassia."},
 {q:"Quanti km percorre la Terra intorno al sole in un anno?",min:0,max:2000000000,risposta:940000000,unit:"km",curiosita:"La Terra percorre circa 940 milioni di km intorno al sole ogni anno — a una velocità di circa 107.000 km/h. Lo facciamo ogni anno senza nemmeno sentirlo."},
 {q:"Quante lingue parlava Alessandro Magno?",min:0,max:20,risposta:4,unit:"lingue",curiosita:"Alessandro Magno parlava greco, macedone, persiano e aramaico — 4 lingue. Studiò con Aristotele e aveva un'enorme biblioteca con lui durante le campagne militari."},
 {q:"Quanti km di strade ci sono in Italia?",min:0,max:1000000,risposta:487700,unit:"km",curiosita:"L'Italia ha circa 487.700 km di strade — abbastanza per andare e tornare dalla Luna più di una volta. È una delle reti stradali più dense d'Europa."},
 {q:"A quante persone ha insegnato a leggere l'inventore dell'alfabeto Braille?",min:0,max:10000,risposta:1,unit:"persone",curiosita:"Louis Braille inventò il sistema nel 1824 a soli 15 anni. Fu adottato solo 2 anni dopo la sua morte nel 1852. Oggi permette a circa 285 milioni di ipovedenti di leggere."},
 {q:"Quanti km/h raggiunge un ghepardo a velocità massima?",min:0,max:200,risposta:112,unit:"km/h",curiosita:"Il ghepardo è l'animale terrestre più veloce: raggiunge 112 km/h in pochi secondi. Ma può mantenerla solo per 400-500 metri prima di surriscaldarsi."},
 {q:"Quanti Paesi fanno parte dell'Unione Europea?",min:0,max:50,risposta:27,unit:"paesi",curiosita:"Dal 2020, dopo la Brexit, l'UE conta 27 stati membri. La popolazione totale è di circa 450 milioni di persone, la terza più grande economia del mondo."},
 {q:"Quante volte è stato campione del mondo di F1 Michael Schumacher?",min:0,max:10,risposta:7,unit:"volte",curiosita:"Schumacher ha vinto 7 titoli mondiali di F1 — record condiviso con Lewis Hamilton. Cinque consecutivi dal 2000 al 2004 con la Ferrari."},
 {q:"Quanti metri è alta la Torre Eiffel (con antenna)?",min:0,max:500,risposta:330,unit:"metri",curiosita:"Con l'antenna, la Torre Eiffel misura 330 metri. Fu costruita in 2 anni per l'Esposizione Universale del 1889. Originariamente doveva essere demolita dopo 20 anni."},
 {q:"Quanti litri di acqua beve al giorno un elefante adulto?",min:0,max:400,risposta:150,unit:"litri",curiosita:"Un elefante adulto può bere fino a 150 litri d'acqua al giorno. Usa la proboscide come tubo — riesce ad aspirare fino a 8 litri alla volta."},
 {q:"A quanti gradi centigradi corrisponde la temperatura al centro della Terra?",min:0,max:10000,risposta:6000,unit:"°C",curiosita:"Il nucleo interno della Terra ha una temperatura di circa 6.000°C — quanto la superficie del Sole. La pressione è talmente alta che il ferro rimane solido nonostante il calore."},
 {q:"Quante ossa ha il corpo umano adulto?",min:0,max:400,risposta:206,unit:"ossa",curiosita:"Un adulto ha 206 ossa. I neonati ne hanno circa 270-300 — molte si fondono durante la crescita. Il femore è l'osso più lungo, le staffa nell'orecchio il più piccolo."},
 {q:"Quante composizioni ha scritto Mozart in tutta la sua vita?",min:0,max:2000,risposta:626,unit:"composizioni",curiosita:"Mozart compose 626 opere catalogate — sinfonie, concerti, opere liriche, messe e molto altro. Tutto questo tra i 5 e i 35 anni, quando morì. Un'opera ogni 3 settimane in media."},
 {q:"Quanti millimetri cresce in media un'unghia al mese?",min:0,max:20,risposta:3,unit:"mm",curiosita:"Le unghie crescono circa 3 mm al mese — 36 mm l'anno. Crescono più veloci d'estate e di giorno. Il pollice cresce più lentamente, il medio più velocemente."},
 {q:"Quanti miliardi di anni ha la Terra?",min:0,max:15,risposta:5,unit:"miliardi di anni",curiosita:"La Terra ha circa 4,5 miliardi di anni — formata da gas e polveri del disco protoplanetario del nostro Sole. La vita è comparsa 'solo' 3,8 miliardi di anni fa."},
 {q:"Quante calorie brucia il cervello ogni giorno?",min:0,max:1000,risposta:300,unit:"kcal",curiosita:"Il cervello consuma circa 300 calorie al giorno — il 20% di tutta l'energia del corpo, pur pesando solo il 2% del peso totale. È l'organo più energivoro in proporzione."},
 {q:"Quanti km/h è il limite di velocità sulle autostrade italiane?",min:0,max:200,risposta:130,unit:"km/h",curiosita:"Il limite sulle autostrade italiane è 130 km/h, che scende a 110 km/h in caso di pioggia. La Germania è l'unico grande paese europeo senza limite generico in autostrada."},
 {q:"Quante persone ci sono sulla Stazione Spaziale Internazionale (ISS) normalmente?",min:0,max:20,risposta:7,unit:"astronauti",curiosita:"La ISS ospita normalmente 7 astronauti. Orbita a circa 400 km di quota a 27.600 km/h — compie un giro completo intorno alla Terra ogni 92 minuti."},
 {q:"Quanti anni ci vuole ad una tartaruga delle Galapagos per raggiungere la maturità?",min:0,max:50,risposta:25,unit:"anni",curiosita:"Le tartarughe giganti delle Galapagos maturano tra i 20 e i 30 anni. Vivono oltre 150 anni — alcune esemplari vivi oggi sono nati prima dell'Unità d'Italia."},
 {q:"Quante volte il cuore umano batte nel corso di una vita media?",min:0,max:5000000000,risposta:2500000000,unit:"battiti",curiosita:"In una vita media di 75 anni, il cuore batte circa 2,5 miliardi di volte — senza mai fermarsi per riposare. È l'unico muscolo del corpo che lavora ininterrottamente."},
 {q:"Quante ossa ha il cranio umano?",min:0,max:50,risposta:22,unit:"ossa",curiosita:"Il cranio è composto da 22 ossa: 8 formano la scatola cranica e 14 il viso. Alla nascita le ossa del cranio non sono ancora fuse per permettere il passaggio nel canale del parto."},
 {q:"Quanti litri d'aria respira un adulto in un giorno?",min:0,max:50000,risposta:11000,unit:"litri",curiosita:"Circa 11.000 litri al giorno — abbastanza per riempire 550 palloni da calcio. L'aria inspirata contiene il 21% di ossigeno, quella espirata il 16%."},
 {q:"Quanti muscoli usa un essere umano per sorridere?",min:0,max:50,risposta:12,unit:"muscoli",curiosita:"Un sorriso autentico usa circa 12 muscoli. Per aggrottare la fronte ne servono 11. Il sorriso è universale: studi mostrano che anche i neonati ciechi dalla nascita sorridono."},
 {q:"Quanti grammi pesa il cuore umano?",min:0,max:1000,risposta:300,unit:"grammi",curiosita:"Il cuore pesa circa 250-350 grammi — quanto una mela. Pompa circa 5 litri di sangue al minuto e in una vita percorre una distanza pari a 2,7 volte la distanza dalla Terra alla Luna."},
 {q:"Quanti anni può vivere un corvo?",min:0,max:100,risposta:30,unit:"anni",curiosita:"I corvi possono vivere 30 anni in libertà. Sono tra gli uccelli più intelligenti: usano strumenti, risolvono problemi complessi e riconoscono i volti umani per anni."},
 {q:"Quanti cm cresce in media un capello al mese?",min:0,max:10,risposta:1,unit:"cm",curiosita:"I capelli crescono circa 1-1,5 cm al mese — 15 cm l'anno. Crescono più veloci d'estate e di notte. Un capello vive in media 3-7 anni prima di cadere."},
 {q:"Quanti anni fa è iniziata la rivoluzione industriale?",min:0,max:500,risposta:270,unit:"anni fa",curiosita:"La rivoluzione industriale iniziò in Inghilterra intorno al 1750-1760. La macchina a vapore di Watt (1769) fu il simbolo di quel cambiamento che trasformò il mondo da agricolo a industriale."},
 {q:"Quanti km è la circumnavigazione della Terra all'equatore?",min:0,max:60000,risposta:40075,unit:"km",curiosita:"La Terra misura 40.075 km all'equatore. Magellano impiegò quasi 3 anni per circumnavigare il globo (1519-1522). Oggi in aereo ci vogliono circa 40 ore."},
 {q:"Quanti secondi ci sono in un anno?",min:0,max:50000000,risposta:31536000,unit:"secondi",curiosita:"Un anno ha esattamente 31.536.000 secondi (365 giorni × 24 ore × 3600 secondi). Un anno bisestile ne ha 86.400 in più."},
 {q:"Quanti pianeti ci sono nel Sistema Solare?",min:0,max:15,risposta:8,unit:"pianeti",curiosita:"Dal 2006 il Sistema Solare ha ufficialmente 8 pianeti dopo la declassazione di Plutone a pianeta nano: Mercurio, Venere, Terra, Marte, Giove, Saturno, Urano, Nettuno."},
 {q:"Quanti anni fa è stato inventato il telefono?",min:0,max:200,risposta:150,unit:"anni fa",curiosita:"Alexander Graham Bell brevettò il telefono nel 1876. La prima parola trasmessa fu 'Mr. Watson, come here!' Lo stesso giorno Elisha Gray depositò un brevetto simile, perdendo per poche ore."},
 {q:"Quanti anni fa è stata inventata la ruota?",min:0,max:10000,risposta:5500,unit:"anni fa",curiosita:"La ruota fu inventata circa 5.500 anni fa in Mesopotamia. Inizialmente fu usata per la ceramica, solo dopo per il trasporto. Fu una delle invenzioni più rivoluzionarie della storia."},
 {q:"Quanti kg di miele produce un alveare in un anno?",min:0,max:100,risposta:25,unit:"kg",curiosita:"Un alveare produce in media 20-30 kg di miele l'anno. Per produrre 1 kg di miele, le api devono volare complessivamente circa 90.000 km e visitare 2 milioni di fiori."},
 {q:"Quanti km/h raggiunge un ghepardo a velocità massima?",min:0,max:200,risposta:112,unit:"km/h",curiosita:"Il ghepardo raggiunge i 112 km/h in pochi secondi ma può mantenerla solo per 400-500 metri prima di surriscaldarsi. È l'animale terrestre più veloce del pianeta."},
 {q:"Quante specie di farfalle esistono nel mondo?",min:0,max:30000,risposta:20000,unit:"specie",curiosita:"Esistono circa 20.000 specie di farfalle. La più grande è la Attacus atlas con un'apertura alare di 30 cm. La farfalla monarca migra ogni anno dal Canada al Messico: 4.500 km."},
 {q:"Quanti anni fa è comparso il primo Homo sapiens?",min:0,max:500000,risposta:300000,unit:"anni fa",curiosita:"I fossili più antichi di Homo sapiens risalgono a circa 300.000 anni fa, trovati in Marocco. Lasciò l'Africa circa 70.000 anni fa e colonizzò tutto il pianeta in pochi millenni."},
 {q:"Quanti chilometri cammina in media un essere umano in tutta la vita?",min:0,max:500000,risposta:160000,unit:"km",curiosita:"In una vita media un essere umano cammina circa 160.000 km — l'equivalente di 4 volte intorno alla Terra. Le scarpe durano circa 800 km prima di perdere il loro ammortizzamento."},
 {q:"Quante spine ha un riccio?",min:0,max:10000,risposta:5000,unit:"spine",curiosita:"Un riccio adulto ha circa 5.000-7.000 spine — modificazioni dei peli. Quando è minacciato si arrotola formando una palla. È immune al veleno di serpenti e al veleno delle vespe."},
 {q:"Quanti gradi conta un cerchio completo?",min:0,max:720,risposta:360,unit:"gradi",curiosita:"360 gradi per un cerchio completo. I Babilonesi scelsero 360 perché è divisibile per molti numeri: 2, 3, 4, 5, 6, 8, 9, 10, 12, 15, 18, 20, 24, 30, 36, 40, 45, 60, 72, 90, 120, 180."},
 {q:"Quanti anni ci volle a costruire la Cattedrale di Milano?",min:0,max:1000,risposta:600,unit:"anni",curiosita:"Il Duomo di Milano fu costruito in circa 600 anni (1386-1965). È la terza cattedrale più grande del mondo. Ha 3.400 statue, 135 guglie e 3.400 sculture esterne."},
 {q:"A quanti km/h viaggia un treno Frecciarossa?",min:0,max:500,risposta:300,unit:"km/h",curiosita:"Il Frecciarossa raggiunge i 300 km/h in servizio commerciale. Collega Milano a Napoli in meno di 3 ore. Il record mondiale su rotaia è 574 km/h, stabilito dal TGV francese nel 2007."},
 {q:"Quante specie di coccodrilli esistono?",min:0,max:50,risposta:23,unit:"specie",curiosita:"Esistono 23 specie di coccodrilli e alligatori. Il coccodrillo del Nilo può vivere 70-100 anni. Sono rimasti quasi invariati per 200 milioni di anni — sopravvissuti all'estinzione dei dinosauri."},
 {q:"Quanti milioni di globuli rossi produce il corpo ogni secondo?",min:0,max:10,risposta:2,unit:"milioni al secondo",curiosita:"Il corpo produce circa 2 milioni di globuli rossi al secondo. Vivono circa 120 giorni. Vengono prodotti nel midollo osseo di sterno, vertebre e bacino."},
 {q:"Quante notti dura la notte polare alle Svalbard (Norvegia)?",min:0,max:200,risposta:67,unit:"giorni",curiosita:"A Longyearbyen (Svalbard) la notte polare dura circa 67 giorni. Il sole non sorge dal 26 ottobre al 15 febbraio. In compenso, il sole di mezzanotte dura anch'esso circa 4 mesi."},
 {q:"Quanti Hz ha la nota La usata per accordare gli strumenti?",min:0,max:1000,risposta:440,unit:"Hz",curiosita:"Il La centrale (A4) è a 440 Hz — lo standard internazionale dal 1939. Prima del 1939 ogni paese aveva il suo standard. Verdi preferiva 432 Hz per un suono più morbido."},
 {q:"Quante vertebre ha un essere umano?",min:0,max:50,risposta:33,unit:"vertebre",curiosita:"La colonna vertebrale ha 33-34 vertebre: 7 cervicali, 12 toraciche, 5 lombari, 5 sacrali fuse e 4-5 coccigee fuse. È più alta al mattino perché i dischi si decomprimono durante la notte."},
 {q:"Quanti paesi riconoscono il passaporto italiano senza visto?",min:0,max:200,risposta:190,unit:"paesi",curiosita:"Il passaporto italiano dà accesso a circa 190 paesi senza visto — tra i più potenti al mondo. I passaporti più forti sono quelli di Giappone, Singapore e alcuni paesi europei."},
 {q:"Quanti km/h è la velocità del vento in un uragano categoria 5?",min:0,max:400,risposta:252,unit:"km/h",curiosita:"Un uragano categoria 5 ha venti sostenuti sopra i 252 km/h. Il più potente mai registrato è il tifone Tip del 1979 con 305 km/h. Si formano solo sugli oceani tropicali caldi."},
 {q:"Quante ore dorme in media un adulto?",min:0,max:24,risposta:8,unit:"ore",curiosita:"Gli adulti hanno bisogno di 7-9 ore di sonno. Durante il sonno il cervello consolida la memoria e rimuove le tossine. Dormire meno di 6 ore aumenta del 48% il rischio cardiovascolare."},
 {q:"Quanti grammi pesa un uovo di gallina?",min:0,max:200,risposta:60,unit:"grammi",curiosita:"Un uovo medio pesa circa 55-65 grammi. L'uovo di struzzo è il più grande con circa 1,5 kg. L'uovo più piccolo è quello del colibrì ape: appena 0,4 grammi — meno di un'aspirina."},
 {q:"Quanti milioni di km² sono ricoperti dai ghiacci della calotta antartica?",min:0,max:20,risposta:14,unit:"milioni di km²",curiosita:"L'Antartide ha un ghiacciaio che copre 14 milioni di km² con uno spessore medio di 2.000 metri. Contiene il 70% dell'acqua dolce del pianeta. Se si sciogliesse, il mare salirebbe di 60 metri."},
 {q:"Quante specie di pinguini esistono?",min:0,max:50,risposta:18,unit:"specie",curiosita:"Esistono 18 specie di pinguini, tutte nell'emisfero australe. Il pinguino imperatore è il più grande: 1,2 metri e 45 kg. Può immergersi a 550 metri di profondità e trattenere il respiro 20 minuti."},
 {q:"Quanti km è lungo il canale di Suez?",min:0,max:500,risposta:193,unit:"km",curiosita:"Il Canale di Suez è lungo 193 km. Aperto nel 1869, accorcia il percorso dall'Europa all'Asia di circa 7.000 km evitando il giro intorno all'Africa. Nel 2021 la Ever Given lo bloccò per 6 giorni."},
 {q:"Quanti anni fa fu scoperta l'America da Colombo?",min:0,max:1000,risposta:534,unit:"anni fa",curiosita:"Colombo sbarcò il 12 ottobre 1492, oltre 530 anni fa. Morì convinto di aver raggiunto l'Asia. Amerigo Vespucci fu il primo a capire che si trattava di un continente sconosciuto."},
 {q:"Quante uova al giorno depone una Regina delle api?",min:0,max:5000,risposta:2000,unit:"uova",curiosita:"Una Regina delle api depone fino a 2.000 uova al giorno. Vive 3-5 anni. Un alveare in estate può contenere 60.000-80.000 operaie, tutte figlie della Regina."},
 {q:"Quanti anni fa Galileo costruì il suo telescopio?",min:0,max:1000,risposta:415,unit:"anni fa",curiosita:"Galileo costruì il suo telescopio nel 1609. Fu tra i primi a puntarlo verso il cielo, scoprendo i satelliti di Giove e le fasi di Venere. Confermò che la Terra gira intorno al Sole."},
 {q:"Quante settimane dura una gravidanza umana?",min:0,max:50,risposta:40,unit:"settimane",curiosita:"Una gravidanza dura circa 40 settimane (280 giorni) dall'ultimo ciclo mestruale. La gravidanza più lunga documentata è di 375 giorni. L'elefante porta avanti la gravidanza per 22 mesi."},
 {q:"Quanti km/h nuota il tonno rosso?",min:0,max:100,risposta:70,unit:"km/h",curiosita:"Il tonno rosso può raggiungere i 70 km/h in velocità massima. Ha un cuore proporzionalmente enorme e mantiene il corpo più caldo dell'acqua circostante — rarità tra i pesci."},
 {q:"Quante lingue parlate hanno più di 100 milioni di parlanti nativi?",min:0,max:20,risposta:13,unit:"lingue",curiosita:"13 lingue hanno più di 100 milioni di parlanti nativi: mandarino, spagnolo, inglese, hindi, portoghese, bengalese, russo, giapponese, yue, turco, coreano, francese e tedesco."},
 {q:"Quanti anni ha il più vecchio albero del mondo?",min:0,max:10000,risposta:4855,unit:"anni",curiosita:"Methuselah, un Pino Bristlecone in California, ha 4.855 anni — il più vecchio organismo vivente noto con posizione segreta. Era già vecchio quando si costruivano le piramidi."},
 {q:"Quanti g di proteine ha 100g di petto di pollo?",min:0,max:50,risposta:31,unit:"grammi di proteine",curiosita:"Il petto di pollo contiene circa 31g di proteine per 100g — tra le fonti proteiche più efficienti. Ha anche pochi grassi saturi ed è ricco di vitamina B3 (niacina)."},
 {q:"Quanti ossigeno (in %) c'è nell'aria che respiriamo?",min:0,max:100,risposta:21,unit:"%",curiosita:"L'aria è composta per il 78% da azoto e il 21% da ossigeno. Il restante 1% è principalmente argon con tracce di CO2 e altri gas. L'ossigeno fu scoperto da Priestley nel 1774."},
 {q:"Quanti anni fa è nata la scrittura?",min:0,max:10000,risposta:5400,unit:"anni fa",curiosita:"La scrittura cuneiforme sumerica nacque circa 5.400 anni fa in Mesopotamia (Iraq). Inizialmente serviva per registrare transazioni commerciali — non per letteratura. L'alfabeto fonetico arrivò molto dopo."},
 {q:"Quanti km è la distanza dalla Terra alla Luna?",min:0,max:1000000,risposta:384400,"unit":"km",curiosita:"La distanza media Terra-Luna è 384.400 km. Varia tra 356.500 km (perigeo) e 406.700 km (apogeo). La luce impiega circa 1,3 secondi per percorrerla."},
 {q:"Quante ore dura il volo da Roma a Tokyo?",min:0,max:20,risposta:13,unit:"ore",curiosita:"Un volo da Roma a Tokyo dura circa 12-14 ore. Tokyo dista circa 9.500 km da Roma. I voli più lunghi al mondo, come Singapore-New York, durano oltre 18 ore."},
 {q:"Quanti litri di sangue pompa il cuore ogni giorno?",min:0,max:20000,risposta:7000,unit:"litri",curiosita:"Il cuore pompa circa 7.000 litri di sangue al giorno — abbastanza per riempire 35 vasche da bagno. In una vita pompa circa 200 milioni di litri, equivalenti a 3.500 cisterne."},
 {q:"Quante calorie brucia un'ora di corsa?",min:0,max:1000,risposta:600,unit:"kcal",curiosita:"Un'ora di corsa a ritmo moderato brucia circa 500-700 kcal. Dipende da peso, velocità e pendenza. Per bruciare le calorie di una pizza intera servirebbero circa 2 ore di corsa."},
 {q:"Quanti anni fa è iniziato l'Impero Romano?",min:0,max:5000,risposta:2050,unit:"anni fa",curiosita:"L'Impero Romano iniziò nel 27 a.C. quando Ottaviano fu proclamato Augusto — circa 2.050 anni fa. Roma fu fondata nel 753 a.C. L'impero durò circa 500 anni in Occidente."},
 {q:"Quante ossa rompono gli sport di contatto mediamente per atleta per anno?",min:0,max:10,risposta:1,unit:"fratture",curiosita:"Gli atleti di sport di contatto subiscono in media meno di 1 frattura all'anno. Le ossa si riformano più forti dopo una frattura grazie all'osteointegrazione, processo scoperto quasi per caso negli anni '50."},
 {q:"Quanti miliardi di insetti esistono per ogni essere umano?",min:0,max:1000,risposta:200,unit:"milioni di insetti per persona",curiosita:"Si stima che ci siano circa 10 quintilioni (10^19) di insetti sul pianeta — circa 1,4 miliardi per ogni essere umano. Le formiche da sole pesano quanto tutti gli esseri umani messi insieme."},
 {q:"Quante ore al giorno un bambino di 1 anno dorme?",min:0,max:24,risposta:14,unit:"ore",curiosita:"I bambini di 1 anno dormono 12-16 ore al giorno. Il sonno è fondamentale per lo sviluppo del cervello: durante il sonno si rafforzano le connessioni neurologiche formate durante il giorno."},
 {q:"Quanti anni ha impiegato la costruzione della Grande Muraglia Cinese?",min:0,max:2000,risposta:1800,unit:"anni (in varie fasi)",curiosita:"La Grande Muraglia fu costruita in diverse fasi per circa 1.800 anni (VII sec. a.C. - XVII sec. d.C.). Mao Zedong permise di demolirne parti per costruire case. Oggi solo il 30% è ben conservata."},
 {q:"Quanti km/h è la velocità media dell'International Space Station?",min:0,max:50000,risposta:27600,unit:"km/h",curiosita:"La ISS orbita a 27.600 km/h a circa 400 km d'altitudine. Compie un'orbita completa in 92 minuti. Vede 16 albe e tramonti ogni 24 ore. È in orbita continuamente dal novembre 2000."},
 {q:"Quanti gradi è l'angolo di inclinazione dell'asse terrestre?",min:0,max:90,risposta:23,unit:"gradi",curiosita:"L'asse terrestre è inclinato di 23,4° rispetto alla perpendicolare dell'orbita. Questa inclinazione causa le stagioni. Se la Terra fosse dritta non ci sarebbero stagioni."},
 {q:"Quante ore impiega la Terra a ruotare su se stessa?",min:0,max:48,risposta:24,unit:"ore",curiosita:"La Terra compie una rotazione completa in 23 ore, 56 minuti e 4 secondi — non esattamente 24 ore. Il giorno solare è 24 ore perché include il moto della Terra intorno al Sole."},
 {q:"Quanti anni fa fu inventata la stampa a caratteri mobili?",min:0,max:1000,risposta:580,unit:"anni fa",curiosita:"Gutenberg inventò la stampa a caratteri mobili intorno al 1440. La prima grande opera stampata fu la Bibbia di Gutenberg nel 1455. Prima ogni libro era copiato a mano dai monaci."},
 {q:"Quante ali ha un'ape?",min:0,max:10,risposta:4,unit:"ali",curiosita:"Le api hanno 4 ali collegate a paia. Le ali anteriori sono più grandi. Battono le ali circa 200 volte al secondo, producendo il caratteristico ronzio. Volano fino a 30 km/h."},
 {q:"Quanti denti da latte ha un bambino?",min:0,max:40,risposta:20,unit:"denti",curiosita:"I bambini hanno 20 denti da latte: 8 incisivi, 4 canini e 8 molari. Iniziano a spuntare a circa 6 mesi. La sostituzione con i denti permanenti dura da 6 a 12 anni."},
 {q:"Quante calorie brucia il cervello al giorno?",min:0,max:1000,risposta:300,unit:"kcal",curiosita:"Il cervello consuma circa 300 kcal al giorno — il 20% dell'energia corporea pur pesando solo il 2% del corpo. Usa il glucosio come carburante preferenziale. In situazioni di stress il consumo aumenta."},
 {q:"Quante lune ha Marte?",min:0,max:20,risposta:2,unit:"lune",curiosita:"Marte ha 2 lune: Fobos e Deimos. Sono probabilmente asteroidi catturati. Fobos si avvicina a Marte di 1,8 cm l'anno — tra circa 50 milioni di anni si frantumerà formando un anello."},
 {q:"Quanti anni ci volle a costruire le Piramidi di Giza?",min:0,max:200,risposta:20,unit:"anni",curiosita:"La Grande Piramide di Cheope fu costruita in circa 20 anni (2560 a.C.). Usò 2,3 milioni di blocchi di pietra da 2,5-15 tonnellate. Per secoli fu la struttura più alta del mondo: 146 metri."},
 {q:"Quante tonnellate di rifiuti produce l'Italia ogni anno?",min:0,max:50000000,risposta:30000000,unit:"tonnellate",curiosita:"L'Italia produce circa 30 milioni di tonnellate di rifiuti urbani all'anno. La raccolta differenziata supera il 60% in media. Il nord Italia ha le percentuali più alte."},
 {q:"Quanti anni ha il Pantheon di Roma?",min:0,max:3000,risposta:1900,unit:"anni",curiosita:"Il Pantheon fu ricostruito da Adriano intorno al 125 d.C. — ha circa 1.900 anni. È in eccezionale stato di conservazione grazie all'uso continuo. La sua cupola in calcestruzzo è ancora la più grande del mondo non armata."},
 {q:"Quante nazioni parteciparono alle prime Olimpiadi moderne (1896)?",min:0,max:50,risposta:14,unit:"nazioni",curiosita:"Alle prime Olimpiadi moderne di Atene 1896 parteciparono 14 nazioni con 241 atleti (tutti maschi). Oggi le Olimpiadi riuniscono circa 200 nazioni e 10.000 atleti."},
 {q:"Quanti anni vive una mosca comune?",min:0,max:100,risposta:0,unit:"giorni (circa 28)",curiosita:"Una mosca comune (Musca domestica) vive circa 28 giorni. In questo tempo una femmina può deporre fino a 900 uova. Le larve diventano adulte in soli 10-14 giorni."},
 {q:"Quanti kg pesa il cuore di una balenottera azzurra?",min:0,max:1000,risposta:180,unit:"kg",curiosita:"Il cuore della balenottera azzurra pesa circa 180 kg — quanto un'automobile utilitaria. È grande come una piccola auto. Un bambino potrebbe gattonare nelle arterie più grandi."},
 {q:"Quanti anni fa è avvenuta la prima ascensione dell'Everest?",min:0,max:200,risposta:71,unit:"anni fa",curiosita:"Edmund Hillary e Tenzing Norgay scalarono l'Everest il 29 maggio 1953 — circa 71 anni fa. Da allora oltre 6.000 persone hanno raggiunto la vetta. Circa 300 persone ci hanno perso la vita."},
 {q:"Quanti km/h è la velocità massima di un'aquila reale in picchiata?",min:0,max:400,risposta:240,unit:"km/h",curiosita:"L'aquila reale può raggiungere i 240 km/h in picchiata. Ha una vista 8 volte più acuta di quella umana. Può scorgere una lepre da 3 km di distanza."},
 {q:"Quante settimane dura il Tour de France?",min:0,max:6,risposta:3,unit:"settimane",curiosita:"Il Tour de France dura 3 settimane e 21 tappe per circa 3.300 km. I corridori bruciano circa 7.000-8.000 kcal al giorno. Fu fondato nel 1903 da un giornale sportivo per aumentare le vendite."},
 {q:"Quanti anni fa nacque Leonardo da Vinci?",min:0,max:600,risposta:572,unit:"anni fa",curiosita:"Leonardo da Vinci nacque il 15 aprile 1452 — circa 572 anni fa. Dipinse la Gioconda, progettò macchine volanti, studiò anatomia. Lasciò incompiuta la maggior parte dei suoi progetti."},
 {q:"Quante stelle ha la bandiera europea?",min:0,max:20,risposta:12,unit:"stelle",curiosita:"La bandiera europea ha 12 stelle disposte in cerchio. Il numero 12 non rappresenta i paesi membri ma è un simbolo di perfezione e completezza. Fu adottata nel 1955 dal Consiglio d'Europa."},
 {q:"Quanti miliardi di anni è durata l'era dei dinosauri?",min:0,max:5,risposta:0,unit:"(165 milioni di anni)",curiosita:"I dinosauri vissero per circa 165 milioni di anni — dal Triassico al Cretaceo. L'Homo sapiens esiste da soli 300.000 anni. Se un anno rappresentasse 165 milioni di anni, noi esisteremmo da meno di 19 ore."},
 {q:"Quante ore al giorno medita in media un monaco buddista tibetano?",min:0,max:24,risposta:8,unit:"ore",curiosita:"I monaci tibetani meditano in media 6-8 ore al giorno. Studi neuroscientifici mostrano che la meditazione intensa cambia fisicamente il cervello, aumentando la materia grigia nell'ippocampo."},
 {q:"Quanti km è lungo il fiume Po?",min:0,max:1000,risposta:652,unit:"km",curiosita:"Il Po è lungo 652 km — il fiume più lungo d'Italia. Nasce dal Monviso in Piemonte e sfocia nell'Adriatico. La Pianura Padana che attraversa è la pianura più fertile d'Italia."},
 {q:"Quanti anni ci vuole a un albero di quercia per produrre ghiande?",min:0,max:100,risposta:20,unit:"anni",curiosita:"Una quercia inizia a produrre ghiande dopo circa 20-50 anni. Può vivere oltre 500 anni e produrre fino a 70.000 ghiande all'anno. Un tempo servivano per sfamare i maiali e produrre farina."},
 {q:"Quanti milioni di automobili ci sono in Italia?",min:0,max:100,risposta:39,unit:"milioni",curiosita:"In Italia circolano circa 39 milioni di automobili — il rapporto auto/abitante più alto d'Europa con quasi 680 auto ogni 1.000 abitanti. Gli italiani amano le auto: il 90% degli spostamenti avviene su strada."},
 {q:"Quante canzoni ha scritto Ennio Morricone?",min:0,max:1000,risposta:500,unit:"colonne sonore",curiosita:"Ennio Morricone ha composto musiche per oltre 500 film e serie TV. Ha vinto l'Oscar nel 2016 per The Hateful Eight. Le sue composizioni più famose includono Per un pugno di dollari e C'era una volta in America."},
 {q:"Quanti watt produce un pannello solare domestico standard?",min:0,max:1000,risposta:400,unit:"watt",curiosita:"Un pannello solare domestico produce mediamente 300-400 watt di picco. In Italia, un impianto da 6 kW (15 pannelli) produce circa 7.000 kWh/anno — il consumo di una famiglia media."},
 {q:"Quante tonnellate di CO2 assorbe un ettaro di foresta all'anno?",min:0,max:100,risposta:5,unit:"tonnellate di CO2",curiosita:"Un ettaro di foresta assorbe circa 3-8 tonnellate di CO2 all'anno. Le foreste del mondo assorbono circa il 30% delle emissioni globali di CO2. L'Amazzonia da sola assorbe 2 miliardi di tonnellate l'anno."},
 {q:"Quante ore al giorno un adolescente usa il telefono in media?",min:0,max:24,risposta:7,unit:"ore",curiosita:"Gli adolescenti usano il telefono in media 7-9 ore al giorno. L'OMS raccomanda meno di 2 ore di schermo per i bambini e adolescenti. Il tempo medio è più che triplicato nell'ultimo decennio."},
 {q:"Quanti anni ha impiegato Michelangelo a dipingere la Cappella Sistina?",min:0,max:20,risposta:4,unit:"anni",curiosita:"Michelangelo dipinse il soffitto della Cappella Sistina dal 1508 al 1512 — circa 4 anni. Lavorò sdraiato su impalcature alte 20 metri. Il Giudizio Universale sulla parete lo dipinse 25 anni dopo."},
 {q:"Quanti milioni di km² copre la foresta boreale (taiga)?",min:0,max:50,risposta:17,unit:"milioni di km²",curiosita:"La taiga copre circa 17 milioni di km² nell'emisfero nord — la foresta più grande del mondo. Si estende attraverso Russia, Canada, Scandinavia e Alaska. Assorbe enormi quantità di CO2."},
 {q:"Quanti anni fa fu costruito il Partenone ad Atene?",min:0,max:3000,risposta:2460,unit:"anni fa",curiosita:"Il Partenone fu costruito tra il 447 e il 432 a.C. — circa 2.460 anni fa. Fu tempio, chiesa cristiana e moschea ottomana. Nel 1687 esplose quando i veneziani colpirono un deposito di polvere da sparo al suo interno."},
 {q:"Quante ore lavora in media un italiano a settimana?",min:0,max:60,risposta:36,unit:"ore",curiosita:"Gli italiani lavorano in media circa 36 ore settimanali secondo l'OCSE. I messicani sono i più lavoratori con 45 ore. I tedeschi solo 34 ma con una produttività tra le più alte del mondo."},
 {q:"Quanti anni ha la più antica università del mondo?",min:0,max:2000,risposta:1160,unit:"anni",curiosita:"L'Università di Bologna, fondata nel 1088, è la più antica università del mondo occidentale — ha circa 935 anni. Oggi ha circa 85.000 studenti. Dante, Petrarca e Copernico studiarono in Italia."},
 {q:"Quanti km di tubi ha l'acquedotto di una grande città come Roma?",min:0,max:50000,risposta:9000,unit:"km",curiosita:"La rete idrica di Roma ha circa 9.000 km di condutture. Gli Acquedotti romani antichi portavano acqua per centinaia di km. L'Aqua Claudia fu costruita nel 38 d.C. e serviva 14 milioni di litri al giorno."},
 {q:"Quanti km/h è la velocità di caduta libera di un paracadutista?",min:0,max:300,risposta:200,unit:"km/h",curiosita:"Un paracadutista in caduta libera raggiunge circa 190-200 km/h in posizione orizzontale. Con il corpo verticale si possono superare i 250 km/h. Il record in tuta alare è di oltre 400 km/h."},
 {q:"Quanti anni vive un cigno?",min:0,max:50,risposta:20,unit:"anni",curiosita:"I cigni vivono circa 20-30 anni. Si accoppiano a vita — se un partner muore il superstite può morire di crepacuore. Il cigno nero dell'Australia è uno dei simboli di eventi impossibili: il 'Black Swan'."},
 {q:"Quante note ci sono in un'ottava musicale?",min:0,max:20,risposta:12,unit:"semitoni",curiosita:"Un'ottava ha 12 semitoni (7 note naturali + 5 alterazioni). Bach nella sua opera 'Il clavicembalo ben temperato' compose pezzi in tutte le 24 tonalità per dimostrare il sistema temperato."},
 {q:"Quanti kg mangia al giorno un orso grizzly prima del letargo?",min:0,max:100,risposta:20,unit:"kg di cibo",curiosita:"Un orso grizzly mangia circa 20.000 calorie al giorno nei mesi pre-letargo — equivalenti a 20 kg di cibo. Può aumentare il peso del 30% in poche settimane. Durante il letargo non mangia né beve per 5-7 mesi."},
 {q:"Quante canzoni ha composto Johann Sebastian Bach?",min:0,max:2000,risposta:1100,unit:"composizioni",curiosita:"Bach compose circa 1.100 opere catalogate — forse di più andato perduto. Compose fino alla fine della vita nonostante la cecità. Aveva 20 figli da due matrimoni, molti dei quali diventarono anche loro compositori."},
 {q:"Quanti anni fa fu inventata la penicillina?",min:0,max:200,risposta:96,unit:"anni fa",curiosita:"Alexander Fleming scoprì la penicillina nel 1928 — circa 96 anni fa. La storia racconta che tornò dalle vacanze e trovò muffa che uccideva i batteri. Ha salvato centinaia di milioni di vite."},
 {q:"Quanti milioni di italiani vivono all'estero?",min:0,max:20,risposta:6,unit:"milioni",curiosita:"Circa 6 milioni di italiani residono all'estero — il 10% della popolazione. Le mete preferite sono Germania, Svizzera, UK, USA e Australia. L'emigrazione italiana fu massiccia tra il 1880 e il 1970."},
 {q:"Quante calorie ha una porzione di pasta al pomodoro (80g di pasta)?",min:0,max:1000,risposta:330,unit:"kcal",curiosita:"Una porzione di pasta al pomodoro con 80g di pasta ha circa 300-360 kcal. La pasta è l'alimento simbolo della dieta mediterranea. Gli italiani consumano circa 24 kg di pasta a testa all'anno — i maggiori consumatori al mondo."},
 {q:"Quanti anni fa fu eretta la Torre Pendente di Pisa?",min:0,max:1000,risposta:851,unit:"anni fa",curiosita:"La costruzione iniziò nel 1173 — circa 851 anni fa. La pendenza iniziò durante la costruzione per un terreno cedevole. Dal 1990 al 2001 fu raddrizzata di 44 cm per stabilizzarla. Oggi pende di circa 4 gradi."},
 {q:"Quante ore settimanali di TV guarda in media un italiano?",min:0,max:50,risposta:26,unit:"ore",curiosita:"Gli italiani guardano circa 26 ore di TV a settimana — quasi 4 ore al giorno. Sono tra i maggiori fruitori europei. I programmi più seguiti rimangono i notiziari e i programmi di intrattenimento."},
 {q:"Quanti km è la distanza dal centro della Terra al centro del Sole?",min:0,max:1000000000,risposta:149600000,"unit":"km",curiosita:"La distanza media Terra-Sole è circa 149,6 milioni di km — detta Unità Astronomica (UA). In inverno la Terra è leggermente più vicina al Sole rispetto all'estate (la differenza è di circa 5 milioni di km)."}
,
 {q:"Quanti miliardi di dollari fattura Amazon ogni anno?",min:0,max:1000,risposta:574,unit:"miliardi di dollari",curiosita:"Amazon ha fatturato circa 574 miliardi di dollari nel 2023. Fu fondata da Jeff Bezos nel garage di casa nel 1994 vendendo libri online. Oggi è il più grande retailer e provider cloud del mondo."},
 {q:"Quanti anni ci volle a costruire la Via Appia?",min:0,max:500,risposta:100,unit:"anni circa",curiosita:"La Via Appia fu costruita a partire dal 312 a.C. I Romani costruirono 80.000 km di strade nell'impero. Molte sono ancora usate oggi. 'Tutte le strade portano a Roma' nasce da qui."},
 {q:"Quanti milioni di persone parlano italiano nel mondo?",min:0,max:200,risposta:85,unit:"milioni",curiosita:"Circa 85 milioni di persone parlano italiano nel mondo tra madrelingua e L2. È la lingua ufficiale di Italia, Svizzera, San Marino e Vaticano. È molto studiata per l'arte, la musica e la cucina."},
 {q:"Quante ossa rompono i surfisti mediamente nella carriera?",min:0,max:20,risposta:3,unit:"fratture",curiosita:"I surfisti professionisti subiscono in media 2-4 fratture nella carriera. I rischi principali sono le cadute sulla tavola e sugli scogli. Le onde più grandi al mondo sono a Nazaré in Portogallo: fino a 30 metri."},
 {q:"Quante ore al giorno un bambino di 5 anni dovrebbe stare all'aperto?",min:0,max:10,risposta:3,unit:"ore",curiosita:"L'OMS raccomanda almeno 3 ore di attività fisica per i bambini sotto i 5 anni. La vitamina D prodotta dalla luce solare è essenziale per lo sviluppo osseo. I bambini di oggi trascorrono il 50% di tempo in meno all'aperto rispetto ai loro genitori."},
 {q:"Quanti km è lunga la rete autostradale italiana?",min:0,max:10000,risposta:6943,unit:"km",curiosita:"L'Italia ha circa 6.943 km di autostrade — la quarta rete più estesa d'Europa. L'Autostrada del Sole (A1) è la più lunga con 754 km. L'Italia fu pioniera: la prima autostrada al mondo fu la Milano-Laghi nel 1924."},
 {q:"Quanti litri d'acqua utilizza una doccia di 5 minuti?",min:0,max:200,risposta:50,unit:"litri",curiosita:"Una doccia di 5 minuti consuma circa 50-60 litri d'acqua (10 litri/minuto). Un bagno ne consuma circa 150-200 litri. Ridurre la doccia di 2 minuti risparmia 20 litri al giorno — 7.300 litri all'anno."},
 {q:"Quanti anni vive in media un cane?",min:0,max:30,risposta:12,unit:"anni",curiosita:"I cani vivono in media 10-13 anni. Le razze piccole vivono più a lungo delle grandi. Il cane più vecchio mai documentato era Bobi, un pastore portoghese vissuto fino a 31 anni."},
 {q:"Quanti km percorre un'ape in tutta la sua vita?",min:0,max:1000,risposta:800,unit:"km",curiosita:"Un'ape operaia percorre circa 800 km nel corso della sua breve vita (4-6 settimane). Vola fino a 3 km dall'alveare per cercare fiori. Nel corso della vita produce circa 1/12 di cucchiaino di miele."},
 {q:"Quante persone vivono sotto il livello del mare in Olanda?",min:0,max:100,risposta:60,unit:"% della popolazione",curiosita:"Circa il 26% del territorio olandese è sotto il livello del mare, dove vive il 60% della popolazione. L'Olanda ha costruito un sistema di dighe, canali e pompe (polder) per tenere l'acqua fuori da secoli."},
 {q:"Quanti milioni di km² occupa il Sahara?",min:0,max:20,risposta:9,unit:"milioni di km²",curiosita:"Il Sahara copre circa 9 milioni di km² — quasi quanto gli USA. Paradossalmente in alcune zone non piove per anni, in altre cadono brevi ma violente tempeste. Solo il 25% è sabbia: il resto è roccia e ghiaia."},
 {q:"Quanti anni fa fu costruito il Taj Mahal?",min:0,max:500,risposta:380,unit:"anni fa",curiosita:"Il Taj Mahal fu costruito tra il 1632 e il 1643 dal Mughal Shah Jahan in memoria della moglie morta di parto. Ci vollero 20.000 operai. È considerato il più bel edificio del mondo e simbolo dell'amore eterno."},
 {q:"Quanti km/h è la velocità media di un velista olimpico?",min:0,max:100,risposta:20,unit:"km/h",curiosita:"Un velista olimpico nella classe 49er raggiunge circa 20-30 km/h. I catamarani da regata superano i 50 km/h. I foiling (barca che 'vola' sull'acqua) raggiungono oltre 100 km/h."},
 {q:"Quante specie di squali esistono?",min:0,max:600,risposta:500,unit:"specie",curiosita:"Esistono circa 500 specie di squali. Il più grande è lo squalo balena (18 metri) che si nutre solo di plancton. Lo squalo bianco è il predatore più temuto ma attacca raramente l'uomo: muoiono più persone colpite da fulmini."},
 {q:"Quante calorie ha un avocado?",min:0,max:500,risposta:240,unit:"kcal",curiosita:"Un avocado medio (200g) ha circa 240 kcal e 22g di grassi — quasi tutti grassi buoni monoinsaturi. È ricchissimo di potassio (più delle banane) e vitamina K, B5 e acido folico."},
 {q:"Quanti anni di differenza c'è tra Giulio Cesare e Napoleone?",min:0,max:2000,risposta:1800,unit:"anni",curiosita:"Giulio Cesare nacque nel 100 a.C., Napoleone nel 1769 d.C. — circa 1.869 anni di differenza. Entrambi erano grandi generali, entrambi riformatori, entrambi avevano problemi con le potenze europee."},
 {q:"Quanti campionati del mondo di calcio ha vinto il Brasile?",min:0,max:10,risposta:5,unit:"Mondiali",curiosita:"Il Brasile ha vinto 5 Mondiali (1958, 1962, 1970, 1994, 2002) — il paese con più titoli. È l'unica nazionale ad aver partecipato a tutti i 22 Mondiali. Pelé vinse 3 Mondiali."},
 {q:"Quanti anni ci volle a costruire la Torre di Pisa?",min:0,max:400,risposta:177,unit:"anni",curiosita:"La costruzione della Torre Pendente di Pisa durò dal 1173 al 1350 — circa 177 anni, interrotta più volte per guerre. La pendenza iniziò quasi subito per il terreno cedevole. Paradossalmente la salvò: rese la torre famosa nel mondo."},
 {q:"Quanti minuti impiega un essere umano per addormentarsi in media?",min:0,max:60,risposta:7,unit:"minuti",curiosita:"Ci vogliono in media 7-20 minuti per addormentarsi. Addormentarsi in meno di 5 minuti è segno di privazione del sonno. Il tempo cambia con l'età: i bambini si addormentano più lentamente degli adulti."},
 {q:"Quante partite gioca una squadra di Serie A in una stagione?",min:0,max:50,risposta:38,unit:"partite",curiosita:"Ogni squadra di Serie A gioca 38 partite di campionato (20 squadre × 2 partite ciascuna). Con coppe europee e nazionali una grande squadra può arrivare a 60 partite stagionali."},
 {q:"Quanti anni fa nacque la pizza napoletana?",min:0,max:500,risposta:250,unit:"anni fa circa",curiosita:"La pizza napoletana come la conosciamo nacque nella seconda metà del '700 a Napoli. La margherita fu creata nel 1889 in onore della Regina Margherita. La pizza napoletana è patrimonio UNESCO dal 2017."},
 {q:"Quanti miliardi di euro vale il PIL italiano?",min:0,max:5000,risposta:2000,unit:"miliardi di euro",curiosita:"Il PIL italiano è circa 2.000 miliardi di euro — l'ottava economia mondiale. L'Italia eccelle in manifattura di lusso, meccanica, chimica e agroalimentare. Il nord produce circa il 60% del PIL nazionale."},
 {q:"Quanti euro vale mediamente uno stipendio netto in Italia?",min:0,max:5000,risposta:1600,unit:"euro/mese netto",curiosita:"Lo stipendio netto medio in Italia è circa 1.500-1.700 euro al mese. Ma c'è grande disparità: il nord supera i 2.000 euro, il sud spesso non raggiunge i 1.200. Il gap con Germania e Francia è di circa 400 euro."},
 {q:"Quanti km/h è la velocità massima di un'automobile di Formula 1?",min:0,max:500,risposta:378,unit:"km/h",curiosita:"La velocità massima in gara di una F1 è circa 350-378 km/h. Honda registrò 397 km/h in prova nel 2006. Le G laterali nelle curve arrivano a 6G — come 6 volte il proprio peso che preme sul corpo."},
 {q:"Quante persone muoiono ogni anno a causa del fumo nel mondo?",min:0,max:20000000,risposta:8000000,unit:"persone",curiosita:"Circa 8 milioni di persone muoiono ogni anno per cause legate al fumo. È la principale causa di morte evitabile nel mondo. Il tabacco uccide la metà dei suoi consumatori abituali."},
 {q:"Quanti anni ci vuole al plastica per decomporsi?",min:0,max:1000,risposta:500,unit:"anni",curiosita:"La plastica impiega 100-1000 anni per decomporsi. Una bottiglia di plastica dura circa 450 anni. Anche quando si 'decompone' non sparisce ma diventa microplastica che entra nella catena alimentare."},
 {q:"Quanti anni aveva il più giovane Papa della storia?",min:0,max:100,risposta:18,unit:"anni",curiosita:"Secondo alcune fonti storiche, Papa Giovanni XII salì al soglio pontificio a soli 18 anni nel 955 d.C. Altri storici indicano età tra 18 e 25 anni. Fu tra i papi più controversi della storia."},
 {q:"Quanti km di coste ha la Grecia?",min:0,max:30000,risposta:13676,unit:"km",curiosita:"La Grecia ha circa 13.676 km di coste — la decima al mondo per lunghezza. Le isole greche sono circa 6.000, di cui circa 230 abitate. Le isole rappresentano il 20% del territorio greco."},
 {q:"Quanti anni fa morì Cleopatra?",min:0,max:3000,risposta:2063,unit:"anni fa",curiosita:"Cleopatra morì nel 30 a.C. — circa 2.050 anni fa. Era vissuta più vicina all'invenzione dello smartphone che alla costruzione delle Piramidi. Parlava 9 lingue ed era una studiosa di filosofia."},
 {q:"Quanti litri di latte produce una mucca al giorno?",min:0,max:100,risposta:25,unit:"litri",curiosita:"Una mucca da latte produce in media 20-30 litri di latte al giorno. Le razze più produttive come la Frisona Holstein arrivano a 50 litri. Per produrre 1 litro di latte servono circa 1.000 litri d'acqua."},
 {q:"Quanti anni ha impiegato Cristoforo Colombo nel primo viaggio verso le Americhe?",min:0,max:5,risposta:1,unit:"anno circa (36 giorni)",curiosita:"Il primo viaggio di Colombo durò dal 3 agosto al 12 ottobre 1492 — circa 70 giorni totali, di cui 36 di navigazione atlantica. Partì con 3 caravelle e 87 uomini. Tornò in Spagna nel marzo 1493."},
 {q:"Quanti grammi di zucchero ha una lattina di Coca-Cola?",min:0,max:100,risposta:39,unit:"grammi",curiosita:"Una lattina da 330ml di Coca-Cola classica contiene circa 39 grammi di zucchero — quasi 10 cucchiaini. L'OMS raccomanda non più di 25g di zuccheri liberi al giorno per gli adulti."},
 {q:"Quanti anni vive in media un albero di ulivo?",min:0,max:5000,risposta:500,unit:"anni",curiosita:"Un ulivo vive in media 500 anni, ma molti esemplari superano i 2.000 anni. Gli ulivi più antichi del mondo si trovano in Palestina, Grecia e Sardegna. L'ulivo simboleggia pace e longevità."},
 {q:"Quante ore di luce solare arriva sulla Terra ogni anno?",min:0,max:100000,risposta:8760,unit:"ore di irraggiamento solare",curiosita:"La Terra riceve luce solare per le stesse ore in cui il sole è sopra l'orizzonte — circa 4.380 ore all'anno in media alle medie latitudini. L'energia solare che arriva sulla Terra in 1 ora supera il consumo energetico mondiale annuo."},
 {q:"Quanti km è la tratta ferroviaria più lunga del mondo (Trans-Siberiana)?",min:0,max:15000,risposta:9289,unit:"km",curiosita:"La Transiberiana è la ferrovia più lunga del mondo con 9.289 km da Mosca a Vladivostok. Attraversa 8 fusi orari e impiega 6 giorni completi senza fermate. Fu costruita tra il 1891 e il 1916."},
 {q:"Quante ore impiegherebbe una lumaca a percorrere 1 km?",min:0,max:100,risposta:10,unit:"ore",curiosita:"Una lumaca si muove a circa 0,08 km/h — 1 km le richiederebbe circa 10-15 ore. Ma nonostante la lentezza, riescono a percorrere diversi km in una notte alla ricerca di cibo. Alcune specie migrano stagionalmente."},
 {q:"Quanti anni fa è avvenuto lo sbarco degli Alleati in Sicilia (Operazione Husky)?",min:0,max:200,risposta:81,unit:"anni fa",curiosita:"L'Operazione Husky si svolse il 9-10 luglio 1943 — circa 81 anni fa. Fu il più grande sbarco anfibio della storia fino a Normandia. Segnò l'inizio della liberazione dell'Italia."},
 {q:"Quanti anni fa nacque Dante Alighieri?",min:0,max:1000,risposta:759,unit:"anni fa",curiosita:"Dante nacque nel 1265 a Firenze — circa 759 anni fa. Fu esiliato dalla sua città e morì a Ravenna nel 1321 senza potervi tornare. La Divina Commedia è considerata il più grande poema della letteratura italiana."},
 {q:"Quante km è lunga la Costiera Amalfitana?",min:0,max:100,risposta:50,unit:"km",curiosita:"La Costiera Amalfitana è lunga circa 50 km tra Positano e Vietri sul Mare. È patrimonio UNESCO dal 1997. La strada statale che la percorre (SS163) è considerata tra le più belle e pericolose d'Italia."},
 {q:"Quanti anni fa è stata fondata la città di Venezia?",min:0,max:2000,risposta:1600,unit:"anni fa circa",curiosita:"Venezia fu fondata intorno al 421 d.C. su isolotti lagunari dai profughi che fuggivano dalle invasioni barbariche. Per secoli fu la più potente repubblica marinara del Mediterraneo. Oggi rischia di affogare per il cambiamento climatico."},
 {q:"Quanti milioni di turisti visita l'Italia ogni anno?",min:0,max:200,risposta:65,unit:"milioni di turisti",curiosita:"L'Italia accoglie circa 65 milioni di turisti stranieri all'anno — la quinta destinazione mondiale. I più numerosi sono tedeschi, americani, francesi e britannici. Il turismo vale circa il 13% del PIL italiano."},
 {q:"Quante lune ha Nettuno?",min:0,max:20,risposta:16,unit:"lune",curiosita:"Nettuno ha 16 lune conosciute. Tritone, la più grande, orbita in senso contrario alla rotazione del pianeta — probabilmente un corpo del Cintura di Kuiper catturato dalla gravità di Nettuno miliardi di anni fa."},
 {q:"Quanti anni fa nacque il calcio moderno?",min:0,max:300,risposta:162,unit:"anni fa",curiosita:"Le regole del calcio moderno furono codificate nel 1863 a Londra dalla Football Association — circa 162 anni fa. Prima le regole variavano da scuola a scuola. Il calcio è oggi lo sport più popolare del mondo con 4 miliardi di tifosi."},
 {q:"Quanti euro costa in media una notte in un albergo 4 stelle a Roma?",min:0,max:1000,risposta:200,unit:"euro",curiosita:"Una notte in un 4 stelle a Roma costa in media 180-250 euro. In alta stagione (primavera-estate) i prezzi raddoppiano. Roma è tra le 10 città più visitate al mondo con oltre 10 milioni di turisti l'anno."},
 {q:"Quanti anni fa nacque la Ferrari?",min:0,max:200,risposta:78,unit:"anni fa",curiosita:"La Ferrari fu fondata da Enzo Ferrari nel 1947 a Maranello — circa 77 anni fa. La prima Ferrari da corsa fu la 125 S. Oggi produce circa 14.000 auto l'anno e ogni Ferrari ha una lista d'attesa media di 2 anni."},
 {q:"Quante persone lavora mediamente un circo tradizionale italiano?",min:0,max:500,risposta:50,unit:"persone",curiosita:"Un circo tradizionale italiano impiega circa 40-80 persone tra artisti, tecnici e personale. Il circo moderno nacque in Inghilterra nel 1768. Il Cirque du Soleil canadese ha trasformato il genere eliminando gli animali."},
 {q:"Quante ore ci vuole per attraversare l'Atlantico in barca a vela?",min:0,max:2000,risposta:336,unit:"ore (circa 14 giorni)",curiosita:"Attraversare l'Atlantico in barca a vela richiede circa 14-21 giorni partendo dalle Canarie. La Transatlantic Race in barca a vela monoscafo dura circa 6-7 giorni. Il record assoluto con un trimarano è meno di 6 giorni."},
 {q:"Quanti anni ha il formaggio Parmigiano Reggiano più stagionato?",min:0,max:100,risposta:36,unit:"mesi (al massimo)",curiosita:"Il Parmigiano Reggiano si produce da stagionature di 12 mesi fino a 36 mesi ('stravecchio'). Più è stagionato, più è duro e ricco di cristalli di tirosina. Servono 16 litri di latte per ogni kg di formaggio."},
 {q:"Quante volte la Nazionale italiana di calcio ha vinto il Mondiale?",min:0,max:10,risposta:4,unit:"volte",curiosita:"L'Italia ha vinto 4 Mondiali: 1934, 1938, 1982 e 2006. L'82 con Rossi e l'86 con Zoff è il più celebre. Il 2006 a Berlino contro la Francia fu deciso ai rigori dopo il colpo di testa di Zidane."},
 {q:"Quante calorie ha 100g di mozzarella di bufala?",min:0,max:500,risposta:270,unit:"kcal",curiosita:"La mozzarella di bufala campana DOP ha circa 270 kcal per 100g — più della mozzarella vaccina. È prodotta esclusivamente nel sud Italia con latte di bufala. Ha una consistenza più cremosa e un sapore più intenso."},
 {q:"Quanti anni fa nacque Isaac Newton?",min:0,max:500,risposta:382,unit:"anni fa",curiosita:"Isaac Newton nacque il 25 dicembre 1642 — circa 382 anni fa. Formulò le leggi della gravità, del moto e il calcolo infinitesimale. Disse che le sue scoperte furono possibili 'stando sulle spalle di giganti'."},
 {q:"Quante notti ci sono state tra la prima notte di Natale e oggi?",min:0,max:1000000,risposta:735000,unit:"notti (circa)",curiosita:"Dal primo Natale cristiano (circa 25 d.C.) sono trascorse circa 730.000 notti. Il Natale fu fissato al 25 dicembre per sovrapporsi alle feste pagane del Solstizio d'inverno. Il Babbo Natale moderno fu inventato dalla Coca-Cola nel 1930."},
 {q:"Quanti anni ha il brandy più vecchio mai venduto all'asta?",min:0,max:300,risposta:200,unit:"anni",curiosita:"Alcuni brandy d'annate del XIX secolo (più di 200 anni) sono stati venduti all'asta per migliaia di euro a bottiglia. Il cognac più pregiato proviene dalla regione di Cognac in Francia e invecchia in botti di rovere."},
 {q:"Quante note ha la scala musicale di Do maggiore?",min:0,max:20,risposta:7,unit:"note",curiosita:"La scala di Do maggiore ha 7 note: Do, Re, Mi, Fa, Sol, La, Si. L'ottava (Do superiore) chiude il ciclo. Ci sono 12 scale maggiori e 12 minori nella musica occidentale temperata."},
 {q:"Quante migliaia di km percorre l'uccello Sterna artica nella migrazione annuale?",min:0,max:100,risposta:70,unit:"migliaia di km",curiosita:"La Sterna artica percorre circa 70.000-90.000 km l'anno — la migrazione più lunga di qualsiasi animale. Vola dall'Artico all'Antartide e ritorno. In una vita percorre la stessa distanza di 3 viaggi Terra-Luna."},
 {q:"Quante stelle Michelin ha il ristorante più premiato del mondo?",min:0,max:10,risposta:3,unit:"stelle",curiosita:"Il massimo delle stelle Michelin è 3 — ottenuto da circa 130 ristoranti nel mondo. L'Italia ha circa 40 ristoranti con 2-3 stelle. La prima guida Michelin fu pubblicata nel 1900 come guida turistica per automobilisti."},
 {q:"Quanti anni fa è stata composta la Nona Sinfonia di Beethoven?",min:0,max:300,risposta:200,unit:"anni fa",curiosita:"La Nona Sinfonia di Beethoven fu eseguita per la prima volta nel 1824 — circa 200 anni fa. Beethoven era completamente sordo ma batteva il tempo sul palco. L'Inno alla Gioia è il suo quarto e ultimo movimento."},
 {q:"Quanti km è lungo il confine tra Italia e Francia?",min:0,max:2000,risposta:488,unit:"km",curiosita:"Il confine Italia-Francia misura circa 488 km lungo le Alpi. Il Monte Bianco si trova esattamente sulla frontiera. Il Traforo del Monte Bianco (11,6 km) è uno dei tunnel stradali più lunghi del mondo."},
 {q:"Quante tonnellate di formaggi produce l'Italia ogni anno?",min:0,max:2000000,risposta:1200000,unit:"tonnellate",curiosita:"L'Italia produce circa 1,2 milioni di tonnellate di formaggio l'anno. Con 487 varietà è il paese con più tipi di formaggio DOP/IGP. Il Grana Padano è il più prodotto, il Parmigiano il più esportato."},
 {q:"Quanti anni ci volle a Michelangelo per scolpire il David?",min:0,max:20,risposta:2,unit:"anni",curiosita:"Michelangelo scolpì il David tra il 1501 e il 1504 — circa 2 anni. Ricavò la statua da un blocco di marmo che altri scultori avevano abbandonato. È alta 5,17 metri e pesa 5,6 tonnellate."},
 {q:"Quanti astronauti sono morti in missioni spaziali?",min:0,max:100,risposta:18,unit:"astronauti",curiosita:"Diciotto astronauti hanno perso la vita in missioni spaziali: 3 nell'Apollo 1 (1967), 7 nello Challenger (1986) e 7 nel Columbia (2003). Molti altri sono morti durante l'addestramento."}
,
 {q:"Quanti km è lungo il Po?",min:0,max:1000,risposta:652,unit:"km",curiosita:"Il Po è il fiume più lungo d'Italia con 652 km. Nasce dal Monviso (2.022 m) in Piemonte e sfocia nell'Adriatico. Drena il 16% del territorio italiano e irrigua la pianura più fertile d'Italia."},
 {q:"Quante specie di uccelli esistono nel mondo?",min:0,max:20000,risposta:10000,unit:"specie",curiosita:"Esistono circa 10.000 specie di uccelli. Il pinguino imperatore è il più grande (1,2 m), il colibrì ape il più piccolo (5 cm). Il passero è l'uccello più diffuso al mondo."},
 {q:"Quante ore al giorno dorme un koala?",min:0,max:24,risposta:22,unit:"ore",curiosita:"I koala dormono 18-22 ore al giorno — il mammifero che dorme di più. Mangiano solo foglie di eucalipto, che sono povere di nutrienti e leggermente tossiche: servono molte ore per digerirle."},
 {q:"Quanti anni fa cadde Troia?",min:0,max:4000,risposta:3200,unit:"anni fa circa",curiosita:"La guerra di Troia si svolse intorno al 1200 a.C. — circa 3.200 anni fa. Il sito archeologico di Troia è in Turchia. L'Odissea di Omero racconta il viaggio di ritorno di Ulisse durato 10 anni."},
 {q:"Quante centinaia di km sono tra Milano e Roma?",min:0,max:20,risposta:6,unit:"centinaia di km (578 km)",curiosita:"Milano e Roma distano circa 578 km in linea retta, 730 km su strada. Il Frecciarossa le collega in circa 3 ore. Storicamente era un viaggio di 2 settimane in carrozza."},
 {q:"Quanti anni impiegò Cristoforo Colombo a convincere i Re Spagnoli?",min:0,max:20,risposta:7,unit:"anni",curiosita:"Colombo trascorse 7 anni a cercare finanziatori dopo che Portogallo, Inghilterra e altri avevano rifiutato. La Spagna accettò nel 1492. Isabella di Castiglia fu la sua sostenitrice principale."},
 {q:"Quante calorie ha 100g di noci?",min:0,max:1000,risposta:654,unit:"kcal",curiosita:"Le noci hanno 654 kcal per 100g — sono molto caloriche ma ricche di omega-3, antiossidanti e vitamina E. Studi mostrano che mangiare una manciata di noci al giorno riduce il rischio cardiovascolare."},
 {q:"Quanti anni ci vuole a un albero da frutto per produrre i primi frutti?",min:0,max:20,risposta:4,unit:"anni",curiosita:"La maggior parte degli alberi da frutto produce i primi frutti dopo 3-5 anni dalla piantagione. Un melo vive 50-80 anni in produzione. I melograni e i fichi del Medio Oriente vivono fino a 200 anni."},
 {q:"Quante specie di scimmie esistono?",min:0,max:500,risposta:300,unit:"specie",curiosita:"Esistono circa 300 specie di primati non umani. Il gorilla di montagna è il più a rischio: ne restano circa 1.000. I bonobo condividono il 98,7% del DNA con gli esseri umani — la stessa percentuale degli scimpanzé."},
 {q:"Quanti anni ci volle a costruire la Basilica di San Pietro?",min:0,max:300,risposta:120,unit:"anni",curiosita:"La Basilica di San Pietro fu costruita tra il 1506 e il 1626 — circa 120 anni. Vi lavorarono Bramante, Raffaello, Michelangelo e Bernini. La cupola di Michelangelo è alta 136 metri."},
 {q:"Quanti km è il confine tra USA e Messico?",min:0,max:5000,risposta:3145,unit:"km",curiosita:"Il confine USA-Messico è lungo 3.145 km — uno dei più attraversati al mondo. Dal 1994 con il NAFTA il commercio tra i due paesi ha raggiunto i 600 miliardi di dollari l'anno."},
 {q:"Quanti anni fa nacque Alessandro Magno?",min:0,max:2500,risposta:2366,unit:"anni fa",curiosita:"Alessandro Magno nacque nel 356 a.C. Morì a 32 anni nel 323 a.C. ad Alessandria. In 13 anni di campagne conquistò un impero che si estendeva dalla Grecia all'India — 5 milioni di km²."},
 {q:"Quante specie di api esistono nel mondo?",min:0,max:30000,risposta:20000,unit:"specie",curiosita:"Esistono circa 20.000 specie di api. Solo l'ape mellifera produce il miele commerciale. Senza api il 70% delle colture alimentari mondiali cesserebbe — sono impollinatrici fondamentali."},
 {q:"Quanti anni ha la ricetta della pasta fresca all'uovo?",min:0,max:1000,risposta:800,unit:"anni circa",curiosita:"Le prime ricette di pasta fresca all'uovo risalgono al XIII secolo in Italia. Marco Polo non portò la pasta dalla Cina — era già presente in Italia. La pasta secca fu introdotta dagli Arabi in Sicilia nell'800 d.C."},
 {q:"Quante ore dura la notte più lunga dell'anno a Roma?",min:0,max:24,risposta:15,unit:"ore",curiosita:"A Roma al solstizio d'inverno (21 dicembre) la notte dura circa 14,5-15 ore. Al solstizio d'estate dura invece solo 9 ore. La differenza è causata dall'inclinazione dell'asse terrestre."},
 {q:"Quanti km è lungo il tunnel del Gottardo (ferrovia)?",min:0,max:100,risposta:57,unit:"km",curiosita:"Il tunnel di base del San Gottardo in Svizzera è lungo 57 km — il più lungo del mondo. Aperto nel 2016 dopo 17 anni di costruzione e 9 miliardi di euro. Collega il nord e il sud dell'Europa."},
 {q:"Quanti anni ci volle a Napoleone per conquistare l'Europa?",min:0,max:30,risposta:15,unit:"anni",curiosita:"Napoleone dominò l'Europa dal 1799 al 1814 — circa 15 anni. Fu esiliato all'Elba nel 1814, tornò per i 100 Giorni nel 1815, poi fu definitivamente sconfitto a Waterloo e esiliato a Sant'Elena."},
 {q:"Quanti litri di vino produce l'Italia ogni anno?",min:0,max:100000000,risposta:49000000,unit:"ettolitri",curiosita:"L'Italia produce circa 49 milioni di ettolitri di vino l'anno — la prima al mondo con la Francia. Ha 350 varietà autoctone e 400 DOC/DOCG. Il Chianti Classico, il Barolo e il Brunello sono tra i più famosi."},
 {q:"Quanti anni vive un cavallo?",min:0,max:50,risposta:25,unit:"anni",curiosita:"I cavalli vivono in media 25-30 anni. Old Billy, un cavallo inglese, visse 62 anni. I cavalli sono stati domesticati circa 6.000 anni fa in Asia centrale. Hanno una memoria eccezionale."},
 {q:"Quante persone abitano in Africa?",min:0,max:3000000000,risposta:1400000000,unit:"abitanti",curiosita:"L'Africa ha circa 1,4 miliardi di abitanti — il 17% della popolazione mondiale. Entro il 2050 raddoppierà a 2,5 miliardi. L'Africa subsahariana ha il tasso di crescita demografica più alto al mondo."},
 {q:"Quante lingue ufficiali ha la Svizzera?",min:0,max:10,risposta:4,unit:"lingue ufficiali",curiosita:"La Svizzera ha 4 lingue ufficiali: tedesco (63%), francese (23%), italiano (8%) e romancio (1%). È uno dei pochi paesi multilingue stabili. Berna è la capitale federale ma Ginevra è la città internazionale."},
 {q:"Quanti anni fa fu inventato il microscopio?",min:0,max:500,risposta:400,unit:"anni fa circa",curiosita:"Il microscopio fu inventato intorno al 1600 da Hans e Zacharias Janssen in Olanda. Van Leeuwenhoek migliorò l'invenzione e nel 1674 osservò per la prima volta i batteri — li chiamò 'animaletti'."},
 {q:"Quanti kg di sale si producono nel mondo ogni anno?",min:0,max:1000000000,risposta:300000000,unit:"tonnellate",curiosita:"Il mondo produce circa 300 milioni di tonnellate di sale l'anno. Solo il 6% viene usato in cucina — il resto va all'industria chimica, alla deghiacciatura delle strade e alla conservazione."},
 {q:"Quanti anni fa morì Giulio Cesare?",min:0,max:3000,risposta:2068,unit:"anni fa",curiosita:"Giulio Cesare fu assassinato il 15 marzo del 44 a.C. — le Idi di Marzo — circa 2.068 anni fa. Ricevette 23 coltellate da 60 senatori. Morì ai piedi della statua di Pompeo, suo ex alleato e rivale."},
 {q:"Quante ore al giorno un leone dorme?",min:0,max:24,risposta:20,unit:"ore",curiosita:"I leoni dormono 16-20 ore al giorno — tra i mammiferi più pigri. Le leonesse cacciano quasi esclusivamente, i maschi mangiano per primi malgrado non partecipino alla caccia."},
 {q:"Quante specie di pesci esistono?",min:0,max:50000,risposta:33000,unit:"specie",curiosita:"Esistono circa 33.000 specie di pesci — metà di tutte le specie vertebrate. Il più grande è lo squalo balena (18 m), il più piccolo è il Paedocypris progenetica: 7,9 mm."},
 {q:"Quanti anni ci volle alla NASA per portare l'uomo sulla Luna dall'annuncio di Kennedy?",min:0,max:20,risposta:8,unit:"anni",curiosita:"Kennedy annunciò l'obiettivo lunare nel 1961. L'allunaggio avvenne nel 1969 — 8 anni dopo. Il programma Apollo costò 25 miliardi di dollari (150 miliardi attuali) e impiegò 400.000 persone."},
 {q:"Quanti km è lungo il confine italiano con l'Austria?",min:0,max:1000,risposta:430,unit:"km",curiosita:"Il confine Italia-Austria è lungo circa 430 km lungo le Alpi. Il passo più alto è lo Stelvio (2.757 m). La questione dell'Alto Adige/Südtirol fu risolta con lo Statuto speciale del 1972."},
 {q:"Quanti milioni di euro vale il mercato della moda italiana?",min:0,max:200,risposta:100,unit:"miliardi di euro",curiosita:"Il sistema moda italiano vale circa 100 miliardi di euro — tra i primi al mondo. Milano è la quarta capitale della moda dopo Parigi, New York e Londra. Armani, Gucci, Prada e Versace sono tra i marchi più famosi."},
 {q:"Quanti anni fa fu fondato Facebook?",min:0,max:50,risposta:20,unit:"anni fa",curiosita:"Facebook fu fondato da Mark Zuckerberg nel 2004 al dormitorio di Harvard — 20 anni fa. Oggi Meta (Facebook, Instagram, WhatsApp) ha circa 3 miliardi di utenti attivi mensili."},
 {q:"Quante stazioni ci sono nella metropolitana di New York?",min:0,max:500,risposta:472,unit:"stazioni",curiosita:"La metro di New York ha 472 stazioni — la rete con più stazioni al mondo. Aperta nel 1904, ha 27 linee. Funziona 24 ore su 24, 365 giorni l'anno — una delle poche metro al mondo a non chiudere mai."},
 {q:"Quanti anni fa è morto Steve Jobs?",min:0,max:50,risposta:13,unit:"anni fa",curiosita:"Steve Jobs morì il 5 ottobre 2011 — circa 13 anni fa. Aveva 56 anni. Co-fondò Apple nel 1976, fu licenziato nel 1985 e tornò nel 1997 salvando l'azienda sull'orlo del fallimento. Poi lanciò iPod, iPhone e iPad."},
 {q:"Quante parole ha il libro Guinness dei primati ogni anno?",min:0,max:1000000,risposta:300000,unit:"parole",curiosita:"Il Guinness dei Primati contiene circa 300.000 parole per edizione. Fu creato nel 1955 da Norris McWhirter per risolvere le dispute nei pub britannici su chi detenesse i record. È il libro non di fede più venduto al mondo."},
 {q:"Quanti anni fa fu inventato il vaccino contro il vaiolo?",min:0,max:300,risposta:228,unit:"anni fa",curiosita:"Edward Jenner inventò il vaccino nel 1796. Osservò che le mucinatrici che avevano contratto il vaiolo bovino non prendevano quello umano. Il vaiolo fu eradicato nel 1980 — prima malattia eliminata nella storia."},
 {q:"Quanti km è lungo il percorso del Giro d'Italia?",min:0,max:5000,risposta:3500,unit:"km",curiosita:"Il Giro d'Italia è lungo circa 3.300-3.500 km in 21 tappe. Si svolge ogni maggio. Fu fondato nel 1909 dal giornale La Gazzetta dello Sport. La maglia rosa (colore del giornale) distingue il leader."},
 {q:"Quante ore ci vogliono per cuocere un brasato?",min:0,max:10,risposta:3,unit:"ore",curiosita:"Un buon brasato richiede 3-4 ore di cottura lenta. Le carni dure diventano tenere grazie alla lunga cottura che scioglie il collagene. Il vino usato per la cottura deve essere buono quanto quello da bere."},
 {q:"Quanti anni fa è avvenuta l'eruzione del Vesuvio che distrusse Pompei?",min:0,max:2100,risposta:1945,unit:"anni fa",curiosita:"Il Vesuvio eruttò il 24 agosto del 79 d.C. — circa 1.945 anni fa — seppellendo Pompei sotto 6 metri di cenere in 18 ore. Gli scavi iniziati nel 1748 hanno portato alla luce una città perfettamente conservata."},
 {q:"Quanti anni ha la Muraglia di Adriano in Inghilterra?",min:0,max:2000,risposta:1900,unit:"anni",curiosita:"Il Vallo di Adriano fu costruito nel 122 d.C. — circa 1.900 anni fa. Lungo 117 km, attraversava l'Inghilterra da est a ovest per separare la Britannia romana dai Pitti scozzesi. È patrimonio UNESCO."},
 {q:"Quante formazioni geologiche ha il Grand Canyon?",min:0,max:50,risposta:40,unit:"strati geologici",curiosita:"Il Grand Canyon ha circa 40 strati geologici visibili che coprono 2 miliardi di anni di storia della Terra. È profondo fino a 1.800 metri, largo 29 km e lungo 446 km. Fu scavato dal fiume Colorado."},
 {q:"Quanti anni fa fu costruita la Prima Ferrovia Italiana (Napoli-Portici)?",min:0,max:250,risposta:187,unit:"anni fa",curiosita:"La prima ferrovia italiana fu inaugurata il 3 ottobre 1839 tra Napoli e Portici — 187 anni fa. Era lunga solo 7,5 km. Re Ferdinando II di Borbone fu tra i primi passeggeri. Il biglietto costava 30 centesimi."},
 {q:"Quante persone abitano a Parigi?",min:0,max:20000000,risposta:2161000,unit:"abitanti (comune)",curiosita:"Il comune di Parigi ha circa 2,16 milioni di abitanti. Con la grande area metropolitana sale a 12 milioni. È la terza città europea dopo Istanbul e Mosca. Ospita 12 milioni di turisti all'anno."},
 {q:"Quanti anni ci volle all'Unione Europea ad espandersi da 6 a 27 membri?",min:0,max:100,risposta:65,unit:"anni",curiosita:"La CEE nacque nel 1957 con 6 paesi. L'UE ha raggiunto 28 con la Brexit e ora è tornata a 27 — ci sono voluti circa 65 anni. Ogni allargamento ha richiesto decenni di trattative e riforme istituzionali."},
 {q:"Quante lune ha Plutone?",min:0,max:10,risposta:5,unit:"lune",curiosita:"Plutone ha 5 lune: Caronte, Nix, Idra, Cerbero e Stige. Caronte è così grande (1.212 km) rispetto a Plutone (2.377 km) che alcuni astronomi li considerano un sistema doppio. Plutone fu scoperto nel 1930."},
 {q:"Quanti anni fa fu stampata la prima banconota al mondo?",min:0,max:1500,risposta:1000,unit:"anni fa circa",curiosita:"Le prime banconote furono usate in Cina durante la dinastia Tang (VII-X sec. d.C.) — circa 1.000-1.300 anni fa. In Europa arrivarono solo nel XVII secolo tramite i banchieri olandesi e svedesi."},
 {q:"Quante ore impiegò il bombardamento di Pearl Harbor?",min:0,max:24,risposta:2,unit:"ore",curiosita:"L'attacco giapponese a Pearl Harbor del 7 dicembre 1941 durò circa 110 minuti in due ondate. Affondò 4 corazzate e uccise 2.403 americani. Spinse gli USA ad entrare nella Seconda Guerra Mondiale."},
 {q:"Quanti kg di pesce mangia mediamente un italiano all'anno?",min:0,max:50,risposta:28,unit:"kg",curiosita:"Gli italiani consumano circa 28 kg di pesce pro capite all'anno — tra i più alti d'Europa. Il pesce più consumato è il merluzzo (baccalà), poi tonno, salmone e gamberi."},
 {q:"Quante lingue parlano i cittadini del Canton Ticino?",min:0,max:10,risposta:3,unit:"lingue principali",curiosita:"In Ticino si parlano principalmente italiano, tedesco e, per una piccola minoranza, romancio. È l'unico cantone svizzero a maggioranza italiana. Condivide confini con Lombardia e Piemonte."},
 {q:"Quanti anni ha la Coca-Cola?",min:0,max:200,risposta:138,unit:"anni",curiosita:"La Coca-Cola fu inventata nel 1886 da John Pemberton — circa 138 anni fa. La ricetta originale conteneva estratto di foglie di coca (oggi decocainizzate). Viene venduta in 200 paesi — più dell'ONU."},
 {q:"Quanti km è lunga la Via Francigena?",min:0,max:5000,risposta:1800,unit:"km",curiosita:"La Via Francigena è lunga circa 1.800 km da Canterbury a Roma. Era il principale pellegrinaggio medievale verso Roma e poi Gerusalemme. Oggi è percorsa a piedi da migliaia di pellegrini ogni anno."},
 {q:"Quanti anni ci volle all'Italia a scrivere la Costituzione?",min:0,max:10,risposta:2,unit:"anni",curiosita:"La Costituzione Italiana fu scritta dall'Assemblea Costituente dal giugno 1946 al dicembre 1947 — circa 18 mesi. Entrò in vigore il 1° gennaio 1948. È composta da 139 articoli e una serie di disposizioni transitorie."},
 {q:"Quante calorie brucia una persona che scala una montagna di 1000 m?",min:0,max:3000,risposta:500,unit:"kcal",curiosita:"Scalare 1.000 metri di dislivello brucia circa 400-700 kcal per una persona media. L'altitudine riduce l'appetito ma aumenta il consumo energetico. Gli alpinisti sull'Everest possono perdere 10-15 kg in una spedizione."},
 {q:"Quante ore al giorno usa internet in media un adolescente?",min:0,max:24,risposta:9,unit:"ore",curiosita:"Gli adolescenti usano internet in media 8-10 ore al giorno tra studio, social, gaming e streaming. L'OMS raccomanda di non superare le 2 ore di tempo di schermo passivo per i minori."},
 {q:"Quanti anni fa nacque Napoleone Bonaparte?",min:0,max:300,risposta:255,unit:"anni fa",curiosita:"Napoleone nacque il 15 agosto 1769 ad Ajaccio in Corsica — circa 255 anni fa. Morì nel 1821 a Sant'Elena. Riformò il diritto (Codice Napoleonico), l'istruzione e l'amministrazione di tutta l'Europa."},
 {q:"Quanti miliardi di dispositivi sono connessi a internet nel mondo?",min:0,max:100,risposta:15,unit:"miliardi",curiosita:"Circa 15 miliardi di dispositivi sono connessi a internet (IoT incluso). Entro il 2030 si prevede arrivino a 30 miliardi. Il 99% del traffico dati intercontinentale passa per cavi sottomarini in fibra ottica."},
 {q:"Quante ore impiega una lumaca di mare per diventare adulta?",min:0,max:100000,risposta:8760,unit:"ore (circa 1 anno)",curiosita:"Una lumaca di mare (nudibranchi) raggiunge la maturità sessuale in circa 1 anno. Esistono 3.000 specie di nudibranchi — creature marine straordinariamente colorate. Alcune sono bioluminescenti."},
 {q:"Quanti anni fa nacque la prima moneta coniata?",min:0,max:3000,risposta:2700,unit:"anni fa",curiosita:"Le prime monete furono coniate in Lidia (attuale Turchia) circa 700 a.C. — 2.700 anni fa. Erano in elettro (lega naturale d'oro e argento). Prima si usava il baratto o lingotti di metallo pesati."},
 {q:"Quante varietà di mele esistono nel mondo?",min:0,max:10000,risposta:7500,unit:"varietà",curiosita:"Esistono circa 7.500 varietà di mele nel mondo. La Golden Delicious è la più coltivata in Italia. Le mele impiegano 4-10 anni per produrre i primi frutti. Sono originarie dell'Asia centrale."},
 {q:"Quanti anni fa nacque la prima civiltà (Sumeria)?",min:0,max:10000,risposta:6000,unit:"anni fa",curiosita:"La civiltà sumerica nacque in Mesopotamia circa 4.000-6.000 anni fa. Inventarono la scrittura cuneiforme, la ruota, la birra, la legge scritta e il primo codice di leggi: il Codice di Ur-Nammu (2100 a.C.)."},
 {q:"Quanti km è lunga la muraglia del Giappone medievale?",min:0,max:1000,risposta:7,unit:"km (la maggiore in Giappone)",curiosita:"Diversamente dalla Cina, il Giappone ha poche grandi muraglie. Il castello di Osaka ha circa 7 km di mura. Il Giappone si difendeva con castelli e la sua posizione insulare — attaccato con successo solo nel 1945."},
 {q:"Quanti anni fa fu inventato il motore a vapore moderno?",min:0,max:400,risposta:255,unit:"anni fa",curiosita:"James Watt brevettò il motore a vapore migliorato nel 1769 — circa 255 anni fa. Il motore a vapore aveva già 60 anni, ma Watt lo rese 4 volte più efficiente. Diede inizio alla Rivoluzione Industriale."},
 {q:"Quante specie di pipistrelli esistono?",min:0,max:2000,risposta:1400,unit:"specie",curiosita:"Esistono circa 1.400 specie di pipistrelli — un quinto di tutte le specie di mammiferi. Sono gli unici mammiferi capaci di volo sostenuto. Molti si orientano con l'ecolocalizzazione (ultrasuoni)."},
 {q:"Quanti anni fa fu inventata la fotografia?",min:0,max:300,risposta:200,unit:"anni fa circa",curiosita:"La prima fotografia permanente fu realizzata da Nicéphore Niépce nel 1826 — circa 198 anni fa. Richiedeva 8 ore di esposizione. Daguerre perfezionò il processo nel 1839 con esposizioni di pochi minuti."},
 {q:"Quante ore impiega la luce a raggiungere Plutone dal Sole?",min:0,max:24,risposta:5,unit:"ore",curiosita:"La luce impiega circa 5-7 ore per raggiungere Plutone dal Sole. A 5,9 miliardi di km dal Sole, Plutone è così lontano che dall'estate all'inverno dura 124 anni terrestri — il suo anno orbitale."},
 {q:"Quanti km è la distanza tra Napoli e Palermo in linea retta?",min:0,max:1000,risposta:470,unit:"km",curiosita:"Napoli e Palermo distano circa 470 km in linea retta. Via traghetto sono circa 10 ore di navigazione. Il Ponte sullo Stretto di Messina, discusso da decenni, ridurrebbe il viaggio di ore."},
 {q:"Quanti anni ha la più antica ricetta di cucina scritta?",min:0,max:5000,risposta:4000,unit:"anni",curiosita:"Le più antiche ricette conosciute sono tavolette cuneiformi babilonesi di 4.000 anni fa trovate in Iraq. Includono ricette di brodi, stufati e pane. La birra è menzionata in testi sumerici di 5.000 anni fa."},
 {q:"Quante calorie ha una porzione di tiramisù (100g)?",min:0,max:600,risposta:400,unit:"kcal",curiosita:"Il tiramisù ha circa 350-450 kcal per 100g. Fu inventato negli anni '60 a Treviso (Veneto). Il nome significa 'tira su' per il suo effetto energizzante grazie al caffè. È uno dei dessert italiani più famosi al mondo."},
 {q:"Quanti anni dura una batteria di un'auto elettrica?",min:0,max:30,risposta:10,unit:"anni",curiosita:"Le batterie delle auto elettriche durano in media 8-15 anni o 200.000 km prima di perdere il 20% della capacità. Dopo la vita nel veicolo vengono riusate come accumulo fisso di energia rinnovabile."},
 {q:"Quante persone hanno scalato l'Everest?",min:0,max:20000,risposta:7000,unit:"scalatori",curiosita:"Circa 7.000 persone hanno raggiunto la vetta dell'Everest (con molte doppie). I nepalesi Sherpa detengono il record con ascensioni ripetute — il più scalato è salito 26 volte. Circa 300 persone sono morte nel tentativo."},
 {q:"Quanti anni fa fu inventato il televisore?",min:0,max:200,risposta:100,unit:"anni fa circa",curiosita:"John Logie Baird fece la prima dimostrazione pubblica di televisione nel 1926 — circa 98 anni fa. I televisori a colori arrivarono negli anni '50. Oggi nel mondo ci sono più TV (1,7 miliardi) che famiglie."},
 {q:"Quante km è il perimetro della città di Londra?",min:0,max:1000,risposta:58,unit:"km (Greater London)",curiosita:"La Greater London ha un perimetro di circa 58 km con un diametro di circa 50 km. Ospita 9 milioni di abitanti in 1.572 km². Il 'quadrato miglio' (City of London) è il centro storico: solo 1 km² con 9.000 residenti."},
 {q:"Quanti anni fa nacque il Rinascimento a Firenze?",min:0,max:700,risposta:620,unit:"anni fa circa",curiosita:"Il Rinascimento nacque a Firenze nella prima metà del '400 — circa 600-620 anni fa. I Medici finanziarono artisti come Botticelli, Michelangelo e Leonardo. Firenze era allora la città più ricca d'Europa."},
 {q:"Quanti km è lungo il fiume Tevere?",min:0,max:500,risposta:405,unit:"km",curiosita:"Il Tevere è lungo 405 km — il terzo fiume italiano. Nasce dal Monte Fumaiolo in Romagna. Roma fu fondata sulle sue rive. Nel Medioevo era navigabile fino a Perugia. Oggi è molto inquinato nel tratto romano."},
 {q:"Quante varietà di olio d'oliva DOP/IGP esistono in Italia?",min:0,max:50,risposta:42,unit:"denominazioni",curiosita:"L'Italia ha 42 denominazioni DOP/IGP per l'olio d'oliva — più di qualsiasi altro paese. Puglia, Calabria e Sicilia producono il 70% dell'olio italiano. L'Italia è il secondo produttore mondiale dopo la Spagna."},
 {q:"Quanti anni ci vollero per costruire il Canale di Panama?",min:0,max:50,risposta:10,unit:"anni",curiosita:"Il Canale di Panama fu costruito dagli USA in 10 anni (1904-1914). I Francesi ci avevano provato prima ma fallirono per la malaria e la febbre gialla. Accorcia il viaggio dall'Atlantico al Pacifico di 15.000 km."},
 {q:"Quanti anni fa fu fondata l'università di Bologna?",min:0,max:1000,risposta:936,unit:"anni fa",curiosita:"L'Università di Bologna fu fondata nel 1088 — circa 936 anni fa. È la più antica università del mondo occidentale. Dante, Petrarca, Copernico e Torquato Tasso studiarono nelle università italiane medievali."},
 {q:"Quanti grammi di proteine ha 100g di lenticchie cotte?",min:0,max:30,risposta:9,unit:"grammi",curiosita:"Le lenticchie cotte contengono circa 9g di proteine per 100g — tra i legumi più proteici. Sono anche ricche di ferro, fibre e acido folico. Coltivate da 10.000 anni, sono uno degli alimenti più antichi dell'umanità."},
 {q:"Quanti anni fa fu inventato l'ascensore?",min:0,max:200,risposta:170,unit:"anni fa circa",curiosita:"Elisha Otis brevettò l'ascensore sicuro nel 1854 — circa 170 anni fa. Dimostrò la sicurezza tagliando la fune di sospensione in pubblico — il meccanismo di sicurezza bloccò la caduta. Rese possibili i grattacieli."},
 {q:"Quante specie di tartarughe esistono?",min:0,max:400,risposta:350,unit:"specie",curiosita:"Esistono circa 350 specie di tartarughe. Alcune come la tartaruga gigante delle Galapagos vivono oltre 190 anni. Sono tra i rettili più antichi: simili a quelle attuali già 220 milioni di anni fa."},
 {q:"Quanti anni fa fu inventata la carta?",min:0,max:3000,risposta:2100,unit:"anni fa",curiosita:"La carta fu inventata in Cina circa 105 d.C. da Cai Lun, un funzionario imperiale — circa 1.900 anni fa. Ma già nel 200 a.C. si usava carta di bambu e seta. In Europa arrivò attraverso gli Arabi nell'VIII secolo."},
 {q:"Quante ore al giorno uno studente universitario studia in media?",min:0,max:20,risposta:4,unit:"ore",curiosita:"Uno studente universitario studia in media 3-5 ore al giorno fuori dalle lezioni. Ricerche mostrano che le sessioni di studio efficace non dovrebbero superare i 50 minuti consecutivi per mantenere la concentrazione."},
 {q:"Quanti anni fa fu fondata Roma?",min:0,max:3000,risposta:2777,unit:"anni fa",curiosita:"Secondo la tradizione, Roma fu fondata il 21 aprile del 753 a.C. da Romolo — circa 2.777 anni fa. La vera fondazione fu probabilmente un processo graduale tra l'800 e il 700 a.C. con l'unificazione di villaggi."},
 {q:"Quante specie di coralli esistono?",min:0,max:5000,risposta:2500,unit:"specie",curiosita:"Esistono circa 2.500 specie di coralli. La Grande Barriera Corallina australiana è il più grande organismo vivente del mondo: 2.300 km, visibile dallo spazio. Il 50% dei coralli del mondo è andato perduto dal 1950."},
 {q:"Quante parole nuove vengono aggiunte all'Oxford English Dictionary ogni anno?",min:0,max:5000,risposta:1000,unit:"parole",curiosita:"L'Oxford English Dictionary aggiunge circa 1.000-2.000 nuove parole ogni anno. Negli ultimi decenni molte vengono da internet e tecnologia. 'Selfie', 'emoji' e 'podcast' sono tra le aggiunte recenti."},
 {q:"Quanti anni ci volle a costruire il Castello di Versailles?",min:0,max:200,risposta:50,unit:"anni",curiosita:"Versailles fu costruita tra il 1661 e il 1710 — circa 50 anni. Ospitava 20.000 persone tra nobili, servitù e guardie. Luigi XIV vi si trasferì nel 1682. Oggi è visitata da 10 milioni di turisti l'anno."},
 {q:"Quanti anni fa nacque il basket?",min:0,max:200,risposta:133,unit:"anni fa",curiosita:"James Naismith inventò il basket nel dicembre 1891 a Springfield (USA) — circa 133 anni fa. Le prime 'canestri' erano cestini di pesche appiccati al muro. Oggi è il terzo sport più seguito al mondo."},
 {q:"Quante parole ha mediamente un romanzo bestseller?",min:0,max:200000,risposta:90000,unit:"parole",curiosita:"Un romanzo bestseller medio ha circa 70.000-100.000 parole. Harry Potter e la pietra filosofale ne ha 77.325. Tolstoj's Guerra e Pace ne ha 580.000 — uno dei romanzi più lunghi mai scritti."},
 {q:"Quanti anni fa morì William Shakespeare?",min:0,max:600,risposta:408,unit:"anni fa",curiosita:"Shakespeare morì il 23 aprile 1616 — circa 408 anni fa. Curiosamente stesso giorno di Miguel de Cervantes (autore di Don Chisciotte). Scrisse 37 opere teatrali, 154 sonetti e inventò 1.700 parole inglesi."},
 {q:"Quante volte al secondo una zanzara batte le ali?",min:0,max:1000,risposta:500,unit:"volte al secondo",curiosita:"Le zanzare battono le ali 400-600 volte al secondo producendo il caratteristico ronzio. I maschi e le femmine emettono frequenze diverse — si trovano per accoppiarsi armonizzando i suoni."},
 {q:"Quanti anni fa fu inventato l'aeroplano?",min:0,max:200,risposta:121,unit:"anni fa",curiosita:"I fratelli Wright effettuarono il primo volo a motore il 17 dicembre 1903 — circa 121 anni fa. Il volo durò 12 secondi e percorse 36 metri. Meno di 70 anni dopo si era già sulla Luna."},
 {q:"Quanti kg di pasta mangia un italiano in media all'anno?",min:0,max:100,risposta:23,unit:"kg",curiosita:"Gli italiani mangiano circa 23 kg di pasta pro capite all'anno — i maggiori consumatori al mondo. Seguono Tunisia (17 kg) e Venezuela (12 kg). L'Italia esporta pasta in 190 paesi."},
 {q:"Quanti anni fa nacque il jazz?",min:0,max:200,risposta:130,unit:"anni fa circa",curiosita:"Il jazz nacque a New Orleans intorno al 1895-1900 dalle tradizioni musicali africane, europee e caraibiche. Si diffuse rapidamente negli anni '20 ('Anni ruggenti'). Miles Davis, Coltrane e Armstrong ne sono i grandi maestri."},
 {q:"Quante ore impiega un adulto a leggere 100 pagine?",min:0,max:20,risposta:3,unit:"ore",curiosita:"Un adulto legge in media 200-250 parole al minuto — 100 pagine impiegano circa 3-4 ore. I lettori veloci arrivano a 500-700 parole/minuto. Il record mondiale di lettura veloce è oltre 3.000 parole/minuto."},
 {q:"Quanti anni fa fu inventata la penicillina?",min:0,max:200,risposta:96,unit:"anni fa",curiosita:"Alexander Fleming scoprì la penicillina nel 1928 — circa 96 anni fa. La usò clinicamente solo nel 1942. Ha salvato centinaia di milioni di vite. Fleming disse che fu un caso — come tante scoperte scientifiche."},
 {q:"Quante nazioni ha visitato il Papa Francesco nei suoi viaggi apostolici?",min:0,max:100,risposta:65,unit:"paesi circa",curiosita:"Papa Francesco ha visitato circa 65 paesi nel corso del suo pontificato (dal 2013). È il papa che ha viaggiato di più in termini di luoghi visitati. Ha visitato per primo l'Arabia Saudita nel 2019."},
 {q:"Quanti anni fa fu costruito il Foro Romano?",min:0,max:3000,risposta:2700,unit:"anni fa circa",curiosita:"Il Foro Romano fu il cuore politico e commerciale di Roma per secoli. I principali monumenti risalgono al VI-I sec. a.C. — circa 2.500-2.700 anni fa. Fu abbandonato nel Medioevo e usato come pascolo ('Campo Vaccino')."},
 {q:"Quante ore ci vuole per cucinare un risotto perfetto?",min:0,max:5,risposta:1,unit:"ora circa",curiosita:"Un risotto richiede circa 18-25 minuti di cottura attiva, più il tempo di preparazione. Il segreto è la tostatura del riso e il brodo aggiunto poco a poco. Il riso Carnaroli è il migliore per il risotto."},
 {q:"Quanti anni fa fu costruito l'Acquedotto di Segovia (Spagna)?",min:0,max:2500,risposta:1900,unit:"anni fa circa",curiosita:"L'Acquedotto romano di Segovia fu costruito nel I-II sec. d.C. — circa 1.900 anni fa. È lungo 17 km e ha 163 archi su due livelli. Trasportava acqua per 16 km senza l'uso di malta — solo pietre squadrate."},
 {q:"Quanti km percorre il sole nella galassia in un anno?",min:0,max:1000000000000,risposta:200000000000,unit:"km",curiosita:"Il Sole orbita intorno al centro della Via Lattea a circa 220 km/s percorrendo circa 200 miliardi di km all'anno. Un'orbita completa dura 225-250 milioni di anni — un 'anno galattico' o 'anno cosmico'."},
 {q:"Quante medaglie d'oro ha vinto l'Italia alle Olimpiadi in totale?",min:0,max:500,risposta:250,unit:"ori circa",curiosita:"L'Italia ha vinto circa 250 medaglie d'oro olimpiche (estate + inverno) — tra i paesi con più ori. Le discipline più vittoriose sono scherma, canottaggio, ciclismo e atletica. Federica Pellegrini è l'atleta italiana più decorata."},
 {q:"Quanti anni fa fu costruita la prima ferrovia (Inghilterra)?",min:0,max:300,risposta:200,unit:"anni fa circa",curiosita:"La prima ferrovia pubblica a vapore fu la Stockton and Darlington Railway aperta nel 1825 — circa 199 anni fa. La locomotiva Rocket di Stephenson raggiunse i 48 km/h nel 1829 — scandaloso per l'epoca."},
 {q:"Quante righe di codice ha Windows 10?",min:0,max:200000000,risposta:80000000,unit:"righe di codice",curiosita:"Windows 10 ha circa 80 milioni di righe di codice. Google ha circa 2 miliardi di righe. Un programmatore professionista scrive in media 10-100 righe di codice pulito al giorno."},
 {q:"Quanti anni fa nacque Galileo Galilei?",min:0,max:500,risposta:460,unit:"anni fa",curiosita:"Galileo nacque il 15 febbraio 1564 a Pisa — circa 460 anni fa. Stesso anno di Shakespeare. Fu processato dall'Inquisizione ma non fu mai torturato. Morì nel 1642, lo stesso anno in cui nacque Newton."},
 {q:"Quante specie di lombrichi esistono?",min:0,max:10000,risposta:7000,unit:"specie",curiosita:"Esistono circa 7.000 specie di lombrichi. Darwin li studiò per 40 anni e scrisse un libro su di loro. Un lombrico aereo il suolo in modo che piante crescano meglio. Un ettaro di buon terreno può contenere 1 milione di lombrichi."},
 {q:"Quanti anni fa fu inaugurata la Torre Eiffel?",min:0,max:200,risposta:135,unit:"anni fa",curiosita:"La Torre Eiffel fu inaugurata il 31 marzo 1889 — circa 135 anni fa. Fu costruita in 2 anni, 2 mesi e 5 giorni. Alta 330 metri, fu la struttura più alta del mondo per 41 anni, fino al Chrysler Building di New York."},
 {q:"Quante nazioni sono member dell'ONU?",min:0,max:200,risposta:193,unit:"paesi",curiosita:"L'ONU ha 193 stati membri. Fu fondata il 24 ottobre 1945 dopo la Seconda Guerra Mondiale. Il Vaticano e la Palestina sono osservatori non membri. Nauru, il paese più piccolo con 10.000 abitanti, è un membro."},
 {q:"Quanti anni ci vuole a un diamante per formarsi naturalmente?",min:0,max:4000000000,risposta:1000000000,unit:"anni",curiosita:"I diamanti si formano in 1-3 miliardi di anni a 150 km di profondità a 900-1300°C. Vengono poi portati in superficie dai kimberliti — vulcani profondi. I diamanti sintetici oggi valgono il 90% in meno di quelli naturali."},
 {q:"Quante ore di sonno ha dormito Einstein?",min:0,max:24,risposta:10,unit:"ore",curiosita:"Einstein dormiva circa 10 ore per notte e faceva regolarmente pisolini durante il giorno. Credeva che il sonno fosse fondamentale per la creatività. Darwin, Churchill e Tesla erano anch'essi noti per le loro abitudini di sonno."},
 {q:"Quanti anni fa fu inventato l'automobil?",min:0,max:200,risposta:138,unit:"anni fa",curiosita:"Karl Benz brevettò il primo automobile (Benz Patent-Motorwagen) nel 1886 — circa 138 anni fa. Raggiungeva i 16 km/h con un motore a benzina di 0,9 HP. Sua moglie Bertha fu la prima a percorrere 106 km in automobile."},
 {q:"Quante specie di serpenti sono velenosi?",min:0,max:1000,risposta:600,unit:"specie",curiosita:"Su circa 3.700 specie di serpenti, circa 600 sono velenose e solo 200 pericolose per l'uomo. Il serpente più velenoso è il serpente taipan australiano — il suo veleno potrebbe uccidere 100 adulti. I serpenti muoiono 100 volte di più per l'uomo che viceversa."},
 {q:"Quante calorie ha 100g di Grana Padano?",min:0,max:600,risposta:384,unit:"kcal",curiosita:"Il Grana Padano ha 384 kcal per 100g — un alimento denso di nutrienti ma calorico. È ricco di calcio, proteine e aminoacidi essenziali. La crosta non è edibile ma può essere usata per insaporire i minestroni."},
 {q:"Quanti anni fa fu inventato internet?",min:0,max:100,risposta:55,unit:"anni fa circa",curiosita:"ARPANET, il precursore di internet, fu lanciato nel 1969 — circa 55 anni fa. Il World Wide Web di Tim Berners-Lee arrivò nel 1991. Il primo sito web è ancora online: info.cern.ch. L'email è più vecchia del web."},
 {q:"Quanti km è lungo il confine tra Cina e Russia?",min:0,max:5000,risposta:4209,unit:"km",curiosita:"Il confine sino-russo è lungo 4.209 km — uno dei più lunghi del mondo. Fu teatro di scontri armati nel 1969. Oggi i due paesi sono alleati strategici ma hanno visioni diverse sull'Asia centrale e la Siberia."},
 {q:"Quante specie di funghi esistono?",min:0,max:5000000,risposta:150000,unit:"specie catalogate",curiosita:"Sono state catalogate circa 150.000 specie di funghi ma si stima ne esistano 2-6 milioni. Il fungo più grande del mondo è un Armillaria in Oregon: occupa 9 km² ed è vivo da 8.000 anni."},
 {q:"Quanti anni fa fu costruita la prima piramide egizia?",min:0,max:5000,risposta:4700,unit:"anni fa",curiosita:"La prima piramide egizia fu la Piramide a Gradoni di Gioser a Saqqara, costruita circa 2.700 a.C. — 4.700 anni fa. La Grande Piramide di Cheope fu completata nel 2560 a.C. e fu la struttura più alta del mondo per 3.800 anni."},
 {q:"Quanti anni ci vuole a un salmone per tornare al luogo di nascita?",min:0,max:10,risposta:4,unit:"anni",curiosita:"I salmoni nascono nei fiumi d'acqua dolce, migrano nell'oceano e dopo 2-6 anni tornano esattamente al loro fiume di nascita per riprodursi e morire. Navigano grazie al campo magnetico terrestre e all'olfatto."},
 {q:"Quante canzoni ha scritto Lucio Battisti?",min:0,max:500,risposta:200,unit:"canzoni circa",curiosita:"Lucio Battisti ha inciso circa 200 canzoni in carriera (1966-1994). Con il paroliere Mogol creò capolavori della musica italiana. Negli ultimi anni rifiutò interviste e apparizioni televisive, diventando un mistero."},
 {q:"Quanti anni fa fu costruito il Colosseo?",min:0,max:2500,risposta:1944,unit:"anni fa",curiosita:"Il Colosseo fu completato nel 80 d.C. — circa 1.944 anni fa. Impiegò 10 anni di costruzione e 100.000 schiavi secondo alcune stime. Poteva allagarsi per ospitare battaglie navali (naumachie)."},
 {q:"Quante calorie brucia una giornata di sci?",min:0,max:3000,risposta:1500,unit:"kcal",curiosita:"Una giornata di sci attivo brucia circa 1.000-2.000 kcal. Il freddo aumenta il metabolismo basale. Lo sci di fondo è ancora più dispendioso: fino a 800-1.000 kcal/ora nei percorsi più impegnativi."},
 {q:"Quanti anni ha Ötzi, la mummia dei ghiacci?",min:0,max:6000,risposta:5300,unit:"anni",curiosita:"Ötzi, trovato nel 1991 sulle Alpi tra Italia e Austria, aveva circa 5.300 anni. Era un uomo di 46 anni, morto ucciso da una freccia. Indossava abiti sofisticati e portava 61 tatuaggi terapeutici."},
 {q:"Quanti kg di CO2 produce mediamente un italiano all'anno?",min:0,max:30000,risposta:6000,unit:"kg",curiosita:"L'italiano medio produce circa 6 tonnellate di CO2 l'anno — sopra la media mondiale (4,7 t) ma sotto quella USA (15 t). I voli aerei pesano molto: un volo Roma-New York e ritorno produce 1,6 tonnellate."},
 {q:"Quante ore ci vuole per andare da Milano a Barcellona in treno?",min:0,max:24,risposta:11,unit:"ore",curiosita:"Il treno da Milano a Barcellona impiega circa 11 ore con cambio a Lione. In aereo sono 2 ore. Ma considerando check-in, trasferimenti e attese, il treno è competitivo per city center."},
 {q:"Quanti anni fa nacque il movimento dei diritti civili negli USA?",min:0,max:200,risposta:70,unit:"anni fa circa",curiosita:"Il movimento dei diritti civili americano nacque negli anni '50. Rosa Parks rifiutò di cedere il posto sul bus nel 1955. Il discorso 'I Have a Dream' di Martin Luther King fu pronunciato nel 1963. Il Civil Rights Act fu del 1964."},
 {q:"Quante varianti del virus dell'influenza ci sono ogni anno?",min:0,max:1000,risposta:3,unit:"varianti nel vaccino stagionale",curiosita:"Il vaccino antiinfluenzale annuale copre 3-4 varianti del virus, scelte ogni anno in base alle previsioni dell'OMS. Il virus muta continuamente — per questo il vaccino va rifatto ogni anno."},
 {q:"Quanti km quadrati ha Monaco (principato)?",min:0,max:10,risposta:2,unit:"km²",curiosita:"Monaco misura 2,02 km² — il secondo stato più piccolo del mondo dopo il Vaticano. Ha la densità di popolazione più alta al mondo: 19.000 ab/km². Nonostante le dimensioni ha la sua squadra di F1 e il Gran Premio."},
 {q:"Quante parole conosce in media un madrelingua italiano adulto?",min:0,max:100000,risposta:40000,unit:"parole",curiosita:"Un adulto italiano conosce passivamente circa 40.000-60.000 parole ma ne usa attivamente solo 5.000-10.000. Un bambino di 6 anni già conosce circa 10.000 parole. La lettura è il modo più efficace per aumentare il vocabolario."},
 {q:"Quanti anni fa la Terra aveva le giornate di 22 ore?",min:0,max:2000000000,risposta:1400000000,unit:"anni fa",curiosita:"Circa 1,4 miliardi di anni fa la Terra ruotava più velocemente e il giorno durava solo 18-22 ore. La rotazione rallenta gradualmente per la forza di marea della Luna. Tra un miliardo di anni il giorno terrestre durerà 25 ore."},
 {q:"Quanti anni fa fu costruito Stonehenge?",min:0,max:10000,risposta:5000,unit:"anni fa",curiosita:"Stonehenge fu costruito in varie fasi tra il 3000 e il 1500 a.C. — circa 5.000-3.500 anni fa. Le pietre più grandi pesano 50 tonnellate e furono trasportate dal Galles per 250 km. La sua funzione rimane misteriosa."},
 {q:"Quanti km è lunga la Costiera dei Cieli in Campania?",min:0,max:200,risposta:80,unit:"km circa",curiosita:"La Costiera Cilentana ('Costiera dei Cieli') si estende per circa 80 km nel Cilento. Insieme alla Costiera Amalfitana è tra le coste più belle d'Italia. Il Parco Nazionale del Cilento è patrimonio UNESCO."},
 {q:"Quante specie di papere esistono?",min:0,max:200,risposta:120,unit:"specie",curiosita:"Esistono circa 120 specie di anatre (incluse papere, oche e cigni nella famiglia Anatidae). Il germano reale è il più comune. Le papere sono tra i pochi animali che riescono a volare, nuotare e camminare."},
 {q:"Quanti anni fa fu inventata la lampadina (Edison)?",min:0,max:200,risposta:145,unit:"anni fa",curiosita:"Edison inventò la lampadina a incandescenza pratica nel 1879 — circa 145 anni fa. In realtà molti inventori ci lavorarono contemporaneamente. Edison la rese commerciale grazie alla rete di distribuzione elettrica."},
 {q:"Quanti anni ha la democrazia (dalla Grecia antica)?",min:0,max:3000,risposta:2500,unit:"anni",curiosita:"La democrazia ateniese fu fondata da Clistene nel 508 a.C. — circa 2.500 anni fa. Solo i cittadini maschi adulti votavano (circa il 10-20% della popolazione). Le donne, gli schiavi e gli stranieri erano esclusi."},
 {q:"Quante ore al giorno passa alla scrivania un lavoratore d'ufficio?",min:0,max:20,risposta:8,unit:"ore",curiosita:"I lavoratori d'ufficio trascorrono in media 7-9 ore seduti al lavoro. Studi mostrano che stare seduti troppo a lungo aumenta il rischio cardiovascolare. Anche fare 5 minuti di cammino ogni ora riduce significativamente i rischi."},
 {q:"Quanti anni fa nacque il cinema?",min:0,max:200,risposta:129,unit:"anni fa",curiosita:"I fratelli Lumière proiettarono il primo film al pubblico il 28 dicembre 1895 a Parigi — circa 129 anni fa. Il primo film durava 50 secondi e mostrava operai uscire da una fabbrica. Al Jolson incise la prima colonna sonora nel 1927."},
 {q:"Quante stelle ha il cielo visto a occhio nudo?",min:0,max:10000,risposta:5000,unit:"stelle circa",curiosita:"In condizioni perfette, senza inquinamento luminoso, si vedono circa 4.500-5.000 stelle. In una città se ne vedono 200-400. L'inquinamento luminoso copre il cielo stellato al 99% della popolazione europea e statunitense."},
 {q:"Quanti anni fa nacque il movimento femminista?",min:0,max:300,risposta:180,unit:"anni fa circa",curiosita:"Il femminismo di prima ondata nacque nel 1848 con la Convenzione di Seneca Falls negli USA — circa 176 anni fa. Il voto alle donne fu conquistato in Australia nel 1902, in Italia solo nel 1945."},
 {q:"Quante ore ci vuole per cucinare un ragù bolognese?",min:0,max:10,risposta:4,unit:"ore",curiosita:"Un ragù bolognese autentico cuoce a fuoco lento per almeno 3-4 ore. La cottura lenta permette alle proteine della carne di sfaldarsi e al vino di evaporare. La ricetta depositata all'Accademia di Cucina di Bologna non prevede l'aglio."},
 {q:"Quanti anni fa nacque Leonardo da Vinci?",min:0,max:600,risposta:572,unit:"anni fa",curiosita:"Leonardo nacque il 15 aprile 1452 a Vinci (Toscana) — circa 572 anni fa. Era figlio illegittimo di un notaio e di una contadina. Non finì mai l'università ma divenne il più grande genio universale della storia."},
 {q:"Quanti batteri vivono nel corpo umano?",min:0,max:100000000000000,risposta:38000000000000,unit:"batteri",curiosita:"Il corpo umano ospita circa 38 trilioni di batteri — quasi quante le cellule del corpo stesso. La maggior parte vive nell'intestino. Sono fondamentali per la digestione, il sistema immunitario e persino l'umore."},
 {q:"Quanti anni fa fu costruita la prima piramide Maya?",min:0,max:3000,risposta:2300,unit:"anni fa circa",curiosita:"Le piramidi Maya più antiche risalgono al 300 a.C. circa. La civiltà Maya raggiunse l'apice tra il 250 e il 900 d.C. Avevano un calendario preciso, la scrittura geroglifica e svilupparono il concetto matematico dello zero."},
 {q:"Quante km è lunga la Dolomiti Superski (piste totali)?",min:0,max:2000,risposta:1200,unit:"km",curiosita:"Il comprensorio Dolomiti Superski ha circa 1.200 km di piste — il più grande al mondo. Collega 12 valli e utilizza un unico skipass. Le Dolomiti sono patrimonio UNESCO e tra le montagne più belle del mondo."},
 {q:"Quanti anni fa è stato costruito il Ponte di Rialto a Venezia?",min:0,max:500,risposta:434,unit:"anni fa",curiosita:"Il Ponte di Rialto fu completato nel 1591 — circa 433 anni fa. Disegnato da Antonio da Ponte, fu controverso all'epoca — molti preferivano un progetto di Michelangelo o Palladio. Oggi è tra i ponti più fotografati al mondo."},
 {q:"Quanti kg pesa un panettone artigianale?",min:0,max:20,risposta:1,unit:"kg",curiosita:"Il panettone tradizionale pesa circa 1 kg. La sua altezza dev'essere almeno il 50% del diametro. Il termine protetto 'Panettone di Milano' prevede almeno 3 giorni di lievitazione naturale. Fu inventato a Milano nel XV secolo."},
 {q:"Quante ore di sole ha in media Palermo all'anno?",min:0,max:5000,risposta:2800,unit:"ore di sole",curiosita:"Palermo ha circa 2.800 ore di sole l'anno — tra le città italiane più soleggiate. Londra ne ha 1.600, Milano 2.000. Le città più soleggiate d'Europa sono in Spagna meridionale con oltre 3.000 ore annue."},
 {q:"Quante varietà di pomodori esistono?",min:0,max:20000,risposta:10000,unit:"varietà",curiosita:"Esistono circa 10.000 varietà di pomodori. Il pomodoro San Marzano campano DOP è il più pregiato per la salsa. Il pomodoro fu portato in Europa dalle Americhe nel '500 e per secoli fu considerato ornamentale e velenoso."},
 {q:"Quanti anni fa nacque il Calcio Storico Fiorentino?",min:0,max:600,risposta:490,unit:"anni fa circa",curiosita:"Il Calcio Storico Fiorentino risale al XVI secolo (1530) — circa 490 anni fa. Si gioca in Piazza Santa Croce ogni giugno. È considerato il progenitore del calcio moderno e del rugby. Gli 'azzurri' della Sante Croce sono famosi."},
 {q:"Quante stelle ha lo Zodiaco?",min:0,max:200,risposta:12,unit:"costellazioni",curiosita:"Lo Zodiaco è diviso in 12 costellazioni che il Sole attraversa nel corso dell'anno. Fu sviluppato dagli antichi Babilonesi 3.000 anni fa. In astronomia moderna si conta anche Ofiuco — la 13a costellazione zodiacale."},
 {q:"Quanti anni fa nacque Giovanni da Palestrina, il maestro della musica sacra?",min:0,max:600,risposta:500,unit:"anni fa circa",curiosita:"Giovanni Pierluigi da Palestrina nacque intorno al 1525 — circa 500 anni fa. È il massimo compositore della polifonia sacra rinascimentale. Il Concilio di Trento lo ascoltò per decidere le regole della musica in chiesa."},
 {q:"Quanti anni ci volle a costruire la Sagrada Familia?",min:0,max:200,risposta:142,unit:"anni finora",curiosita:"La Sagrada Família di Barcellona è in costruzione dal 1882 — 142 anni fa. Gaudí la guidò dal 1883 fino alla sua morte nel 1926. Si prevede il completamento per il 2026, centenario della morte di Gaudí."},
 {q:"Quanti anni fa è nata la chirurgia moderna?",min:0,max:300,risposta:200,unit:"anni fa circa",curiosita:"La chirurgia moderna nasce con l'introduzione dell'anestesia (1846) e dell'antisepsi (Lister, 1867). Prima i pazienti morivano spesso di infezioni post-operatorie. Florence Nightingale rivoluzionò la cura del paziente."},
 {q:"Quanti km è lungo il canale di Panama?",min:0,max:200,risposta:82,unit:"km",curiosita:"Il Canale di Panama è lungo 82 km e collega Atlantico e Pacifico. Aperto nel 1914, fu ampliato nel 2016. Circa 13.000-14.000 navi lo attraversano ogni anno riducendo i percorsi oceanici di migliaia di km."},
 {q:"Quante canzoni esistono nel repertorio del Festival di Sanremo?",min:0,max:5000,risposta:3000,unit:"canzoni circa",curiosita:"Il Festival di Sanremo ha prodotto circa 3.000 canzoni dalla sua prima edizione nel 1951. È la kermesse canora più longeva al mondo. 'Volare' di Modugno (1958) fu la prima canzone italiana a entrare nella Billboard americana."},
 {q:"Quanti anni fa fu aperto il Canale di Suez?",min:0,max:200,risposta:155,unit:"anni fa",curiosita:"Il Canale di Suez fu aperto il 17 novembre 1869 — circa 155 anni fa. Fu costruito in 10 anni da ingegneri francesi. Nasser lo nazionalizzò nel 1956 provocando una crisi internazionale. Genera circa 6 miliardi di dollari l'anno."},
 {q:"Quante opere scrisse Giacomo Puccini?",min:0,max:30,risposta:12,unit:"opere liriche",curiosita:"Puccini scrisse 12 opere, tra cui Tosca, Bohème, Madama Butterfly e Turandot (lasciata incompiuta). È il compositore italiano più rappresentato al mondo dopo Verdi. La Bohème del 1896 è l'opera lirica più eseguita."},
 {q:"Quanti anni fa nacque Raffaello Sanzio?",min:0,max:600,risposta:541,unit:"anni fa",curiosita:"Raffaello Sanzio nacque il 6 aprile 1483 a Urbino — circa 541 anni fa. Morì giovane, a 37 anni, dopo aver dipinto capolavori come La Scuola di Atene, le Stanze Vaticane e innumerevoli Madonne."},
 {q:"Quanti km è lungo il confine tra la Cina e l'India?",min:0,max:5000,risposta:3488,unit:"km",curiosita:"Il confine sino-indiano è lungo circa 3.488 km ed è uno dei più contesi al mondo. La guerra sino-indiana del 1962 lasciò dispute territoriali ancora irrisolte. Incidenti di confine avvengono ancora periodicamente."},
 {q:"Quante uova depone un'ostrica nella vita?",min:0,max:1000000000,risposta:100000000,unit:"uova",curiosita:"Un'ostrica produce fino a 100 milioni di uova in un anno. Sono ermafrodite sequenziali: cambiano sesso durante la vita. Filtrano 190 litri d'acqua al giorno, pulendo gli estuari. La perla è prodotta come difesa da un granello."},
 {q:"Quanti anni ci volle alla Germania per riunificarsi?",min:0,max:50,risposta:45,unit:"anni (dal 1945 al 1990)",curiosita:"La Germania fu divisa dal 1945 al 1990 — 45 anni. Il Muro di Berlino fu in piedi dal 1961 al 1989. La riunificazione ufficiale avvenne il 3 ottobre 1990. Il costo della riunificazione fu di circa 2.000 miliardi di euro."},
 {q:"Quanti anni fa fu composto Il Barbiere di Siviglia?",min:0,max:300,risposta:208,unit:"anni fa",curiosita:"Il Barbiere di Siviglia di Rossini fu composto nel 1816 — circa 208 anni fa. Fu scritto in soli 13 giorni. All'esordio fu un fiasco clamoroso per le interruzioni del pubblico. Poi diventò l'opera buffa più famosa al mondo."},
 {q:"Quanti paesi hanno ricevuto il Codice di Napoleone?",min:0,max:50,risposta:30,unit:"paesi circa",curiosita:"Il Codice Napoleonico del 1804 è alla base del sistema giuridico di circa 30 paesi: Francia, Italia, Spagna, Portogallo, Belgio, Olanda, America Latina. Introduce l'uguaglianza di fronte alla legge e la proprietà privata."},
 {q:"Quanti anni fa i Vichinghi arrivarono in America?",min:0,max:1100,risposta:1024,unit:"anni fa",curiosita:"I Vichinghi arrivarono in America intorno all'anno 1000 d.C. — circa 1.024 anni fa. Leif Eriksson fondò una colonia a 'Vinland' (probabilmente Terranova). Abbandonarono l'insediamento per conflitti con i nativi americani."},
 {q:"Quanti anni fa fu scritto il Decameron di Boccaccio?",min:0,max:700,risposta:680,unit:"anni fa",curiosita:"Il Decameron fu scritto tra il 1349 e il 1353 — circa 670-680 anni fa. Fu ispirato dalla Peste Nera del 1347-1351, che uccise il 30-50% degli europei. È considerato il capolavoro della prosa italiana medievale."},
 {q:"Quanti anni fa morì Frédéric Chopin?",min:0,max:300,risposta:175,unit:"anni fa",curiosita:"Chopin morì il 17 ottobre 1849 a Parigi — 175 anni fa. Aveva solo 39 anni. La tubercolosi lo consumò lentamente. Le sue Polacche, Notturni e Ballate sono tra i vertici della letteratura pianistica."},
 {q:"Quante specie di orchidee esistono?",min:0,max:50000,risposta:28000,unit:"specie",curiosita:"Esistono circa 28.000 specie di orchidee — la famiglia di piante con fiori più diversificata. Crescono su ogni continente tranne l'Antartide. La vaniglia è un'orchidea: i suoi baccelli sono i semi fermentati del fiore."},
 {q:"Quanti km è lungo il percorso del Cammino di Santiago?",min:0,max:1000,risposta:780,unit:"km",curiosita:"Il Camino Francés, il percorso principale del Cammino di Santiago, è lungo 780 km da Saint-Jean-Pied-de-Port in Francia a Santiago di Compostela in Spagna. Richiede circa 30-35 giorni a piedi."},
 {q:"Quanti anni fa nacque Giuseppe Verdi?",min:0,max:300,risposta:211,unit:"anni fa",curiosita:"Verdi nacque il 10 ottobre 1813 a Le Roncole (Parma) — circa 211 anni fa. Compose 28 opere tra cui Aida, Otello, Falstaff e la Traviata. Fu anche un senatore del Regno d'Italia e un'icona del Risorgimento."},
 {q:"Quante volte il Monte Everest è stato scalato in totale?",min:0,max:20000,risposta:12000,unit:"ascensioni",curiosita:"L'Everest è stato scalato circa 12.000 volte da circa 7.000 persone diverse. Le prime salite erano estenuanti spedizioni di mesi; oggi alcuni sherpa lo scalano più volte l'anno. L'inquinamento di rifiuti è diventato un problema serio."},
 {q:"Quanti anni ci volle a Cristoforo Colombo per morire dopo la scoperta dell'America?",min:0,max:30,risposta:14,unit:"anni",curiosita:"Colombo scoprì l'America nel 1492 e morì nel 1506 — 14 anni dopo. Non divenne mai ricco come sperava. Morì a Valladolid, probabilmente di artrite reumatoide. Non fu mai certo di aver scoperto un nuovo continente."},
 {q:"Quante pagine ha la Bibbia in media?",min:0,max:3000,risposta:1500,unit:"pagine",curiosita:"La Bibbia ha mediamente 1.000-1.500 pagine a seconda del formato e della traduzione. Il libro più lungo è quello dei Salmi con 150 capitoli. Il Vangelo di Giovanni è il più teologico, quello di Marco il più breve."},
 {q:"Quanti anni fa fu composta la Traviata di Verdi?",min:0,max:300,risposta:171,unit:"anni fa",curiosita:"La Traviata fu composta da Verdi nel 1853 — circa 171 anni fa. Il debutto veneziano fu un fiasco per le critiche alle cantanti. Poi diventò una delle opere più eseguite al mondo. Si basa sulla Signora delle Camelie di Dumas."},
 {q:"Quante ore ci vogliono per fare a piedi il sentiero degli Dei in Costiera Amalfitana?",min:0,max:10,risposta:5,unit:"ore",curiosita:"Il Sentiero degli Dei, da Agerola a Positano, impiega 4-6 ore. È il trekking più famoso d'Italia. Il nome viene dalla leggenda che gli dèi greci lo usassero per osservare Ulisse. Il panorama è mozzafiato."},
 {q:"Quanti anni fa nacque Archimede?",min:0,max:3000,risposta:2335,unit:"anni fa",curiosita:"Archimede nacque nel 287 a.C. a Siracusa — circa 2.335 anni fa. Scoprì il principio di galleggiamento correndo nudo urlando 'Eureka!'. Inventò viti ad acqua, catapulte e macchine da guerra. Morì nel 212 a.C. durante la conquista romana."},
 {q:"Quanti km è lunga la costa della Sardegna?",min:0,max:5000,risposta:1849,unit:"km",curiosita:"La Sardegna ha circa 1.849 km di coste — tra le più lunghe e belle del Mediterraneo. Le sue acque cristalline della Costa Smeralda e del Golfo di Orosei sono tra le più spettacolari d'Europa."},
 {q:"Quante specie di leone esistono?",min:0,max:10,risposta:2,unit:"sottospecie principali",curiosita:"Esistono 2 sottospecie di leoni: il leone africano (Panthera leo leo) e il leone asiatico (Panthera leo persica), sopravvissuto solo in India con circa 600 esemplari. 100 anni fa i leoni erano 200.000, oggi sono meno di 25.000."},
 {q:"Quante persone sono morte nel Titanic?",min:0,max:3000,risposta:1514,unit:"persone",curiosita:"Il Titanic affondò il 15 aprile 1912 causando la morte di 1.514 persone su 2.224 a bordo. Le scialuppe erano sufficienti solo per 1.178 persone. Le classi basse avevano molta meno probabilità di sopravvivere."},
 {q:"Quanti anni fa fu scoperto il vaccino contro la polio?",min:0,max:100,risposta:70,unit:"anni fa",curiosita:"Jonas Salk sviluppò il vaccino contro la polio nel 1955 — circa 69 anni fa. La polio paralizzava 60.000 bambini americani all'anno. Salk rifiutò di brevettarlo: 'Non si può brevettare il sole'. Oggi la polio è quasi eradicata."},
 {q:"Quante specie di meduse esistono?",min:0,max:5000,risposta:2000,unit:"specie",curiosita:"Esistono circa 2.000 specie di meduse. La Turritopsis dohrnii è chiamata la 'medusa immortale' perché può ringiovanire — tecnicamente potrebbe vivere per sempre. La physalia physalis (caravella portoghese) può uccidere un uomo."},
 {q:"Quanti anni fa nacque Marie Curie?",min:0,max:200,risposta:157,unit:"anni fa",curiosita:"Marie Curie nacque il 7 novembre 1867 a Varsavia — circa 157 anni fa. Fu la prima donna a vincere un Nobel (1903, Fisica) e l'unica persona a vincerne due in scienze diverse (1911, Chimica). Morì di leucemia per le radiazioni."},
 {q:"Quante dita ha un panda rosso?",min:0,max:10,risposta:6,unit:"dita funzionali",curiosita:"Il panda rosso ha 6 dita funzionali — 5 normali più un 'falso pollice' osseo che usa per afferrare il bambù. Lo stesso adattamento del panda gigante, nonostante non siano parenti. Il panda rosso è in pericolo critico."},
 {q:"Quanti anni fa fu incisa la Stele di Rosetta?",min:0,max:3000,risposta:2222,unit:"anni fa",curiosita:"La Stele di Rosetta fu incisa nel 196 a.C. — circa 2.222 anni fa. Trovata nel 1799 da soldati napoleonici, permise a Champollion di decifrare i geroglifici nel 1822. È esposta al British Museum di Londra."},
 {q:"Quanti km è lungo il Corridoio Vasariano a Firenze?",min:0,max:5,risposta:1,unit:"km circa",curiosita:"Il Corridoio Vasariano è lungo circa 1 km e collegava Palazzo Vecchio agli Uffizi e poi a Palazzo Pitti. Costruito da Giorgio Vasari nel 1565 in soli 5 mesi. Ospita ritratti di artisti famosi."},
 {q:"Quante milioni di anni fa vissero i triceratopi?",min:0,max:300000000,risposta:68000000,unit:"anni fa",curiosita:"I triceratopi vissero tra 68 e 66 milioni di anni fa. Erano tra gli ultimi dinosauri prima dell'estinzione di massa. Pesavano fino a 12 tonnellate. Le tre corna servivano per difesa e combattimenti rituali tra maschi."},
 {q:"Quanti anni fa fu trovato il papiro di Ipuwer?",min:0,max:5000,risposta:4000,unit:"anni fa (età)",curiosita:"Il Papiro di Ipuwer, una delle lamentele più antiche della storia, fu scritto in Egitto circa 3.800-4.000 anni fa. Descrive calamità sociali e ambientali che alcuni mettono in relazione con le Piaghe d'Egitto bibliche."},
 {q:"Quanti anni ci volle ad Erasmo da Rotterdam per scrivere l'Elogio della Follia?",min:0,max:20,risposta:1,unit:"settimana",curiosita:"Erasmo scrisse l'Elogio della Follia nel 1509 in pochi giorni — quasi una settimana — alloggiando a casa di Thomas More a Londra. Divenne uno dei libri più letti del Rinascimento. More (Morus) era il destinatario del dedicazione."},
 {q:"Quante specie di piovra esistono?",min:0,max:500,risposta:300,unit:"specie",curiosita:"Esistono circa 300 specie di polpi. Hanno 3 cuori, sangue blu (per il rame) e possono cambiare colore in 0,3 secondi. I polpi comuni vivono solo 1-2 anni. Hanno 500 milioni di neuroni — un quinto quelli umani."},
 {q:"Quante settimane dura la Quaresima?",min:0,max:10,risposta:6,unit:"settimane",curiosita:"La Quaresima dura 40 giorni (6 settimane) dal Mercoledì delle Ceneri alla Pasqua, commemorando i 40 giorni di digiuno di Gesù nel deserto. In passato i cristiani erano obbligati a digiunare ogni giorno."},
 {q:"Quanti anni fa nacque il Carnevale di Venezia?",min:0,max:1000,risposta:900,unit:"anni fa circa",curiosita:"Il Carnevale di Venezia è documentato dal 1162 — circa 900 anni fa. Era famoso per consentire alle persone di ogni classe di mescolarsi sotto le maschere. Fu soppresso da Napoleone nel 1797 e ripristinato nel 1979."},
 {q:"Quante mila linee di codice ha il kernel Linux?",min:0,max:100000,risposta:30000,unit:"migliaia di righe",curiosita:"Il kernel Linux ha circa 30 milioni di righe di codice — e cresce di milioni ogni anno. Fu creato da Linus Torvalds nel 1991 come hobby. Oggi gira su il 96% dei server web, tutti i supercomputer e la maggior parte degli smartphone."},
 {q:"Quanti anni ci volle a tradurre la Bibbia in italiano?",min:0,max:200,risposta:100,unit:"anni circa",curiosita:"Le prime traduzioni bibliche in italiano nacquero nel XIII-XIV secolo. La Bibbia di Antonio Brucioli (1532) fu la prima traduzione integrale dall'ebraico e greco. La CEI completò la traduzione ufficiale cattolica nel 1971."},
 {q:"Quante ore al giorno mangia un panda gigante?",min:0,max:24,risposta:14,unit:"ore",curiosita:"Il panda gigante mangia bambù per 10-16 ore al giorno — deve ingerire 12-38 kg di bambù perché il suo sistema digestivo non è adatto alle piante. Per questo è quasi sempre a mangiare o a dormire."},
 {q:"Quante volte ha nevicato a Roma negli ultimi 50 anni?",min:0,max:50,risposta:10,unit:"eventi nevosi significativi",curiosita:"A Roma nevica in media ogni 5-8 anni in modo significativo. L'ultima nevicata importante fu nel 2018 con 10-20 cm. Il clima mediterraneo rende la neve un evento straordinario che paralizza la città."},
 {q:"Quanti anni fa fu inventato il gelato?",min:0,max:500,risposta:400,unit:"anni fa circa",curiosita:"Il gelato come lo conosciamo nacque in Italia nel XVII secolo — circa 400 anni fa. Le origini sono a Firenze, dove i Medici commissionarono ricette ai cuochi. Si diffuse in Europa attraverso la corte di Caterina de' Medici in Francia."},
 {q:"Quante specie di topi esistono?",min:0,max:2000,risposta:1000,unit:"specie",curiosita:"Esistono circa 1.000 specie di roditori del genere topo e simili. Il topo domestico (Mus musculus) è tra i mammiferi più studiati in laboratorio. Si riproducono ogni 3 settimane con 5-10 cuccioli per nidiata."},
 {q:"Quanti anni ci volle a Dickens per scrivere Canto di Natale?",min:0,max:10,risposta:0,unit:"settimane (6)",curiosita:"Charles Dickens scrisse Canto di Natale in sole 6 settimane nel 1843 — quasi in tempo reale. Il libro rivoluzionò il modo di celebrare il Natale in Inghilterra e USA. Scrooge è diventato sinonimo di avaro."},
 {q:"Quante ore al giorno un pipistrello dorme?",min:0,max:24,risposta:20,unit:"ore",curiosita:"I pipistrelli dormono 16-20 ore al giorno appesi a testa in giù. La loro circolazione è tale che il sangue non va alla testa. Sono gli unici mammiferi volanti e sono attivi di notte grazie all'ecolocalizzazione."},
 {q:"Quanti anni fa nacque il tennis?",min:0,max:200,risposta:152,unit:"anni fa",curiosita:"Il tennis moderno fu inventato da Walter Wingfield nel 1873 a Londra — circa 151 anni fa. Wimbledon, il primo torneo, fu nel 1877. La forma medievale del gioco (jeu de paume) è molto più antica: XII secolo."},
 {q:"Quante settimane dura il Ramadan?",min:0,max:8,risposta:4,unit:"settimane",curiosita:"Il Ramadan dura un mese lunare — circa 29-30 giorni (4 settimane). I musulmani digiunano dall'alba al tramonto. È il nono mese del calendario islamico e commemora la rivelazione del Corano a Maometto."},
 {q:"Quanti anni fa nacque il tennis tavolo (ping pong)?",min:0,max:200,risposta:135,unit:"anni fa circa",curiosita:"Il ping pong nacque in Inghilterra negli anni 1880-1890 come gioco da tavolo indoor. Il nome 'ping pong' fu registrato nel 1901. È lo sport olimpico più praticato al mondo per numero di partecipanti — 40 milioni di giocatori."},
 {q:"Quante pagine ha mediamente un dizionario della lingua italiana?",min:0,max:10000,risposta:3000,unit:"pagine",curiosita:"I grandi dizionari italiani come il Sabatini Coletti o il GRADIT hanno 2.000-5.000 pagine. Il vocabolario della lingua italiana contiene circa 270.000 lemmi. Lo Zingarelli (2024) ne conta oltre 147.000."},
 {q:"Quanti anni ci volle a costruire la Torre di Babele (secondo la Bibbia)?",min:0,max:100,risposta:0,unit:"(non specificato, leggenda)",curiosita:"La Torre di Babele è un racconto biblico — non un fatto storico. Potrebbe ispirarsi all'Etemenanki, ziggurat babilonese alta 91 metri costruita circa 2.200-2.500 anni fa. Oggi sono visibili solo le fondamenta a Babilonia (Iraq)."},
 {q:"Quanti anni fa fu fondato il Codice di Hammuarabi?",min:0,max:5000,risposta:3800,unit:"anni fa",curiosita:"Il Codice di Hammurabi fu scritto circa 1.754 a.C. — 3.800 anni fa. È uno dei codici di leggi più antichi. Include 282 leggi con principi come 'occhio per occhio'. La stele originale è al Louvre di Parigi."},
 {q:"Quante ore dura un volo da Roma a Buenos Aires?",min:0,max:24,risposta:14,unit:"ore",curiosita:"Roma-Buenos Aires dura circa 13-15 ore con scalo, meno di 14 ore senza scalo. È una delle rotte transatlantiche più lunghe. Buenos Aires ha la più grande comunità italiana al di fuori dell'Italia: 25 milioni di italoargentini."},
 {q:"Quanti anni fa fu composta la Quinta Sinfonia di Beethoven?",min:0,max:300,risposta:216,unit:"anni fa",curiosita:"La Quinta Sinfonia fu composta tra il 1804 e il 1808 — circa 216 anni fa. I quattro accordi iniziali (ta-ta-ta-taaaa) sono tra i più famosi della musica. Durante la Seconda Guerra Mondiale la BBC usò quel ritmo per il simbolo della vittoria (V)."},
 {q:"Quante specie di cactus esistono?",min:0,max:3000,risposta:1750,unit:"specie",curiosita:"Esistono circa 1.750 specie di cactus, originarie tutte delle Americhe (tranne una specie africana). Alcuni vivono 200 anni. Il saguaro dell'Arizona può contenere 750 litri d'acqua e crescere fino a 15 metri."},
 {q:"Quante mila anni fa i Romani costruirono il primo acquedotto?",min:0,max:10,risposta:2,unit:"millenni fa (312 a.C.)",curiosita:"Il primo acquedotto romano fu l'Aqua Appia nel 312 a.C. — 2.300 anni fa. Roma alla fine ne aveva 11 che portavano 1 milione di m³ d'acqua al giorno — più di molte città moderne. Alcuni tratti sono ancora usati."},
 {q:"Quanti anni fa nacque il calcio a 5 (futsal)?",min:0,max:100,risposta:93,unit:"anni fa",curiosita:"Il futsal fu inventato nel 1931 a Montevideo (Uruguay) da Juan Carlos Ceriani. Si diffuse in Brasile dove divenne il terreno di allenamento dei più grandi campioni: Pelé, Ronaldo e Ronaldinho vi sono cresciuti."},
 {q:"Quante specie di ragne esistono?",min:0,max:100000,risposta:45000,unit:"specie",curiosita:"Esistono circa 45.000 specie di ragni catalogate — e probabilmente altrettante ancora da scoprire. La tela è 5 volte più resistente dell'acciaio a parità di peso. Il ragno goliath di Goliath bird-eater può avere un'apertura di 30 cm."},
 {q:"Quanti anni fa nacque il Rinascimento veneziano?",min:0,max:700,risposta:550,unit:"anni fa circa",curiosita:"Il Rinascimento veneziano fiorì nel XV-XVI secolo — 500-550 anni fa. Bellini, Giorgione, Tiziano e Tintoretto ne furono i protagonisti. Venezia era allora la potenza commerciale dominante del Mediterraneo."},
 {q:"Quante stelle ci sono nel logo dell'UE?",min:0,max:30,risposta:12,unit:"stelle",curiosita:"La bandiera UE ha 12 stelle gialle su fondo blu — fisse, non proporzionali ai membri. Il numero 12 simboleggia perfezione e completezza. Fu adottata nel 1955 e divenne simbolo dell'UE nel 1985."},
 {q:"Quanti anni fa fu fondato il Club Alpino Italiano?",min:0,max:200,risposta:163,unit:"anni fa",curiosita:"Il Club Alpino Italiano (CAI) fu fondato a Torino il 23 ottobre 1863 — circa 161 anni fa. Oggi ha 360.000 soci. Gestisce 7.000 km di sentieri e 750 rifugi alpini. Promuove la cultura e la sicurezza in montagna."},
 {q:"Quante spezie contiene il curry?",min:0,max:50,risposta:20,unit:"spezie circa",curiosita:"Il curry è un mix di 15-25 spezie che varia regione per regione in India. Non esiste un'unica ricetta. Curcuma, cumino, coriandolo, pepe nero e peperoncino sono le base. Il termine 'curry' fu inventato dai colonizzatori britannici."},
 {q:"Quanti anni fa nacque il volley ball?",min:0,max:200,risposta:129,unit:"anni fa",curiosita:"La pallavolo fu inventata nel 1895 da William Morgan a Holyoke (Massachusetts) — 129 anni fa. Voleva uno sport meno fisico del basket. Si chiamava 'Mintonette' inizialmente. La versione beach fu introdotta alle Olimpiadi nel 1996."},
 {q:"Quante km è la distanza tra Torino e Venezia?",min:0,max:1000,risposta:285,unit:"km",curiosita:"Torino e Venezia distano circa 285 km in linea retta, 370 km su strada. Torino fu la prima capitale d'Italia (1861-1865). Venezia fu la più potente repubblica marinara per secoli. Entrambe sono città d'arte di fama mondiale."},
 {q:"Quanti anni fa fu costruita la piramide di Cheope?",min:0,max:5000,risposta:4580,unit:"anni fa",curiosita:"La Grande Piramide di Giza fu completata intorno al 2560 a.C. — circa 4.580 anni fa. Alta 146 metri (oggi 138), fu la struttura più alta del mondo per 3.800 anni. Fu costruita da operai stipendiati — non schiavi come si credeva."},
 {q:"Quante righe ha la Costituzione Italiana?",min:0,max:1000,risposta:139,unit:"articoli",curiosita:"La Costituzione Italiana è composta da 139 articoli più le disposizioni transitorie. Fu scritta dall'Assemblea Costituente nel 1946-1947. È considerata tra le più belle costituzioni del mondo per il suo linguaggio e i principi fondamentali."},
 {q:"Quante note ci sono in una scala musicale occidentale?",min:0,max:20,risposta:7,unit:"note (Do Re Mi Fa Sol La Si)",curiosita:"La scala diatonica occidentale ha 7 note (Do Re Mi Fa Sol La Si). Con le alterazioni (diesis e bemolle) si arriva a 12 semitoni. Molte culture usano scale diverse: la musica araba usa quarti di tono non presenti nelle scale occidentali."},
 {q:"Quanti anni fa fu fondato Instagram?",min:0,max:20,risposta:14,unit:"anni fa",curiosita:"Instagram fu fondato nel 2010 da Kevin Systrom e Mike Krieger — 14 anni fa. Facebook (ora Meta) lo acquistò nel 2012 per 1 miliardo di dollari — una delle migliori acquisizioni tech della storia. Oggi ha 2 miliardi di utenti."},
 {q:"Quante specie di formiche esistono?",min:0,max:30000,risposta:20000,unit:"specie",curiosita:"Esistono circa 20.000 specie di formiche. Vivono su tutti i continenti tranne l'Antartide. Se si pesassero tutte le formiche del mondo, equivarrebbero a circa il 15-20% della biomassa animale terrestre totale."},
 {q:"Quanti anni fa fu composta la Nona Sinfonia di Beethoven?",min:0,max:300,risposta:200,unit:"anni fa",curiosita:"La Nona Sinfonia fu eseguita per la prima volta nel 1824 — 200 anni fa. Beethoven era completamente sordo. Il quarto movimento include l'Inno alla Gioia, diventato l'inno dell'Unione Europea nel 1985."},
 {q:"Quante km è larga la Via Lattea?",min:0,max:200000,risposta:100000,unit:"anni luce",curiosita:"La Via Lattea è larga circa 100.000-120.000 anni luce. Il nostro Sole è a circa 26.000 anni luce dal centro. La galassia ha circa 200-400 miliardi di stelle. La luce impiegherebbe 100.000 anni per attraversarla."},
 {q:"Quanti anni fa cadde il Muro di Berlino?",min:0,max:100,risposta:35,unit:"anni fa",curiosita:"Il Muro di Berlino cadde il 9 novembre 1989 — circa 35 anni fa. Rimase in piedi dal 1961 al 1989 — 28 anni. Circa 140 persone morirono tentando di attraversarlo. La riunificazione tedesca seguì il 3 ottobre 1990."},
 {q:"Quanti litri d'acqua beve un elefante al giorno?",min:0,max:500,risposta:150,unit:"litri",curiosita:"Un elefante adulto beve 150-300 litri d'acqua al giorno. Usa la proboscide come tubo — può contenere 8 litri. In tempo di siccità, gli elefanti scavano nel letto di fiumi secchi con le zanne per trovare acqua."},
 {q:"Quanti anni fa fu scoperta l'America da Colombo?",min:0,max:600,risposta:532,unit:"anni fa",curiosita:"Colombo arrivò nelle Americhe il 12 ottobre 1492 — circa 532 anni fa. Sbarcò nelle Bahamas, convinto di essere in Asia. Non capì mai di aver scoperto un nuovo continente — fu Amerigo Vespucci a comprenderlo."},
 {q:"Quante ore dura un volo da Roma a Tokyo?",min:0,max:24,risposta:13,unit:"ore",curiosita:"Roma-Tokyo dura circa 12-14 ore senza scalo. La distanza in linea retta è circa 9.500 km. Il Giappone e l'Italia, nonostante la distanza, hanno rapporti culturali storici: Marco Polo aprì le vie commerciali con l'Oriente."},
 {q:"Quanti grammi pesa un cuore umano?",min:0,max:1000,risposta:300,unit:"grammi",curiosita:"Il cuore umano pesa in media 250-350 grammi — come un pugno chiuso. Pompa circa 5 litri di sangue al minuto, 7.500 litri al giorno. È composto quasi interamente di muscolo cardiaco — uno dei tessuti più resistenti del corpo."},
 {q:"Quante km è la distanza tra la Terra e la Luna?",min:0,max:500000,risposta:384000,unit:"km",curiosita:"La Luna è in media a 384.400 km dalla Terra (varia tra 356.000 e 406.000 km per l'orbita ellittica). La luce impiega 1,3 secondi. L'Apollo 11 impiegò 3 giorni per raggiungere la Luna."},
 {q:"Quanti anni fa nacque Albert Einstein?",min:0,max:200,risposta:145,unit:"anni fa",curiosita:"Einstein nacque il 14 marzo 1879 a Ulm (Germania) — circa 145 anni fa. Imparò a parlare tardi e fu espulso da scuola. A 26 anni pubblicò 4 articoli rivoluzionari tra cui la teoria della relatività speciale."},
 {q:"Quante specie di alberi esistono nel mondo?",min:0,max:100000,risposta:73000,unit:"specie",curiosita:"Esistono circa 73.000 specie di alberi. Il Brasile ne ha la maggior varietà: 15.000 specie. L'albero più antico è un pino bristlecone californiano di 5.068 anni, chiamato 'Matusalemme'."},
 {q:"Quanti anni ci vuole a un asteroide per orbitare il Sole?",min:0,max:10,risposta:4,unit:"anni (fascia principale)",curiosita:"Gli asteroidi della fascia principale tra Marte e Giove impiegano 3-6 anni per orbitare il Sole. Ci sono milioni di asteroidi. La missione DART della NASA nel 2022 ha deviato con successo un asteroide per la prima volta."},
 {q:"Quante specie di cetacei (balene e delfini) esistono?",min:0,max:200,risposta:90,unit:"specie",curiosita:"Esistono circa 90 specie di cetacei. La balena azzurra è il più grande animale mai vissuto sulla Terra (33 m, 200 tonnellate). I delfini hanno nomi individuali — si chiamano tra loro con fischi specifici."},
 {q:"Quanti anni fa fu inventato il telefono?",min:0,max:200,risposta:148,unit:"anni fa",curiosita:"Alexander Graham Bell brevettò il telefono nel 1876 — 148 anni fa. La prima parola trasmessa fu 'Mr. Watson, come here!' al suo assistente. Bell voleva chiamarlo 'telettrofono' ma vinse 'telefono'."},
 {q:"Quante ore ci vuole per fare un corso di pilotaggio base?",min:0,max:100,risposta:40,unit:"ore di volo",curiosita:"La licenza di pilota privato richiede almeno 40 ore di volo in Europa. Un pilota commerciale ne necessita 250. I piloti di linea arrivano a 10.000+ ore nella carriera. I simulatori di volo valgono fino al 100% delle ore."},
 {q:"Quante stelle ci sono nella costellazione di Orione?",min:0,max:100,risposta:7,unit:"stelle principali",curiosita:"Orione ha 7 stelle principali visibili a occhio nudo. Betelgeuse (spalla sinistra) è una supergigante rossa 700 volte il Sole — quando esploderà sarà visibile di giorno. La 'Cintura di Orione' ha 3 stelle allineate."},
 {q:"Quanti anni fa fu pubblicato il primo romanzo (considerato tale)?",min:0,max:400,risposta:420,unit:"anni fa circa",curiosita:"Il Chishingura giapponese o il Don Chisciotte (1605) di Cervantes sono tra i primi romanzi moderni — circa 400-420 anni fa. Don Chisciotte è considerato il primo romanzo moderno occidentale e il più venduto dopo la Bibbia."},
 {q:"Quante vite umane ha salvato la penicillina dal 1942?",min:0,max:500000000,risposta:200000000,unit:"vite stimate",curiosita:"Si stima che la penicillina abbia salvato 200 milioni di vite dal 1942. Prima degli antibiotici, infezioni banali erano letali. La polmonite uccideva il 30% dei malati; oggi con antibiotici la mortalità è sotto il 5%."},
 {q:"Quanti anni fa il Titanic affondò?",min:0,max:150,risposta:112,unit:"anni fa",curiosita:"Il Titanic affondò il 15 aprile 1912 — circa 112 anni fa. Erano stati avvertiti di iceberg ma navigavano a piena velocità. Il relitto fu trovato solo nel 1985 da Robert Ballard a 3.800 m di profondità."},
 {q:"Quante calorie ha un uovo sodo?",min:0,max:200,risposta:77,unit:"kcal",curiosita:"Un uovo sodo ha circa 77 kcal. È uno degli alimenti più completi: proteine complete, colina (importante per il cervello), vitamine A, D, E, K e B12. La tuorlo contiene la maggior parte dei nutrienti."},
 {q:"Quanti anni fa nacque il cinema sonoro?",min:0,max:200,risposta:97,unit:"anni fa",curiosita:"Il primo film sonoro di successo commerciale, Il Cantante di Jazz con Al Jolson, uscì nel 1927 — 97 anni fa. Charlie Chaplin resistette al sonoro fino al 1940. Il cinema muto aveva sviluppato un linguaggio visivo straordinario."},
 {q:"Quante specie di granchi esistono?",min:0,max:10000,risposta:6800,unit:"specie",curiosita:"Esistono circa 6.800 specie di granchi. Il granchio reale delle Aleutine ha un'apertura delle chele di 1,8 m. I granchi vivono ovunque: dalla riva del mare alle grotte, dalle mangrovie alle profondità oceaniche."},
 {q:"Quanti anni fa fu costruita la Cattedrale di Chartres?",min:0,max:1000,risposta:800,unit:"anni fa circa",curiosita:"La Cattedrale di Chartres fu costruita principalmente tra il 1194 e il 1220 — circa 800 anni fa. È il capolavoro del gotico francese. I suoi 172 vetri colorati medievali sono tra i più belli e meglio conservati al mondo."},
 {q:"Quanti km è lungo il Rio delle Amazzoni?",min:0,max:10000,risposta:6992,unit:"km",curiosita:"Il Rio delle Amazzoni è lungo 6.992 km — si contende con il Nilo il titolo di fiume più lungo. Scarica il 20% di tutta l'acqua dolce del mondo nell'oceano. La sua foce è larga 350 km — quasi la Sardegna."},
 {q:"Quante ore al giorno un adulto passa in media sui social media?",min:0,max:20,risposta:3,unit:"ore",curiosita:"La media globale di utilizzo dei social media è circa 2,5-3 ore al giorno. Tra i giovani 18-24 anni supera le 4 ore. L'Italia è sopra la media europea. Il confronto sociale sui social è associato ad ansia e insoddisfazione."},
 {q:"Quanti anni fa nacque Dante Alighieri?",min:0,max:800,risposta:759,unit:"anni fa",curiosita:"Dante nacque nel 1265 a Firenze — circa 759 anni fa. La Divina Commedia fu completata nel 1321, anno della sua morte. Il 25 marzo 1300 è l'inizio del viaggio nel poema. Dante inventò l'italiano letterario moderno."},
 {q:"Quante specie di rane esistono?",min:0,max:10000,risposta:7000,unit:"specie",curiosita:"Esistono circa 7.000 specie di rane e rospi. La rana dendrobate (rana freccia) è la più velenosa: 2 cm con abbastanza veleno per uccidere 10 uomini. Le rane assorbono acqua e ossigeno attraverso la pelle."},
 {q:"Quanti anni fa fu scritto il Principe di Machiavelli?",min:0,max:600,risposta:511,unit:"anni fa",curiosita:"Il Principe fu scritto nel 1513 — circa 511 anni fa. Machiavelli lo dedicò a Lorenzo de' Medici sperando di ottenere un incarico politico. Il libro rivoluzionò il pensiero politico separando etica e politica."},
 {q:"Quante km è il percorso della Maratona di New York?",min:0,max:100,risposta:42,unit:"km (42.195 m)",curiosita:"La maratona misura 42,195 km. La distanza deriva dal mito del soldato greco Filippide che corse da Maratona ad Atene nel 490 a.C. per annunciare la vittoria contro i Persiani — poi morì per lo sforzo."},
 {q:"Quanti anni fa fu fondata Venezia?",min:0,max:2000,risposta:1553,unit:"anni fa circa",curiosita:"Venezia fu fondata nel 421 d.C. — circa 1.600 anni fa — secondo la tradizione il 25 marzo. Fu costruita su 118 isole nel mare Adriatico da profughi fuggiti dalle invasioni barbariche. Ha 435 ponti e 177 canali."},
 {q:"Quante specie di lucertole esistono?",min:0,max:10000,risposta:6000,unit:"specie",curiosita:"Esistono circa 6.000 specie di lucertole. Il drago di Komodo è la più grande (3 m, 70 kg) e può uccidere un bufalo. Il geco ha ventose ai piedi che gli permettono di camminare sul soffitto."},
 {q:"Quanti anni fa fu stampato il primo giornale?",min:0,max:500,risposta:420,unit:"anni fa circa",curiosita:"I primi giornali stampati regolari apparvero in Germania tra il 1605 e il 1650 — circa 400-420 anni fa. La Gazzetta Ufficiale di Venezia (1563) era un foglio a mano. Il New York Times fu fondato nel 1851."},
 {q:"Quante specie di balene azzurre esistono?",min:0,max:5,risposta:3,unit:"sottospecie",curiosita:"La balena azzurra ha 3 sottospecie riconosciute. Il suo cuore pesa 600 kg ed è grande come un'auto utilitaria. Il battito cardiaco in apnea scende a 2 battiti al minuto. Il suo canto è udibile a 1.600 km di distanza."},
 {q:"Quanti anni fa cadde l'Impero Romano d'Occidente?",min:0,max:2000,risposta:1548,unit:"anni fa",curiosita:"L'Impero Romano d'Occidente cadde nel 476 d.C. — circa 1.548 anni fa. L'ultimo imperatore, Romolo Augustolo, fu deposto da Odoacre. La data è considerata convenzionalmente la fine dell'Antichità e l'inizio del Medioevo."},
 {q:"Quante lingue parlava Cleopatra?",min:0,max:15,risposta:9,unit:"lingue",curiosita:"Cleopatra parlava circa 9 lingue tra cui egizio, greco, latino, aramaico, ebraico, etiopico, partico e arabo. Era la prima della sua dinastia (i Tolomei) a imparare l'egizio. Conquistò Cesare e Marco Antonio con l'intelligenza, non la bellezza."},
 {q:"Quanti anni fa fu composta l'Iliade di Omero?",min:0,max:3000,risposta:2750,unit:"anni fa circa",curiosita:"L'Iliade fu composta circa 800-700 a.C. — circa 2.750 anni fa. Originariamente era un poema orale trasmesso a memoria. Omero fu probabilmente cieco secondo la tradizione. L'Iliade e l'Odissea sono i capostipiti della letteratura occidentale."},
 {q:"Quante ore ci vogliono per digerire una pizza margherita?",min:0,max:12,risposta:4,unit:"ore",curiosita:"Una pizza margherita si digerisce completamente in 4-6 ore. I carboidrati sono digeriti per primi (2 ore), le proteine e i grassi poi (4-6 ore). Il processo digestivo brucia il 10% delle calorie ingerite."},
 {q:"Quanti anni fa nacque la Repubblica Italiana?",min:0,max:100,risposta:78,unit:"anni fa",curiosita:"La Repubblica Italiana nacque con il referendum del 2 giugno 1946 — 78 anni fa. Il 54,3% votò per la repubblica contro il 45,7% per la monarchia. Le donne votavano per la prima volta. De Gasperi e Togliatti guidarono la ricostruzione."},
 {q:"Quante specie di api carpenter (api legnaiole) esistono?",min:0,max:1000,risposta:500,unit:"specie",curiosita:"Esistono circa 500 specie di api legnaiole. Scavano gallerie nel legno marcio per nidificare — fondamentali per la biodiversità. A differenza delle api mellifere, vivono solitarie e non producono miele commerciale."},
 {q:"Quanti anni fa fu pubblicata La Divina Commedia?",min:0,max:800,risposta:703,unit:"anni fa circa",curiosita:"La Divina Commedia fu scritta tra il 1304 e il 1321. La prima edizione a stampa è del 1472 — 552 anni fa. Il poema è diviso in Inferno (34 canti), Purgatorio (33) e Paradiso (33) — 100 canti in terzine dantesche."},
 {q:"Quante km è lungo il confine fra Italia e Francia?",min:0,max:1000,risposta:488,unit:"km",curiosita:"Il confine Italia-Francia è lungo 488 km lungo le Alpi. Il Traforo del Monte Bianco (11,6 km) è uno dei tunnel stradali più lunghi d'Europa. La Costa Azzurra francese confina con la Liguria italiana."},
 {q:"Quanti anni fa fu scritta la Magna Carta?",min:0,max:1000,risposta:809,unit:"anni fa",curiosita:"La Magna Carta fu firmata nel 1215 — circa 809 anni fa. Fu il primo documento a limitare i poteri del re inglese. Introdusse il concetto di habeas corpus e il diritto a un giusto processo — fondamenti della democrazia moderna."},
 {q:"Quante specie di gufi esistono?",min:0,max:300,risposta:220,unit:"specie",curiosita:"Esistono circa 220 specie di gufi. I gufi possono girare la testa di 270°. Cacciano di notte grazie alla visione notturna (100 volte superiore alla nostra) e all'udito direzionale. Le 'orecchie' dei gufi sono in realtà ciuffi di piume."},
 {q:"Quanti anni fa nacque il Rugby?",min:0,max:250,risposta:202,unit:"anni fa circa",curiosita:"La leggenda vuole che William Webb Ellis inventò il rugby nel 1823 a Rugby School (Inghilterra) raccogliendo il pallone con le mani durante una partita di calcio — circa 201 anni fa. Le prime regole scritte risalgono al 1845."},
 {q:"Quante calorie ha un cornetto semplice al bar?",min:0,max:500,risposta:250,unit:"kcal",curiosita:"Un cornetto semplice ha 200-280 kcal. Con la crema o la marmellata arriva a 300-350 kcal. La colazione italiana (cornetto + cappuccino) è tra le più leggere d'Europa, nonostante la reputazione calorica."},
 {q:"Quanti anni fa fu istituita la Croce Rossa?",min:0,max:200,risposta:161,unit:"anni fa",curiosita:"La Croce Rossa fu fondata nel 1863 da Henry Dunant a Ginevra — 161 anni fa. Fu ispirata dall'orrore della Battaglia di Solferino (1859) dove Dunant vide 40.000 feriti abbandonati sul campo. Ha vinto 3 Premi Nobel per la pace."},
 {q:"Quante specie di pinguini esistono?",min:0,max:30,risposta:18,unit:"specie",curiosita:"Esistono 18 specie di pinguini. Vivono tutti nell'emisfero sud — dal Polo Sud alle Galapagos. Il pinguino imperatore è il più grande (1,2 m) e l'unico che incuba le uova in pieno inverno antartico a -50°C."},
 {q:"Quanti anni fa nacque il ciclismo come sport?",min:0,max:200,risposta:170,unit:"anni fa circa",curiosita:"Il primo velocipede pratico fu inventato nel 1865 — 159 anni fa. Il Tour de France nacque nel 1903. Coppi e Bartali polarizzarono l'Italia degli anni '40-'50. Oggi il ciclismo è tra gli sport con più km percorsi al mondo."},
 {q:"Quante km di metropolitana ha Parigi?",min:0,max:500,risposta:220,unit:"km",curiosita:"La metropolitana di Parigi ha 220 km di linee e 302 stazioni — aperta nel 1900. È una delle più antiche e dense d'Europa. Parigi ha anche 650 km di gallerie sotterranee antiche (Catacombe) con i resti di 6 milioni di parigini."},
 {q:"Quanti anni fa nacque il cinema d'animazione?",min:0,max:150,risposta:127,unit:"anni fa circa",curiosita:"Il primo film di animazione fu 'Fantasmagorie' di Émile Cohl nel 1908 — circa 116 anni fa. Diseny rivoluzionò il settore con Biancaneve nel 1937. Pixar cambiò tutto con Toy Story (1995) — il primo lungometraggio 3D."},
 {q:"Quante specie di rinoceronte esistono?",min:0,max:20,risposta:5,unit:"specie",curiosita:"Esistono 5 specie di rinoceronti: bianco, nero, indiano, di Giava e di Sumatra. Tutti sono in pericolo critico o vulnerabili. Il rinoceronte di Sumatra ha due corna ed è il più piccolo. Il corno è fatto di cheratina come le unghie."},
 {q:"Quanti anni fa fu inventato l'arco e la freccia?",min:0,max:100000,risposta:64000,unit:"anni fa",curiosita:"Le più antiche prove dell'arco risalgono a 64.000 anni fa in Sudafrica (punte di freccia). L'arco rivoluzionò la caccia e la guerra. L'arco lungo inglese medievale poteva scagliare una freccia a 300 m con precisione letale."},
 {q:"Quanti anni ha la Via Appia Antica?",min:0,max:2500,risposta:2334,unit:"anni",curiosita:"La Via Appia fu costruita nel 312 a.C. — 2.336 anni fa. Era la 'regina delle strade' romane: collega Roma a Brindisi per 540 km. Lungo questa strada furono crocifissi gli schiavi ribelli di Spartaco nel 71 a.C."},
 {q:"Quante nazioni hanno una costituzione scritta?",min:0,max:200,risposta:160,unit:"paesi circa",curiosita:"Circa 160 paesi hanno una costituzione scritta. Tra le eccezioni ci sono UK, Israele e Nuova Zelanda che hanno costituzioni non codificate. La più antica ancora in vigore è quella degli USA (1788). La più lunga è quella dell'India (395 articoli)."},
 {q:"Quanti anni fa nacque la lingua italiana?",min:0,max:1000,risposta:750,unit:"anni fa circa",curiosita:"L'italiano come lingua letteraria consolidata nasce con Dante, Petrarca e Boccaccio nel XIV secolo — circa 700-750 anni fa. Il 'Placito Cassinese' (960 d.C.) è il primo documento in volgare italiano. Fu Dante a fissare le basi del toscano letterario."},
 {q:"Quanti giorni impiega la ISS (Stazione Spaziale Internazionale) a fare un giro della Terra?",min:0,max:2,risposta:0,unit:"giorni (90 minuti)",curiosita:"La ISS orbita a 408 km di altitudine e completa un giro della Terra ogni 90 minuti — 16 orbite al giorno! Viaggia a 27.600 km/h. È abitata continuativamente dal 2000. Ha la dimensione di un campo da calcio."},
 {q:"Quante ore al giorno gli italiani guardano la TV?",min:0,max:20,risposta:4,unit:"ore",curiosita:"Gli italiani guardano la TV mediamente 4 ore al giorno — tra i più alti d'Europa. Gli anziani guardano più di 6 ore. La TV via cavo e streaming sta erodendo i telespettatori RAI/Mediaset, soprattutto tra i giovani."},
 {q:"Quanti anni fa fu fondata Roma come capitale del mondo antico?",min:0,max:3000,risposta:2070,unit:"anni fa (fine della Repubblica)",curiosita:"Roma divenne caput mundi (capitale del mondo) con Augusto nel 27 a.C. — circa 2.051 anni fa. Al suo apice (II sec. d.C.) l'Impero Romano aveva 70 milioni di abitanti — il 20-25% della popolazione mondiale dell'epoca."},
 {q:"Quante specie di corvo esistono?",min:0,max:50,risposta:45,unit:"specie nel genere Corvus",curiosita:"Il genere Corvus ha circa 45 specie tra corvi e cornacchie. Sono tra gli uccelli più intelligenti: risolvono problemi complessi, usano strumenti, riconoscono facce umane e comunicano tra loro in modo sofisticato."},
 {q:"Quanti anni fa fu compiuto il primo viaggio intorno al mondo?",min:0,max:600,risposta:503,unit:"anni fa",curiosita:"La spedizione di Magellano-Elcano completò il primo giro del mondo nel 1522 — 502 anni fa. Partirono in 265, tornarono in 18. Magellano morì nelle Filippine. Elcano portò a termine il viaggio in 3 anni."},
 {q:"Quante persone vivono a Tokyo?",min:0,max:50000000,risposta:14000000,unit:"abitanti (comune)",curiosita:"Il comune di Tokyo ha 14 milioni di abitanti, la grande area metropolitana ne ha 37 milioni — la più grande agglomerazione urbana del mondo. Ha la rete ferroviaria sotterranea più utilizzata al mondo con 3 miliardi di passeggeri l'anno."},
 {q:"Quanti anni fa nacque Abraham Lincoln?",min:0,max:300,risposta:215,unit:"anni fa",curiosita:"Lincoln nacque il 12 febbraio 1809 — circa 215 anni fa. Crebbe in una capanna di tronchi nel Kentucky. Fu presidente durante la Guerra Civile e abolì la schiavitù nel 1863. Fu assassinato nel 1865, poche settimane dopo la fine della guerra."},
 {q:"Quante specie di papaveri esistono?",min:0,max:500,risposta:120,unit:"specie",curiosita:"Esistono circa 120 specie di papaveri. Il papavero da oppio (Papaver somniferum) è la fonte naturale della morfina. I papaveri rossi di Fiandre diventarono il simbolo delle vittime della Prima Guerra Mondiale."},
 {q:"Quanti anni fa fu pubblicato il manifesto del Surrealismo?",min:0,max:200,risposta:100,unit:"anni fa",curiosita:"Il Manifesto del Surrealismo di André Breton fu pubblicato nel 1924 — 100 anni fa. Dalí, Magritte e Ernst ne furono i maggiori esponenti pittorici. Freud e il sogno come porta dell'inconscio furono le ispirazioni."},
 {q:"Quante specie di orsi esistono?",min:0,max:20,risposta:8,unit:"specie",curiosita:"Esistono 8 specie di orsi: bruno, polare, nero americano, asiatico, degli occhiali, malese, dalle labbra pendule e del sole. L'orso polare è il più grande predatore terrestre. Il panda gigante è tecnicamente un orso."},
 {q:"Quanti anni fa fu costruita la prima mongolfiera?",min:0,max:300,risposta:241,unit:"anni fa",curiosita:"I fratelli Montgolfier lanciarono la prima mongolfiera il 4 giugno 1783 — 241 anni fa. I primi passeggeri erano un'anatra, un gallo e una pecora. Il primo volo umano fu il 21 novembre 1783, con Pilâtre de Rozier."},
 {q:"Quante calorie ha 100g di cioccolato fondente al 70%?",min:0,max:700,risposta:600,unit:"kcal",curiosita:"Il cioccolato fondente al 70% ha circa 560-620 kcal per 100g. Contiene flavonoidi antiossidanti, magnesio e serotonina. Studi mostrano che il cioccolato fondente (non al latte) riduce la pressione arteriosa."},
 {q:"Quanti anni fa nacque Michelangelo?",min:0,max:600,risposta:549,unit:"anni fa",curiosita:"Michelangelo nacque il 6 marzo 1475 a Caprese (Arezzo) — 549 anni fa. Dipinse la Cappella Sistina sdraiato (non in piedi come si crede) tra il 1508 e il 1512 — 4 anni. Morì nel 1564, lo stesso anno di nascita di Galileo e Shakespeare."},
 {q:"Quante ore ci vuole per fare il giro della Sardegna in barca a vela?",min:0,max:500,risposta:120,unit:"ore circa (5 giorni)",curiosita:"Il periplo della Sardegna in barca è circa 1.849 km di costa — con tappe e soste dura dai 5 ai 15 giorni. La Costa Smeralda, la Penisola del Sinis e il Golfo di Orosei sono le mete più spettacolari."},
 {q:"Quanti anni fa fu fondata la NATO?",min:0,max:100,risposta:75,unit:"anni fa",curiosita:"La NATO fu fondata il 4 aprile 1949 — 75 anni fa. Nata dalla Guerra Fredda per contrastare il patto di Varsavia sovietico. Oggi ha 32 membri dopo l'adesione di Svezia e Finlandia nel 2023-2024."},
 {q:"Quante specie di pappagalli esistono?",min:0,max:500,risposta:393,unit:"specie",curiosita:"Esistono circa 393 specie di pappagalli. Il cacatua può vivere 80 anni. I pappagalli grigi africani hanno le capacità cognitive di un bambino di 5 anni. Alex, un famoso grigo africano, capiva il concetto di zero."},
 {q:"Quanti anni fa nacque il Dadaismo?",min:0,max:200,risposta:108,unit:"anni fa",curiosita:"Il Dadaismo nacque a Zurigo nel 1916 — 108 anni fa. Fu una risposta artistica all'assurdità della Prima Guerra Mondiale. Marcel Duchamp espose un orinatoio chiamato 'Fontana' come opera d'arte, scuotendo il mondo dell'arte."},
 {q:"Quante km è il perimetro dell'Italia?",min:0,max:10000,risposta:7600,unit:"km di coste",curiosita:"L'Italia ha 7.456 km di coste — le più lunghe d'Europa occidentale. Con la sua forma a stivale e le isole Sicilia e Sardegna, è uno dei paesi con il rapporto costa/superficie più alto. Il mare è a meno di 150 km da ogni punto."},
 {q:"Quanti anni fa fu fondata la Fiat?",min:0,max:200,risposta:125,unit:"anni fa",curiosita:"La Fiat (Fabbrica Italiana Automobili Torino) fu fondata il 11 luglio 1899 — 125 anni fa. La 500 del 1957 motorizzò l'Italia del boom economico. Fiat acquistò Chrysler nel 2009 dopo la sua bancarotta. Oggi è Stellantis."},
 {q:"Quante specie di piante carnivore esistono?",min:0,max:1000,risposta:700,unit:"specie",curiosita:"Esistono circa 700 specie di piante carnivore. La Dionaea muscipula (acchiappamosche) chiude la trappola in meno di 100 ms — uno dei movimenti più veloci nel regno vegetale. Crescono in terreni poveri di azoto."},
 {q:"Quanti anni fa nacque Napoleone III (nipote di Napoleone)?",min:0,max:250,risposta:196,unit:"anni fa",curiosita:"Napoleone III nacque nel 1808 — 216 anni fa. Fu il primo presidente e poi imperatore della Francia (1848-1870). Trasformò Parigi nella città moderna con i boulevards di Haussmann. Perse contro la Prussia nel 1870."},
 {q:"Quante ore al giorno un delfino dorme?",min:0,max:24,risposta:8,unit:"ore",curiosita:"I delfini dormono circa 8 ore ma con mezzo cervello alla volta (sonno unilaterale). L'altro mezzo rimane sveglio per respirare e sorvegliare l'ambiente. Dormono vicino alla superficie per poter inspirare."},
 {q:"Quanti anni fa fu costruita la Muraglia Cinese?",min:0,max:3000,risposta:2300,unit:"anni fa (iniziata)",curiosita:"La costruzione della Grande Muraglia Cinese iniziò nel III sec. a.C. — circa 2.300 anni fa. Qin Shi Huang unificò le muraglie esistenti. La Muraglia attuale è in gran parte Ming (XIV-XVII sec.). Lunga 21.196 km totali."},
 {q:"Quante specie di piante medicinali sono conosciute?",min:0,max:100000,risposta:50000,unit:"specie",curiosita:"Circa 50.000 specie vegetali hanno usi medicinali documentati. Il 25-50% dei farmaci moderni deriva da composti naturali. L'aspirina viene dalla corteccia del salice. La morfina dal papavero. La chinina dalla chinchona."},
 {q:"Quanti anni fa fu scoperta l'Australia dai europei?",min:0,max:500,risposta:400,unit:"anni fa circa",curiosita:"I primi esploratori europei (olandesi) avvistarono l'Australia nel 1606 — circa 418 anni fa. James Cook mappò la costa est nel 1770. La colonizzazione britannica iniziò nel 1788 con una flotta di condannati."},
 {q:"Quante km è lungo il Po da sorgente a foce?",min:0,max:1000,risposta:652,unit:"km",curiosita:"Il Po è lungo 652 km — il fiume più lungo d'Italia. Nasce a 2.022 m sul Monte Viso (Cuneo) e sfocia nell'Adriatico con un delta di 380 km². La pianura Padana è irrigata dal Po e dai suoi affluenti: Ticino, Adda, Mincio."},
 {q:"Quanti anni fa fu scritto Il Principe di Machiavelli?",min:0,max:600,risposta:511,unit:"anni fa",curiosita:"Il Principe fu scritto nel 1513 ma pubblicato postumo nel 1532 — 511 anni dalla scrittura. Machiavelli era stato torturato e esiliato dai Medici. Dedico il libro a Lorenzo de' Medici per ottenere grazia. La parola 'machiavellico' nasce da quest'opera."},
 {q:"Quante specie di orche (Orca killer whale) esistono?",min:0,max:10,risposta:3,unit:"ecotipi principali",curiosita:"Esistono 3 ecotipi principali di orche: residenti (mangiano pesci), transienti (mangiano mammiferi) e offshore. DNA diverso suggerisce che potrebbero essere specie separate. Le orche sono i predatori più veloci del mare: 56 km/h."},
 {q:"Quanti anni fa nacque la pasta al pesto genovese?",min:0,max:500,risposta:350,unit:"anni fa circa",curiosita:"Il pesto alla genovese nasce nel XVII-XVIII sec. — circa 300-350 anni fa. La prima ricetta scritta è del 1800. IGP protegge il pesto genovese: deve contenere basilico DOP di Pra (Genova), parmigiano, pecorino, pinoli, aglio e olio ligure."},
 {q:"Quante km è larga la Pianura Padana?",min:0,max:500,risposta:200,unit:"km (nord-sud)",curiosita:"La Pianura Padana è larga circa 200 km da nord a sud e 500 km da ovest a est. È la pianura alluvionale più grande d'Italia — 46.000 km². Ha il 40% della produzione agricola italiana e il 30% del PIL."},
 {q:"Quanti anni fa nacque l'opera lirica italiana?",min:0,max:500,risposta:420,unit:"anni fa circa",curiosita:"La prima opera lirica, 'Dafne' di Jacopo Peri, fu eseguita a Firenze nel 1598 — circa 426 anni fa. 'L'Orfeo' di Monteverdi (1607) è la più antica ancora eseguita. L'opera nacque dal tentativo di ricreare il teatro greco antico."},
 {q:"Quante specie di insetti esistono?",min:0,max:10000000,risposta:1000000,unit:"specie catalogate",curiosita:"Sono state catalogate circa 1 milione di specie di insetti — il 70% di tutte le specie animali conosciute. Si stima ne esistano 4-8 milioni in totale. La biomassa degli insetti è 17 volte quella dell'umanità."},
 {q:"Quanti anni fa fu istituito il Premio Nobel?",min:0,max:200,risposta:123,unit:"anni fa",curiosita:"Il Premio Nobel fu istituito nel 1901 — 123 anni fa. Alfred Nobel, inventore della dinamite, lasciò il suo patrimonio di 31 milioni di corone svedesi per istituirlo. Ogni anno vengono assegnati in Fisica, Chimica, Medicina, Letteratura, Pace ed Economia."},
 {q:"Quante ore di volo ci vuole per andare da Roma a New York?",min:0,max:20,risposta:10,unit:"ore",curiosita:"Roma-New York dura circa 9-11 ore. Il Concorde faceva la tratta Parigi-New York in 3,5 ore — ritirato nel 2003. I nuovi aerei supersonici in sviluppo promettono di tornare a questi tempi entro il 2030."},
 {q:"Quanti anni fa nacque la pittura rupestre?",min:0,max:100000,risposta:40000,unit:"anni fa",curiosita:"Le pitture rupestri più antiche risalgono a 40.000-65.000 anni fa in Indonesia. In Europa le più antiche sono in Spagna (La Pasiega, 65.000 anni). Le grotte di Lascaux in Francia (17.000 anni) mostrano arte raffinata con animali in movimento."},
 {q:"Quante specie di funghi commestibili esistono?",min:0,max:5000,risposta:2000,unit:"specie",curiosita:"Esistono circa 2.000 specie di funghi commestibili su 150.000 note. Il tartufo bianco d'Alba è il più pregiato: può valere 5.000 euro al kg. L'Italia è uno dei paesi con maggiore biodiversità fungina in Europa."},
 {q:"Quanti anni ci volle a Shakespeare per scrivere Amleto?",min:0,max:20,risposta:1,unit:"anno circa",curiosita:"Amleto fu scritto tra il 1599 e il 1601 — circa un anno. È l'opera teatrale più rappresentata al mondo. Il monologo 'Essere o non essere' è il testo più famoso nella storia della letteratura. Ha 30.557 parole."},
 {q:"Quante specie di aquile esistono?",min:0,max:100,risposta:68,unit:"specie",curiosita:"Esistono 68 specie di aquile. L'aquila di Verreaux (Africa) può portare un'impala adulta. L'aquila reale ha un'apertura alare di 2,2 m e una vista 8 volte superiore all'uomo. Le aquile del Filippino possono attaccare scimmie."},
 {q:"Quanti anni fa fu fondata la Repubblica di San Marino?",min:0,max:2000,risposta:1723,unit:"anni fa (301 d.C.)",curiosita:"San Marino fu fondata nel 301 d.C. — circa 1.723 anni fa. È la più antica repubblica del mondo e uno dei paesi più piccoli (61 km²). Si trova interamente all'interno dell'Italia, sul Monte Titano. Non ha mai subito invasioni riuscite."},
 {q:"Quante specie di ape mellifera esistono?",min:0,max:30,risposta:7,unit:"specie",curiosita:"Esistono 7 specie dell'Apis (api mellifere). L'Apis mellifera è quella allevata in tutto il mondo per il miele. Una colonia ha 50.000-80.000 api. La regina vive 5 anni e depone 2.000 uova al giorno. Le api percorrono 800 km per fare 1 kg di miele."},
 {q:"Quanti anni fa nacque il cinema muto?",min:0,max:150,risposta:129,unit:"anni fa",curiosita:"Il cinema muto nacque nel 1895 con i Lumière — 129 anni fa. Chaplin, Keaton e Lloyd ne furono i grandi artisti. Il cinema muto usava la musica dal vivo durante le proiezioni. Il passaggio al sonoro nel 1927 distrusse molte carriere."},
 {q:"Quante km è lungo il Corso Buenos Aires a Milano (uno dei corsi più lunghi d'Europa)?",min:0,max:10,risposta:2,unit:"km",curiosita:"Corso Buenos Aires a Milano è lungo 1,7 km ed è uno dei corsi commerciali più frequentati d'Europa con 200 negozi. La Via dello Shopping per eccellenza della città laburista milanese — opposta alla lussuosa Via Montenapoleone."},
 {q:"Quanti anni fa il primo uomo camminò sulla Luna?",min:0,max:100,risposta:55,unit:"anni fa",curiosita:"Neil Armstrong camminò sulla Luna il 21 luglio 1969 — 55 anni fa. Con lui Buzz Aldrin. Le sue parole: 'Un piccolo passo per un uomo, un grande balzo per l'umanità'. Michael Collins rimase in orbita. In totale 12 astronauti camminarono sulla Luna."},
 {q:"Quante specie di libellule esistono?",min:0,max:10000,risposta:5900,unit:"specie",curiosita:"Esistono circa 5.900 specie di libellule e damigelle. Le libellule hanno 4 ali che muovono indipendentemente — possono volare all'indietro. Cacciano con un'efficienza del 95% — i predatori più letali in proporzione al mondo animale."},
 {q:"Quanti anni fa fu scoperta la penicillina (senza uso clinico)?",min:0,max:200,risposta:96,unit:"anni fa",curiosita:"Fleming scoprì casualmente la penicillina nel 1928 — 96 anni fa. Notò che muffa Penicillium contaminate aveva ucciso i batteri nelle sue piastre. Non approfondì la scoperta — fu Florey e Chain a svilupparla clinicamente nel 1940."},
 {q:"Quante ore al giorno lavora mediamente un italiano?",min:0,max:16,risposta:8,unit:"ore",curiosita:"Gli italiani lavorano in media 7,5-8 ore al giorno — sopra la media europea. La settimana lavorativa italiana (36-40 ore) è simile alla media UE. I tedeschi lavorano meno ore ma producono di più per la maggiore produttività."},
 {q:"Quanti anni fa nacque il jazz italiano?",min:0,max:100,risposta:90,unit:"anni fa circa",curiosita:"Il jazz arrivò in Italia negli anni '30 — circa 90 anni fa. Durante il fascismo fu censurato come 'musica negroide americana'. Tuttavia club clandestini lo suonavano. Paolo Conte, Enrico Rava e Antonello Salis sono tra i jazzisti italiani più famosi."},
 {q:"Quante specie di conifere esistono?",min:0,max:1000,risposta:600,unit:"specie",curiosita:"Esistono circa 600 specie di conifere. La sequoia gigante californiana è il più grande albero del mondo (volume). Il General Sherman sequoia ha un volume di 1.487 m³ e pesa 2 milioni di kg. Le conifere producono il 45% del legname mondiale."},
 {q:"Quanti anni fa fu fondata Google?",min:0,max:50,risposta:26,unit:"anni fa",curiosita:"Google fu fondata il 4 settembre 1998 da Larry Page e Sergey Brin in un garage a Menlo Park — 26 anni fa. Il nome nasce da 'googol' (10^100). Oggi gestisce 8,5 miliardi di ricerche al giorno e controlla il 92% del mercato dei motori di ricerca."},
 {q:"Quante specie di piovra esistono?",min:0,max:500,risposta:300,unit:"specie",curiosita:"Esistono circa 300 specie di polpi. Hanno 9 cervelli (uno centrale + uno per ogni tentacolo), 3 cuori e sangue blu per il rame. Sono daltonici ma vedono la luce polarizzata. I polpi giganti del Pacifico nordest raggiungono 9 m di apertura tentacoli."},
 {q:"Quanti anni fa nacque il Rock and Roll?",min:0,max:100,risposta:70,unit:"anni fa circa",curiosita:"Il rock and roll nacque negli USA intorno al 1954-1955 — 70 anni fa. Chuck Berry, Elvis Presley e Little Richard ne furono i pionieri. Elvis portò il suono nero al pubblico bianco. I Beatles poi lo diffusero nel mondo nel 1963."},
 {q:"Quante lingue sono parlate in India?",min:0,max:2000,risposta:1600,unit:"lingue e dialetti",curiosita:"L'India ha 1.600 lingue e dialetti. Le lingue ufficiali riconosciute dalla Costituzione sono 22. L'hindi è parlato dal 44% della popolazione, l'inglese è la seconda lingua ufficiale. Il Tamil è una delle lingue più antiche del mondo: 2.000 anni."},
 {q:"Quanti anni fa fu composto il Rigoletto di Verdi?",min:0,max:200,risposta:173,unit:"anni fa",curiosita:"Il Rigoletto fu composto nel 1851 — 173 anni fa. Basato su 'Il re si diverte' di Victor Hugo, inizialmente censurato. L'aria 'La donna è mobile' è una delle più famose della storia dell'opera lirica."},
 {q:"Quante specie di civette esistono?",min:0,max:200,risposta:200,unit:"specie",curiosita:"Ci sono circa 200 specie di civette e gufi. La civetta nana settentrionale pesa solo 31 grammi. Gli occhi dei gufi sono fissi nelle orbite: devono girare l'intera testa per cambiare direzione dello sguardo. Sentono una preda sotto la neve a 1 metro."},
 {q:"Quanti anni fa fu costruita la Fontana di Trevi?",min:0,max:400,risposta:272,unit:"anni fa",curiosita:"La Fontana di Trevi fu completata nel 1762 — 262 anni fa. È la fontana barocca più grande di Roma (26 m di altezza, 49 m di larghezza). La tradizione di gettare una moneta nacque con il film 'Tre soldi nella fontana' del 1954."},
 {q:"Quante specie di balena esistono?",min:0,max:100,risposta:90,unit:"specie (cetacei)",curiosita:"Esistono circa 90 specie di cetacei inclusi delfini e balene. La balena azzurra emette suoni da 188 decibel — il suono più forte prodotto da un animale. La megattera (balena jobbosa) canta canzoni complesse che evolvono nel tempo."},
 {q:"Quanti anni fa nacque l'Illuminismo?",min:0,max:400,risposta:300,unit:"anni fa circa",curiosita:"L'Illuminismo fiorì nel XVIII secolo — circa 300 anni fa. Voltaire, Rousseau, Locke e Kant ne furono i protagonisti. L'Enciclopedia di Diderot (1751-1772) voleva raccogliere tutto il sapere umano. Ispirò le rivoluzioni americana e francese."},
 {q:"Quanti km è lungo il confine tra Spagna e Portogallo?",min:0,max:2000,risposta:1214,unit:"km",curiosita:"Il confine iberico è lungo 1.214 km — uno dei più lunghi d'Europa. È rimasto relativamente stabile per secoli. L'accordo di Schengen (1985) eliminò i controlli. Portogallo e Spagna sono gli unici due paesi ad abitare l'Iberia."},
 {q:"Quante specie di cicale esistono?",min:0,max:5000,risposta:3000,unit:"specie",curiosita:"Esistono circa 3.000 specie di cicale. La Magicicada americana emerge ogni 13 o 17 anni (numeri primi — strategia evolutiva). Le cicale producono suoni fino a 120 dB. Non fanno danni alle piante — solo ai nidi dove depongono le uova nei rami."},
 {q:"Quanti anni fa fu fondata l'Accademia della Crusca?",min:0,max:500,risposta:437,unit:"anni fa",curiosita:"L'Accademia della Crusca fu fondata a Firenze nel 1583 — 441 anni fa. È la più antica accademia linguistica del mondo. Pubblica il Vocabolario della lingua italiana. Il logo è un frullino per separare la farina (il buono) dalla crusca (il cattivo)."},
 {q:"Quanti kg pesa un gorilla maschio adulto?",min:0,max:500,risposta:180,unit:"kg",curiosita:"Un gorilla maschio adulto pesa 140-200 kg. I gorilla sono i nostri parenti più simili dopo scimpanzé e bonobo (98,3% DNA). Vivono in famiglie guidate da un silverback. Sono erbivori ma usano bastoni come strumenti."},
 {q:"Quanti anni fa fu composto il Don Giovanni di Mozart?",min:0,max:300,risposta:237,unit:"anni fa",curiosita:"Il Don Giovanni fu composto nel 1787 e andò in scena a Praga — 237 anni fa. Considerato il capolavoro di Mozart. La composizione richiese solo 6 settimane. Beethoven lo definì 'il più perfetto capolavoro del teatro musicale'."},
 {q:"Quante specie di coccodrilli esistono?",min:0,max:30,risposta:25,unit:"specie",curiosita:"Esistono 25 specie di coccodrilli, alligatori e gaviali. Il coccodrillo marino australiano è il più grande rettile del mondo (6 m, 1.000 kg). Hanno il morso più forte di qualsiasi animale vivente: 16.000 N."},
 {q:"Quanti anni fa nacque il Rinascimento Fiammingo?",min:0,max:700,risposta:600,unit:"anni fa circa",curiosita:"Il Rinascimento Fiammingo fiorì nei Paesi Bassi nel XV sec. — circa 600 anni fa. Jan van Eyck perfezionò la pittura ad olio. I Primitivi Fiamminghi come Van Eyck, Memling e Bruegel il Vecchio crearono ritratti e scene di vita cotidiana straordinari."},
 {q:"Quante ore ci vogliono per cucinare una cassoeula lombarda?",min:0,max:10,risposta:3,unit:"ore",curiosita:"La cassoeula lombarda (verza con costine e verzin) cuoce per 2-3 ore a fuoco lento. È il piatto invernale per eccellenza della Lombardia. Si usa la prima verza dopo le gelate invernali — il freddo la ammorbidisce e la rende dolce."},
 {q:"Quanti anni fa nacque Galileo Galilei?",min:0,max:500,risposta:460,unit:"anni fa",curiosita:"Galileo Galilei nacque il 15 febbraio 1564 a Pisa — 460 anni fa. Morì nel 1642 agli arresti domiciliari per ordine dell'Inquisizione. La sua condanna fu ritirata dalla Chiesa cattolica solo nel 1992, 350 anni dopo la morte."},
 {q:"Quante specie di mangrovie esistono?",min:0,max:100,risposta:70,unit:"specie",curiosita:"Esistono circa 70 specie di mangrovie. Le mangrovie filtrano il 90% del sale dall'acqua del mare. Proteggono le coste dagli tsunami e uragani. Assorbono 4 volte più CO2 per ettaro delle foreste tropicali. Stanno scomparendo al 1-3% l'anno."},
 {q:"Quanti anni fa fu costruito il Pantheon di Roma?",min:0,max:2000,risposta:1901,unit:"anni fa",curiosita:"Il Pantheon fu completato nell'Imperatore Adriano intorno al 125 d.C. — circa 1.900 anni fa. La cupola di cemento romano (43,3 m) rimase la più grande del mondo per 1.300 anni. L'occhio al centro (oculus, 9 m) è aperto — non entra pioggia perché drena."},
 {q:"Quante specie di scoiattoli esistono?",min:0,max:500,risposta:265,unit:"specie",curiosita:"Esistono 265 specie di scoiattoli. Nascondono cibo per l'inverno ma dimenticano il 25% dei nascondigli — contribuendo a piantare alberi involontariamente. Lo scoiattolo volante plana fino a 90 m tra gli alberi."},
 {q:"Quanti anni fa fu scoperto il DNA?",min:0,max:200,risposta:71,unit:"anni fa",curiosita:"La struttura del DNA fu scoperta nel 1953 da Watson e Crick (con i dati di Rosalind Franklin) — 71 anni fa. Il genoma umano ha 3 miliardi di coppie di basi. Se esteso, il DNA di una singola cellula è lungo 2 metri. Il sequenziamento del genoma umano fu completato nel 2003."},
 {q:"Quante specie di cinghiali esistono?",min:0,max:20,risposta:14,unit:"sottospecie",curiosita:"Il cinghiale (Sus scrofa) ha 14 sottospecie. In Europa è la specie di ungulato selvatico più comune. In Italia la popolazione è esplosa: da 100.000 negli anni '80 a 2 milioni oggi. Causano danni all'agricoltura per centinaia di milioni l'anno."},
 {q:"Quanti anni fa morì Napoleone Bonaparte?",min:0,max:300,risposta:203,unit:"anni fa",curiosita:"Napoleone morì il 5 maggio 1821 a Sant'Elena — 203 anni fa. Aveva 51 anni. La causa ufficiale fu cancro allo stomaco ma il mercurio nelle analisi dei capelli alimenta teorie sul veleno. Fu esiliato nell'isola atlantica nel 1815."},
 {q:"Quante specie di tartarughe marine esistono?",min:0,max:20,risposta:7,unit:"specie",curiosita:"Esistono 7 specie di tartarughe marine. La più grande è la liuto (600 kg, 2 m). Tornano a deporre le uova sulla stessa spiaggia dove sono nate, anche dopo 30 anni. La temperatura della sabbia determina il sesso delle uova."},
 {q:"Quanti anni fa fu costruita la prima ferrovia tedesca?",min:0,max:300,risposta:189,unit:"anni fa",curiosita:"La prima ferrovia tedesca aprì nel 1835 tra Norimberga e Fürth — circa 189 anni fa. La Germania sviluppò rapidamente la rete ferroviaria che fu determinante nell'unificazione e nell'industrializzazione del paese."},
 {q:"Quante specie di castori esistono?",min:0,max:10,risposta:2,unit:"specie",curiosita:"Esistono solo 2 specie di castori: europeo e americano. I castori costruiscono dighe modificando i corsi d'acqua più di qualsiasi altro animale tranne l'uomo. Le loro tane hanno entrate subacquee nascoste. I denti crescono ininterrottamente."},
 {q:"Quanti anni fa fu composta la Traviata di Verdi?",min:0,max:300,risposta:171,unit:"anni fa",curiosita:"La Traviata fu composta da Verdi nel 1853 — 171 anni fa. Basata su La Dame aux Camélias di Dumas figlio. Prima il pubblico veneziano la contestò, poi divenne l'opera più rappresentata al mondo. Alfredo e Violetta sono tra i più amati eroi operistici."},
 {q:"Quante specie di farfalle notturne (falene) esistono?",min:0,max:200000,risposta:160000,unit:"specie",curiosita:"Esistono circa 160.000 specie di falene — 10 volte più delle farfalle diurne. Athas atlas ha un'apertura alare di 30 cm. Le falene sono fondamentali per l'impollinazione notturna. La seta viene dal bozzolo della Bombyx mori."},
 {q:"Quanti anni fa fu inventato il Braille (scrittura per non vedenti)?",min:0,max:250,risposta:200,unit:"anni fa circa",curiosita:"Louis Braille inventò il suo sistema nel 1824 — 200 anni fa, a 15 anni. Lui stesso era cieco dall'età di 3 anni. Il Braille permette ai non vedenti di leggere toccando i punti in rilievo. Oggi è usato in 133 lingue."},
 {q:"Quante specie di gamberi esistono?",min:0,max:3000,risposta:2000,unit:"specie",curiosita:"Esistono circa 2.000 specie di gamberetti e gamberi. La tigre del gambero mantide può colpire con la velocità di una pallottola (23 m/s). Le loro chele creano cavitazione (bolle di vapore) che uccide le prede senza toccarle."},
 {q:"Quanti anni fa fu fondata la città di Venezia?",min:0,max:2000,risposta:1603,unit:"anni fa circa (421 d.C.)",curiosita:"Venezia fu fondata tradizionalmente il 25 marzo 421 d.C. — 1.603 anni fa. Costruita su 118 isole unite da 435 ponti. Governata per secoli da un Doge eletto. Fu la più grande potenza commerciale del Mediterraneo medievale."},
 {q:"Quante specie di muffe esistono?",min:0,max:100000,risposta:100000,unit:"specie",curiosita:"Esistono oltre 100.000 specie di muffe fungine. Alcune producono antibiotici (penicillina), altre micotossine mortali. Le muffe si riproducono con spore che possono sopravvivere per secoli. In Artide sono state trovate spore di 140 anni."},
 {q:"Quanti anni fa fu dipinto Il Bacio di Klimt?",min:0,max:150,risposta:116,unit:"anni fa",curiosita:"Il Bacio di Gustav Klimt fu dipinto nel 1907-1908 — circa 116 anni fa. Fa parte del Periodo d'Oro di Klimt, con uso di foglia d'oro. È esposto alla Galleria del Belvedere di Vienna. È uno dei quadri più riprodotti al mondo."},
 {q:"Quante km è lungo il Corridoio Adriatico (Autostrada A14)?",min:0,max:800,risposta:743,unit:"km",curiosita:"L'A14 Autostrada Adriatica è lunga 743 km da Bologna a Taranto — l'autostrada più lunga d'Italia e una delle più lunghe d'Europa. Costeggia il mare Adriatico e attraversa Emilia-Romagna, Marche, Abruzzo, Molise e Puglia."},
 {q:"Quanti anni fa nacque il movimento Impressionista?",min:0,max:200,risposta:150,unit:"anni fa circa",curiosita:"L'Impressionismo nacque nel 1874 con la prima mostra collettiva a Parigi — 150 anni fa. Il nome venne da un critico che derise 'Impressione, levar del sole' di Monet. Monet, Renoir, Degas e Pissarro ne furono i protagonisti."},
 {q:"Quante specie di alghe esistono?",min:0,max:1000000,risposta:300000,unit:"specie",curiosita:"Esistono tra 300.000 e 1 milione di specie di alghe. Producono il 50% dell'ossigeno terrestre attraverso la fotosintesi. Le alghe kelp crescono fino a 60 m e formano foreste sottomarini. Le microalghe potrebbero essere il carburante del futuro."},
 {q:"Quanti anni fa fu firmata la pace di Versailles (Prima Guerra Mondiale)?",min:0,max:200,risposta:105,unit:"anni fa",curiosita:"Il Trattato di Versailles fu firmato il 28 giugno 1919 — 105 anni fa. Impose alla Germania riparazioni di guerra impossibili (132 miliardi di marchi d'oro). Molti storici ritengono che le sue condizioni umilianti portarono al nazismo e alla Seconda Guerra Mondiale."},
 {q:"Quante specie di lombrichi marini (policheti) esistono?",min:0,max:20000,risposta:10000,unit:"specie",curiosita:"I policheti (vermi marini) hanno circa 10.000 specie. Vivono dal fondale oceanico alla riva. Alcune specie come i 'pompei worms' vivono vicino ai vulcani sottomarini a 80°C. Sono una fonte fondamentale di cibo per pesci e uccelli marini."},
 {q:"Quanti anni fa fu fondata la città di Napoli?",min:0,max:3000,risposta:2800,unit:"anni fa circa",curiosita:"Napoli fu fondata dai Greci come Neapolis (Nuova Città) intorno all'800-700 a.C. — circa 2.800 anni fa. La città precedente si chiamava Partenope. Oggi è la terza città italiana con 3 milioni di abitanti nell'area metropolitana."},
 {q:"Quante specie di mante esistono?",min:0,max:500,risposta:400,unit:"specie (mantis religiosa e parenti)",curiosita:"Esistono circa 400 specie di mantidi. La mantide religiosa può girare la testa di 180°. Le femmine mangiano i maschi durante l'accoppiamento in alcune specie — ma non sempre. Cacciano con velocità fulminea: 60-100 ms."},
 {q:"Quanti anni fa nacque il Futurismo italiano?",min:0,max:200,risposta:115,unit:"anni fa",curiosita:"Il Futurismo nacque nel 1909 con il Manifesto di Marinetti pubblicato su Le Figaro — 115 anni fa. Esaltava la velocità, la macchina e la guerra. Boccioni, Balla e Severini ne furono i principali pittori. Fu il primo movimento artistico italiano con eco mondiale."},
 {q:"Quanti km è lungo il traghetto Civitavecchia-Olbia?",min:0,max:1000,risposta:220,unit:"km circa",curiosita:"La rotta Civitavecchia-Olbia è lunga circa 220 km e dura 7-8 ore. È una delle rotte più frequentate del Mediterraneo. La Sardegna è la seconda isola del Mediterraneo per dimensioni (dopo la Sicilia) con 24.000 km²."},
 {q:"Quante specie di coccinelle esistono?",min:0,max:10000,risposta:5000,unit:"specie",curiosita:"Esistono circa 5.000 specie di coccinelle. Non tutte hanno 7 punti neri — alcune ne hanno 2, 14 o nessuno. I punti avvertono i predatori del sapore amaro. In inglese si chiamano 'ladybird' — uccellino della Madonna."},
 {q:"Quanti anni fa fu scritta la Costituzione degli Stati Uniti?",min:0,max:300,risposta:237,unit:"anni fa",curiosita:"La Costituzione USA fu scritta nel 1787 e ratificata nel 1788 — 237 anni fa. È la costituzione in vigore più antica del mondo. Ha solo 27 emendamenti in oltre 200 anni. Il Bill of Rights (i primi 10 emendamenti) fu aggiunto nel 1791."},
 {q:"Quante specie di peli (piante della famiglia Rosaceae) esistono?",min:0,max:5000,risposta:2500,unit:"specie nella famiglia Rosaceae",curiosita:"La famiglia delle Rosacee ha 2.500 specie tra cui rose, mele, pere, ciliegie, fragole e mandorle. La rosa è il simbolo dell'amore da millenni — presente nell'arte, poesia e religione di ogni cultura."},
 {q:"Quanti anni fa nacque il movimento dei diritti LGBT+ negli USA?",min:0,max:100,risposta:55,unit:"anni fa circa",curiosita:"I moti di Stonewall del giugno 1969 — 55 anni fa — segnarono la nascita del movimento moderno LGBT+. La polizia irruppe nel bar Stonewall Inn di New York e i clienti resistettero. Il primo Gay Pride fu nel 1970, un anno dopo."},
 {q:"Quante specie di anguille esistono?",min:0,max:1000,risposta:800,unit:"specie",curiosita:"Esistono circa 800 specie di anguille. L'anguilla europea migra dal Mediterraneo al Mar dei Sargassi (6.000 km) per riprodursi — poi muore. I giovani tornano in Europa senza averla mai vista prima."},
 {q:"Quanti anni fa fu costruita la statua della Libertà?",min:0,max:200,risposta:138,unit:"anni fa",curiosita:"La Statua della Libertà fu inaugurata il 28 ottobre 1886 — 138 anni fa. Alta 93 m con il piedistallo. Fu progettata da Bartholdi con la struttura interna in ferro di Eiffel (l'ingegnere della Torre Eiffel). È un dono della Francia agli USA."},
 {q:"Quante specie di cervi esistono?",min:0,max:100,risposta:47,unit:"specie",curiosita:"Esistono 47 specie di cervi. I palchi del cervo rosso sono le strutture ossee a crescita più veloce della natura: 2,5 cm al giorno. Solo i maschi (tranne la renna) li sviluppano. I cervi si orinatano sulle proprie gambe per attrarre le femmine."},
 {q:"Quanti anni fa fu inventata la macchina fotografica digitale?",min:0,max:100,risposta:49,unit:"anni fa",curiosita:"La prima fotocamera digitale fu inventata da Steven Sasson alla Kodak nel 1975 — 49 anni fa. Pesava 3,6 kg e produceva immagini in bianco e nero di 0,01 megapixel. Le fotocamere digitali consumer arrivarono nel mercato solo negli anni '90."},
 {q:"Quante specie di lupi esistono?",min:0,max:20,risposta:4,unit:"specie/sottospecie riconosciute",curiosita:"Esistono 4 specie di lupi: grigio (Canis lupus, con 38 sottospecie), rosso, etiope e himalayano. Il lupo è il progenitore del cane: addomesticato 15.000-40.000 anni fa. In Italia la popolazione di lupi appenninici è risalita a circa 3.000."},
 {q:"Quanti anni fa fu fondata la città di Amsterdam?",min:0,max:800,risposta:750,unit:"anni fa circa",curiosita:"Amsterdam fu fondata nel XIII sec. — circa 750 anni fa. Il nome significa 'diga sull'Amstel'. Ha 165 canali, 1.200 ponti e 100 km di vie d'acqua. Il suo porto nel XVII sec. era il più trafficato del mondo — la 'età dell'oro olandese'."},
 {q:"Quante specie di girasoli esistono?",min:0,max:100,risposta:70,unit:"specie nel genere Helianthus",curiosita:"Il genere Helianthus ha circa 70 specie. Il girasole segue il sole durante la crescita (eliotropismo) ma da adulto guarda sempre a est. Una testa di girasole contiene 1.000-2.000 semi. L'Italia produce 400.000 tonnellate di olio di girasole l'anno."},
 {q:"Quanti anni fa nacque il Romanticismo letterario?",min:0,max:300,risposta:230,unit:"anni fa circa",curiosita:"Il Romanticismo nacque in Germania alla fine del '700 — circa 220-230 anni fa. Foscolo, Leopardi e Manzoni ne furono i protagonisti italiani. Il Romanticismo esaltava l'emozione, la natura, il passato medievale e la nazionalità."},
 {q:"Quante specie di bisonti esistono?",min:0,max:10,risposta:2,unit:"specie",curiosita:"Esistono 2 specie: bisonte americano e bisonte europeo (wisente). Il bisonte americano fu quasi sterminato: da 60 milioni nel 1800 a 500 nel 1890. Oggi si è ripreso a 500.000. Il wisente fu estinto allo stato selvatico nel 1927, poi reintrodotto."},
 {q:"Quanti anni fa fu scritta la Commedia dell'Arte?",min:0,max:600,risposta:500,unit:"anni fa circa",curiosita:"La Commedia dell'Arte nacque in Italia nel XVI sec. — circa 500 anni fa. Arlecchino, Pantalone, il Dottore e la Colombina erano le maschere fisse. Gli attori improvvisavano. Fu la prima forma di teatro professionale con compagnie itineranti."},
 {q:"Quante specie di lamprede esistono?",min:0,max:100,risposta:40,unit:"specie",curiosita:"Esistono circa 40 specie di lamprede — pesci primitivi senza mascelle. Si attaccano ai pesci succhiando sangue. Sono tra i vertebrati più antichi: simili a quelli di 360 milioni di anni fa. Invasive nei Grandi Laghi americani, causano danni enormi."},
 {q:"Quanti anni fa fu costruita la prima centrale nucleare commerciale?",min:0,max:100,risposta:68,unit:"anni fa",curiosita:"La prima centrale nucleare commerciale fu Obninsk in URSS (1954) — 70 anni fa. La prima in Italia fu quella di Latina (1963). L'Italia uscì dal nucleare nel 1987 dopo Chernobyl. Oggi torna a discutere il rientro nel nucleare di nuova generazione."},
 {q:"Quante specie di piante succulent (piante grasse) esistono?",min:0,max:50000,risposta:10000,unit:"specie",curiosita:"Esistono circa 10.000 specie di piante succulente. Contengono riserve d'acqua nei tessuti fogliari o staminali. L'Aloe vera è la più usata in cosmetica e medicina. Gli agavi messicani producono il mezcal e il tequila."},
 {q:"Quanti anni fa nacque Giuseppe Garibaldi?",min:0,max:300,risposta:217,unit:"anni fa",curiosita:"Garibaldi nacque il 4 luglio 1807 a Nizza — 217 anni fa. Con i Mille sbarcò in Sicilia il 5 maggio 1860. Conquistò il Sud Italia e lo cedette a Vittorio Emanuele II. È l'eroe più popolare del Risorgimento italiano."},
 {q:"Quante specie di colibrì esistono?",min:0,max:500,risposta:360,unit:"specie",curiosita:"Esistono circa 360 specie di colibrì. Sono gli unici uccelli a volare all'indietro. Battono le ali fino a 80 volte al secondo. Il loro cuore batte 1.260 volte al minuto. Per sopravvivere alla notte entrano in torpore rallentando il metabolismo del 95%."},
 {q:"Quanti anni fa fu emanata la Legge Basaglia che chiuse i manicomi?",min:0,max:100,risposta:46,unit:"anni fa",curiosita:"La Legge 180 'Basaglia' fu approvata il 13 maggio 1978 — 46 anni fa. Chiuse i manicomi italiani — la prima legge al mondo di questo tipo. Franco Basaglia dimostrò che il contesto istituzionale peggiorava la malattia mentale."},
 {q:"Quante specie di cigni esistono?",min:0,max:20,risposta:6,unit:"specie",curiosita:"Esistono 6 specie di cigni. Il cigno reale (il più comune in Europa) non emette il canto melodioso della leggenda — emette grugniti e fischi. L'idea del 'canto del cigno' prima di morire è un mito. I cigni sono monogami a vita."},
 {q:"Quanti anni fa nacque Lucio Battisti?",min:0,max:100,risposta:81,unit:"anni fa",curiosita:"Lucio Battisti nacque il 5 marzo 1943 a Poggio Bustone (Rieti) — 81 anni fa. Morì nel 1998 a 55 anni. Con Mogol creò canzoni come Acqua Azzurra, Il mio canto libero, La canzone del sole — capolavori della musica italiana."},
 {q:"Quante specie di fenicotteri esistono?",min:0,max:20,risposta:6,unit:"specie",curiosita:"Esistono 6 specie di fenicotteri. Il colore rosa viene dai carotenoidi dei gamberi e alghe che mangiano — in cattività diventano bianchi senza quei pigmenti. Vivono in lagune saline in grandi stormi. Possono vivere 40 anni."},
 {q:"Quanti anni fa fu fondato il Touring Club Italiano?",min:0,max:200,risposta:131,unit:"anni fa",curiosita:"Il Touring Club Italiano fu fondato nel 1894 a Milano — 130 anni fa. Era nato per i ciclisti poi si estese a tutti i viaggiatori. Oggi ha 300.000 soci e pubblica le famose guide rosse. Gestisce i musei Mille Miglia e altri siti culturali."},
 {q:"Quante specie di tartarughe di terra esistono?",min:0,max:200,risposta:60,unit:"specie",curiosita:"Esistono circa 60 specie di tartarughe terrestri. La tartaruga gigante delle Galapagos può pesare 400 kg e vivere 200 anni. La tartaruga Herman (comune in Italia) vive 50-70 anni. In Italia è illegale catturarle."},
 {q:"Quanti anni fa fu fondato il giornale La Repubblica?",min:0,max:100,risposta:48,unit:"anni fa",curiosita:"La Repubblica fu fondata il 14 gennaio 1976 — 48 anni fa. Fondato da Eugenio Scalfari e Carlo Caracciolo. È diventato il secondo giornale italiano per diffusione dopo il Corriere della Sera. Scalfari la diresse fino al 1996."},
 {q:"Quante specie di gabbiani esistono?",min:0,max:100,risposta:54,unit:"specie",curiosita:"Esistono 54 specie di gabbiani. Sono tra gli uccelli più adattabili: vivono dalle coste artiche ai deserti. Negli ultimi decenni si sono insediati in città grazie ai rifiuti. Il gabbiano reale è diffusissimo nel Mediterraneo."},
 {q:"Quanti anni fa nacque la Pop Art?",min:0,max:100,risposta:70,unit:"anni fa circa",curiosita:"La Pop Art nacque negli anni '50 in Inghilterra e negli USA — circa 70 anni fa. Andy Warhol con le zuppe Campbell e le Marilyn Monroe, Roy Lichtenstein con i fumetti furono i protagonisti. Sfidò i confini tra arte alta e cultura popolare."},
 {q:"Quante specie di tarantole esistono?",min:0,max:1000,risposta:900,unit:"specie",curiosita:"Esistono circa 900 specie di tarantole. La tarantola di Goliath (Sudamerica) è il ragno più grande del mondo: 30 cm di apertura zampe, 170 g. Nonostante la fama, il morso delle tarantole è raramente pericoloso per l'uomo."},
 {q:"Quanti anni fa fu lanciato il primo satellite artificiale?",min:0,max:100,risposta:67,unit:"anni fa",curiosita:"Lo Sputnik 1 fu lanciato dall'URSS il 4 ottobre 1957 — 67 anni fa. Aveva dimensioni di una palla da basket. Il suo segnale radio fu ascoltato da tutto il mondo. Inaugurò la 'corsa allo spazio' tra USA e URSS."},
 {q:"Quante specie di ippopotami esistono?",min:0,max:10,risposta:2,unit:"specie",curiosita:"Esistono 2 specie: ippopotamo comune e ippopotamo pigmeo. L'ippopotamo comune è il terzo mammifero terrestre più grande (3-5 tonnellate) dopo elefante e rinoceronte bianco. Nonostante l'aspetto bonario, è responsabile di più morti umane in Africa."},
 {q:"Quanti anni fa fu costruita la Sagrestia Nuova di Michelangelo?",min:0,max:600,risposta:494,unit:"anni fa circa",curiosita:"La Sacrestia Nuova (Cappella Medicea) a Firenze fu progettata da Michelangelo tra il 1520 e il 1534 — circa 490-500 anni fa. Le sculture del Giorno e della Notte, dell'Aurora e del Crepuscolo sui sarcofagi sono tra le sue opere più potenti."},
 {q:"Quante specie di capodogli esistono?",min:0,max:10,risposta:3,unit:"specie",curiosita:"Esistono 3 specie di capodogli. Il capodoglio comune è il più grande predatore della Terra (fino a 18 m, 55 tonnellate). Può immergersi fino a 3 km di profondità. Il suo cervello pesa 8 kg — il più grande del regno animale."},
 {q:"Quanti anni fa fu fondata la Juventus Football Club?",min:0,max:200,risposta:127,unit:"anni fa",curiosita:"La Juventus fu fondata il 1° novembre 1897 a Torino — 127 anni fa. È il club italiano più titolato con 36 scudetti. La maglia zebrata bianconera fu adottata nel 1903. È chiamata 'La Vecchia Signora'."},
 {q:"Quante specie di cavallette esistono?",min:0,max:20000,risposta:11000,unit:"specie",curiosita:"Esistono circa 11.000 specie di cavallette e grilli. Gli sciami di locuste distruggono i raccolti da millenni — la Bibbia li cita come piaga. Una locusta mangia il suo peso ogni giorno. In Africa causano ancora carestie devastanti."},
 {q:"Quanti anni fa nacque Tiziano Vecellio (pittore)?",min:0,max:600,risposta:546,unit:"anni fa circa",curiosita:"Tiziano nacque intorno al 1477 a Pieve di Cadore (Belluno) — circa 546 anni fa. Visse quasi 100 anni e dipinse fino alla fine. Re, papi e imperatori lo corteggiarono. Carlo V d'Asburgo si chinò a raccogliere il pennello cadutogli."},
 {q:"Quante specie di crostacei esistono?",min:0,max:100000,risposta:68000,unit:"specie",curiosita:"Esistono circa 68.000 specie di crostacei. Comprendono granchi, aragoste, gamberi, barnacle e persino i minuscoli copepodi — base della catena alimentare marina. Il granchio ferro di cavallo non è un vero crostaceo ma un parente dei ragni."},
 {q:"Quanti anni fa fu fondata la città di Milano?",min:0,max:3000,risposta:2600,unit:"anni fa circa",curiosita:"Milano fu fondata dai Celti (Insubri) intorno al 600 a.C. — circa 2.600 anni fa. I Romani la conquistarono nel 222 a.C. e la chiamarono Mediolanum. Diventò capitale dell'Impero Romano d'Occidente nel 286 d.C. sotto Massimiano."},
 {q:"Quante specie di lombrichi (oligocheti) esistono?",min:0,max:10000,risposta:6000,unit:"specie",curiosita:"Esistono circa 6.000 specie di lombrichi. Un ettaro di suolo agricolo fertile può contenere 400.000-500.000 lombrichi. Producono fino a 50 tonnellate di deiezioni per ettaro all'anno — il miglior fertilizzante naturale."},
 {q:"Quanti anni fa fu pubblicato il romanzo I Promessi Sposi di Manzoni?",min:0,max:300,risposta:198,unit:"anni fa (prima edizione)",curiosita:"I Promessi Sposi furono pubblicati in prima edizione nel 1827 e revisionati nel 1840 — circa 197 anni fa. Manzoni ci lavorò dal 1821. Il romanzo è il più letto in lingua italiana dopo la Bibbia. La peste di Milano del 1630 è un personaggio del romanzo."},
 {q:"Quante specie di stelle marine esistono?",min:0,max:10000,risposta:2000,unit:"specie",curiosita:"Esistono circa 2.000 specie di stelle marine. Possono rigenerare interi arti perduti — alcune persino l'intero corpo da un solo braccio. Non hanno sangue: usano acqua marina nei loro 'piedi ambulacrali'. Alcune mangiano le ostriche aprendo i gusci."},
 {q:"Quanti anni fa fu fondata Mediaset?",min:0,max:100,risposta:42,unit:"anni fa circa",curiosita:"Mediaset fu fondata da Silvio Berlusconi nel 1978 — circa 46 anni fa. Dalla prima rete locale TV alla rete nazionale: Canale 5, Italia 1 e Rete 4. Berlusconi rivoluzionò la TV italiana con pubblicità, soap opera e reality. Oggi è controllata in parte da MFE-Mediaforeurope."},
 {q:"Quante specie di lombrichi si trovano in Italia?",min:0,max:200,risposta:60,unit:"specie",curiosita:"In Italia vivono circa 60 specie di lombrichi. La specie più comune è il Lumbricus terrestris. Il lombrico africano Microchaerus rappi può raggiungere 60 cm. Darwin scrisse 'La formazione della terra vegetale per opera dei lombrichi' nel 1881."},
 {q:"Quanti anni fa fu scritta la Gerusalemme Liberata di Torquato Tasso?",min:0,max:500,risposta:446,unit:"anni fa",curiosita:"La Gerusalemme Liberata fu completata nel 1575 — circa 449 anni fa. Racconta la Prima Crociata (1096-1099). Tasso era ossessionato dall'opera, continuamente riscritta. Dopo anni in manicomio morì nel 1595, vigilia del suo incoronamento poeta."},
 {q:"Quante specie di spugne marine esistono?",min:0,max:20000,risposta:9000,unit:"specie",curiosita:"Esistono circa 9.000 specie di spugne. Sono i più semplici animali multicellulari: niente organi, niente sistema nervoso. Filtrano 1.000 litri d'acqua al giorno. Le spugne carnivore del Pacifico profondo cacciano minuscoli crostacei."},
 {q:"Quanti anni fa fu composto il Requiem di Mozart?",min:0,max:300,risposta:233,unit:"anni fa",curiosita:"Mozart iniziò il Requiem nel 1791 — l'anno della sua morte. Rimase incompiuto — fu completato dal suo allievo Süssmayr. La leggenda vuole che Mozart lo componesse per se stesso. Il film Amadeus (1984) rese popolare questa storia."},
 {q:"Quante km è lungo il Gran Canale di Venezia?",min:0,max:10,risposta:4,unit:"km circa",curiosita:"Il Canal Grande è lungo 3,8 km e largo 30-90 m. Ospita 200 edifici gotici e rinascimentali sulle rive. Il Ponte di Rialto (1591) e il Ponte dell'Accademia lo attraversano. Il Palazzo Ducale e Ca' d'Oro sono tra i più famosi."},
 {q:"Quante specie di ragni granchio esistono?",min:0,max:3000,risposta:2000,unit:"specie",curiosita:"I ragni granchio (Thomisidae) hanno circa 2.000 specie. Non costruiscono ragnatele — aspettano le prede mimetizzati sui fiori. Possono cambiare colore per adattarsi ai fiori su cui si trovano. Il Misumena vatia europeo è bianco o giallo."},
 {q:"Quanti anni fa fu scritto il Canzoniere di Petrarca?",min:0,max:700,risposta:680,unit:"anni fa circa",curiosita:"Petrarca scrisse il Canzoniere tra il 1336 e il 1374 — circa 680-688 anni fa. I 366 sonetti (uno per ogni giorno dell'anno bisestile) cantano l'amore per Laura. Non si sa chi fosse Laura — forse un simbolo più che una persona reale."},
 {q:"Quante specie di cavalli selvatici esistono?",min:0,max:10,risposta:1,unit:"specie (Equus ferus)",curiosita:"Esistono solo 2 sottospecie di cavallo selvatico: il cavallo domestico inselvatichito e il cavallo di Przewalski, l'unico mai addomesticato. Quasi estinto, oggi è stato reintrodotto nelle steppe asiatiche con 2.000 esemplari."},
 {q:"Quanti anni fa nacque la fotografia a colori?",min:0,max:200,risposta:163,unit:"anni fa",curiosita:"La prima fotografia a colori fu realizzata dal fisico Maxwell nel 1861 — circa 163 anni fa. La Kodachrome film (1935) rese la fotografia a colori accessibile. Il digitale a colori arrivò negli anni '90. Le prime foto a colori usavano tre filtri RGB separati."},
 {q:"Quante specie di mantarays (mante) esistono?",min:0,max:20,risposta:2,unit:"specie",curiosita:"Esistono 2 specie di mante oceaniche (Mobula birostris e Mobula alfredi). Possono avere un'apertura alare di 7 m e pesare 2 tonnellate. Sono i pesci con il cervello più grande in rapporto al corpo. Hanno 'corni' cefalici che guidano il plankton in bocca."},
 {q:"Quanti anni fa nacque Dante Gabriel Rossetti (Preraffaelliti)?",min:0,max:250,risposta:196,unit:"anni fa",curiosita:"Dante Gabriel Rossetti nacque nel 1828 — 196 anni fa. Fu fondatore dei Preraffaelliti britannici, ispirati all'arte italiana prima di Raffaello. La Beata Beatrix (ispirata alla Beatrice dantesca) è la sua opera più famosa."},
 {q:"Quante specie di scarabei stercorari esistono?",min:0,max:10000,risposta:6000,unit:"specie",curiosita:"Esistono circa 6.000 specie di scarabei stercorari. Erano sacri nell'antico Egitto — simbolo del sole che rotola. Uno scarabeo stercorario da 10 g può rotolare una pallina di sterco 10 volte il suo peso. Riciclano nutrienti fondamentali."},
 {q:"Quanti anni fa fu costruita la Torre dei Lamberti a Verona?",min:0,max:1000,risposta:800,unit:"anni fa circa",curiosita:"La Torre dei Lamberti a Verona fu eretta tra il 1172 e il 1464 — circa 800 anni fa. Alta 84 m, è la più alta di Verona. Dall'alto si vedono la città medievale, l'Arena romana e le colline. Il suo orologio segnava il tempo cittadino."},
 {q:"Quante specie di lombriche di mare (sipuncula) esistono?",min:0,max:500,risposta:162,unit:"specie",curiosita:"I Sipuncula sono vermi marini con circa 162 specie. Si retraggono completamente quando disturbati (da cui 'peanut worm' — verme arachide). Vivono nei fondali da riva a 7.000 m. Alcuni sono tra 200 milioni di anni fa quasi invariati."},
 {q:"Quanti anni fa nacque il pittore El Greco?",min:0,max:500,risposta:483,unit:"anni fa",curiosita:"Doménikos Theotokópoulos (El Greco) nacque nel 1541 a Creta — 483 anni fa. Si formò a Venezia con Tiziano poi si trasferì a Toledo (Spagna). Le sue figure allungate e i colori irreali lo rendono uno dei pittori più originali della storia."},
 {q:"Quante specie di cetrioli di mare esistono?",min:0,max:2000,risposta:1700,unit:"specie",curiosita:"Esistono circa 1.700 specie di oloturia (cetrioli di mare). Sono echinodermi come stelle di mare. Se minacciati espellono i loro organi interni — che poi rigenerano. Sono una pregiata fonte di cibo in Asia orientale."},
 {q:"Quanti anni fa fu fondato l'Ordine Benedettino?",min:0,max:2000,risposta:1516,unit:"anni fa circa",curiosita:"San Benedetto fondò il suo ordine intorno al 529 d.C. — circa 1.495 anni fa. La Regola di San Benedetto (ora et labora — prega e lavora) fondò la vita monastica occidentale. Montecassino fu il primo monastero. I Benedettini salvarono molti testi antichi."},
 {q:"Quante specie di platelminti (vermi piatti) esistono?",min:0,max:100000,risposta:20000,unit:"specie",curiosita:"I platelminti hanno circa 20.000 specie tra planarie, tenie e distomi. Le planarie sono famose per la rigenerazione: tagliate in 200 pezzi rigenerano 200 individui completi. Le tenie possono raggiungere 10 m nell'intestino umano."},
 {q:"Quanti anni fa nacque Johann Sebastian Bach?",min:0,max:400,risposta:339,unit:"anni fa",curiosita:"Bach nacque il 31 marzo 1685 a Eisenach (Germania) — 339 anni fa. Compose oltre 1.000 opere. Le Invenzioni a due voci, i Preludi e Fughe del Clavicembalo Ben Temperato e la Messa in si minore sono tra i massimi capolavori della musica."},
 {q:"Quante specie di lombrichi australiani esistono?",min:0,max:5000,risposta:400,unit:"specie",curiosita:"L'Australia ha circa 400 specie di lombrichi endemici. Il lombrico gigante del Gippsland australiano può raggiungere 3 m di lunghezza — il più grande del mondo. Si sente il loro gorgoglio nel terreno quando si muovono."},
 {q:"Quanti anni fa fu composta la Messa da Requiem di Verdi?",min:0,max:200,risposta:150,unit:"anni fa",curiosita:"La Messa da Requiem di Verdi fu composta nel 1874 — 150 anni fa. Fu commissionata per commemorare il primo anniversario della morte di Alessandro Manzoni. Il 'Dies Irae' è tra i momenti più spettacolari della musica corale."},
 {q:"Quante specie di rettili esistono?",min:0,max:20000,risposta:11000,unit:"specie",curiosita:"Esistono circa 11.000 specie di rettili. Sono ectotermici — dipendono dal sole per scaldarsi. Hanno dominato la Terra per 165 milioni di anni (dinosauri). Il tuatara della Nuova Zelanda è l'unico sopravvissuto di un ordine risalente a 200 milioni di anni fa."},
 {q:"Quanti anni fa nacque Pablo Picasso?",min:0,max:200,risposta:143,unit:"anni fa",curiosita:"Picasso nacque il 25 ottobre 1881 a Málaga (Spagna) — 143 anni fa. Morì nel 1973 a 91 anni. Cofondò il Cubismo con Braque. Guernica (1937) è considerato il più grande dipinto politico del '900. Creò 13.500 dipinti, 100.000 stampe, 34.000 illustrazioni."},
 {q:"Quante specie di coleotteri (scarabei) esistono?",min:0,max:500000,risposta:400000,unit:"specie",curiosita:"I coleotteri hanno circa 400.000 specie — il 25% di tutte le specie animali. Quando chiese quale caratteristica della natura l'avrebbe fatto credere in Dio, il biologo Haldane rispose: 'Un'eccessiva passione per i coleotteri'."},
 {q:"Quanti anni fa nacque Benedetto Croce?",min:0,max:200,risposta:158,unit:"anni fa",curiosita:"Benedetto Croce nacque il 25 febbraio 1866 — 158 anni fa. Filosofo, storico e politico, fu il più grande intellettuale italiano del '900. Rifiutò il giuramento fascista nel 1931. Fondò e diresse La Critica per 50 anni."},
 {q:"Quante specie di roditori esistono?",min:0,max:5000,risposta:2200,unit:"specie",curiosita:"Esistono circa 2.200 specie di roditori — il 40% di tutti i mammiferi. I loro denti crescono ininterrottamente. Il capibara (Amazzonia) è il più grande: 65 kg. I topi muschiati canadesi costruiscono isole artificiali nei laghi."},
 {q:"Quanti anni fa fu composto il Flauto Magico di Mozart?",min:0,max:300,risposta:233,unit:"anni fa",curiosita:"Il Flauto Magico fu composto e eseguito per la prima volta nel 1791 — 233 anni fa, poco prima della morte di Mozart. È un'opera massonica con numerosi simboli esoterici. Papageno e la Regina della Notte sono personaggi amatissimi."},
 {q:"Quante specie di nematodi (vermi cilindrici) esistono?",min:0,max:1000000,risposta:25000,unit:"specie catalogate",curiosita:"I nematodi hanno circa 25.000 specie catalogate ma se ne stimano 1 milione. Il 60% degli animali del suolo sono nematodi. Il C. elegans è il primo organismo con ogni singolo neurone mappato (302 neuroni) — modello della biologia moderna."},
 {q:"Quanti anni fa nacque Ugo Foscolo?",min:0,max:300,risposta:246,unit:"anni fa",curiosita:"Ugo Foscolo nacque il 6 febbraio 1778 a Zante (Grecia) — 246 anni fa. 'I Sepolcri' e 'Le Grazie' sono le sue opere più famose. Morì povero a Londra nel 1827. Le sue spoglie furono portate a Firenze nella basilica di Santa Croce nel 1871."},
 {q:"Quante specie di aracnidi esistono?",min:0,max:200000,risposta:100000,unit:"specie",curiosita:"Gli aracnidi hanno circa 100.000 specie: ragni, scorpioni, acari, zecche e opilioni. L'acaro Demodex vive nei follicoli piliferi del 96% degli adulti umani — senza causare problemi. Gli scorpioni possono sopravvivere a temperatura di -7°C."},
 {q:"Quanti anni fa fu scritto il Boccaccio nel Decameron?",min:0,max:700,risposta:673,unit:"anni fa",curiosita:"Il Decameron fu scritto tra il 1349 e il 1353 — circa 671-675 anni fa. 100 novelle dette da 10 giovani rifugiati dalla Peste Nera. Boccaccio costruì un'opera di godimento della vita, in contrasto con l'orrore dell'epoca."},
 {q:"Quante specie di celenterati (meduse e coralli) esistono?",min:0,max:20000,risposta:10000,unit:"specie",curiosita:"I celenterati (cnidari) hanno circa 10.000 specie: meduse, anemoni, coralli e idre. Il corallo non è un animale singolo ma una colonia. Una medusa box australiana ha 64 occhi ma nessun cervello. Sente la luce con i manti."},
 {q:"Quanti anni fa morì Alessandro Manzoni?",min:0,max:200,risposta:151,unit:"anni fa",curiosita:"Alessandro Manzoni morì il 22 maggio 1873 — 151 anni fa. Aveva 88 anni — insolitamente longevo per l'epoca. La sua morte suscitò cordoglio nazionale. Verdi gli dedicò la Messa da Requiem composta per il primo anniversario della sua morte."},
 {q:"Quante specie di echinodermi esistono?",min:0,max:10000,risposta:7000,unit:"specie",curiosita:"Gli echinodermi (stelle marine, ricci di mare, cetrioli di mare) hanno circa 7.000 specie. Sono l'unico gruppo animale con simmetria pentaradiale. Non hanno cervello. Usano l'acqua marina come 'sangue' nel sistema vascolare acquifero."},
 {q:"Quanti anni fa fu inventato il motore diesel?",min:0,max:200,risposta:130,unit:"anni fa",curiosita:"Rudolf Diesel brevettò il suo motore nel 1892-1893 — circa 130 anni fa. Era più efficiente del motore a vapore. Diesel scomparve misteriosamente in mare nel 1913. Il motore diesel è ancora il più diffuso per navi, camion e mezzi pesanti."},
 {q:"Quante specie di poriferi (spugne) esistono?",min:0,max:15000,risposta:9000,unit:"specie",curiosita:"Le spugne (poriferi) hanno circa 9.000 specie. Sono organismi sessili — non si muovono. Vivono ovunque: dai mari polari ai tropici, dai 1 m ai 8.840 m. Alcune spugne di vetro (esactinoidae) nelle acque profonde australi vivono 10.000 anni."},
 {q:"Quanti anni fa nacque Giorgio Vasari (pittore e storico dell'arte)?",min:0,max:600,risposta:513,unit:"anni fa",curiosita:"Giorgio Vasari nacque il 30 luglio 1511 ad Arezzo — 513 anni fa. Le sue 'Vite dei più eccellenti pittori, scultori e architettori' (1550) fondarono la critica d'arte moderna. Progettò gli Uffizi e il Corridoio Vasariano di Firenze."},
 {q:"Quante specie di sifonofori esistono?",min:0,max:200,risposta:175,unit:"specie",curiosita:"I sifonofori sono colonie di individui specializzati (zoidi) che formano un superorganismo. La Physalia (caravella portoghese) è un sifonofore. Il Praya dubia raggiunge 50 m — uno degli animali più lunghi del mondo."},
 {q:"Quanti anni fa fu scoperta la Grotta Altamira (pitture rupestri)?",min:0,max:200,risposta:151,unit:"anni fa",curiosita:"Le pitture di Altamira in Spagna furono scoperte nel 1879 — 145 anni fa. Risalgono a 36.000-14.000 anni fa. Inizialmente gli esperti non credettero alla loro autenticità — troppo belle per l'uomo preistorico. Oggi sono patrimonio UNESCO."},
 {q:"Quante specie di oligocheti (lombrichi e simili) esistono?",min:0,max:10000,risposta:6000,unit:"specie",curiosita:"Gli oligocheti (lombrichi e simili) hanno circa 6.000 specie. Sono ermafroditi — ogni individuo ha sia organi maschili che femminili. Il lombrico Merlusia maxima del Congo può raggiungere 6,7 m — il più lungo del mondo."},
 {q:"Quanti anni fa nacque Antonio Vivaldi?",min:0,max:400,risposta:346,unit:"anni fa",curiosita:"Vivaldi nacque il 4 marzo 1678 a Venezia — 346 anni fa. Le Quattro Stagioni (1723) sono il concerto orchestrale più eseguito al mondo. Era chiamato il 'Prete Rosso' per i capelli rossi. Morì povero a Vienna nel 1741, dimenticato."},
 {q:"Quante specie di bivalvi (ostriche, cozze, vongole) esistono?",min:0,max:30000,risposta:15000,unit:"specie",curiosita:"I bivalvi hanno circa 15.000 specie. La venerpa gigante del Pacifico (Tridacna gigas) può pesare 300 kg. Le ostriche perlifere producono la perla come difesa da un granello di sabbia — processo che dura 2-7 anni."},
 {q:"Quanti anni fa fu costruita la prima linea del metrò di Londra?",min:0,max:200,risposta:161,unit:"anni fa",curiosita:"La prima metropolitana del mondo aprì a Londra il 10 gennaio 1863 — 161 anni fa. Usava locomotive a vapore — i passeggeri viaggiavano in un fumo terribile. Oggi ha 11 linee e 272 stazioni. È chiamata 'The Tube' (il tubo)."},
 {q:"Quante specie di cactus colonnari esistono?",min:0,max:500,risposta:200,unit:"specie",curiosita:"I cactus colonnari sono circa 200 specie. Il saguaro dell'Arizona cresce 1 cm l'anno — a 100 anni è alto 15 m. Un saguaro maturo può contenere 750 litri d'acqua. Fornisce casa e cibo a decine di specie: upupe, pipistrelli, serpenti."},
 {q:"Quanti anni fa nacque Giuseppe Mazzini?",min:0,max:300,risposta:219,unit:"anni fa",curiosita:"Giuseppe Mazzini nacque il 22 giugno 1805 a Genova — 219 anni fa. Fondò la Giovine Italia (1831) per l'indipendenza e l'unità d'Italia. Trascorse gran parte della vita in esilio. Le sue idee ispirarono molti movimenti nazionalisti europei."},
 {q:"Quante specie di gasteropodi (lumache e chiocciole) esistono?",min:0,max:100000,risposta:70000,unit:"specie",curiosita:"I gasteropodi hanno circa 70.000 specie — la classe di molluschi più grande. La chiocciola Achatina fulica africana può pesare 900 g. Alcune lumache di mare (opistobranchi) sono tra le creature più colorate del mondo."},
 {q:"Quanti anni fa nacque Niccolò Paganini?",min:0,max:300,risposta:242,unit:"anni fa",curiosita:"Paganini nacque il 27 ottobre 1782 a Genova — 242 anni fa. Era così bravo che fu accusato di aver venduto l'anima al diavolo. I 24 Capricci per violino solo sono tecnicamente impossibili per la maggior parte dei violinisti. Morì nel 1840."},
 {q:"Quante specie di protozoi parassiti dell'uomo esistono?",min:0,max:1000,risposta:30,unit:"specie principali",curiosita:"Circa 30 specie di protozoi parassitano l'uomo. La malaria (Plasmodium) uccide 600.000 persone l'anno. Il Toxoplasma gondii infetta il 30-50% degli esseri umani e può alterare il comportamento dell'ospite."},
 {q:"Quanti anni fa fu dipinta la Sistina di Raffaello (Stanza della Segnatura)?",min:0,max:600,risposta:515,unit:"anni fa circa",curiosita:"La Stanza della Segnatura con la Scuola di Atene fu dipinta nel 1509-1511 — circa 513-515 anni fa. È il capolavoro di Raffaello nella sua breve vita. Platone con il dito verso l'alto (Leonardo da Vinci) e Aristotele con il palmo verso il basso."},
 {q:"Quante specie di polpi abissali esistono?",min:0,max:500,risposta:100,unit:"specie circa",curiosita:"Negli abissi oceanici vivono circa 100 specie di polpi e calamari. Il polpo di Dumbo (Grimpoteuthis) vive a 5.000 m — il più profondo. Il calamaro gigante (Architeuthis) può raggiungere 13 m. Interi esemplari sono raramente osservati."},
 {q:"Quanti anni fa nacque Federico Chopin?",min:0,max:300,risposta:214,unit:"anni fa",curiosita:"Chopin nacque il 1° marzo 1810 a Żelazowa Wola (Polonia) — 214 anni fa. Si trasferì a Parigi dove suonava in salotti privati — detestava i grandi concerti. Amò George Sand per 9 anni. Morì di tubercolosi nel 1849, a 39 anni."},
 {q:"Quante specie di flatworm (planarie) esistono?",min:0,max:30000,risposta:20000,unit:"specie",curiosita:"I platelminti (vermi piatti) hanno circa 20.000 specie. Le planarie d'acqua dolce sono famose per la rigenerazione: ogni frammento ricresce in un individuo completo. Il verme fantasma (Symsagittifera roscoffensis) fa fotosintesi grazie ad alghe simbiotiche."},
 {q:"Quanti anni fa nacque Giovanni Verga?",min:0,max:300,risposta:184,unit:"anni fa",curiosita:"Giovanni Verga nacque il 2 settembre 1840 a Catania — 184 anni fa. Il Verismo di cui fu fondatore raccontava la vita dura dei contadini e pescatori siciliani. I Malavoglia e Mastro-don Gesualdo sono i suoi capolavori."},
 {q:"Quanti anni fa nacque Isaac Newton?",min:0,max:400,risposta:382,unit:"anni fa",curiosita:"Newton nacque il 25 dicembre 1642 a Woolsthorpe (Inghilterra) — 382 anni fa. Sviluppò la legge di gravitazione universale, il calcolo infinitesimale e la teoria della luce. Disse di aver scoperto la gravità vedendo cadere una mela — probabilmente una leggenda."},
 {q:"Quante specie di cormorani esistono?",min:0,max:50,risposta:40,unit:"specie",curiosita:"Esistono circa 40 specie di cormorani. Non hanno ghiandole uropigio — le ali si bagnano e devono asciugarle al sole. Sono straordinari subacquei: raggiungono 45 m di profondità. In Cina e Giappone vengono addestrati per pescare."},
 {q:"Quanti anni fa fu fondata la Croazia come stato indipendente?",min:0,max:50,risposta:33,unit:"anni fa",curiosita:"La Croazia dichiarò l'indipendenza dalla Jugoslavia il 25 giugno 1991 — 33 anni fa. La guerra seguente durò fino al 1995. È entrata nell'UE nel 2013 e nell'Eurozona nel 2023. Ha 1.246 isole nel mare Adriatico."},
 {q:"Quante calorie ha una porzione di lasagne al forno (300g)?",min:0,max:1000,risposta:450,unit:"kcal",curiosita:"Una porzione di lasagne al forno (300g) ha circa 400-500 kcal. La besciamella e il ragù sono le componenti più caloriche. Le lasagne verdi (con spinaci) sono tipiche di Bologna. La parola lasagna viene dal greco 'laganon' — pasta piatta."},
 {q:"Quanti anni fa fu completata la Cappella Sistina?",min:0,max:600,risposta:515,unit:"anni fa circa",curiosita:"Michelangelo completò il soffitto della Cappella Sistina nel 1512 — circa 512 anni fa. Ci lavorò 4 anni. La volta ha 1.100 m² di affreschi con 300 figure. Il 'Giudizio Universale' della parete fu aggiunto nel 1541."},
 {q:"Quante specie di aironi esistono?",min:0,max:100,risposta:64,unit:"specie",curiosita:"Esistono circa 64 specie di aironi e garzette. L'airone cenerino è il più comune in Italia — può stare immobile ore ad aspettare i pesci. La garzetta è tornata in Italia negli anni '80 dopo essere quasi scomparsa per le piume usate nella moda."},
 {q:"Quanti anni fa nacque Charles Darwin?",min:0,max:300,risposta:215,unit:"anni fa",curiosita:"Darwin nacque il 12 febbraio 1809 — 215 anni fa, stesso giorno di Lincoln. Pubblicò 'L'Origine delle Specie' nel 1859. Impiegò 20 anni a pubblicarla per paura delle conseguenze religiose. La teoria dell'evoluzione rimane la più confermata nella biologia."},
 {q:"Quante specie di merli esistono?",min:0,max:100,risposta:65,unit:"specie nel genere Turdus",curiosita:"Il genere Turdus include circa 65 specie. Il merlo comune è uno dei più intelligenti tra gli uccelli — può imitare suoni dell'ambiente urbano inclusi i cellulari. I maschi cantano per delimitare il territorio e attirare le femmine."},
 {q:"Quanti anni fa fu fondata la città di Firenze?",min:0,max:2500,risposta:2100,unit:"anni fa circa",curiosita:"Firenze fu fondata dai Romani come Florentia nel 59 a.C. — circa 2.080 anni fa. Nel Medioevo era la più ricca città d'Europa grazie alla lavorazione della lana e alla banca. I Medici governarono per secoli finanziando il Rinascimento."},
 {q:"Quante specie di rondini esistono?",min:0,max:100,risposta:83,unit:"specie",curiosita:"Esistono 83 specie di rondini e balestrucci. Migrano dall'Europa all'Africa subsahariana (10.000 km) ogni anno. Una rondine mangia circa 60 insetti al minuto durante il volo. Tornano sempre allo stesso nido — nido che riusano per anni."},
 {q:"Quanti anni fa fu fondata la città di Genova?",min:0,max:3000,risposta:2600,unit:"anni fa circa",curiosita:"Genova fu fondata dai Liguri intorno al VI sec. a.C. — circa 2.500-2.600 anni fa. Fu la principale rivale commerciale di Venezia nel Medioevo. Cristoforo Colombo era genovese. Il suo porto è ancora oggi il più grande d'Italia."},
 {q:"Quante specie di falchi esistono?",min:0,max:100,risposta:40,unit:"specie nel genere Falco",curiosita:"Il genere Falco ha circa 40 specie. Il falco pellegrino è il più veloce di tutti gli animali: in picchiata raggiunge 389 km/h. I falconi venivano addestrati per la caccia in tutto il mondo antico — la falconeria è patrimonio UNESCO."},
 {q:"Quanti anni fa nacque Sigmund Freud?",min:0,max:200,risposta:168,unit:"anni fa",curiosita:"Freud nacque il 6 maggio 1856 a Příbor (oggi Rep. Ceca) — 168 anni fa. Fondò la psicoanalisi. Fuggì da Vienna nel 1938 dopo l'annessione nazista e morì a Londra nel 1939. Il suo letto del paziente è nel museo di Hampstead."},
 {q:"Quante specie di pellicani esistono?",min:0,max:20,risposta:8,unit:"specie",curiosita:"Esistono 8 specie di pellicani. La sacca della gola può contenere 13 litri d'acqua. Pescano in gruppo guidando i pesci verso riva. Il pellicano dalmata è a rischio: ne restano circa 10.000, principalmente in Bulgaria e Grecia."},
 {q:"Quanti anni fa nacque Karl Marx?",min:0,max:300,risposta:206,unit:"anni fa",curiosita:"Marx nacque il 5 maggio 1818 a Treviri (Germania) — 206 anni fa. Il Manifesto Comunista (1848) con Engels e Il Capitale (1867) sono le sue opere principali. È sepolto a Londra — la sua tomba è uno dei memoriali più visitati al mondo."},
 {q:"Quante specie di ibis esistono?",min:0,max:50,risposta:28,unit:"specie",curiosita:"Esistono 28 specie di ibis. L'ibis sacro egiziano era venerato come simbolo del dio Thoth. L'ibis eremita è uno dei più rari d'Europa: ne restano circa 500 in Marocco. Recenti programmi di reintroduzione lo riportano in Austria."},
 {q:"Quanti anni fa nacque Galileo Galilei?",min:0,max:500,risposta:460,unit:"anni fa",curiosita:"Già risposto! Galileo nacque il 15 febbraio 1564 a Pisa. Ma ecco qualcosa in più: inventò il termoscopio (precursore del termometro), migliorò il telescopio e fu il primo a misurare la velocità della luce — anche se erroneamente."},
 {q:"Quante specie di upupe esistono?",min:0,max:10,risposta:3,unit:"specie",curiosita:"L'upupa (Upupa epops) ha 3 specie o sottospecie. Il suo caratteristico ciuffo si erge quando è eccitata. Il suo verso onomatopeico 'up-up-up' ha dato il nome in molte lingue. Nidifica nelle cavità degli alberi e non teme l'uomo."},
 {q:"Quanti anni fa nacque Wolfgang Amadeus Mozart?",min:0,max:300,risposta:268,unit:"anni fa",curiosita:"Mozart nacque il 27 gennaio 1756 a Salisburgo — 268 anni fa. A 5 anni componeva già minuetti. Morì a 35 anni nel 1791. Compose 626 opere catalogate nel Köchel. Il suo cranio è esposto (forse) nel Mozarteum di Salisburgo."},
 {q:"Quante specie di cicogne esistono?",min:0,max:30,risposta:19,unit:"specie",curiosita:"Esistono 19 specie di cicogne. La cicogna bianca migra dall'Europa all'Africa (12.000 km). Porta fortuna secondo la tradizione — in realtà porta insetti, topi e serpenti ai campi dove nidifica. In Italia è tornata a nidificare dopo decenni."},
 {q:"Quanti anni fa nacque Franz Kafka?",min:0,max:200,risposta:141,unit:"anni fa",curiosita:"Kafka nacque il 3 luglio 1883 a Praga — 141 anni fa. Morì di tubercolosi nel 1924 a 40 anni. Chiese all'amico Max Brod di bruciare tutti i suoi manoscritti — Brod disobbedì e pubblicò Il Processo, Il Castello e La Metamorfosi."},
 {q:"Quante specie di martin pescatore esistono?",min:0,max:100,risposta:90,unit:"specie",curiosita:"I martin pescatori (Alcedinidae) hanno circa 90 specie. Il martin pescatore comune tuffa a 40 km/h e non sbatte gli occhi sull'impatto. Il suo becco ispiró la forma del treno Shinkansen giapponese — riducendo il rumore del boom sonico in galleria."},
 {q:"Quanti anni fa nacque Friedrich Nietzsche?",min:0,max:200,risposta:180,unit:"anni fa",curiosita:"Nietzsche nacque il 15 ottobre 1844 — 180 anni fa. 'Così parlò Zarathustra', 'Al di là del bene e del male' e 'La gaia scienza' sono le sue opere principali. Impazzì nel 1889 — forse sifilide, forse un tumore. Morì nel 1900."},
 {q:"Quante specie di guepardo (ghepardo) esistono?",min:0,max:5,risposta:1,unit:"specie (con 5 sottospecie)",curiosita:"Il ghepardo (Acinonyx jubatus) ha 1 specie con 5 sottospecie. È il mammifero più veloce: 112 km/h in 3 secondi. Ne restano circa 7.100 in natura. Non ruggisce ma fa un suono simile a un gatto domestico. Non riesce a retrarre gli artigli."},
 {q:"Quanti anni fa nacque Immanuel Kant?",min:0,max:400,risposta:300,unit:"anni fa",curiosita:"Kant nacque il 22 aprile 1724 a Königsberg (oggi Kaliningrad, Russia) — 300 anni fa. Non lasciò mai la sua città. La 'Critica della ragion pura' (1781) rivoluzionò la filosofia. Kant aveva abitudini così precise che i vicini regolavano gli orologi sul suo passaggio."},
 {q:"Quante specie di alcedo (martin pescatore vero) esistono?",min:0,max:20,risposta:3,unit:"specie nel genere Alcedo",curiosita:"Il genere Alcedo ha 3 specie. L'alcione (martin pescatore comune) è lungo 16 cm ma è uno degli uccelli più veloci nell'immersione. In mitologia era la figlia di Eolo che si trasformò in uccello. I 'giorni dell'alcione' erano i giorni sereni d'inverno."},
 {q:"Quanti anni fa nacque Vincent van Gogh?",min:0,max:200,risposta:171,unit:"anni fa",curiosita:"Van Gogh nacque il 30 marzo 1853 — 171 anni fa. Vendette solo un dipinto in vita. Si tagliò l'orecchio sinistro e lo portò a una prostituta. Morì nel 1890 a 37 anni, forse suicidio. Oggi i suoi quadri valgono centinaia di milioni."},
 {q:"Quante specie di pangolini esistono?",min:0,max:10,risposta:8,unit:"specie",curiosita:"Esistono 8 specie di pangolini. Sono i mammiferi più trafficati al mondo — per le squame usate in medicina tradizionale cinese. Rotolano in palla difensiva come ricci. Mangiano formiche e termiti con una lingua più lunga del loro corpo."},
 {q:"Quanti anni fa nacque Fyodor Dostoevsky?",min:0,max:300,risposta:203,unit:"anni fa",curiosita:"Dostoevsky nacque il 11 novembre 1821 — 203 anni fa. Fu condannato a morte per le idee rivoluzionarie — graziato all'ultimo secondo davanti al plotone di esecuzione. Questa esperienza ispirò tutta la sua opera. Morì nel 1881."},
 {q:"Quante specie di orangutan esistono?",min:0,max:5,risposta:3,unit:"specie",curiosita:"Esistono 3 specie di orangutan: di Borneo, di Sumatra e di Tapanuli (scoperta nel 2017). Condividono il 96,9% del DNA umano. Usano foglie come ombrello. Il loro nome viene dal malese: 'orang' (persona) + 'utan' (foresta) = persona della foresta."},
 {q:"Quanti anni fa nacque Leo Tolstoy?",min:0,max:300,risposta:196,unit:"anni fa",curiosita:"Tolstoy nacque il 9 settembre 1828 — 196 anni fa. Guerra e Pace (1869) e Anna Karenina (1878) sono i suoi capolavori. A 50 anni abbandonò la ricchezza per vivere come contadino. Morì nel 1910 fuggendo da casa a 82 anni, in una stazione ferroviaria."},
 {q:"Quante specie di lontre esistono?",min:0,max:20,risposta:13,unit:"specie",curiosita:"Esistono 13 specie di lontre. La lontra di mare usa pietre come utensili per aprire i molluschi — uno dei rari usi di strumenti tra i mammiferi. Dormono sull'acqua tenendosi per mano a coppie per non separarsi."},
 {q:"Quanti anni fa nacque il compositore Brahms?",min:0,max:300,risposta:191,unit:"anni fa",curiosita:"Johannes Brahms nacque il 7 maggio 1833 ad Amburgo — 191 anni fa. Amico intimo di Clara Schumann (forse innamorato di lei). Le 4 Sinfonie, i Concerti per pianoforte e il Requiem Tedesco sono le sue opere principali."},
 {q:"Quante specie di koala esistono?",min:0,max:5,risposta:1,unit:"specie (Phascolarctos cinereus)",curiosita:"Il koala ha 1 specie. Non è un orso — è un marsupiale. I cuccioli nascono grandi come un fagiolo e rimangono nel marsupio 6 mesi. Le impronte digitali del koala sono quasi indistinguibili da quelle umane — hanno ingannato la polizia."},
 {q:"Quanti anni fa nacque il pittore Claude Monet?",min:0,max:200,risposta:184,unit:"anni fa",curiosita:"Monet nacque il 14 novembre 1840 a Parigi — 184 anni fa. Negli ultimi anni della vita diventò quasi cieco ma continuò a dipingere. Le ninfee di Giverny le dipinse per 30 anni. Bruciò 30 suoi quadri che non lo soddisfacevano."},
 {q:"Quante specie di ricci di mare esistono?",min:0,max:1000,risposta:950,unit:"specie",curiosita:"Esistono circa 950 specie di ricci di mare. Alcune vivono 200 anni. I denti (l'apparato di Aristotele) possono rosicchiare la roccia. In Sardegna le gonadi (ricci freschi) sono una prelibatezza. Le spine si rompono facilmente nella pelle."},
 {q:"Quanti anni fa nacque il filosofo Platone?",min:0,max:2500,risposta:2427,unit:"anni fa",curiosita:"Platone nacque intorno al 428 a.C. ad Atene — circa 2.427 anni fa. Fu discepolo di Socrate e maestro di Aristotele. Fondò l'Accademia — la prima università della storia. La sua 'Allegoria della caverna' è tra le metafore filosofiche più famose."},
 {q:"Quante specie di tartarughe di acqua dolce esistono?",min:0,max:300,risposta:260,unit:"specie",curiosita:"Esistono circa 260 specie di tartarughe di acqua dolce. La tartaruga dalla testa grossa (Platysternon megacephalum) non può rientrare del tutto nel guscio. La tartaruga azzannatrice americana può staccare un dito — la più aggressiva."},
 {q:"Quanti anni fa nacque il fisico Richard Feynman?",min:0,max:200,risposta:106,unit:"anni fa",curiosita:"Feynman nacque l'11 maggio 1918 — 106 anni fa. Vinse il Nobel per la fisica nel 1965 per la QED (elettrodinamica quantistica). Era famoso per le sue lezioni brillanti a Caltech. Craccare le casseforti della bomba atomica a Los Alamos era il suo hobby."},
 {q:"Quante specie di gechi esistono?",min:0,max:2000,risposta:1500,unit:"specie",curiosita:"Esistono circa 1.500 specie di gechi. Le ventose delle zampe funzionano grazie a milioni di setole che creano forza di Van der Waals. Un geco da 70g regge il proprio peso su un vetro liscio. Il Tokay geco di Singapore abbaia come un cane."},
 {q:"Quanti anni fa nacque il compositore Schubert?",min:0,max:300,risposta:227,unit:"anni fa",curiosita:"Franz Schubert nacque il 31 gennaio 1797 a Vienna — 227 anni fa. Morì a soli 31 anni nel 1828 — un anno dopo Beethoven. Compose oltre 600 Lieder (canzoni), 8 sinfonie e molta musica da camera. La Sinfonia Incompiuta (n.8) è la più famosa."},
 {q:"Quante specie di cerambici (coleotteri longicorni) esistono?",min:0,max:50000,risposta:26000,unit:"specie",curiosita:"I cerambici (longicorni) hanno circa 26.000 specie. Le loro antenne possono essere 3-4 volte la lunghezza del corpo. Le larve scavano tunnel nel legno e possono distruggere alberi da frutto. Il Cerambyx cerdo è protetto in Europa."},
 {q:"Quanti anni fa nacque il compositore Handel?",min:0,max:400,risposta:339,unit:"anni fa",curiosita:"Georg Friedrich Händel nacque il 23 febbraio 1685 ad Halle — 339 anni fa (stesso anno di Bach!). Visse in Inghilterra dal 1712. Il Messia (1741) con il coro dell'Alleluia fu scritto in 24 giorni. Il re Giorgio II si alzò in piedi durante l'Alleluia — da qui la tradizione."},
 {q:"Quante specie di mantidi preganti esistono?",min:0,max:3000,risposta:2400,unit:"specie",curiosita:"Le mantidi hanno circa 2.400 specie. Vedono in 3D con i loro grandi occhi composti. Riconoscono oggetti in movimento. In Cina le loro posture ispirarono uno stile di kung fu. La mantide orchidea malese è identica a un fiore per ingannare le prede."},
 {q:"Quanti anni fa nacque il musicista Jimi Hendrix?",min:0,max:100,risposta:82,unit:"anni fa",curiosita:"Hendrix nacque il 27 novembre 1942 a Seattle — 82 anni fa. Morì nel 1970 a 27 anni — il famoso 'Club dei 27'. In soli 4 anni di carriera rivoluzionò la chitarra elettrica. Era mancino ma suonava una Stratocaster per destrorsi capovolta."},
 {q:"Quante specie di falene del genere Attacus esistono?",min:0,max:20,risposta:10,unit:"specie circa",curiosita:"Il genere Attacus ha circa 10 specie tra le più grandi farfalle notturne. L'Attacus atlas ha un'apertura alare di 30 cm. Le sue ali terminano con punte simili ai capi di un serpente — per spaventare i predatori. Non hanno bocca da adulte."},
 {q:"Quanti anni fa nacque Friedrich Schiller?",min:0,max:300,risposta:265,unit:"anni fa",curiosita:"Schiller nacque il 10 novembre 1759 — 265 anni fa. Amico di Goethe. Scrisse 'I Masnadieri', 'Don Carlos' e 'Guglielmo Tell'. L'Ode alla Gioia (1785) fu poi musicata da Beethoven nella Nona Sinfonia — oggi è l'inno europeo."},
 {q:"Quante specie di odonati (libellule e damigelle) esistono?",min:0,max:7000,risposta:6000,unit:"specie",curiosita:"Esistono circa 6.000 specie di odonati. Le libellule esistono da 300 milioni di anni — quasi invariate. Possono volare a 50 km/h e catturare il 95% delle prede che inseguono — i più efficaci predatori nel regno animale in proporzione."},
 {q:"Quanti anni fa nacque Galileo Galilei (ripetiamo per errore)?",min:0,max:500,risposta:460,unit:"anni fa",curiosita:"Ecco una curiosità aggiuntiva: Galileo fu il primo a capire che oggetti di massa diversa cadono alla stessa velocità — avrebbe lanciato palle di cannone dalla Torre di Pisa. La storia è probabilmente leggendaria ma il principio è vero."},
 {q:"Quante specie di scarabei rinoceronte esistono?",min:0,max:1000,risposta:300,unit:"specie circa",curiosita:"Gli scarabei rinoceronte (Dynastinae) hanno circa 300 specie. Il più grande è l'Ercole (Dynastes hercules): 17 cm — uno degli insetti più grandi del mondo. Possono sollevare 850 volte il loro peso — proporzionalmente i più forti."},
 {q:"Quanti anni fa nacque lo scrittore Franz Kafka?",min:0,max:200,risposta:141,unit:"anni fa",curiosita:"Un'altra curiosità su Kafka: lavorava come assicuratore e odiava il suo lavoro. Scrisse di notte. Disse: 'C'è una speranza infinita, ma non per noi'. Le sue opere influenzarono Camus, Borges, Beckett e tutta la narrativa esistenzialista."},
 {q:"Quante specie di lombrichi giganti africani esistono?",min:0,max:100,risposta:30,unit:"specie circa",curiosita:"L'Africa ha circa 30 specie di lombrichi giganti. Il Microchaetus rappi del Sudafrica raggiunge 6,7 m — il più lungo al mondo. Il Megascolides australis australiano raggiunge 3 m. Questi giganti vivono in profondi tunnel nel terreno."},
 {q:"Quanti anni fa nacque il pittore Salvador Dalí?",min:0,max:200,risposta:120,unit:"anni fa",curiosita:"Dalí nacque l'11 maggio 1904 a Figueres (Spagna) — 120 anni fa. Fondò il Teatro-Museo Dalí nella sua città natale. La Persistenza della Memoria (1931) con gli orologi molli è la sua opera più famosa. Morì nel 1989 e fu sepolto sotto il suo museo."},
 {q:"Quante specie di calamari esistono?",min:0,max:1000,risposta:300,unit:"specie",curiosita:"Esistono circa 300 specie di calamari. Il calamaro gigante (Architeuthis dux) può raggiungere 13 m. Il calamaro vampiro (Vampyroteuthis infernalis) vive a 600-900 m e ha gli occhi più grandi in rapporto al corpo di qualsiasi animale."},
 {q:"Quanti anni fa nacque il pittore Caravaggio?",min:0,max:500,risposta:453,unit:"anni fa",curiosita:"Michelangelo Merisi da Caravaggio nacque il 29 settembre 1571 a Milano — 453 anni fa. Rivoluzionò la pittura con il chiaroscuro drammatico. Uccise un uomo in una rissa nel 1606 e fuggì da Roma. Morì misteriosamente nel 1610 a 38 anni."},
 {q:"Quante specie di polpi di barriera corallina esistono?",min:0,max:200,risposta:100,unit:"specie circa",curiosita:"Nelle barriere coralline vivono circa 100 specie di polpi. Il polpo mimetico (Thaumoctopus mimicus) imita forme di 15 animali diversi: sogliole, leone di mare, meduse. Il polpo dagli anelli blu (Hapalochlaena) contiene veleno sufficiente per uccidere 26 persone."},
 {q:"Quanti anni fa nacque il filosofo Aristotele?",min:0,max:2500,risposta:2386,unit:"anni fa",curiosita:"Aristotele nacque nel 384 a.C. a Stagira (Grecia) — circa 2.386 anni fa. Discepolo di Platone, maestro di Alessandro Magno. Fondò il Liceo ad Atene. Scrisse di logica, biologia, fisica, etica, politica, retorica e poetica — il più enciclopedico degli antichi."},
 {q:"Quante specie di platessa (pesci piatti) esistono?",min:0,max:1000,risposta:700,unit:"specie (Pleuronectiformes)",curiosita:"I Pleuronectiformes (pesci piatti) hanno circa 700 specie tra platessa, sogliola, rombo. Da larve sono simmetrici con un occhio per lato — poi si 'appiattiscono' e un occhio migra sull'altro lato. Vivono sul fondale camuffandosi."},
 {q:"Quanti anni fa nacque il compositore Debussy?",min:0,max:200,risposta:162,unit:"anni fa",curiosita:"Claude Debussy nacque il 22 agosto 1862 a Saint-Germain-en-Laye — 162 anni fa. Creò l'Impressionismo musicale. La suite 'Claire de Lune' e il Prélude à l'après-midi d'un faune sono le sue opere più famose. Morì durante i bombardamenti di Parigi nel 1918."},
 {q:"Quante specie di vongole esistono?",min:0,max:1000,risposta:500,unit:"specie circa",curiosita:"Le vongole (famiglia Veneridae) hanno circa 500 specie. L'Arctica islandica è il bivalve più longevo: può vivere 507 anni. Una vongola campionessa di età fu accidentalmente uccisa dai ricercatori che tentavano di scoprire quanti anni avesse."},
 {q:"Quanti anni fa nacque il filosofo Socrate?",min:0,max:2600,risposta:2474,unit:"anni fa",curiosita:"Socrate nacque intorno al 470 a.C. ad Atene — circa 2.474 anni fa. Non scrisse nulla — conosciamo il suo pensiero attraverso Platone e Senofonte. Fu condannato a morte nel 399 a.C. per 'corruzione della gioventù'. Bevve la cicuta con serenità."},
 {q:"Quante specie di polmonate (lumache terrestri) esistono?",min:0,max:50000,risposta:20000,unit:"specie",curiosita:"Le lumache terrestri polmonate hanno circa 20.000 specie. Il bave di lumaca è ricco di allantoina e mucopolisaccaridi — usato in cosmetica come anti-rughe. Le lumache africane giganti (Achatina) possono pesare 900 g."},
 {q:"Quanti anni fa nacque il compositore Mahler?",min:0,max:200,risposta:164,unit:"anni fa",curiosita:"Gustav Mahler nacque il 7 luglio 1860 — 164 anni fa. Le sue 9 Sinfonie sono tra le più lunghe e ambiziose della storia (la 3a dura 100 minuti). Direttore dell'Opera di Vienna. Morì nel 1911 a 50 anni di endocardite."},
 {q:"Quante specie di stelle cadenti (meteoroidi) bruciano ogni notte?",min:0,max:1000000,risposta:100,unit:"visibili dalla Terra ogni notte (circa)",curiosita:"Ogni notte cadono circa 100 meteore visibili. Le grandi piogge di stelle cadenti come le Perseidi (agosto) possono raggiungere 100 l'ora. I frammenti di meteora che raggiungono il suolo si chiamano meteoriti — circa 5 tonnellate al giorno."},
 {q:"Quanti anni fa nacque il pittore Sandro Botticelli?",min:0,max:600,risposta:580,unit:"anni fa",curiosita:"Sandro Botticelli nacque nel 1445 a Firenze — circa 579 anni fa. La Nascita di Venere e La Primavera sono i suoi capolavori. Lavorò per Lorenzo de' Medici. Dopo la morte di Lorenzo cadde in disgrazia e morì povero nel 1510."},
 {q:"Quante specie di lombriche bioluminescenti esistono?",min:0,max:100,risposta:30,unit:"specie circa",curiosita:"Circa 30 specie di lombrichi producono bioluminescenza quando disturbati. La Diplocardia longa americana emette luce verde-gialla. La bioluminescenza serve per confondere i predatori o attirare prede. Il lombrico di Endruweit svizzero è bioluminescente."},
 {q:"Quanti anni fa nacque il pianista e compositore Liszt?",min:0,max:300,risposta:213,unit:"anni fa",curiosita:"Franz Liszt nacque il 22 ottobre 1811 in Ungheria — 213 anni fa. Fu il primo pianista 'rock star' della storia: le donne svengono ai suoi concerti, raccoglievano le sue cicche come reliquie. Inventò il concerto solistico (recital) moderno."},
 {q:"Quante specie di acari (aracnidi microscopici) esistono?",min:0,max:100000,risposta:48000,unit:"specie",curiosita:"Esistono circa 48.000 specie di acari catalogate — e forse 1 milione in totale. Vivono ovunque: dal suolo artico agli intestini umani. L'acaro del formaggio (Tyroglyphus) vive nei formaggi stagionati. I Demodex vivono nei follicoli piliferi umani."},
 {q:"Quanti anni fa nacque il pittore Paul Gauguin?",min:0,max:200,risposta:176,unit:"anni fa",curiosita:"Gauguin nacque il 7 giugno 1848 — 176 anni fa. Lasciò moglie, figli e lavoro bancario per dipingere a Tahiti. Visse in povertà nelle isole del Pacifico. I suoi dipinti di donne polinesiane valgono oggi decine di milioni."},
 {q:"Quante specie di ditteri (mosche e zanzare) esistono?",min:0,max:200000,risposta:160000,unit:"specie",curiosita:"I ditteri hanno circa 160.000 specie: mosche, zanzare, pappataci, moscerini. La mosca tsè-tsè trasmette la malattia del sonno. Le larve di mosca (bigattini) sono usate in medicina per pulire le ferite infette — tornano di moda in chirurgia."},
 {q:"Quanti anni fa nacque il poeta Leopardi?",min:0,max:300,risposta:226,unit:"anni fa",curiosita:"Giacomo Leopardi nacque il 29 giugno 1798 a Recanati — 226 anni fa. Morì a 38 anni nel 1837. L'Infinito (1819) è la poesia italiana più letta al mondo. Soffriva di scoliosi e malattie agli occhi — studiava 10-14 ore al giorno da autodidatta."},
 {q:"Quante specie di imenotteri (api, vespe, formiche) esistono?",min:0,max:300000,risposta:150000,unit:"specie",curiosita:"Gli imenotteri hanno circa 150.000 specie. Sono tra gli insetti più evoluti — vivono in colonie complesse con divisione dei compiti. Le api e i calabroni hanno un pungiglione modificato dall'ovopositore. Le formiche sono le sole creature a coltivare funghi e allevare afidi."},
 {q:"Quanti anni fa nacque il poeta Arthur Rimbaud?",min:0,max:200,risposta:170,unit:"anni fa",curiosita:"Arthur Rimbaud nacque il 20 ottobre 1854 a Charleville — 170 anni fa. Scrisse tutte le sue poesie prima dei 19 anni poi smise per sempre. Divenne mercante di armi in Etiopia. Morì a 37 anni di cancro. Verlaine lo amò e lo sparò al polso."},
 {q:"Quante specie di lepidotteri (farfalle) esistono?",min:0,max:200000,risposta:180000,unit:"specie",curiosita:"I lepidotteri hanno circa 180.000 specie (90% falene, 10% farfalle diurne). La farfalla morpho blu del Brasile ha ali iridescenti senza pigmento — il colore viene dalla struttura nanostrutturata delle scaglie. Le antenne servono per olfatto e orientamento."},
 {q:"Quanti anni fa nacque il compositore Ravel?",min:0,max:200,risposta:149,unit:"anni fa",curiosita:"Maurice Ravel nacque il 7 marzo 1875 a Ciboure — 149 anni fa. Il Bolero (1928) è il pezzo orchestrale più famoso del '900. Durata 15 minuti, ipnotico crescendo su un'unica melodia ripetuta 18 volte. Ravel era un perfezionista ossessivo — alcune composizioni richiesero 10 anni."},
 {q:"Quante specie di tardigradi (animali microscopici indistruttibili) esistono?",min:0,max:2000,risposta:1300,unit:"specie",curiosita:"I tardigradi ('orsetti d'acqua') hanno circa 1.300 specie. Sopravvivono a -272°C, +150°C, raggi cosmici, vuoto dello spazio, 6.000 atm di pressione e 10 anni senza acqua. Sono stati esposti nello spazio aperto — sopravvissuti. Gli animali più resistenti della Terra."},
 {q:"Quanti anni fa nacque il pittore Jan Vermeer?",min:0,max:400,risposta:392,unit:"anni fa",curiosita:"Vermeer nacque nell'ottobre 1632 a Delft — 392 anni fa. Dipinse solo 34-36 opere in vita. La Ragazza con l'orecchino di perla (1665) è la Monna Lisa olandese. Morì a 43 anni, lasciando 11 figli e molti debiti. Fu dimenticato per 200 anni."},
 {q:"Quante specie di ctenofori (meduse a pettine) esistono?",min:0,max:200,risposta:100,unit:"specie",curiosita:"I ctenofori hanno circa 100-150 specie. Sono bioluminescenti e hanno ciglia iridescenti. Non hanno sistema nervoso centrale ma un sistema nervoso diffuso. Mangiano zooplancton. La loro bocca può inghiottire prede grandi quanto loro stessi."},
 {q:"Quanti anni fa nacque il musicista Bob Dylan?",min:0,max:100,risposta:83,unit:"anni fa",curiosita:"Bob Dylan nacque il 24 maggio 1941 — 83 anni fa. Il suo vero nome è Robert Allen Zimmerman. Nel 2016 ha vinto il Nobel per la Letteratura — il primo musicista. Blowin' in the Wind (1963) divenne l'inno del movimento per i diritti civili."},
 {q:"Quante specie di eufonie (uccelli del Nuovo Mondo) esistono?",min:0,max:50,risposta:30,unit:"specie",curiosita:"Le eufonie (Euphonia) hanno circa 30 specie — uccellini coloratissimi del Nuovo Mondo. I maschi sono iridescenti — giallo, blu, viola. Nidificano in cavità degli alberi. Si nutrono principalmente di frutti di vischio che contribuiscono a diffondere."},
 {q:"Quanti anni fa nacque il filosofo Hegel?",min:0,max:300,risposta:254,unit:"anni fa",curiosita:"Georg Wilhelm Friedrich Hegel nacque il 27 agosto 1770 a Stoccarda — 254 anni fa. La Fenomenologia dello Spirito (1807) è la sua opera principale. Marx lo capovolse: 'La dialettica hegeliana cammina in testa — io l'ho rimessa in piedi'."},
 {q:"Quante specie di terrapeni (tartarughe semiacquatiche) esistono?",min:0,max:200,risposta:50,unit:"specie circa",curiosita:"I terrapeni (Emydidae) hanno circa 50 specie. La tartaruga dalla guancia rossa americana è la più commercializzata come animale domestico — e la più invasiva nelle acque europee. In Italia è vietato commercializzarla dal 2012."},
 {q:"Quanti anni fa nacque il pittore Hieronymus Bosch?",min:0,max:600,risposta:574,unit:"anni fa circa",curiosita:"Bosch nacque intorno al 1450 a 's-Hertogenbosch — circa 574 anni fa. Il Giardino delle Delizie Terrestri (1500-1510) è un capolavoro visionario e grottesco. Ispirò Dalí e i surrealisti 4 secoli dopo. Quasi tutte le sue opere sono al Prado di Madrid."},
 {q:"Quante specie di pesci volanti esistono?",min:0,max:100,risposta:64,unit:"specie",curiosita:"Esistono 64 specie di pesci volanti (Exocoetidae). Planano fino a 45 secondi e raggiungono i 400 m di distanza battendo la coda 70 volte al secondo per prendere velocità. Arrivano a 60 km/h e si elevano fino a 6 m sopra il mare."},
 {q:"Quanti anni fa nacque il compositore Scarlatti?",min:0,max:400,risposta:339,unit:"anni fa",curiosita:"Domenico Scarlatti nacque il 26 ottobre 1685 a Napoli — 339 anni fa (stesso anno di Bach e Händel!). Compose 555 sonate per clavicembalo di straordinaria originalità. Visse in Spagna come maestro della principessa Maria Bárbara del Portogallo."},
 {q:"Quante specie di storni esistono?",min:0,max:200,risposta:120,unit:"specie (Sturnidae)",curiosita:"La famiglia degli storni ha circa 120 specie. Il murmure degli storni in Italia d'inverno è uno degli spettacoli naturali più straordinari: decine di migliaia di uccelli formano forme tridimensionali in cielo. Ogni uccello segue i 7 vicini più prossimi."},
 {q:"Quanti anni fa nacque il pittore Paul Cézanne?",min:0,max:200,risposta:185,unit:"anni fa",curiosita:"Cézanne nacque il 19 gennaio 1839 ad Aix-en-Provence — 185 anni fa. Fu rifiutato dal Salon parigino per anni. Amico di Zola (poi litigarono). Le sue nature morte e paesaggi del Mont Sainte-Victoire aprirono la strada al Cubismo."},
 {q:"Quante specie di tucani esistono?",min:0,max:50,risposta:43,unit:"specie",curiosita:"Esistono 43 specie di tucani. Il becco coloratissimo serve per la termoregolazione — cambia la vascolarizzazione per disperdere calore. Vivono nelle foreste tropicali americane. Il Toco toucan ha il becco più lungo in rapporto alla testa di qualsiasi uccello."},
 {q:"Quanti anni fa nacque il pittore Francisco Goya?",min:0,max:300,risposta:278,unit:"anni fa",curiosita:"Goya nacque il 30 marzo 1746 a Fuendetodos (Spagna) — 278 anni fa. Pittore di corte di re spagnoli, poi critico feroce del potere. Le 'Pinturas negras' (le pitture nere) del periodo finale, tra cui Saturno che divora un figlio, sono visioni oscure e potenti."},
 {q:"Quante specie di pappagalli cenerino africano esistono?",min:0,max:5,risposta:2,unit:"specie",curiosita:"Esistono 2 sottospecie del pappagallo grigio africano (Psittacus erithacus). Alex, un grigio africano dello zoo di Harvard, riconobbe 50 oggetti, 7 colori, capì il concetto di zero e morì nel 2007 dicendo al suo ricercatore 'Ti voglio bene. Sii buono'."},
 {q:"Quanti anni fa nacque il pittore Edvard Munch?",min:0,max:200,risposta:161,unit:"anni fa",curiosita:"Edvard Munch nacque il 12 dicembre 1863 a Oslo — 161 anni fa. L'Urlo (1893) è l'opera d'arte più iconica della storia dopo la Monna Lisa. La figura non urla — è sopraffatta dall'urlo della natura. Fu rubato due volte dal museo osloense."},
 {q:"Quante specie di passeriformi (passeri, pettirossi, rondini) esistono?",min:0,max:10000,risposta:6500,unit:"specie",curiosita:"I passeriformi hanno circa 6.500 specie — il 60% di tutti gli uccelli. Si dividono in oscillini (che imparano il canto) e suboscini. Il lyrebird australiano imita perfettamente altri uccelli, motoseghe, scatti di macchine fotografiche e allarmi d'auto."},
 {q:"Quanti anni fa nacque il compositore Sibelius?",min:0,max:200,risposta:159,unit:"anni fa",curiosita:"Jean Sibelius nacque l'8 dicembre 1865 in Finlandia — 159 anni fa. Il Finlandia (1899) divenne l'inno informale della resistenza finlandese contro la dominazione russa. Gli ultimi 30 anni di vita non compose nulla — il 'Silenzio di Järvenpää'."},
 {q:"Quante specie di fringillidi (fringuelli e cardellini) esistono?",min:0,max:250,risposta:220,unit:"specie",curiosita:"I fringillidi hanno circa 220 specie: fringuelli, cardellini, verdoni, ciuffolotti. I fringuelli di Darwin nelle Galapagos — 14 specie derivate da un antenato comune — illustrarono la teoria dell'evoluzione. I maschi cantano per attirare le femmine."},
 {q:"Quanti anni fa nacque il pittore Egon Schiele?",min:0,max:200,risposta:134,unit:"anni fa",curiosita:"Egon Schiele nacque il 12 giugno 1890 a Tulln (Austria) — 134 anni fa. Morì a soli 28 anni nella pandemia di influenza spagnola (1918). I suoi autoritratti tormentati e i nudi angolari e crudi sono tra le opere più potenti dell'Espressionismo."},
 {q:"Quante specie di picchi esistono?",min:0,max:250,risposta:236,unit:"specie (Picidae)",curiosita:"La famiglia dei picchi ha 236 specie. Beccano il legno a 20 volte al secondo (3.000 g di accelerazione — 250 volte ciò che fa svenire un astronauta). Il cervello è avvolto in osso spugnoso e un lungo osso ioide avvolge il cranio come una cintura di sicurezza."},
 {q:"Quanti anni fa nacque il pittore Frida Kahlo?",min:0,max:200,risposta:117,unit:"anni fa",curiosita:"Frida Kahlo nacque il 6 luglio 1907 a Città del Messico — 117 anni fa. A 18 anni sopravvisse a un incidente terribile. Durante la convalescenza iniziò a dipingere. I suoi 143 dipinti (55 autoritratti) esplorano dolore, identità e politica."},
 {q:"Quante specie di cetoni (coleotteri fiori) esistono?",min:0,max:5000,risposta:4000,unit:"specie (Cetoniidae)",curiosita:"I cetoni hanno circa 4.000 specie. Sono i coleotteri più colorati d'Europa — iridescenti come gioielli. Si nutrono di polline e nettare — importanti impollinatori. Le larve vivono nel legno marcio per anni prima di metamorfosarsi."},
 {q:"Quanti anni fa nacque il pittore Wassily Kandinsky?",min:0,max:200,risposta:158,unit:"anni fa",curiosita:"Kandinsky nacque il 16 dicembre 1866 a Mosca — 158 anni fa. È considerato il padre della pittura astratta — con 'Primo acquerello astratto' (1910). Credeva che i colori avessero equivalenti sonori. Era sincrostetico: 'sentiva' i colori come musica."},
 {q:"Quante specie di usignoli esistono?",min:0,max:30,risposta:15,unit:"specie nel genere Luscinia",curiosita:"Il genere Luscinia (usignoli) ha circa 15 specie. L'usignolo comune canta sia di giorno che di notte. Il suo canto ha fino a 1.000 note al secondo. In molte culture è simbolo dell'amore e del dolore. Raramente visibile — si nasconde tra le foglie."},
 {q:"Quanti anni fa nacque l'architetto Antoni Gaudí?",min:0,max:200,risposta:172,unit:"anni fa",curiosita:"Gaudí nacque il 25 giugno 1852 a Reus (Spagna) — 172 anni fa. Morì investito da un tram nel 1926 — fu scambiato per un mendicante per i suoi vestiti usurati. Donò tutto il suo patrimonio alla Sagrada Família. È in corso la sua beatificazione."},
 {q:"Quante specie di cardellini esistono?",min:0,max:50,risposta:30,unit:"specie nel genere Carduelis",curiosita:"Il genere Carduelis ha circa 30 specie. Il cardellino comune è uno degli uccelli da gabbia più comuni — illegale catturarlo in Italia dal 1977. La sua canzone complessa ha fino a 25 variazioni di frase. In libertà forma stormi misti con altri fringillidi."},
 {q:"Quanti anni fa nacque il pittore Giorgio de Chirico?",min:0,max:200,risposta:136,unit:"anni fa",curiosita:"De Chirico nacque il 10 luglio 1888 a Volos (Grecia) — 136 anni fa. Padre della Pittura Metafisica con le sue piazze deserte e ombre allungate. Ispirò il Surrealismo ma poi lo rinnegò. Trascorse gli ultimi 40 anni a Roma."},
 {q:"Quante specie di sternidi (rondini di mare) esistono?",min:0,max:50,risposta:44,unit:"specie",curiosita:"Gli sternidi hanno circa 44 specie. La sterna artica compie la migrazione più lunga di qualsiasi animale: 71.000 km l'anno dall'Artico all'Antartico e ritorno. In una vita percorre 2,4 milioni di km — equivalente a tre viaggi sulla Luna."},
 {q:"Quanti anni fa nacque il compositore Puccini?",min:0,max:200,risposta:166,unit:"anni fa",curiosita:"Giacomo Puccini nacque il 22 dicembre 1858 a Lucca — 166 anni fa. Tosca, La Bohème, Madama Butterfly e Turandot (incompiuta) sono le sue opere principali. La Bohème del 1896 è tuttora l'opera più rappresentata al mondo ogni anno."},
 {q:"Quante specie di macachi esistono?",min:0,max:30,risposta:23,unit:"specie",curiosita:"Esistono 23 specie di macachi. I macachi giapponesi (gli unici primati a vivere nella neve) fanno i bagni nelle terme naturali. I macachi rhesus furono i primi primati nello spazio (1948). I macachi di Barberia (Gibraltar) sono gli unici primati selvatici in Europa."},
 {q:"Quanti anni fa nacque il pittore Jackson Pollock?",min:0,max:200,risposta:112,unit:"anni fa",curiosita:"Jackson Pollock nacque il 28 gennaio 1912 — 112 anni fa. Inventò il drip painting — sgocciolando vernice su tele stese a terra. Morì in un incidente d'auto nel 1956 a 44 anni. Nel 2006 il suo 'N.5' fu venduto per 140 milioni di dollari."},
 {q:"Quante specie di cercopitechi esistono?",min:0,max:40,risposta:26,unit:"specie nel genere Cercopithecus",curiosita:"Il genere Cercopithecus ha circa 26 specie. Il cercopiteco diane ha un sistema di allarme vocale sofisticato: emette grida diverse per aquile, leopardi e serpenti — altri animali le capiscono e reagiscono appropriatamente."},
 {q:"Quanti anni fa nacque il pittore Edward Hopper?",min:0,max:200,risposta:142,unit:"anni fa",curiosita:"Hopper nacque il 22 luglio 1882 — 142 anni fa. Il suo 'Nighthawks' (1942) — quattro persone in un bar notturno — è uno dei quadri più famosi del '900. Rappresenta la solitudine urbana americana. È ispirato al Greenwich Village di New York."},
 {q:"Quante specie di scimpanzé esistono?",min:0,max:5,risposta:2,unit:"specie",curiosita:"Esistono 2 specie di scimpanzé: comune (Pan troglodytes) e bonobo (Pan paniscus). I bonobo risolvono i conflitti attraverso l'attività sessuale — la 'pace attraverso l'amore'. Condividono il 98,7% del DNA umano. Usano oltre 30 strumenti diversi."},
 {q:"Quanti anni fa nacque il poeta Pablo Neruda?",min:0,max:200,risposta:120,unit:"anni fa",curiosita:"Pablo Neruda (Ricardo Reyes Basoalto) nacque il 12 luglio 1904 in Cile — 120 anni fa. Nobel per la Letteratura 1971. I suoi Venti Poesie d'Amore sono la raccolta di poesie in spagnolo più venduta di sempre. Morì nel 1973, pochi giorni dopo il golpe di Pinochet."},
 {q:"Quante specie di otarie esistono?",min:0,max:20,risposta:16,unit:"specie (Otariidae)",curiosita:"Le otarie (leoni marini e fur seal) hanno 16 specie. Possono girare le pinne posteriori in avanti e 'camminare' sulla riva. Il leone marino californiano è il pinnipede più addestrato — usato dalla Marina USA per recupero di oggetti in mare."},
 {q:"Quanti anni fa nacque il filosofo John Locke?",min:0,max:400,risposta:392,unit:"anni fa",curiosita:"Locke nacque il 29 agosto 1632 — 392 anni fa. Il suo 'Trattato sul governo civile' (1689) ispirò la Dichiarazione di Indipendenza USA. Jefferson la copiò quasi letteralmente. Locke introdusse i concetti di diritti naturali, tabula rasa e tolleranza religiosa."},
 {q:"Quante specie di marmotte esistono?",min:0,max:20,risposta:15,unit:"specie",curiosita:"Esistono 15 specie di marmotte. La marmotta alpina (Marmota marmota) fischia quando vede i predatori — il fischio ha significati diversi per 'aquila' e 'volpe'. Ibernano fino a 7 mesi. La Groundhog Day americana si basa sulla marmotta americana."},
 {q:"Quanti anni fa nacque lo scrittore James Joyce?",min:0,max:200,risposta:142,unit:"anni fa",curiosita:"James Joyce nacque il 2 febbraio 1882 a Dublino — 142 anni fa. L'Ulisse (1922) è considerato il romanzo più innovativo del '900 — ma anche uno dei più difficili. L'ultimo capitolo di Molly Bloom è un monologo interiore di 40 pagine senza punteggiatura."},
 {q:"Quante specie di capibara e idrochere esistono?",min:0,max:5,risposta:2,unit:"specie",curiosita:"Esistono 2 specie di capibara (Hydrochoerus). Il capibara comune è il più grande roditore al mondo: 60-70 kg. Semi-acquatico, abita le rive dei fiumi sudamericani. È sorprendentemente socievole — vive pacificamente con uccelli, scimmie e caimani."},
 {q:"Quanti anni fa nacque il pittore Giorgio Morandi?",min:0,max:200,risposta:134,unit:"anni fa",curiosita:"Giorgio Morandi nacque il 20 luglio 1890 a Bologna — 134 anni fa. Dipinse quasi esclusivamente nature morte con bottiglie e vasi. Non lasciò mai Bologna. La sua discrezione e semplicità lo rendono unico nell'arte italiana del '900. Il Museo Morandi è a Bologna."},
 {q:"Quante specie di puzzole esistono?",min:0,max:20,risposta:12,unit:"specie",curiosita:"Esistono 12 specie di puzzole (Mephitidae). Il liquido odoroso (mercaptani) viene sparato fino a 6 m e rimane per settimane. I predatori imparano presto ad evitarle. Il succo di pomodoro è il rimedio tradizionale contro l'odore."},
 {q:"Quanti anni fa nacque il filosofo Rousseau?",min:0,max:350,risposta:312,unit:"anni fa",curiosita:"Jean-Jacques Rousseau nacque il 28 giugno 1712 a Ginevra — 312 anni fa. 'Il contratto sociale' e 'L'Emilio' sono le sue opere principali. L'idea del 'buon selvaggio' corrotto dalla civiltà ispirò la Rivoluzione Francese e il Romanticismo."},
 {q:"Quante specie di ghiri esistono?",min:0,max:30,risposta:28,unit:"specie (Gliridae)",curiosita:"I ghiri (Gliridae) hanno 28 specie. Il ghiro comune iberna per 7-8 mesi — il mammifero che iberna più a lungo in Europa. I Romani li allevavano come prelibatezza in contenitori di coccio detti 'gliraria'. Sono protetti in Italia."},
 {q:"Quanti anni fa nacque lo scrittore Ernest Hemingway?",min:0,max:200,risposta:125,unit:"anni fa",curiosita:"Hemingway nacque il 21 luglio 1899 a Oak Park (Illinois) — 125 anni fa. Nobel per la Letteratura 1954. Il Vecchio e il Mare, Addio alle Armi e Per chi suona la campana sono le sue opere principali. Si suicidò nel 1961 con un fucile da caccia."},
 {q:"Quante specie di donnole esistono?",min:0,max:30,risposta:18,unit:"specie nel genere Mustela",curiosita:"Il genere Mustela ha 18 specie: donnole, ermellini, visoni, frettini. La donnola comune (Mustela nivalis) è il più piccolo carnivoro terrestre: 100 g ma attacca prede 10 volte più grandi. Entra in qualsiasi buco dove passa la testa."},
 {q:"Quanti anni fa nacque il pittore Marc Chagall?",min:0,max:200,risposta:137,unit:"anni fa",curiosita:"Marc Chagall nacque il 7 luglio 1887 a Vitebsk (Bielorussia) — 137 anni fa. I suoi dipinti poetici con violinisti, spose volanti e animali colorati uniscono folklore ebraico e modernismo. Le vetrate del Duomo di Metz e dell'ONU sono sue opere."},
 {q:"Quante specie di tassi esistono?",min:0,max:10,risposta:8,unit:"specie (Melinae)",curiosita:"La sottofamiglia dei tassi ha 8 specie. Il tasso comune è sorprendentemente aggressivo — può scacciare un cane. Costruisce complessi sistemi di tane (sett) usati per generazioni. Il miele badger africano è considerato l'animale più coraggioso della Terra."},
 {q:"Quanti anni fa nacque il compositore Elgar?",min:0,max:200,risposta:167,unit:"anni fa",curiosita:"Edward Elgar nacque il 2 giugno 1857 a Broadheath (Inghilterra) — 167 anni fa. Le Variazioni Enigma e la marcia Pomp and Circumstance (Graduation March) sono le sue opere più note. Nonostante il tono imperiale, era cattolico e figlio di un negoziante."},
 {q:"Quante specie di cervi volanti (coleotteri) esistono?",min:0,max:2000,risposta:1200,unit:"specie (Lucanidae)",curiosita:"I cervi volanti (Lucanidae) hanno circa 1.200 specie. Il cervo volante europeo (Lucanus cervus) è il più grande coleottero d'Italia — fino a 9 cm. Le mandibole ipertrofiche dei maschi servono solo per i combattimenti rituali. Le larve vivono nel legno per 3-5 anni."},
 {q:"Quanti anni fa nacque lo scrittore Albert Camus?",min:0,max:200,risposta:111,unit:"anni fa",curiosita:"Camus nacque il 7 novembre 1913 in Algeria — 111 anni fa. Nobel per la Letteratura 1957 a soli 44 anni. Lo straniero e La peste sono le sue opere principali. Morì in un incidente stradale nel 1960 — in tasca fu trovato un biglietto ferroviario non usato."},
 {q:"Quante specie di rondoni esistono?",min:0,max:100,risposta:99,unit:"specie (Apodidae)",curiosita:"I rondoni hanno 99 specie. Passano quasi tutta la vita in volo — dormono, si accoppiano, mangiano in aria. Atterrano solo per nidificare. Possono volare continuativamente per 10 mesi. Hanno le zampe così corte che non riescono a ripartire dal suolo."},
 {q:"Quanti anni fa nacque il pittore Paul Klee?",min:0,max:200,risposta:145,unit:"anni fa",curiosita:"Paul Klee nacque il 18 dicembre 1879 — 145 anni fa. Insegnò al Bauhaus. La sua arte unisce pittura, musica (era violinista) e teoria del colore. La sua opera più famosa, Twittering Machine (1922), anticipa il mondo digitale dei computer."},
 {q:"Quante specie di trilobiti sono conosciute?",min:0,max:20000,risposta:17000,unit:"specie (estinte)",curiosita:"I trilobiti hanno circa 17.000 specie fossili note. Vissero per 270 milioni di anni (500-250 milioni di anni fa) e furono tra i primi animali con occhi complessi. La loro estinzione nella grande crisi del Permiano (252 milioni di anni fa) spazzò via il 90% delle specie marine."},
 {q:"Quanti anni fa nacque il filosofo Voltaire?",min:0,max:350,risposta:330,unit:"anni fa",curiosita:"Voltaire (François-Marie Arouet) nacque il 21 novembre 1694 — 330 anni fa. Candide (1759) è il suo romanzo più famoso — satira dell'ottimismo cieco. Fu incarcerato alla Bastiglia due volte ed esiliato. La sua tomba è al Panthéon di Parigi."},
 {q:"Quante specie di dinoflagellati bioluminescenti esistono?",min:0,max:1000,risposta:70,unit:"specie circa",curiosita:"Circa 70 specie di dinoflagellati emettono luce. Creano le famose 'onde blu' nelle notti calde al mare. Il Noctiluca scintillans illumina le onde in blu elettrico. La bioluminescenza è una risposta meccanica — quando l'acqua si muove, si illuminano."},
 {q:"Quanti anni fa nacque il compositore Richard Wagner?",min:0,max:300,risposta:211,unit:"anni fa",curiosita:"Wagner nacque il 22 maggio 1813 a Lipsia — 211 anni fa. L'Anello del Nibelungo dura 15 ore distribuite in 4 opere. Creò il 'Gesamtkunstwerk' (opera d'arte totale) che unisce musica, testo, scenografia e luci. Hitler lo adorava — questione controversa."},
 {q:"Quante specie di miriapodi (centopiedi e millepiedi) esistono?",min:0,max:20000,risposta:13000,unit:"specie",curiosita:"I miriapodi hanno circa 13.000 specie. Il Scolopendra gigantea può raggiungere 30 cm e attaccare piccoli uccelli. I millepiedi (Diplopoda) hanno fino a 750 zampe — non 1.000. Il Illacme plenipes californiano ha 750 zampe — il record."},
 {q:"Quanti anni fa nacque lo scrittore Jorge Luis Borges?",min:0,max:200,risposta:125,unit:"anni fa",curiosita:"Borges nacque il 24 agosto 1899 a Buenos Aires — 125 anni fa. Scrisse solo racconti e poesie — mai romanzi. La Biblioteca di Babele, Finzioni e L'Aleph sono le sue raccolte principali. Diventò cieco ma continuò a dettare le sue opere fino alla morte nel 1986."},
 {q:"Quante specie di protisti esistono?",min:0,max:200000,risposta:75000,unit:"specie",curiosita:"I protisti hanno circa 75.000 specie catalogate — eucarioti unicellulari che non sono né animali, né piante, né funghi. Includono amebe, ciliati, flagellati e alghe unicellulari. Le diatomee (protisti) producono il 20% dell'ossigeno terrestre."},
 {q:"Quanti anni fa nacque il pittore Piero della Francesca?",min:0,max:600,risposta:614,unit:"anni fa circa",curiosita:"Piero della Francesca nacque intorno al 1410 a Sansepolcro (Arezzo) — circa 614 anni fa. I suoi affreschi ad Arezzo (Leggenda della Vera Croce) sono tra i massimi capolavori del Rinascimento. Era anche matematico e scrisse trattati sulla prospettiva."},
 {q:"Quante specie di archaebatteri (archea) esistono?",min:0,max:10000,risposta:500,unit:"specie catalogate",curiosita:"Sono state catalogate circa 500 specie di archea — ma se ne stimano milioni. Vivono negli ambienti più estremi: vulcani sottomarini a 120°C, laghi acidi, sale a saturazione. Sono più vicini geneticamente agli eucarioti che ai batteri."},
 {q:"Quanti anni fa nacque il pittore Luca Signorelli?",min:0,max:600,risposta:584,unit:"anni fa circa",curiosita:"Signorelli nacque intorno al 1440 a Cortona — circa 584 anni fa. Gli affreschi del Giudizio Universale nella Cattedrale di Orvieto (1499-1504) anticipano Michelangelo di decenni per l'anatomia e il dinamismo. Era già leggenda quando Michelangelo era giovane."},
 {q:"Quante specie di archei termofili estremi esistono?",min:0,max:1000,risposta:100,unit:"specie circa",curiosita:"Circa 100 specie di archea vivono a temperature superiori a 80°C. Il Pyrolobus fumarii vive a 113°C vicino ai vulcani sottomarini. Studiare questi organismi ha permesso di sviluppare la PCR (amplificazione DNA) usata in medicina e archeologia."},
 {q:"Quanti anni fa nacque il compositore Offenbach?",min:0,max:250,risposta:205,unit:"anni fa",curiosita:"Jacques Offenbach nacque il 20 giugno 1819 a Colonia — 205 anni fa. Inventò l'operetta francese. Orfeo all'inferno (1858) e La Belle Hélène (1864) satirizzano il Secondo Impero francese. Il Cancan nella versione finale è la sua musica più famosa."},
 {q:"Quante specie di batteri anaerobici esistono?",min:0,max:100000,risposta:1000,unit:"specie principali",curiosita:"Circa 1.000 specie di batteri anaerobi sono ben studiate ma ne esistono decine di migliaia. Il Clostridium botulinum produce la tossina più letale — 1g uccide 1 milione di persone. Lo stesso Botox (usato in cosmetica) è una versione purificata."},
 {q:"Quanti anni fa nacque il pittore Ambrogio Lorenzetti?",min:0,max:800,risposta:740,unit:"anni fa circa",curiosita:"Lorenzetti nacque intorno al 1285 a Siena — circa 740 anni fa. Gli affreschi 'Allegoria del Buono e Cattivo Governo' a Siena (1338-39) sono la prima rappresentazione laica di una città medievale e del territorio. Morì nella Peste Nera del 1348."},
 {q:"Quante specie di virus sono conosciuti?",min:0,max:100000,risposta:6000,unit:"specie classificate",curiosita:"Sono classificate circa 6.000 specie di virus — ma se ne stimano 1-10 miliardi in natura. I batteriofagi (virus che infettano i batteri) sono i più numerosi: 10^31 nel mondo — più di qualsiasi altra entità biologica. I virus marini sono la principale causa di morte dei batteri oceanici."},
 {q:"Quanti anni fa nacque il pittore Pinturicchio?",min:0,max:600,risposta:564,unit:"anni fa circa",curiosita:"Pinturicchio (Bernardino di Betto) nacque intorno al 1460 a Perugia — circa 564 anni fa. Decorò le Stanze Borgia in Vaticano sotto Papa Alessandro VI Borgia. Le sue scene sono tra le più narrative e colorite del Rinascimento."},
 {q:"Quante specie di archeobatteri alofili esistono?",min:0,max:500,risposta:100,unit:"specie circa",curiosita:"Gli archea alofili vivono in ambienti ultra-salati (lago di sale, mare Morto). L'Halobacterium salinarum colora di rosa o rosso i laghi salati — come il lago Hiller australiano. Producono ATP usando la luce solare senza clorofilla."},
 {q:"Quanti anni fa nacque il pittore Andrea Mantegna?",min:0,max:600,risposta:593,unit:"anni fa",curiosita:"Mantegna nacque il 1431 a Isola di Carturo — 593 anni fa. La Camera degli Sposi a Mantova (1465-74) è il primo trompe-l'oeil della storia dell'arte occidentale. Il Cristo in Scorcio è il suo capolavoro di illusione prospettica."},
 {q:"Quante specie di alghe verdi esistono?",min:0,max:10000,risposta:8000,unit:"specie (Chlorophyta)",curiosita:"Le alghe verdi (Chlorophyta) hanno circa 8.000 specie. Sono i probabili antenati delle piante terrestri — contengono gli stessi pigmenti (clorofilla a e b). Le Chlamydomonas unicellulari nuotano con 2 flagelli e hanno un 'occhio' fotosensibile."},
 {q:"Quanti anni fa nacque il pittore Gentile da Fabriano?",min:0,max:700,risposta:650,unit:"anni fa circa",curiosita:"Gentile da Fabriano nacque intorno al 1370 a Fabriano (Marche) — circa 654 anni fa. L'Adorazione dei Magi (1423) agli Uffizi è il capolavoro del gotico internazionale. Fu il pittore più celebre d'Europa nei primi decenni del '400."},
 {q:"Quante specie di cianobatteri esistono?",min:0,max:10000,risposta:2000,unit:"specie",curiosita:"I cianobatteri hanno circa 2.000 specie. Sono i primi organismi ad aver prodotto ossigeno — 2,7 miliardi di anni fa. La 'Grande Ossidazione' che cambiò l'atmosfera terrestre fu opera loro. Sono anche i progenitori dei cloroplasti nelle cellule vegetali."},
 {q:"Quanti anni fa nacque il pittore Perugino?",min:0,max:600,risposta:576,unit:"anni fa circa",curiosita:"Pietro Perugino (Pietro di Cristoforo Vannucci) nacque intorno al 1448 a Città della Pieve — circa 576 anni fa. Maestro di Raffaello. I suoi affreschi nella Cappella Sistina (1481-82) erano lì prima di Michelangelo. Il suo stile dolce e sereno fu modello per generazioni."},
 {q:"Quante specie di foraminiferi esistono?",min:0,max:10000,risposta:9000,unit:"specie",curiosita:"I foraminiferi hanno circa 9.000 specie viventi e 40.000 fossili. Le loro minuscole conchiglie calcaree costituiscono il calcare — il materiale del Colosseo e delle piramidi. Studiando i foraminiferi fossili si ricostruisce il clima passato."},
 {q:"Quanti anni fa nacque il pittore Masaccio?",min:0,max:700,risposta:623,unit:"anni fa",curiosita:"Masaccio nacque il 21 dicembre 1401 a San Giovanni Valdarno — 623 anni fa. Morì a soli 26 anni. La Cappella Brancacci a Firenze con la Cacciata dal Paradiso e il Tributo rivoluzionò la pittura con la prospettiva e il chiaroscuro."},
 {q:"Quante specie di copepodi (crostacei microscopici) esistono?",min:0,max:20000,risposta:13000,unit:"specie",curiosita:"I copepodi hanno circa 13.000 specie. Sono i crostacei più numerosi — forse gli animali più abbondanti della Terra (10^18 esemplari). Sono la base della catena alimentare marina: il krill, le balene e i pesci dipendono da loro."},
 {q:"Quanti anni fa nacque il pittore Ghirlandaio?",min:0,max:600,risposta:576,unit:"anni fa circa",curiosita:"Domenico Ghirlandaio nacque il 1448 a Firenze — 576 anni fa. Fu il maestro che formò Michelangelo. Le sue scene della vita della Vergine e del Battista in Santa Maria Novella ritraggono realisticamente i ricchi fiorentini del '400."},
 {q:"Quante specie di gasteropodi terrestri esistono?",min:0,max:40000,risposta:25000,unit:"specie",curiosita:"I gasteropodi terrestri (lumache con o senza guscio) hanno circa 25.000 specie. Alcune hanno gusci alti 30 cm. Vengono considerati pesti in agricoltura ma sono importanti decompositori. La chiocciola escargot francese è la specie più consumata."},
 {q:"Quanti anni fa nacque il pittore Paolo Uccello?",min:0,max:700,risposta:633,unit:"anni fa",curiosita:"Paolo Uccello (Paolo di Dono) nacque nel 1397 a Pratovecchio — 627 anni fa. Era ossessionato dalla prospettiva — la studiava di notte mentre la moglie lo supplicava di dormire. La Battaglia di San Romano (1438-40) in tre pannelli è il suo capolavoro."},
 {q:"Quante specie di olmi (Ulmus) esistono?",min:0,max:100,risposta:45,unit:"specie",curiosita:"Il genere Ulmus ha circa 45 specie. La grafiosi dell'olmo (malattia fungina portata da un coleottero) ha sterminato quasi tutti gli olmi europei dal 1970. L'olmo campestre viveva 500 anni — oggi raramente supera i 30 anni prima di morire."},
 {q:"Quanti anni fa nacque il pittore Antonio Pisanello?",min:0,max:700,risposta:634,unit:"anni fa circa",curiosita:"Pisanello nacque intorno al 1390 a Pisa o Verona — circa 634 anni fa. Fu il più grande medaglista del Rinascimento. I suoi affreschi nel Palazzo Ducale di Mantova (cavalieri arturiani) sono perduti in parte. I suoi disegni di animali sono insuperati."},
 {q:"Quante specie di alghe rosse esistono?",min:0,max:20000,risposta:7000,unit:"specie (Rhodophyta)",curiosita:"Le alghe rosse (Rhodophyta) hanno circa 7.000 specie. Crescono a grandi profondità grazie ai ficoeritrina che catturano lunghezze d'onda blu-verdi. L'agar agar (gelificante alimentare), la carragenina e il nori dei sushi vengono da alghe rosse."},
 {q:"Quanti anni fa nacque il pittore Simone Martini?",min:0,max:800,risposta:737,unit:"anni fa circa",curiosita:"Simone Martini nacque intorno al 1285 a Siena — circa 737 anni fa. L'Annunciazione (1333) agli Uffizi è capolavoro del gotico senese. Amico di Petrarca ad Avignone, ritrasse la sua amata Laura — il ritratto è perduto."},
 {q:"Quante specie di emidatteri (cimici) esistono?",min:0,max:100000,risposta:80000,unit:"specie (Hemiptera)",curiosita:"Gli emidatteri (Hemiptera) hanno circa 80.000 specie: cimici, afidi, cocciniglie, cicale. Gli afidi possono riprodursi per partenogenesi (senza maschi) e produrre 50 generazioni l'anno. Una singola afide potrebbe teoricamente produrre una colonia da 600 miliardi in un'estate."},
 {q:"Quanti anni fa nacque il pittore Duccio di Buoninsegna?",min:0,max:800,risposta:770,unit:"anni fa circa",curiosita:"Duccio di Buoninsegna nacque intorno al 1255 a Siena — circa 770 anni fa. La Maestà (1311) del Duomo di Siena fu portata in processione trionfale per le strade. Fondò la scuola senese che rivaleggiò con Giotto e la scuola fiorentina."},
 {q:"Quante specie di dinoflagellati esistono?",min:0,max:5000,risposta:2000,unit:"specie",curiosita:"I dinoflagellati hanno circa 2.000 specie. Sono responsabili delle 'maree rosse' — fioriture tossiche che avvelenano i molluschi. La Pyrocystis fusiformis è bioluminescente. I dinoflagellati forniscono il 90% del nutrimento dei coralli come simbionti."},
 {q:"Quanti anni fa nacque il pittore Cimabue?",min:0,max:800,risposta:775,unit:"anni fa circa",curiosita:"Cimabue (Cenni di Pepo) nacque intorno al 1240 a Firenze — circa 775 anni fa. Maestro di Giotto, fu il primo a rompere con la tradizione bizantina rigida. Il Crocifisso di Arezzo e la Maestà di Santa Trinità segnano l'inizio dell'arte moderna."},
 {q:"Quante specie di briozoi marini esistono?",min:0,max:10000,risposta:6000,unit:"specie",curiosita:"I briozoi hanno circa 6.000 specie viventi e 15.000 fossili. Sono colonie di minuscoli individui (zoidi) che vivono in strutture calcaree. Sembrano alghe o coralli ma sono animali. Producono la briostatina — studiata come anti-tumorale."},
 {q:"Quanti anni fa nacque il pittore Filippo Lippi?",min:0,max:600,risposta:618,unit:"anni fa circa",curiosita:"Fra Filippo Lippi nacque intorno al 1406 a Firenze — circa 618 anni fa. Frate carmelitano, rapì la monaca Lucrezia Buti che divenne sua compagna. Padre del pittore Filippino Lippi. Le sue Madonne dai tratti umani e dolci rivoluzionarono l'iconografia."},
 {q:"Quante specie di graptoliti sono conosciute?",min:0,max:5000,risposta:2000,unit:"specie (estinte)",curiosita:"I graptoliti sono organismi coloniali estinti con circa 2.000 specie. Vissero dal Cambriano al Carbonifero (510-320 milioni di anni fa). Le loro strutture chitinose si conservano come tracce argentee nelle rocce. Erano simili ai briozoi moderni."},
 {q:"Quanti anni fa nacque il pittore Andrea del Castagno?",min:0,max:700,risposta:614,unit:"anni fa circa",curiosita:"Andrea del Castagno nacque intorno al 1421 a Castagno (Mugello) — circa 603 anni fa. L'Ultima Cena di Sant'Apollonia a Firenze è un'opera potente con figure monumentali che anticipano il tardo Rinascimento. Era famoso per il realismo duro e psicologico."},
 {q:"Quante specie di ictiosauri sono conosciute?",min:0,max:200,risposta:100,unit:"specie (estinte)",curiosita:"Gli ittiosauri hanno circa 100 specie fossili. Vissero 250-90 milioni di anni fa — rettili marini con forma simile ai delfini (convergenza evolutiva). Alcune specie raggiunsero 26 m. Partorievano in acqua — trovati fossili di parto."},
 {q:"Quanti anni fa nacque il pittore Benozzo Gozzoli?",min:0,max:700,risposta:614,unit:"anni fa circa",curiosita:"Benozzo Gozzoli nacque intorno al 1421 a Firenze — circa 603 anni fa. Il ciclo di affreschi del Palazzo Medici-Riccardi (1459-60) con il Corteo dei Re Magi è una festa di colori con centinaia di figure — ritratti di Medici e dignitari."},
 {q:"Quante specie di plesiosauri sono conosciute?",min:0,max:200,risposta:120,unit:"specie (estinte)",curiosita:"I plesiosauri hanno circa 120 specie fossili. Vissero 215-66 milioni di anni fa. Il collo lungo del Plesiosaurus poteva raggiungere i 6 m. Il mostro di Loch Ness è spesso paragonato a un plesiosauro — teoricamente impossibile sopravvissuto ai giorni nostri."},
 {q:"Quante specie di bambù esistono?",min:0,max:2000,risposta:1500,unit:"specie",curiosita:"Il bambù ha circa 1.500 specie. Cresce fino a 91 cm al giorno — il più veloce tra le piante. È tecnicamente un'erba, non un albero. I panda giganti mangiano quasi esclusivamente bambù — 12 kg al giorno. I fusti possono sostituire l'acciaio nelle costruzioni."},
 {q:"Quante specie di felci esistono?",min:0,max:15000,risposta:10500,unit:"specie",curiosita:"Le felci (Polypodiopsida) hanno circa 10.500 specie. Sono tra le piante più antiche — 360 milioni di anni. Non hanno fiori né semi — si riproducono con spore. Alcune felci arborescenti tropicali raggiungono i 20 m di altezza."},
 {q:"Quanti anni fa nacque il compositore Dvorak?",min:0,max:200,risposta:183,unit:"anni fa",curiosita:"Antonín Dvořák nacque l'8 settembre 1841 — 183 anni fa. La Sinfonia 'Dal Nuovo Mondo' (1893) la compose a New York dopo 3 anni negli USA. Incluse temi afroamericani e nativi americani. Il Quartetto in fa minore (Americano) ha la melodia più malinconica della musica classica."},
 {q:"Quante specie di muschi (Bryophyta) esistono?",min:0,max:20000,risposta:12000,unit:"specie",curiosita:"I muschi hanno circa 12.000 specie. Non hanno radici vere — assorbono acqua direttamente dalle foglie. La torba è muschio (sfagno) compresso. Assorbe fino a 20 volte il proprio peso in acqua. I muschi colonizzano le superfici più impossibili — dalla roccia artica ai tetti di Dublino."},
 {q:"Quanti anni fa nacque il compositore Grieg?",min:0,max:200,risposta:181,unit:"anni fa",curiosita:"Edvard Grieg nacque il 15 giugno 1843 a Bergen (Norvegia) — 181 anni fa. Il Peer Gynt e il Concerto per pianoforte in la minore sono le sue opere più famose. I suoi Lirici per pianoforte catturano i paesaggi norvegesi in miniature musicali perfette."},
 {q:"Quante specie di licheni esistono?",min:0,max:30000,risposta:20000,unit:"specie",curiosita:"I licheni hanno circa 20.000 specie. Sono una simbiosi tra fungo e alga (o cianobatterio). Crescono su rocce, alberi, tetti — ovunque. Producono acidi che erodono la roccia nel processo di pedogenesi. Vivono fino a 9.000 anni — i più longevi organismi sulla Terra."},
 {q:"Quanti anni fa nacque il pittore Gustave Courbet?",min:0,max:250,risposta:205,unit:"anni fa",curiosita:"Courbet nacque il 10 giugno 1819 a Ornans (Francia) — 205 anni fa. Fondò il Realismo in pittura — rifiutò il classicismo e il romanticismo. 'Sepoltura a Ornans' (1850) con i contadini a grandezza naturale scioccò il pubblico. Partecipò alla Comune di Parigi e morì in esilio."},
 {q:"Quante specie di funghi (regno Fungi) esistono?",min:0,max:5000000,risposta:148000,unit:"specie catalogate",curiosita:"Sono state catalogate circa 148.000 specie di funghi ma se ne stimano 2-4 milioni in totale. Il fungo più grande del mondo è un Armillaria ostoyae nell'Oregon: 8,9 km², 2.400 anni. Le spore fungine sono le particelle biologiche più numerose in atmosfera."},
 {q:"Quanti anni fa nacque il pittore Gustave Moreau?",min:0,max:250,risposta:198,unit:"anni fa",curiosita:"Gustave Moreau nacque il 6 aprile 1826 a Parigi — 198 anni fa. Pittore simbolista di scene mitologiche e religiose lussureggianti. Fu professore all'École des Beaux-Arts e maestro di Matisse e Rouault. Il suo studio a Parigi è ora museo."},
 {q:"Quante specie di diatomee esistono?",min:0,max:200000,risposta:100000,unit:"specie",curiosita:"Le diatomee hanno circa 100.000 specie. Sono alghe unicellulari in gusci di silice con geometrie perfette come cristalli. Producono il 20-25% dell'ossigeno terrestre — più di tutte le foreste. La terra di diatomee (kieselguhr) è usata come filtro e isolante."},
 {q:"Quanti anni fa nacque il pittore Pierre-Auguste Renoir?",min:0,max:200,risposta:183,unit:"anni fa",curiosita:"Renoir nacque il 25 febbraio 1841 a Limoges — 183 anni fa. Uno dei fondatori dell'Impressionismo. Il Ballo al Moulin de la Galette (1876) è il suo capolavoro. Negli ultimi anni dipingeva con il pennello legato alla mano artritica. Morì nel 1919 a 78 anni."},
 {q:"Quante specie di alghe brune esistono?",min:0,max:3000,risposta:1800,unit:"specie (Phaeophyta)",curiosita:"Le alghe brune hanno circa 1.800 specie. I kelp giganti (Macrocystis pyrifera) crescono 30 cm al giorno e formano foreste subacquee alte 60 m. Sono ricche di iodio, alginati (usati in cosmesi, cibo, farmaci) e mannitolo. La kombu usata nel dashi giapponese è un'alga bruna."},
 {q:"Quanti anni fa nacque il pittore Eugène Delacroix?",min:0,max:250,risposta:226,unit:"anni fa",curiosita:"Delacroix nacque il 26 aprile 1798 a Charenton-Saint-Maurice — 226 anni fa. 'La Libertà guida il Popolo' (1830) è il quadro-manifesto del Romanticismo. Viaggiò in Marocco — i colori orientali trasformarono la sua tavolozza. Influenzò profondamente gli Impressionisti."},
 {q:"Quante specie di cetacei (balene e delfini) esistono?",min:0,max:100,risposta:90,unit:"specie",curiosita:"I cetacei hanno circa 90 specie. Il capodoglio ha il cervello più grande degli animali: 7 kg. I delfini dormono con mezzo cervello alla volta — il 'sonno unisemisferico'. Le balene cantano — i canti dei capodoglii si tramandono culturalmente come dialetti."},
 {q:"Quanti anni fa nacque il pittore Théodore Géricault?",min:0,max:250,risposta:233,unit:"anni fa",curiosita:"Géricault nacque il 26 settembre 1791 a Rouen — 233 anni fa. 'La Zattera della Medusa' (1819) scandalizò la Francia — dipinge una tragedia navale reale con cadaveri e disperazione. Morì a soli 32 anni in un incidente a cavallo. Aprì la strada al Romanticismo."},
 {q:"Quante specie di pinnipedi (foche e trichechi) esistono?",min:0,max:40,risposta:33,unit:"specie",curiosita:"I pinnipedi hanno 33 specie. Il tricheco ha zanne fino a 1 m — usate come gancio per salire sul ghiaccio. Le foche elefante immergono a 1.500 m e apnea fino a 2 ore. La foca di Weddell abita l'Antartico — resiste a -60°C."},
 {q:"Quanti anni fa nacque lo scrittore Honoré de Balzac?",min:0,max:250,risposta:225,unit:"anni fa",curiosita:"Balzac nacque il 20 maggio 1799 a Tours — 225 anni fa. 'La Commedia Umana' — 91 romanzi e racconti — è il ritratto più completo della società francese del XIX secolo. Lavorava 16 ore al giorno bevendo 50 tazze di caffè. Morì nel 1850 di una delle malattie dei suoi personaggi."},
 {q:"Quante specie di manatee e dugonghi esistono?",min:0,max:10,risposta:4,unit:"specie (Sirenia)",curiosita:"I sireni hanno 4 specie: 3 manatee e 1 dugongo. Sono i parenti più prossimi degli elefanti tra i mammiferi marini. Vivono in acque costiere tropicali. Il dugongo è a rischio per la caccia — mitologicamente è la sirena che videro i marinai. Vivono fino a 70 anni."},
 {q:"Quanti anni fa nacque lo scrittore Victor Hugo?",min:0,max:250,risposta:222,unit:"anni fa",curiosita:"Victor Hugo nacque il 26 febbraio 1802 a Besançon — 222 anni fa. I Miserabili (1862) e Il Gobbo di Notre-Dame (1831) sono i suoi capolavori. Scrisse in esilio a Guernsey per 19 anni. Al suo funerale nel 1885 sfilò 1 milione di parigini."},
 {q:"Quante specie di rinoceronti esistono?",min:0,max:10,risposta:5,unit:"specie",curiosita:"Esistono 5 specie di rinoceronti. Il rinoceronte bianco del nord è quasi estinto — ne restano 2 femmine in cattività. Il corno è cheratina — come le unghie umane. Il bracconaggio per i corni (medicina tradizionale asiatica) ne ha dimezzato la popolazione."},
 {q:"Quanti anni fa nacque lo scrittore Marcel Proust?",min:0,max:200,risposta:153,unit:"anni fa",curiosita:"Proust nacque il 10 luglio 1871 a Auteuil — 153 anni fa. 'Alla ricerca del tempo perduto' (7 volumi, 1913-1927) è il romanzo più lungo mai scritto. La famosa madeleine intinta nel tè risveglia la memoria involontaria — concetto cardine dell'opera."},
 {q:"Quante specie di ghepardi, leoni e giaguari esistono?",min:0,max:20,risposta:6,unit:"specie nel genere Panthera e Acinonyx",curiosita:"I felidi grandi sono 6 specie: leone, tigre, giaguaro, leopardo, leopardo delle nevi e ghepardo (in realtà genere diverso). La tigre è il felino più grande — fino a 300 kg. Il ghepardo è il più veloce — non ruggisce ma fa le fusa."},
 {q:"Quanti anni fa nacque lo scrittore Gustave Flaubert?",min:0,max:250,risposta:203,unit:"anni fa",curiosita:"Flaubert nacque il 12 dicembre 1821 a Rouen — 203 anni fa. 'Madame Bovary' (1857) fu processato per oscenità ma assolto — divenne bestseller. Lavorava una settimana per trovare 'le mot juste' (la parola giusta). 'L'educazione sentimentale' è l'altro capolavoro."},
 {q:"Quante specie di procioni (Procyonidae) esistono?",min:0,max:20,risposta:14,unit:"specie",curiosita:"I procioni hanno 14 specie: procioni, coati, kinkajou. Il procione lavatore è invasivo in Europa — fuggito dagli allevamenti negli anni '30. Hanno zampe destrissime — aprono serrature e coperchi. Il loro 'lavare' il cibo è in realtà una stimolazione sensoriale."},
 {q:"Quanti anni fa nacque il pittore Edgar Degas?",min:0,max:200,risposta:190,unit:"anni fa",curiosita:"Degas nacque il 19 luglio 1834 a Parigi — 190 anni fa. È famoso per le ballerine, le corse di cavalli e le donne che si lavano. Nonostante la fama di Impressionista, preferiva definirsi Realista. Negli ultimi anni diventò quasi cieco ma continuò a fare sculture."},
 {q:"Quante specie di manguste esistono?",min:0,max:50,risposta:34,unit:"specie (Herpestidae)",curiosita:"Le manguste hanno 34 specie. Sono immuni al veleno del cobra — non totalmente: resistono a dosi normali. La meerkat (suricata) vive in colonie con sentinelle a turno. Rudyard Kipling ha reso famosa Rikki-Tikki-Tavi — la mangusta che salva una famiglia."},
 {q:"Quanti anni fa nacque il pittore Henri Matisse?",min:0,max:200,risposta:155,unit:"anni fa",curiosita:"Matisse nacque il 31 dicembre 1869 a Le Cateau-Cambrésis — 155 anni fa. Fondatore del Fauvismo — colori puri, non realistici. Negli ultimi anni, costretto a letto, creò 'Le Découpages' — figure ritagliate da carta colorata. La Cappella di Vence (1948-51) è la sua opera finale."},
 {q:"Quante specie di viverridae (civette e genet) esistono?",min:0,max:50,risposta:35,unit:"specie",curiosita:"Le viverre hanno 35 specie. Lo zibetto africano produce il muschio più prezioso della profumeria — lo si estrae ancora da ghiandole vive in Etiopia. La genetta è l'unico viverre europeo. Il kopi luwak — il caffè più costoso — è prodotto da civet asiatici."},
 {q:"Quanti anni fa nacque lo scrittore Charles Dickens?",min:0,max:250,risposta:212,unit:"anni fa",curiosita:"Dickens nacque il 7 febbraio 1812 a Portsmouth — 212 anni fa. Oliver Twist, David Copperfield e Grandi Speranze sono i suoi romanzi più famosi. Pubblicava in puntate — il pubblico aspettava i fascicoli come serie TV. Morì nel 1870 lasciando incompiuto Il Mistero di Edwin Drood."},
 {q:"Quante specie di pinnacoli (Pinnipedia) – lo ripetiamo?",min:0,max:40,risposta:33,unit:"specie",curiosita:"Un'altra curiosità sui pinnipedi: il leone marino stellerone (Eumetopias jubatus) è il più grande dei pinnipedi dopo il tricheco — fino a 1.000 kg. Le foche del porto (Phoca vitulina) si trovano anche nel Mediterraneo. I pinnipedi sono tornati in Adriatico dopo decenni."},
 {q:"Quanti anni fa nacque il poeta William Blake?",min:0,max:300,risposta:267,unit:"anni fa",curiosita:"Blake nacque il 28 novembre 1757 — 267 anni fa. Poeta, pittore e incisore. 'Tyger Tyger, burning bright' è la sua poesia più famosa. Non fu riconosciuto in vita. Credeva di avere visioni di angeli e spiriti. Il suo lavoro ispirò il Romanticismo e poi i movimenti hippy."},
 {q:"Quante specie di scoiattoli volanti esistono?",min:0,max:100,risposta:50,unit:"specie (Pteromyini)",curiosita:"Gli scoiattoli volanti hanno circa 50 specie. Non volano davvero — planano fino a 90 m usando la membrana tra le zampe (patagio). Quello della Chuanzang (Eupetaurus cinereus) è il più grande: 60 cm. Sono tutti notturni."},
 {q:"Quanti anni fa nacque il poeta Lord Byron?",min:0,max:250,risposta:236,unit:"anni fa",curiosita:"Byron nacque il 22 gennaio 1788 — 236 anni fa. Don Juan e Childe Harold sono le sue opere principali. Era zoppo dalla nascita ma campione di nuoto. Morì a 36 anni in Grecia mentre lottava per l'indipendenza greca. Era il rocker del suo tempo — rockstar ante litteram."},
 {q:"Quante specie di castor (castori) esistono?",min:0,max:5,risposta:2,unit:"specie",curiosita:"Esistono 2 specie di castori: americano ed europeo. Il castoro nordamericano è il più grande roditore del Nordamerica — 35 kg. Le sue dighe cambiano completamente il paesaggio — creano zone umide abitate da centinaia di specie. I denti non si fermano mai di crescere."},
 {q:"Quanti anni fa nacque il poeta Percy Bysshe Shelley?",min:0,max:250,risposta:232,unit:"anni fa",curiosita:"Shelley nacque il 4 agosto 1792 — 232 anni fa. 'Ozymandias' e 'Ode al vento dell'ovest' sono le sue poesie più famose. Morì annegato nel Golfo della Spezia nel 1822 a 29 anni. La moglie Mary Shelley scrisse 'Frankenstein'."},
 {q:"Quante specie di porcospini esistono?",min:0,max:50,risposta:29,unit:"specie",curiosita:"I porcospini hanno 29 specie in due famiglie. Le spine sono peli modificati rivestiti di cheratina — cadono facilmente nei predatori. Non le lanciano! Alcune spine americane hanno uncini microscopici che penetrano più facilmente di un ago ipodermico e non escono."},
 {q:"Quanti anni fa nacque il poeta John Keats?",min:0,max:250,risposta:229,unit:"anni fa",curiosita:"Keats nacque il 31 ottobre 1795 — 229 anni fa. Morì di tubercolosi a Roma nel 1821 a soli 25 anni. 'Ode a un'Urna Greca' e 'La belle dame sans merci' sono i suoi capolavori. La sua casa a Roma è oggi museo. Impressionò Shelley, Byron e tutti i Romantici."},
 {q:"Quante specie di vespe esistono?",min:0,max:100000,risposta:30000,unit:"specie (Vespidae e parenti)",curiosita:"Le vespe sociali (vespe, calabroni) hanno circa 30.000 specie — ma ci sono oltre 100.000 specie di vespe in senso lato (parassitoidi inclusi). Le vespe parassitiche controllano le popolazioni di insetti nocivi. Il calabrone asiatico (Vespa mandarinia) attacca gli alveari."},
 {q:"Quanti anni fa nacque il poeta Friedrich Hölderlin?",min:0,max:300,risposta:254,unit:"anni fa",curiosita:"Hölderlin nacque il 20 marzo 1770 (stesso anno di Hegel!) — 254 anni fa. Impazzì nel 1802 a 32 anni e visse altri 36 anni in una torre a Tübingen. Riscoperto nel '900. Heidegger gli dedicò saggi fondamentali. Le sue odi greche influenzarono tutta la poesia europea."},
 {q:"Quante specie di scarlatti (Scarabaeidae) esistono?",min:0,max:50000,risposta:30000,unit:"specie",curiosita:"Gli scarabei (Scarabaeidae) hanno circa 30.000 specie. Lo scarabeo sacro egiziano (Scarabaeus sacer) che spinge la pallina di sterco fu identificato con il sole che rotola nel cielo — simbolo di resurrezione. Il cervo volante europeo è il più grande insetto d'Italia."},
 {q:"Quanti anni fa nacque il pittore William Turner?",min:0,max:300,risposta:249,unit:"anni fa",curiosita:"William Turner nacque il 23 aprile 1775 — 249 anni fa. Il 'pittore della luce' rivoluzionò il paesaggio con nebbie, tempeste e tramonti quasi astratti. Si fece legare all'albero di una nave durante una tempesta per dipingerla. Iscritto all'Accademia reale a 14 anni."},
 {q:"Quante specie di pappagalli del genere Amazona esistono?",min:0,max:50,risposta:31,unit:"specie",curiosita:"Le amazzoni hanno 31 specie. Sono tra i più intelligenti pappagalli — parlano e cantano. La amazzonica fronte blu vive anche in pianura padana come specie introdotta. La loro longevità supera 60 anni — possono sopravvivere ai loro proprietari."},
 {q:"Quanti anni fa nacque il pittore Camille Pissarro?",min:0,max:250,risposta:194,unit:"anni fa",curiosita:"Pissarro nacque il 10 luglio 1830 a Charlotte Amalie (Isole Vergini) — 194 anni fa. Unico artista a partecipare a tutte e 8 le mostre impressioniste. Maestro di Cézanne, Gauguin e Seurat. I suoi boulevard parigini visti dall'alto sono tra i documenti visivi più belli del XIX secolo."},
 {q:"Quante specie di cervi (Cervidae) esistono?",min:0,max:100,risposta:55,unit:"specie",curiosita:"I cervi hanno 55 specie. Solo i maschi hanno i palchi — tranne nelle renne dove anche le femmine li hanno. Il palco del cervo rosso può crescere di 2,5 cm al giorno. I palchi cadono e ricrescono ogni anno — i tessuti animali che crescono più veloci. Il caribù migra 5.000 km l'anno."},
 {q:"Quanti anni fa nacque lo scrittore Émile Zola?",min:0,max:200,risposta:184,unit:"anni fa",curiosita:"Zola nacque il 2 aprile 1840 a Parigi — 184 anni fa. 'Germinal' (1885) sul lavoro minerario e 'Nana' (1880) sulla prostituzione sono i suoi romanzi più forti. Il J'Accuse (1898) nella difesa di Dreyfus è uno dei momenti più alti del giornalismo civile."},
 {q:"Quante specie di antilopi esistono?",min:0,max:200,risposta:91,unit:"specie",curiosita:"Le antilopi hanno circa 91 specie. La springbok salta fino a 3,5 m in aria in un comportamento detto 'pronking' — forse per valutare i predatori. Lo gnu migra seguendo le piogge: 1,5 milioni di gnu attraversano il Serengeti ogni anno."},
 {q:"Quanti anni fa nacque il pittore Claude Lorrain?",min:0,max:500,risposta:432,unit:"anni fa circa",curiosita:"Claude Lorrain (Claude Gellée) nacque nel 1600 a Chamagne (Francia) — circa 424 anni fa. Inventò il paesaggio classico con rovinisquilibri e luci dorate al tramonto. Turner lo studiò e volle essere sepolto accanto alla sua opera. Trascorse tutta la vita a Roma."},
 {q:"Quante specie di suini selvatici (Suidae) esistono?",min:0,max:20,risposta:17,unit:"specie",curiosita:"I suidi selvatici hanno 17 specie: cinghiali, facoceri, babirusa, pecari. Il babirusa indonesiano ha zanne che crescono attraverso il muso — possono perforare il cranio. Il facocero percorre fino a 50 km al giorno. Il cinghiale può odorare il tartufo a 1 m di profondità."},
 {q:"Quanti anni fa nacque il pittore Agnolo Bronzino?",min:0,max:600,risposta:521,unit:"anni fa",curiosita:"Bronzino nacque nel 1503 a Monticello (oggi Montelupo Fiorentino) — 521 anni fa. Pittore di corte dei Medici a Firenze. I suoi ritratti hanno una freddezza marmorea unica — figure perfette e distanti. Venere, Cupido, Follia e il Tempo (1545) è il suo quadro più famoso."},
 {q:"Quante specie di ippopotami esistono?",min:0,max:5,risposta:2,unit:"specie",curiosita:"Esistono 2 specie di ippopotami: il comune (3.000 kg) e il pigmeo (250 kg). Nonostante l'aspetto, il loro parente più prossimo è il cetaceo — separati 55 milioni di anni fa. L'ippopotamo è il più pericoloso animale africano per gli umani — molto aggressivo."},
 {q:"Quanti anni fa nacque il pittore Andrea del Sarto?",min:0,max:600,risposta:542,unit:"anni fa",curiosita:"Andrea del Sarto nacque nel 1486 a Firenze — 542 anni fa (il nome 'del Sarto' viene dal padre sarto). 'Madonna delle Arpie' (1517) agli Uffizi è il suo capolavoro. Francesco I lo invitò alla corte francese. Vasari lo chiamava 'pittore senza errori'."},
 {q:"Quante specie di tapiri esistono?",min:0,max:10,risposta:5,unit:"specie",curiosita:"I tapiri hanno 5 specie: 4 americane e 1 asiatica. Il tapiro di Baird è il più grande mammifero terrestre del Centro America. Nuota bene e si immerge per mangiare piante acquatiche. La loro proboscide prensile raccoglie frutti e foglie come una piccola tromba."},
 {q:"Quanti anni fa nacque il compositore Telemann?",min:0,max:400,risposta:363,unit:"anni fa",curiosita:"Georg Philipp Telemann nacque il 14 marzo 1681 ad Halberstadt — 343 anni fa. Fu il compositore più prolifico della storia: circa 3.600 opere! Contemporaneo più famoso di Bach — oggi meno conosciuto. Rivoluzionò la musica da camera tedesca."},
 {q:"Quante specie di ragni saltatori (Salticidae) esistono?",min:0,max:7000,risposta:6000,unit:"specie",curiosita:"I ragni saltatori hanno circa 6.000 specie — la famiglia più numerosa di ragni. Saltano fino a 40 volte la loro lunghezza. Hanno la vista migliore tra gli artropodi — vedono quasi come gli umani. Non usano tele per cacciare ma tendono agguati."},
 {q:"Quanti anni fa nacque il compositore Vivaldi?",min:0,max:400,risposta:346,unit:"anni fa",curiosita:"Antonio Vivaldi nacque il 4 marzo 1678 a Venezia — 346 anni fa. Le Quattro Stagioni (1725) è il concerto più suonato nella storia. Compose circa 500 concerti in vita — Bach li trascrisse ammirandoli. Era chiamato 'il Prete rosso' per i capelli rossi."},
 {q:"Quante specie di pseudoscorpioni esistono?",min:0,max:5000,risposta:3300,unit:"specie",curiosita:"Gli pseudoscorpioni hanno 3.300 specie. Sembrano scorpioni ma senza la coda con il pungiglione — sono innocui. Vivono nella lettiera, nelle case, tra i libri. Hitchhikano su altri insetti per spostarsi — comportamento detto 'foresia'. Lunghi al massimo 8 mm."},
 {q:"Quanti anni fa nacque il pittore Giorgione?",min:0,max:600,risposta:546,unit:"anni fa circa",curiosita:"Giorgione nacque intorno al 1477 a Castelfranco Veneto — circa 547 anni fa. Morì giovanissimo (32 anni) nel 1510. La Tempesta è il suo capolavoro: primo paesaggio autonomo nella pittura italiana. Influenzò Tiziano e tutta la scuola veneziana."},
 {q:"Quante specie di tarante (Theraphosidae) esistono?",min:0,max:1000,risposta:900,unit:"specie",curiosita:"Le tarantole (Theraphosidae) hanno circa 900 specie. La Goliath birdeater (Theraphosa blondi) è il più grande ragno: 30 cm di apertura. Non sono pericolose per gli umani — il morso è come un'ape. In Venezuela vengono mangiate — arrostite alla brace."},
 {q:"Quanti anni fa nacque il pittore Jacopo Tintoretto?",min:0,max:600,risposta:506,unit:"anni fa",curiosita:"Tintoretto nacque nel 1518 a Venezia — 506 anni fa. Figlio di un tintore (da qui il nome). La Scuola Grande di San Rocco a Venezia contiene il suo ciclo di affreschi più completo — lo lavorò per 23 anni. La sua velocità d'esecuzione stupiva i contemporanei."},
 {q:"Quante specie di ragni tessitori d'oro (Nephila) esistono?",min:0,max:20,risposta:12,unit:"specie",curiosita:"I ragni Nephila hanno 12 specie. La loro seta è la più resistente in natura — 5 volte l'acciaio per unità di peso. Le femmine sono grandi (25 cm) mentre i maschi sono microscopici (6 mm). In Papua Nuova Guinea i pescatori usano le tele come reti da pesca."},
 {q:"Quanti anni fa nacque il pittore Bartolomeo Montagna?",min:0,max:600,risposta:569,unit:"anni fa circa",curiosita:"Montagna nacque intorno al 1450 a Bianzano (Bergamo) — circa 574 anni fa. Principale rappresentante della scuola pittorica vicentina nel Rinascimento. Allievo di Giovanni Bellini. Le sue opere sono conservate in molte chiese del Veneto."},
 {q:"Quante specie di scolopendre esistono?",min:0,max:1000,risposta:600,unit:"specie",curiosita:"Le scolopendre hanno circa 600 specie. La Scolopendra gigantea può raggiungere 30 cm e cacciare pipistrelli ai soffitti delle grotte. Il loro veleno causa dolore intenso negli umani ma raramente è mortale. Si muovono a 50 km/h — i più veloci tra i miriapodi."},
 {q:"Quanti anni fa nacque il pittore Giovanni Bellini?",min:0,max:600,risposta:590,unit:"anni fa circa",curiosita:"Giovanni Bellini nacque intorno al 1430 a Venezia — circa 590-600 anni fa. 'Il primo pittore moderno' — Dürer lo incontrò e scrisse che era il più grande pittore d'Italia. Maestro di Tiziano e Giorgione. Lavorò fino agli 80 anni."},
 {q:"Quante specie di echinodermi esistono?",min:0,max:10000,risposta:7000,unit:"specie",curiosita:"Gli echinodermi hanno circa 7.000 specie: stelle marine, ricci, oloturie, crinoidi. Hanno simmetria pentaradiale — 5 parti. Le stelle marine rigenerano i raggi — alcune rigenerano l'intero corpo da un singolo raggio. I piedi ambulacrali funzionano con pressione idraulica."},
 {q:"Quanti anni fa nacque il pittore Rogier van der Weyden?",min:0,max:700,risposta:624,unit:"anni fa circa",curiosita:"Van der Weyden nacque intorno al 1400 a Tournai — circa 624 anni fa. La Deposizione dalla Croce (1435) è tra le opere più potenti del Rinascimento fiammingo. Fu pittore ufficiale di Bruxelles. Il suo stile emotivo intenso influenzò tutta la pittura nordeuropea."},
 {q:"Quante specie di oloturie (cetrioli di mare) esistono?",min:0,max:3000,risposta:1700,unit:"specie",curiosita:"Le oloturie (cetrioli di mare) hanno circa 1.700 specie. Espellono gli intestini quando disturbate — li rigenerano in poche settimane. In Asia orientale sono prelibatezza — treche di mare. Alcune specie ospitano piccoli pesci (Carapidae) che entrano attraverso l'apertura cloacale."},
 {q:"Quanti anni fa nacque il pittore Jan van Eyck?",min:0,max:700,risposta:634,unit:"anni fa circa",curiosita:"Van Eyck nacque intorno al 1390 nel Limburgo — circa 634 anni fa. Sviluppò (o perfezionò) la pittura a olio. Il Polittico di Gand (1432) e i Coniugi Arnolfini (1434) sono i suoi capolavori. La perfezione dei dettagli (insetti, riflessi) è insuperata."},
 {q:"Quante specie di serpenti marini esistono?",min:0,max:100,risposta:70,unit:"specie",curiosita:"I serpenti marini hanno circa 70 specie. Sono tra i più velenosi del mondo — il Hydrophis belcheri è 100 volte più velenoso del cobra. Ma sono docili e raramente mordono l'uomo. Respirano aria e si immergono fino a 30 minuti. Partoriscono in acqua."},
 {q:"Quanti anni fa nacque il pittore Hans Holbein il Giovane?",min:0,max:600,risposta:526,unit:"anni fa circa",curiosita:"Holbein il Giovane nacque intorno al 1497 ad Augusta — circa 527 anni fa. Pittore di corte di Enrico VIII. I ritratti di Enrico, Erasmo e Tommaso Moro sono tra i ritratti più straordinari della storia dell'arte. Morì di peste a Londra nel 1543."},
 {q:"Quante specie di vipere esistono?",min:0,max:500,risposta:330,unit:"specie (Viperidae)",curiosita:"Le vipere (Viperidae) hanno circa 330 specie incluse vipere, crotali, moccasini. Il Bushmaster (Lachesis muta) è il più grande viperide: 3,5 m. Il Black mamba (non una vipera) è il serpente più veloce: 20 km/h. Il morso del taipan australiano può uccidere in 45 minuti."},
 {q:"Quanti anni fa nacque il compositore Monteverdi?",min:0,max:500,risposta:457,unit:"anni fa",curiosita:"Claudio Monteverdi nacque il 15 maggio 1567 a Cremona — 457 anni fa. Inventò l'opera lirica moderna — L'Orfeo (1607) è la prima grande opera. Maestro di cappella a San Marco a Venezia. Il Vespro della Beata Vergine (1610) è un capolavoro di 90 minuti."},
 {q:"Quante specie di lamprede esistono?",min:0,max:50,risposta:38,unit:"specie",curiosita:"Le lamprede hanno 38 specie. Sono tra i vertebrati più primitivi — non hanno mascelle (agnati). La bocca circolare dentata si attacca ai pesci e succhia il sangue. Invasive nei Grandi Laghi americani — devastarono la trota di lago. In Portogallo sono un piatto tradizionale."},
 {q:"Quanti anni fa nacque il pittore Nicolas Poussin?",min:0,max:500,risposta:430,unit:"anni fa",curiosita:"Poussin nacque il 15 giugno 1594 in Normandia — 430 anni fa. Il pittore francese più importante del Seicento. Trascorse la vita a Roma. 'Arcadia' (Et in Arcadia ego) — i pastori leggono un'iscrizione su una tomba — è il suo quadro più famoso e misterioso."},
 {q:"Quante specie di myxine (pesci senza mascelle) esistono?",min:0,max:100,risposta:76,unit:"specie",curiosita:"Le mixine hanno 76 specie. Producono enormi quantità di muco viscoso quando disturbate — intasano le branchie dei predatori. Sono spazzini marini — si infilano nei cadaveri di pesci e balene. Hanno sopravvissuto 300 milioni di anni quasi senza cambiare."},
 {q:"Quanti anni fa nacque il pittore Rubens?",min:0,max:450,risposta:447,unit:"anni fa",curiosita:"Peter Paul Rubens nacque il 28 giugno 1577 ad Siegen (Germania) — 447 anni fa. La sua bottega produceva dipinti come un'industria — con decine di allievi. Diplomatico oltre che pittore — mediò la pace tra Spagna e Inghilterra. Lasciò una delle più grandi fortune del suo tempo."},
 {q:"Quante specie di polipi di corallo costruttori di barriera esistono?",min:0,max:1000,risposta:800,unit:"specie",curiosita:"I coralli costruttori di barriera (Scleractinia) hanno circa 800 specie. La Grande Barriera Corallina australiana è visibile dallo spazio — 2.300 km. I coralli sono in simbiosi con le zooxantelle — alghe che forniscono il 90% del loro nutrimento. Il riscaldamento globale causa lo sbiancamento."},
 {q:"Quanti anni fa nacque il pittore Van Dyck?",min:0,max:500,risposta:426,unit:"anni fa",curiosita:"Anthony van Dyck nacque il 22 marzo 1599 ad Anversa — 425 anni fa. Allievo di Rubens. Pittore di corte di Carlo I d'Inghilterra. I suoi ritratti aristocratici eleganti definirono l'immaginario della nobiltà europea per due secoli. La sua mano era quella più sottile mai ritratta."},
 {q:"Quante specie di anozoi (coralli molli e anemoni) esistono?",min:0,max:10000,risposta:7500,unit:"specie",curiosita:"Gli antozoi hanno circa 7.500 specie: anemoni, coralli molli, gorgonie. Un anemone gigante del Pacifico può avere 1 m di diametro. Il pesce pagliaccio (Nemo) è immune al veleno delle anemoni — grazie a uno strato di muco protettivo."},
 {q:"Quanti anni fa nacque il pittore Frans Hals?",min:0,max:500,risposta:444,unit:"anni fa circa",curiosita:"Hals nacque intorno al 1580 ad Anversa — circa 444 anni fa. Il Banchiere allegro e i Reggenti del ospizio (1664) sono i suoi capolavori. Aveva una tecnica velocissima — pennellate quasi impressioniste. Morì povero a 85 anni. Manet lo studiò ossessivamente."},
 {q:"Quante specie di idropolipi (meduse giovani) esistono?",min:0,max:3000,risposta:2500,unit:"specie (Hydrozoa)",curiosita:"Gli idrozoi hanno circa 2.500 specie. La medusa immortale (Turritopsis dohrnii) è l'unico animale in grado di ringiovanire — torna allo stadio di polipo dopo la maturità. È tecnicamente biologicamente immortale. Originaria del Mediterraneo, ora invasiva ovunque."},
 {q:"Quanti anni fa nacque il pittore Rembrandt?",min:0,max:500,risposta:418,unit:"anni fa",curiosita:"Rembrandt van Rijn nacque il 15 luglio 1606 a Leida — 418 anni fa. 100 autoritratti nell'arco di 40 anni tracciano il suo invecchiamento. La Ronda di Notte (1642) è il più grande dipinto del Rijksmuseum. Morì povero dopo un bancarotta. Uno degli artisti più influenti di sempre."},
 {q:"Quante specie di pesci cartilaginei (squali e razze) esistono?",min:0,max:1200,risposta:1100,unit:"specie (Chondrichthyes)",curiosita:"I condritti (pesci cartilaginei) hanno circa 1.100 specie. Lo squalo balena è il più grande pesce: 12 m. Alcuni squali esistono da 450 milioni di anni. La razza manta ha un'intelligenza sorprendente — si riconosce allo specchio. I loro denti si rinnovano ogni 2 settimane."},
 {q:"Quanti anni fa nacque il pittore Johannes Vermeer?",min:0,max:400,risposta:392,unit:"anni fa",curiosita:"Vermeer nacque nel 1632 — 392 anni fa. La tecnica laser ha rivelato che usava la camera oscura come guida. Aveva 11 figli. Dopo la morte lasciò debiti enormi. La suocera possedeva quasi tutti i suoi dipinti. Fu 'riscoperto' nel 1866 dal critico d'arte Thoré-Bürger."},
 {q:"Quante specie di attinie (anemoni di mare) esistono?",min:0,max:2000,risposta:1000,unit:"specie",curiosita:"Le attinie hanno circa 1.000 specie. Vivono attaccate alle rocce ma possono muoversi lentamente. Alcune vivono in simbiosi con granchi eremiti — protezione in cambio di cibo. La più grande è la Stoichactis gigante del Pacifico — 1 metro di diametro."},
 {q:"Quanti anni fa nacque il pittore Diego Velázquez?",min:0,max:500,risposta:425,unit:"anni fa",curiosita:"Velázquez nacque il 6 giugno 1599 a Siviglia — 425 anni fa. Las Meninas (1656) è considerato il più grande dipinto della storia — Picasso la dipinse 58 volte. Pittore di corte di Filippo IV. Ritrasse i nani e buffoni di corte con dignità e rispetto straordinari."},
 {q:"Quante specie di piovre giganti esistono?",min:0,max:10,risposta:3,unit:"specie nel genere Enteroctopus",curiosita:"Il polpo gigante del Pacifico (Enteroctopus dofleini) è il più grande polpo: 9 m, 50 kg. Vive 3-5 anni. La femmina muore di fame dopo aver ossigenato le uova per 6 mesi senza mangiare. Il polpo è l'invertebrato più intelligente — risolve puzzle e apre barattoli."},
 {q:"Quanti anni fa nacque il pittore Francisco de Zurbarán?",min:0,max:500,risposta:426,unit:"anni fa",curiosita:"Zurbarán nacque nel 1598 a Fuente de Cantos (Estremadura) — 426 anni fa. 'Il pittore dei monaci' — le sue figure sante in bianchi abiti monastici hanno una presenza quasi scultorea. Velázquez fu il suo protettore a corte. Morì povero nel 1664 a Madrid."},
 {q:"Quante specie di meduse (Scyphozoa) esistono?",min:0,max:500,risposta:200,unit:"specie",curiosita:"Le scifozoa (meduse vere) hanno circa 200 specie. La Nomura giapponese pesa 200 kg e misura 2 m. La Cyanea arctica ha tentacoli di 37 m — l'animale più lungo del mondo. Le meduse non hanno cervello, cuore né sangue — solo il 3% di materia secca."},
 {q:"Quanti anni fa nacque il pittore Bronzino?",min:0,max:600,risposta:521,unit:"anni fa",curiosita:"Un'altra curiosità su Bronzino: il suo vero nome era Agnolo di Cosimo. Dipinse anche poesie satiriche e burlesque. La sua opera poetica è meno nota ma mostra il lato giocoso di un pittore che in pittura appare sempre freddo e distante."},
 {q:"Quante specie di pesci abissali (oltre 1000m) esistono?",min:0,max:2000,risposta:1000,unit:"specie circa",curiosita:"Oltre 1.000 m di profondità vivono circa 1.000 specie di pesci. Il Bathysaurus ferox è un predatore apicale delle profondità — aspetta immobile sul fondo. Il pesce vipera (Chauliodus) ha denti così lunghi che non chiude la bocca. Molti sono bioluminescenti."},
 {q:"Quanti anni fa nacque il pittore Annibale Carracci?",min:0,max:500,risposta:464,unit:"anni fa",curiosita:"Annibale Carracci nacque il 3 novembre 1560 a Bologna — 464 anni fa. La Galleria Farnese a Roma (1597-1608) con le scene mitologiche è il suo capolavoro. Con i cugini fondò l'Accademia dei Desiderosi a Bologna — influenzò tutta la pittura del Seicento."},
 {q:"Quante specie di piovre e calamari esistono?",min:0,max:1000,risposta:700,unit:"specie (Cephalopoda)",curiosita:"I cefalopodi hanno circa 700 specie: polpi, calamari, seppie, nautili. Hanno il sangue blu (emocianina con rame al posto del ferro). Il nautilo è un fossile vivente — 500 milioni di anni invariato. La seppia cambia colore in millisecondi grazie a 10 milioni di cromatofori."},
 {q:"Quanti anni fa nacque il pittore Raphael (Raffaello)?",min:0,max:600,risposta:541,unit:"anni fa",curiosita:"Raffaello nacque il 6 aprile 1483 ad Urbino — 541 anni fa. Morì esattamente il 6 aprile 1520 — nel giorno del suo 37° compleanno. Le Stanze Vaticane con la Scuola di Atene sono il suo capolavoro. Fu anche architetto e soprintendente alle antichità romane sotto Leone X."},
 {q:"Quante specie di foraminifera planctonici esistono?",min:0,max:100,risposta:50,unit:"specie",curiosita:"I foraminiferi planctonici hanno circa 50 specie viventi. Quando muoiono, i loro gusci calcarei si accumulano sul fondo oceanico — formando il calcare. Studiando la composizione isotopica dei gusci antichi si ricostruiscono le temperature oceaniche degli ultimi 65 milioni di anni."},
 {q:"Quanti anni fa nacque il pittore Michelangelo?",min:0,max:600,risposta:549,unit:"anni fa",curiosita:"Michelangelo Buonarroti nacque il 6 marzo 1475 a Caprese (Arezzo) — 549 anni fa. Considerava sé stesso scultore — non pittore. Il David (1504), la Pietà (1499) e la Cappella Sistina (1512) sono tra le opere più grandi della civiltà umana. Visse 88 anni — eccezionale per l'epoca."},
 {q:"Quante specie di formiche del fuoco esistono?",min:0,max:300,risposta:200,unit:"specie nel genere Solenopsis",curiosita:"Il genere Solenopsis ha circa 200 specie. La Solenopsis invicta (formica di fuoco importata) è invasiva in tutto il mondo — arrivata dall'Argentina negli anni '30. Il loro morso inietta un alcaloide (solenopsina) che causa vesciche dolorose. Formano 'zattere' per sopravvivere alle inondazioni."},
 {q:"Quanti anni fa nacque Leonardo da Vinci?",min:0,max:600,risposta:572,unit:"anni fa",curiosita:"Leonardo nacque il 15 aprile 1452 a Vinci (Firenze) — 572 anni fa. La Monna Lisa e L'Ultima Cena sono le sue opere pittoriche principali. Ma era soprattutto ingegnere, anatomista, geologo e musicista. Nei suoi quaderni: macchine volanti, carro armato, robot. Michelangelo lo detestava."},
 {q:"Quante specie di anfibi caudati (salamandre) esistono?",min:0,max:1000,risposta:750,unit:"specie",curiosita:"I caudati (salamandre e tritoni) hanno circa 750 specie. L'axolotl messicano è neotenico — rimane allo stadio larvale tutta la vita. Rigenera arti, coda, cuore e parte del cervello. In Cina il Andrias davidinius (salamandra gigante cinese: 1,8 m) viene allevato per uso alimentare."},
 {q:"Quanti anni fa nacque il compositore Corelli?",min:0,max:400,risposta:371,unit:"anni fa",curiosita:"Arcangelo Corelli nacque il 17 febbraio 1653 a Fusignano — 371 anni fa. Fondò la forma del concerto grosso — poi sviluppata da Vivaldi e Handel. I suoi 12 Concerti Grossi (op. 6) sono tra le pietre miliari della musica barocca. Visse tutta la vita a Roma."},
 {q:"Quante specie di ragni delle cantine (Pholcidae) esistono?",min:0,max:2000,risposta:1800,unit:"specie",curiosita:"I ragni delle cantine (Pholcidae) hanno circa 1.800 specie. La leggenda che siano i più velenosi è falsa — il loro veleno è debolissimo e la bocca non penetra la pelle umana. Mangiano altri ragni, compresi i ragni violino. Le loro tele irregolari vibrano per confondere i predatori."},
 {q:"Quanti anni fa nacque il pittore Guercino?",min:0,max:450,risposta:434,unit:"anni fa",curiosita:"Guercino (Giovanni Francesco Barbieri) nacque il 2 febbraio 1591 a Cento (Ferrara) — 433 anni fa. Il soprannome viene dall'italiano 'guercio' — era strabico. L'Aurora nel Casino Ludovisi a Roma (1621) è il suo capolavoro di affresco. Fu l'erede naturale di Annibale Carracci."},
 {q:"Quante specie di grilli esistono?",min:0,max:10000,risposta:6000,unit:"specie (Gryllidae)",curiosita:"I grilli hanno circa 6.000 specie. Il canto del grillo è prodotto dalla stridulazione — sfregamento delle ali. La frequenza del canto varia con la temperatura — il metodo di Dolbear: contare i cri in 14 secondi e aggiungere 40 dà la temperatura in Fahrenheit."},
 {q:"Quanti anni fa nacque il pittore Guido Reni?",min:0,max:500,risposta:452,unit:"anni fa",curiosita:"Guido Reni nacque il 4 novembre 1575 a Bologna — 449 anni fa. L'Aurora (1614) a Roma e l'Atalanta e Ippomene (1618-25) a Napoli sono i suoi capolavori. Il suo stile sublime e idealizzato fu criticato poi esaltato. Era un giocatore d'azzardo compulsivo che lavorava per pagare i debiti."},
 {q:"Quante specie di locuste (grandi cavallette migratorie) esistono?",min:0,max:30,risposta:20,unit:"specie",curiosita:"Le locuste migratorie sono circa 20 specie. La locusta del deserto (Schistocerca gregaria) forma stormi da 50 miliardi di individui — coprono 1.200 km² e mangiano la stessa quantità di cibo di 35.000 persone al giorno. Dal 2020 devastano l'Africa orientale."},
 {q:"Quanti anni fa nacque il pittore Artemisia Gentileschi?",min:0,max:500,risposta:431,unit:"anni fa",curiosita:"Artemisia Gentileschi nacque il 8 luglio 1593 a Roma — 431 anni fa. Prima donna membro dell'Accademia delle Arti del Disegno di Firenze. Giuditta che decapita Oloferne è il suo capolavoro — dipinta con forza e crudezza insolite. Fu violentata a 17 anni dal maestro Tassi."},
 {q:"Quante specie di cetonie (coleotteri fiorali dorati) esistono?",min:0,max:5000,risposta:4000,unit:"specie",curiosita:"Le cetonie hanno circa 4.000 specie. Cetonia aurata (cetonia dorata) ha ali metalliche iridescenti — a volte confusa con uno smeraldo vivente. Le larve decompongono il legno marcio. Gli adulti impollinano i fiori bianchi — specialmente rose e prunus."},
 {q:"Quanti anni fa nacque il pittore Giuseppe Arcimboldo?",min:0,max:600,risposta:502,unit:"anni fa circa",curiosita:"Arcimboldo nacque intorno al 1527 a Milano — circa 497 anni fa. Pittore di corte degli Asburgo a Vienna e Praga. I suoi ritratti composti da frutti, verdure, fiori e oggetti anticipano il Surrealismo di 4 secoli. Fu riscoperto nel '900 da Dalí e i Surrealisti."},
 {q:"Quante specie di lepri esistono?",min:0,max:50,risposta:32,unit:"specie",curiosita:"Le lepri hanno 32 specie. La lepre delle nevi cambia colore: marrone estate, bianca inverno. La lepre europea raggiunge 70 km/h — la più veloce tra i lagomorfi. Non scavano tane — partoriscono nei 'forms' (depressioni nell'erba). Le orecchie lunghissime dissipano il calore."},
 {q:"Quanti anni fa nacque il pittore Federico Barocci?",min:0,max:600,risposta:490,unit:"anni fa circa",curiosita:"Federico Barocci (Federico Fiori) nacque intorno al 1535 ad Urbino — circa 489 anni fa. Inventore del proto-barocco, anticipatore di Rubens. La Madonna del Popolo (1579) agli Uffizi è il suo capolavoro. Lavorava lentamente — un dipinto richiedeva anni. Usò pastelli colorati come studio."},
 {q:"Quante specie di gerenuk e giraffidi esistono?",min:0,max:10,risposta:2,unit:"specie (Giraffidae)",curiosita:"La famiglia Giraffidae ha 2 specie: la giraffa (Giraffa camelopardalis) e l'okapi (Okapia johnstoni). L'okapi fu scoperto dall'Occidente nel 1901 — grazie alle tribù pigmee del Congo. Ha strisce come una zebra sulle zampe posteriori ma è parente della giraffa, non della zebra."},
 {q:"Quanti anni fa nacque il pittore Dosso Dossi?",min:0,max:600,risposta:540,unit:"anni fa circa",curiosita:"Dosso Dossi (Giovanni di Niccolò de Lutero) nacque intorno al 1490 a Tramuschio (Mantova) — circa 534 anni fa. Pittore di corte degli Este a Ferrara — amico di Ariosto. La Circe (o Melissa) è il suo capolavoro. Il suo stile unisce influenza veneziana e fantasia fiabesca."},
 {q:"Quante specie di toporagni (Soricidae) esistono?",min:0,max:500,risposta:385,unit:"specie",curiosita:"I toporagni hanno 385 specie. Sono tra i mammiferi più piccoli (2-3 g) con il metabolismo più alto — battono il cuore 1.200 volte al minuto. Devono mangiare il proprio peso in insetti ogni giorno o muoiono. Alcune specie producono veleno — uniche tra i mammiferi."},
 {q:"Quanti anni fa nacque il pittore Jacopo Bassano?",min:0,max:600,risposta:510,unit:"anni fa circa",curiosita:"Jacopo Bassano (Jacopo Dal Ponte) nacque intorno al 1515 a Bassano del Grappa — circa 509 anni fa. Inventore del notturno pittorico e della scena di genere con animali. Le scene pastorali con animali realistici anticipano la pittura olandese del Seicento di un secolo."},
 {q:"Quante specie di papillonidi (farfalle coda di rondine) esistono?",min:0,max:1000,risposta:600,unit:"specie",curiosita:"I papilionidi hanno circa 600 specie. La Ornithoptera alexandrae della Papua Nuova Guinea è la più grande farfalla del mondo: 28 cm di apertura alare. Molte hanno colori tossici — imitano specie velenose. La macaone (Papilio machaon) è la più comune in Italia."},
 {q:"Quanti anni fa nacque il compositore Buxtehude?",min:0,max:400,risposta:387,unit:"anni fa circa",curiosita:"Dietrich Buxtehude nacque intorno al 1637 a Oldesloe (oggi Holstein) — circa 387 anni fa. Organista e compositore della Marienkirche di Lubecca. Bach camminò 400 km a piedi per sentirlo suonare. Il suo stile improvvisativo influenzò profondamente Bach."},
 {q:"Quante specie di farfalle notturnali Saturniidae esistono?",min:0,max:3000,risposta:2300,unit:"specie",curiosita:"Le Saturniidae hanno circa 2.300 specie. La falena Attacus atlas ha la più grande apertura alare tra le falene: 30 cm. La seta del baco da seta (Bombyx mori) è una Saturniidae. Un bozzolo contiene fino a 900 m di seta continua. Ogni 5 secondi nel mondo nasce un baco da seta."},
 {q:"Quanti anni fa nacque il pittore Giovanni Antonio Canal (Canaletto)?",min:0,max:400,risposta:332,unit:"anni fa",curiosita:"Canaletto nacque il 18 ottobre 1697 a Venezia — 327 anni fa. Le sue vedute di Venezia erano così accurate che gli inglesi in Grand Tour le compravano come souvenir fotografici. Usò la camera oscura. Il National Gallery di Londra ha la più grande collezione."},
 {q:"Quante specie di drosofila (mosche della frutta) esistono?",min:0,max:2000,risposta:1500,unit:"specie",curiosita:"Le drosofila hanno circa 1.500 specie. La Drosophila melanogaster è il modello più usato in genetica — ha solo 4 paia di cromosomi e ciclo vitale di 2 settimane. Ha permesso di scoprire i geni HOX che regolano lo sviluppo corporeo di tutti gli animali."},
 {q:"Quanti anni fa nacque il pittore Francesco Guardi?",min:0,max:350,risposta:312,unit:"anni fa",curiosita:"Francesco Guardi nacque il 5 ottobre 1712 a Venezia — 312 anni fa. Pittore di vedute veneziane — meno preciso di Canaletto ma più poetico e atmosferico. I suoi laghi bruciati dai tramonti anticipano l'Impressionismo. Morì povero nel 1793 a 81 anni."},
 {q:"Quante specie di formiche tagliafoglie esistono?",min:0,max:100,risposta:47,unit:"specie (Attini)",curiosita:"Le formiche tagliafoglie (Attini) hanno 47 specie. Coltivano funghi da 50 milioni di anni — una delle prime agricolture della Terra. Il loro fungo è una specie domesticata che non esiste più in natura senza di loro. Le colonie di Atta possono avere 8 milioni di individui."},
 {q:"Quanti anni fa nacque il pittore Giovanni Battista Tiepolo?",min:0,max:400,risposta:348,unit:"anni fa",curiosita:"Tiepolo nacque il 5 marzo 1696 a Venezia — 328 anni fa. Ultimo grande frescante veneziano — decorò palazzi e chiese in tutta Europa (inclusa la Residenz di Würzburg). La Crocifissione per Palazzo Dolfi e la Traslazione della Santa Casa (1743-50) a Venezia sono i suoi capolavori."},
 {q:"Quante specie di centopiedi (Chilopoda) esistono?",min:0,max:5000,risposta:3300,unit:"specie",curiosita:"I centopiedi (Chilopoda) hanno 3.300 specie. Il Scolopendra gigantea raggiunge 30 cm — caccia rane e piccoli topi. Hanno sempre un numero dispari di paia di zampe (quindi mai esattamente 100). La loro velocità è straordinaria — 50 cm al secondo."},
 {q:"Quanti anni fa nacque il pittore Luca Giordano?",min:0,max:400,risposta:387,unit:"anni fa circa",curiosita:"Luca Giordano nacque il 18 ottobre 1634 a Napoli — 390 anni fa. Detto 'Luca fa presto' per la velocità straordinaria di esecuzione. Decorò il soffitto della Biblioteca dell'Escorial in 2 anni. Pittore di corte di Carlo II di Spagna. Uno dei più prolifici pittori del Barocco."},
 {q:"Quante specie di tarantule Avicularia esistono?",min:0,max:50,risposta:28,unit:"specie",curiosita:"Il genere Avicularia ha 28 specie di tarantole arboricole dell'America tropicale. Sono chiamate 'spider da pinktoe' per le zampe color rosa. Non sono pericolose — il morso è come un'ape. I capelli urticanti (setole) li lanciano come difesa. Molto apprezzate come animali domestici."},
 {q:"Quanti anni fa nacque il pittore Salvator Rosa?",min:0,max:500,risposta:408,unit:"anni fa",curiosita:"Salvator Rosa nacque il 20 luglio 1615 a Arenella (Napoli) — 409 anni fa. Pittore, poeta e attore — personaggio bohemien ante litteram. I suoi paesaggi selvaggi con briganti e rovine ispirarono il Pittoresco inglese e il Romanticismo. Non sopportava il mecenatismo e l'adulazione."},
 {q:"Quante specie di uccelli lira (Menura) esistono?",min:0,max:5,risposta:2,unit:"specie",curiosita:"Il genere Menura ha 2 specie — entrambe in Australia. Il maschio del lyrebird supermago imita perfettamente altri uccelli, motoseghe, obici militari, allarmi d'auto e scatti di macchine fotografiche. La coda del maschio (5 anni per svilupparsi) imita la forma di una lira greca."},
 {q:"Quanti anni fa nacque il pittore Ciro Ferri?",min:0,max:500,risposta:397,unit:"anni fa",curiosita:"Ciro Ferri nacque il 1634 a Roma — 390 anni fa. Allievo di Pietro da Cortona. Completò la decorazione della Galleria Palatina a Firenze dopo la morte del maestro. Le sue pale d'altare nelle chiese romane mostrano un barocco morbido e luminoso."},
 {q:"Quante specie di grandi coleotteri acquatici (Dytiscidae) esistono?",min:0,max:5000,risposta:4300,unit:"specie",curiosita:"I ditiscidi hanno circa 4.300 specie. Sono predatori acquatici veloci — un centimetro di aculeo alla zampa gli basta per trattenere la preda. Volano di notte verso le luci — spesso confondono asfalto lucido con acqua. Respirano portando una bolla d'aria sotto le elitre."},
 {q:"Quanti anni fa nacque il pittore Pietro da Cortona?",min:0,max:500,risposta:431,unit:"anni fa",curiosita:"Pietro da Cortona (Pietro Berrettini) nacque nel 1596 a Cortona — 428 anni fa. Il soffitto di Palazzo Barberini a Roma (Trionfo della Divina Provvidenza, 1639) è tra i più grandiosi affreschi barocchi. Architetto oltre che pittore — progettò SS. Luca e Martina a Roma."},
 {q:"Quante specie di strepsiptera (insetti parassiti) esistono?",min:0,max:600,risposta:600,unit:"specie",curiosita:"Gli strepsipteri hanno circa 600 specie. Sono parassiti di vespe, api, grilli e cavallette. Le femmine sono degenerate — senza occhi, zampe o ali — vivono semi-incastrate nell'ospite. I maschi adulti vivono solo poche ore, giusto per accoppiarsi e morire."},
 {q:"Quanti anni fa nacque il compositore Alessandro Scarlatti?",min:0,max:400,risposta:364,unit:"anni fa",curiosita:"Alessandro Scarlatti nacque il 2 maggio 1660 a Palermo — 364 anni fa. Padre di Domenico Scarlatti. Fondatore della scuola operistica napoletana — compose oltre 70 opere. La Sinfonia avanti l'opera che inventò divenne l'ouverture moderna e poi la sinfonia classica."},
 {q:"Quante specie di coleotteri buprestidi (smeraldini metallici) esistono?",min:0,max:20000,risposta:15000,unit:"specie",curiosita:"I buprestidi hanno circa 15.000 specie. Le loro elitre metalliche iridescenti erano usate come gioielli in Asia e nelle piume dei costumi aztechi. Il buprestide smeraldino del frassino (Agrilus planipennis) è devastante per i frassini — uccide alberi in 3-5 anni."},
 {q:"Quanti anni fa nacque il pittore Bernardo Strozzi?",min:0,max:500,risposta:448,unit:"anni fa",curiosita:"Bernardo Strozzi nacque nel 1581 a Genova — 443 anni fa. Frate cappuccino poi laicizzato. La Cuoca (1620) — una donna anziana che prepara pollame — è il suo capolavoro di pittura di genere. Si trasferì a Venezia nel 1630 portando il caravaggismo norditaliano."},
 {q:"Quante specie di cecidomie (ditteri gallicoli) esistono?",min:0,max:7000,risposta:6000,unit:"specie",curiosita:"Le cecidomie hanno circa 6.000 specie. Le larve inducono la formazione di galle (tumori) sulle piante — ogni specie crea una galla specifica riconoscibile. La Hessian fly devastò il grano americano nella guerra d'indipendenza. Alcune producono feromoni identici a quelli dell'ospite."},
 {q:"Quanti anni fa nacque il pittore Palma il Vecchio?",min:0,max:600,risposta:543,unit:"anni fa circa",curiosita:"Palma il Vecchio (Jacopo Negretti) nacque intorno al 1480 a Serina (Bergamo) — circa 544 anni fa. La sua Santa Barbara (1522) nella chiesa di Santa Maria Formosa a Venezia è una delle figure femminili più celebri del Rinascimento veneziano. Morì nel 1528."},
 {q:"Quante specie di pterosauri sono conosciute?",min:0,max:200,risposta:150,unit:"specie (estinte)",curiosita:"I pterosauri hanno circa 150 specie fossili. Vissero 228-66 milioni di anni fa. Il Quetzalcoatlus northropi aveva un'apertura alare di 10-11 m — grande come un aereo leggero. Non erano dinosauri — erano rettili volanti. Il loro volo era attivo, non planato."},
 {q:"Quanti anni fa nacque il pittore Beccafumi?",min:0,max:600,risposta:540,unit:"anni fa circa",curiosita:"Domenico Beccafumi nacque intorno al 1486 a Montaperti (Siena) — circa 538 anni fa. Il pavimento del Duomo di Siena con scene bibliche in marmo intarsiato è il suo capolavoro (1516-1547). I suoi affreschi uniscono influenza michelangiolesca e colori sienesi luminosi."},
 {q:"Quante specie di cervi acquatici (Hydropotes) esistono?",min:0,max:5,risposta:1,unit:"specie",curiosita:"Il cervo acquatico cinese (Hydropotes inermis) è l'unica specie senza palchi — ha invece canini a sciabola lunghi 8 cm. Originario della Cina e Corea, fu introdotto in Europa. I maschi 'abbaiano' per comunicare. Nuotano per isole del delta dello Yangtze."},
 {q:"Quanti anni fa nacque il compositore Frescobaldi?",min:0,max:500,risposta:441,unit:"anni fa",curiosita:"Girolamo Frescobaldi nacque il 9 settembre 1583 a Ferrara — 441 anni fa. Organista di San Pietro in Vaticano. Alla sua prima esecuzione accorsero 30.000 persone! Bach lo studiò meticolosamente. Le sue toccate per clavicembalo sono la base della musica da tastiera barocca."},
 {q:"Quante specie di zanzare esistono?",min:0,max:5000,risposta:3500,unit:"specie",curiosita:"Le zanzare hanno circa 3.500 specie. Sono gli animali più letali per l'uomo — 750.000 morti l'anno attraverso malaria, dengue, Zika, febbre gialla. Solo le femmine pungono — usano il sangue per produrre le uova. Hanno 47 denti — su 3 diversi 'stiletti'."},
 {q:"Quanti anni fa nacque il pittore Pontormo?",min:0,max:600,risposta:530,unit:"anni fa",curiosita:"Pontormo (Jacopo Carucci) nacque il 24 maggio 1494 a Pontormo (Empoli) — 530 anni fa. Fondatore del Manierismo con la Deposizione (1528) in Santa Felicita a Firenze — colori acidi e innaturali, corpi in movimento impossibile. Teneva un diario ossessivo su salute e cibo."},
 {q:"Quante specie di mammiferi marsupiala (marsupiali) esistono?",min:0,max:500,risposta:330,unit:"specie",curiosita:"I marsupiali hanno circa 330 specie — quasi tutte in Australia. Il tilacino (tigre della Tasmania) si estinse nel 1936. Il wombat produce feci cubiche — uniche nel regno animale. L'echidna e l'ornitorinco sono monotremi (mammiferi che depongono uova) — i più primitivi."},
 {q:"Quanti anni fa nacque il pittore Rosso Fiorentino?",min:0,max:600,risposta:530,unit:"anni fa",curiosita:"Rosso Fiorentino (Giovanni Battista di Jacopo) nacque il 8 marzo 1495 a Firenze — 529 anni fa. La Deposizione di Volterra (1521) con i corpi angolosi e la luce livida è uno dei dipinti più inquietanti del Rinascimento. Morì a Fontainebleau nel 1540, dove lavorava per Francesco I."},
 {q:"Quante specie di cavalli e zebré esistono?",min:0,max:15,risposta:8,unit:"specie (Equidae)",curiosita:"Gli equidi hanno 8 specie: 1 cavallo, 3 asini e 4 zebre (incluse le 3 zebre e il quagga estinto). Il quagga sudafricano si estinse nel 1883. Le zebre hanno strisce uniche come impronte digitali. Il progetto Quagga cerca di far rinascere il quagga selezionando zebre con meno strisce."},
 {q:"Quanti anni fa nacque il pittore Giovanni Bellini (già citato)?",min:0,max:600,risposta:590,unit:"anni fa circa",curiosita:"Un'altra curiosità su Bellini: rimase attivo come pittore fino a quasi 80 anni. Il Festino degli Dei (1514) — l'ultima sua opera — fu poi modificata da Tiziano che aggiunse il paesaggio. La collaborazione tra maestro anziano e giovane allievo è un documento unico."},
 {q:"Quante specie di ragni a bolla d'acqua (Argyroneta) esistono?",min:0,max:5,risposta:1,unit:"specie",curiosita:"Il ragno d'acqua (Argyroneta aquatica) è l'unica specie di ragno che vive sott'acqua. Costruisce una campana d'aria tra le piante acquatiche — vi vive e alleva i piccoli. Ricarica la bolla tornando in superficie. Si trova in acque ferme di tutta Europa e Asia."},
 {q:"Quanti anni fa nacque il pittore Correggio?",min:0,max:600,risposta:540,unit:"anni fa circa",curiosita:"Correggio (Antonio Allegri) nacque intorno al 1489 a Correggio (Reggio Emilia) — circa 535 anni fa. Anticipò il Barocco di un secolo con i suoi chiaroscuri morbidi e le illusioni prospettiche delle cupole (Duomo di Parma). La Notte (1529-30) con la luce emanata dal Bambin Gesù è unica."},
 {q:"Quante specie di libellule vere (Anisoptera) esistono?",min:0,max:3000,risposta:3000,unit:"specie",curiosita:"Le libellule vere (Anisoptera) hanno circa 3.000 specie. Le loro ali anteriori e posteriori si muovono indipendentemente — possono volare in tutte le direzioni. Vedono con 30.000 faccette oculari e captano il movimento a 300 gradi. Predatori di successo nel 95% degli attacchi."},
 {q:"Quanti anni fa nacque il pittore Sodoma?",min:0,max:600,risposta:521,unit:"anni fa",curiosita:"Giovanni Antonio Bazzi detto il Sodoma nacque il 1477 a Vercelli — 547 anni fa. Lavorò per i Medici a Firenze e per i papi a Roma. Le sue storie di San Benedetto a Monteoliveto Maggiore (1505-08) sono tra i cicli narrativi più belli del primo Cinquecento."},
 {q:"Quante specie di aquile esistono?",min:0,max:100,risposta:68,unit:"specie",curiosita:"Esistono circa 68 specie di aquile. L'aquila di Haast estinta della Nuova Zelanda era il più grande rapace mai esistito: 3 m di apertura alare, cacciava il moa gigante. L'aquila di Steller (Haliaeetus pelagicus) è la più pesante aquila vivente: 9 kg."},
 {q:"Quanti anni fa nacque il pittore Giovanni Antonio Pordenone?",min:0,max:600,risposta:540,unit:"anni fa circa",curiosita:"Il Pordenone (Giovanni Antonio de' Sacchis) nacque intorno al 1484 a Pordenone — circa 540 anni fa. Il suo stile muscolare e violento era così lontano da Tiziano che i due erano rivali acerrimi. Gli affreschi del Duomo di Cremona (1520-21) anticipano la pittura barocca di 80 anni."},
 {q:"Quante specie di mantidi acquatiche esistono?",min:0,max:200,risposta:150,unit:"specie (Nepidae)",curiosita:"Le nepe e ranatra (Nepidae) hanno circa 150 specie. Non sono mantidi — sono emitteri. La ranatra è lunga e sottile come un ago. La nepe è piatta come una foglia morta. Entrambe usano un sifone respiratorio per stare sott'acqua. Predatrici di insetti e girini."},
 {q:"Quanti anni fa nacque il pittore Battista Dossi?",min:0,max:600,risposta:530,unit:"anni fa circa",curiosita:"Battista Dossi nacque intorno al 1490 a Ferrara — circa 534 anni fa. Fratello e collaboratore di Dosso Dossi. I due lavorarono sempre insieme per la corte Este. La divisione dei loro contributi è ancora dibattuta dagli storici dell'arte."},
 {q:"Quante specie di pidocchi (Phthiraptera) esistono?",min:0,max:5000,risposta:5000,unit:"specie",curiosita:"I pidocchi hanno circa 5.000 specie. Ogni specie è specializzata in un ospite preciso — il pidocchio dei capelli umani (Pediculus humanus capitis) vive solo sui capelli umani. I pidocchi dei pinguini non possono sopravvivere su altri uccelli. Co-evolvono con i loro ospiti per milioni di anni."},
 {q:"Quanti anni fa nacque il pittore Paris Bordone?",min:0,max:600,risposta:524,unit:"anni fa",curiosita:"Paris Bordone nacque nel 1500 a Treviso — 524 anni fa. Allievo di Tiziano. La Consegna dell'anello al Doge (1534) alle Gallerie dell'Accademia è il suo capolavoro — grande scena narrativa in uno spazio architettonico illusionistico magnifico."},
 {q:"Quante specie di trombidiformes (acari rossi) esistono?",min:0,max:20000,risposta:12000,unit:"specie",curiosita:"I trombidiformes hanno circa 12.000 specie. Includono gli acari della polvere, gli acari del formaggio, le zecche in alcune classificazioni. L'Eriophyes tiliae forma le galle rosse dei tigli — una per ogni specie di pianta. Gli acari predatori sono usati in lotta biologica."},
 {q:"Quanti anni fa nacque il pittore Tiziano Vecellio?",min:0,max:600,risposta:534,unit:"anni fa circa",curiosita:"Tiziano nacque intorno al 1490 a Pieve di Cadore — circa 534 anni fa. Visse quasi 100 anni (morì nel 1576 di peste). Pintò per Carlo V, Filippo II, papi e nobili di tutta Europa. Baccanale degli Andrii (1524), Venere di Urbino (1538) e la Pietà (1576) sono i suoi capolavori."},
 {q:"Quante specie di panda esistono?",min:0,max:5,risposta:2,unit:"specie",curiosita:"Esistono 2 specie di panda: il panda gigante (Ailuropoda melanoleuca) e il panda rosso (Ailurus fulgens). Non sono parenti — il panda gigante è un orso, il panda rosso è un mustelide. Entrambi mangiarono bambù per la stessa soluzione evolutiva. Il panda rosso fu descritto prima — nel 1825."},
 {q:"Quanti lati ha un eptadecagono?",min:0,max:100,risposta:17,unit:"lati",curiosita:"L'eptadecagono ha 17 lati. A soli 19 anni Gauss dimostrò che l'eptadecagono regolare si può costruire con riga e compasso — prima dimostrazione dopo 2000 anni di matematica greca. Fu così orgoglioso da chiedere che fosse inciso sulla sua tomba (in realtà incisero una stella a 17 punte)."},
 {q:"Quante specie di iguane esistono?",min:0,max:50,risposta:35,unit:"specie (Iguanidae)",curiosita:"Le iguane hanno circa 35 specie. L'iguana marina delle Galapagos è l'unico rettile marino al mondo — nuota e si immerge fino a 12 m per mangiare alghe. L'iguana verde può cadere da 15 m di altezza senza farsi del male. Sono erbivore ma possono mordere ferocemente se provocate."},
 {q:"Quanti anni fa nacque il pittore Albrecht Dürer?",min:0,max:600,risposta:553,unit:"anni fa",curiosita:"Dürer nacque il 21 maggio 1471 a Norimberga — 553 anni fa. L'Autoritratto del 1500 è il primo in assoluto in posizione frontale nella storia dell'arte — Cristo-like. Portò l'Umanesimo italiano in Germania. Il Rinoceronte (1515) — incisione basata su descrizioni verbali — fu la più copiata del XVI secolo."},
 {q:"Quante specie di piovre del Pacifico esistono?",min:0,max:50,risposta:25,unit:"specie nell'Oceano Pacifico",curiosita:"Nel Pacifico vivono circa 25 specie di polpi. Il polpo mimetico (Thaumoctopus mimicus) trovato in Indonesia imita 15 specie diverse: suole, leoni marini, meduse, pesci piatti. Ogni imitazione è scelta in base al predatore specifico — comportamento che richiede ragionamento."},
 {q:"Quante specie di dinosauri teropodi bipedi sono conosciute?",min:0,max:2000,risposta:1000,unit:"specie circa",curiosita:"I teropodi (dinosauri bipedi predatori) hanno circa 1.000 specie fossili note. Includono il T-rex, il Velociraptor, l'Allosaurus. Il Velociraptor era grande come un tacchino — non come in Jurassic Park. I teropodi non si estinsero — gli uccelli sono teropodi sopravvissuti."},
 {q:"Quanti metri è alta la Statua della Libertà (dalla base alla torcia)?",min:0,max:200,risposta:93,unit:"metri",curiosita:"La Statua della Libertà misura 93 metri dalla base alla torcia. La statua stessa è 46 metri, il piedistallo 47. Fu donata dalla Francia agli USA nel 1886."},
 {q:"Quanti secondi dura un minuto?",min:0,max:120,risposta:60,unit:"secondi",curiosita:"Un minuto dura 60 secondi — un sistema sessagesimale ereditato dai Babilonesi oltre 4.000 anni fa. Lo stesso sistema divide le ore e i gradi d'arco."},
 {q:"Quante ossa ha il piede umano?",min:0,max:50,risposta:26,unit:"ossa",curiosita:"Ogni piede contiene 26 ossa — il 25% di tutte le ossa del corpo sono nei piedi. Insieme ai 33 giunti permettono un'incredibile varietà di movimenti."},
 {q:"Quanti km di strade ci sono in Italia?",min:0,max:1000000,risposta:487700,unit:"km",curiosita:"L'Italia ha circa 487.700 km di strade. La rete autostradale è di circa 7.000 km — una delle più estese d'Europa. Tutte le strade portano a Roma... o quasi."},
 {q:"Quanti anni ci vuole a Marte per fare un giro completo intorno al Sole?",min:0,max:20,risposta:2,unit:"anni terrestri circa",curiosita:"Marte impiega circa 687 giorni terrestri — quasi 2 anni — a orbitare attorno al Sole. Un anno marziano dura circa 668 giorni marziani (sol)."},
 {q:"Quante formiche esistono sul pianeta Terra?",min:0,max:100000000,risposta:20000000,unit:"miliardi",curiosita:"Si stima che esistano circa 20 milioni di miliardi di formiche. Per ogni essere umano ci sono circa 2,5 milioni di formiche. La loro biomassa supera quella di tutti i mammiferi selvatici combinati."},
 {q:"Quanti grammi pesa un iPhone 15?",min:0,max:500,risposta:171,unit:"grammi",curiosita:"L'iPhone 15 pesa 171 grammi. Il primo iPhone del 2007 pesava 135 grammi. Nonostante schermi più grandi e più funzioni, gli smartphone moderni sono solo leggermente più pesanti."},
 {q:"Quante ore di luce solare riceve mediamente l'Italia al giorno in estate?",min:0,max:24,risposta:14,unit:"ore",curiosita:"In estate (giugno) l'Italia riceve circa 14-15 ore di luce solare al giorno. D'inverno scende a 9-10 ore. Le variazioni aumentano spostandosi verso nord."},
 {q:"Quanti milioni di abitanti ha la Nigeria?",min:0,max:500,risposta:220,unit:"milioni",curiosita:"La Nigeria ha circa 220 milioni di abitanti — la nazione più popolosa d'Africa. Entro il 2050 potrebbe diventare il terzo paese più popoloso al mondo dopo India e Cina."},
 {q:"A quanti gradi Celsius arriva la lava di un vulcano?",min:0,max:2000,risposta:1200,unit:"°C circa",curiosita:"La lava basaltica raggiunge 1.000-1.200°C. La lava più calda mai registrata (komatiitica) superava 1.600°C. Nonostante le temperature, la lava si muove spesso più lentamente di quanto si pensi."},
 {q:"Quanti anni ha impiegato la costruzione della Torre di Pisa?",min:0,max:300,risposta:199,unit:"anni",curiosita:"La costruzione della Torre di Pisa durò circa 199 anni — dal 1173 al 1372. Si è inclinata quasi subito, durante la costruzione, a causa del terreno instabile. L'inclinazione fu corretta parzialmente nel 2001."},
 {q:"Quanti paesi riconoscono il Vaticano come Stato?",min:0,max:200,risposta:183,unit:"paesi",curiosita:"183 paesi hanno relazioni diplomatiche con il Vaticano. Con 0,44 km² è lo Stato più piccolo del mondo — più piccolo di qualsiasi campo da golf professionistico."},
 {q:"Quante stelle conta approssimativamente la Via Lattea?",min:0,max:1000,risposta:300,unit:"miliardi",curiosita:"La Via Lattea contiene circa 200-400 miliardi di stelle. Il Sole è una stella di taglia media situata in un braccio a spirale, a circa 26.000 anni luce dal centro galattico."},
 {q:"Quante ore dorme in media un delfino a notte?",min:0,max:12,risposta:8,unit:"ore",curiosita:"I delfini dormono circa 8 ore al giorno in modo insolito: tenendo un solo emisfero cerebrale attivo per volta (sonno unisemisferico). Così non smettono mai di respirare — devono farlo consciamente."},
 {q:"Quanti anni ci ha messo Dante Alighieri a scrivere la Divina Commedia?",min:0,max:30,risposta:15,unit:"anni circa",curiosita:"Dante iniziò la Divina Commedia intorno al 1307 e terminò il Paradiso poco prima di morire nel 1321 — circa 14-15 anni. È considerata la più grande opera letteraria in lingua italiana."},
 {q:"Quante frecce al secondo può scoccare un arciere olimpico esperto?",min:0,max:10,risposta:2,unit:"frecce al secondo",curiosita:"Un arciere olimpico scocca circa 1-2 frecce al secondo in condizioni ottimali. Le competizioni prevedono sequenze di 3 o 6 frecce in 30-40 secondi. La precisione a 70 metri è sorprendente."},
 {q:"Quanti milioni di auto ci sono in Italia?",min:0,max:80,risposta:42,unit:"milioni",curiosita:"In Italia circolano circa 42 milioni di autovetture — circa 1 auto ogni 1,4 abitanti. Siamo tra i paesi con la più alta densità di auto pro capite al mondo."},
 {q:"Quante calorie brucia un adulto medio dormendo per 8 ore?",min:0,max:1000,risposta:400,unit:"kcal",curiosita:"Dormendo si bruciano circa 50 calorie all'ora — 400 in 8 ore. Il cervello da solo consuma circa il 20% dell'energia totale, anche durante il sonno."},
 {q:"Quanti anni ha l'universo?",min:0,max:20000000000,risposta:13800000000,unit:"anni",curiosita:"L'universo ha circa 13,8 miliardi di anni — dall'esplosione del Big Bang. La Terra ha 4,5 miliardi di anni. Gli esseri umani moderni esistono da soli 300.000 anni — un battito d'occhio cosmico."},
 {q:"Quanti gradi centigradi è la temperatura media del corpo umano?",min:35,max:42,risposta:37,unit:"°C",curiosita:"La temperatura corporea normale è circa 37°C — ma varia tra 36,1 e 37,2°C. Sopra 38°C si parla di febbre. Scendere sotto 35°C causa ipotermia, sopra 41°C convulsioni."},
 {q:"Quanti anni ha impiegato la costruzione del Colosseo?",min:0,max:20,risposta:8,unit:"anni",curiosita:"Il Colosseo fu costruito in soli 8-10 anni (70-80 d.C.) dall'imperatore Vespasiano e completato da Tito. Lavorarono decine di migliaia di operai e schiavi. Poteva ospitare fino a 80.000 spettatori."},
 {q:"Quanti km è lontana la Luna dalla Terra?",min:0,max:1000000,risposta:384400,unit:"km",curiosita:"La Luna dista in media 384.400 km dalla Terra. La distanza varia tra 356.500 km (perigeo) e 406.700 km (apogeo). La luce impiega circa 1,3 secondi a percorrere quella distanza."},
 {q:"Quante lingue parlava Giulio Cesare?",min:0,max:10,risposta:3,unit:"lingue",curiosita:"Cesare parlava latino (madrelingua), greco (lingua della cultura dell'epoca) e probabilmente gallico, acquisito durante le campagne militari. Era anche un rinomato oratore e scrittore."},
 {q:"Quanti litri di acqua contiene il corpo umano in media?",min:0,max:80,risposta:42,unit:"litri",curiosita:"Il corpo umano adulto contiene circa 42 litri di acqua — il 60% del peso corporeo. Nei bambini sale al 75%. Bere almeno 2 litri al giorno è raccomandato per mantenere l'equilibrio idrico."},
 {q:"Quanti anni ha vissuto la tartaruga Jonathan, l'esemplare più anziano conosciuto?",min:0,max:250,risposta:192,unit:"anni",curiosita:"Jonathan, una tartaruga delle Seychelles, ha circa 192 anni (nato intorno al 1832) ed è l'animale terrestre vivente più anziano conosciuto. Vive a Sant'Elena, la stessa isola dell'esilio di Napoleone."},
 {q:"Quanti musicisti compone solitamente un'orchestra sinfonica completa?",min:0,max:150,risposta:100,unit:"musicisti",curiosita:"Un'orchestra sinfonica completa conta circa 80-100 musicisti. L'orchestra più grande mai riunita aveva oltre 6.000 musicisti a Oslo nel 1964. Beethoven scrisse per orchestre di 60-80 elementi."},
 {q:"Quanti vulcani attivi ci sono in Italia?",min:0,max:20,risposta:7,unit:"vulcani",curiosita:"L'Italia ha circa 7 vulcani attivi: Etna, Stromboli, Vulcano, Campi Flegrei, Vesuvio (quiescente), Ischia e Colli Albani. Lo Stromboli è in eruzione quasi continua da 2.000 anni."},
 {q:"Quante persone hanno camminato sulla Luna?",min:0,max:20,risposta:12,unit:"persone",curiosita:"12 astronauti hanno camminato sulla Luna tra il 1969 e il 1972 — tutti americani, tutti uomini. L'ultimo fu Eugene Cernan nel dicembre 1972. Nessun essere umano è tornato sulla Luna da allora."},
 {q:"Quante versioni di Windows ha rilasciato Microsoft dalla sua nascita?",min:0,max:30,risposta:21,unit:"versioni principali",curiosita:"Microsoft ha rilasciato circa 21 versioni principali di Windows dal 1985 (Windows 1.0) ad oggi. Windows 11 è l'ultima versione. Tra le più famose: Windows 95, XP, 7 e 10."},
 {q:"Quanti anni aveva Steve Jobs quando fondò Apple?",min:0,max:30,risposta:21,unit:"anni",curiosita:"Steve Jobs fondò Apple il 1° aprile 1976 all'età di 21 anni, insieme a Steve Wozniak (25) e Ronald Wayne (41). Wayne vendette la sua quota per 800 dollari — oggi varrebbe miliardi."},
 {q:"Quanti Big Mac vengono venduti ogni giorno nel mondo?",min:0,max:20000000,risposta:9000000,unit:"Big Mac",curiosita:"McDonald's vende circa 9 milioni di Big Mac al giorno nel mondo. Il Big Mac è stato inventato nel 1967 da Jim Delligatti, un franchisee di Pittsburgh. L'Economist usa il suo prezzo per confrontare le valute globali."},
 {q:"Quanti elementi chimici contiene la tavola periodica?",min:0,max:150,risposta:118,unit:"elementi",curiosita:"La tavola periodica contiene 118 elementi. 94 sono naturali, 24 sono stati sintetizzati in laboratorio. L'oganesson (118) è l'elemento più pesante mai creato — esiste solo per pochi millisecondi."},
 {q:"Quanti anni fa fu costruita la Piramide di Giza?",min:0,max:10000,risposta:4500,unit:"anni fa circa",curiosita:"La Grande Piramide di Giza fu costruita circa 4.500 anni fa (intorno al 2.560 a.C.) per il faraone Khufu. Fu la struttura più alta del mondo per 3.800 anni, fino alla costruzione della Cattedrale di Lincoln nel 1311."},
 {q:"Quante teste vince chi fa tombola in una serata tipica italiana?",min:0,max:10,risposta:1,unit:"testé",curiosita:"Alla tombola si vince una sola 'tombola' per partita — quando si completano tutti e 15 i numeri del proprio cartellone. Prima arrivano ambo, terno, quaterna, cinquina. La tombola napoletana ha 90 numeri."},
 {q:"Quanti anni ci sono voluti per costruire la Sagrada Família di Barcellona?",min:0,max:200,risposta:142,unit:"anni e non è ancora finita",curiosita:"La Sagrada Família è in costruzione dal 1882 — oltre 140 anni. Gaudí lavorò al progetto dal 1883 fino alla sua morte nel 1926. La conclusione è prevista per il 2026, centenario della morte di Gaudí."},
 {q:"Quanti passi fa in media un essere umano in un giorno?",min:0,max:30000,risposta:7500,unit:"passi",curiosita:"Un adulto cammina circa 7.500 passi al giorno in media. L'OMS raccomanda 10.000 passi. Il popolo Amish percorre in media 18.000 passi al giorno — tra i più attivi al mondo."},
 {q:"Quanti album ha venduto Michael Jackson nella sua carriera?",min:0,max:1000,risposta:350,unit:"milioni",curiosita:"Michael Jackson ha venduto oltre 350 milioni di album in tutto il mondo. 'Thriller' (1982) rimane l'album più venduto di tutti i tempi con oltre 70 milioni di copie."},
 {q:"Quanti millimetri cresce in media un'unghia umana al mese?",min:0,max:10,risposta:3,unit:"mm",curiosita:"Le unghie crescono circa 3 mm al mese (0,1 mm al giorno). Le unghie delle mani crescono più velocemente di quelle dei piedi. Crescono più in estate e sulle mani dominanti."},
 {q:"Quanti piani ha il grattacielo Burj Khalifa di Dubai?",min:0,max:250,risposta:163,unit:"piani",curiosita:"Il Burj Khalifa ha 163 piani e un'altezza di 828 metri — il più alto del mondo. La costruzione è durata dal 2004 al 2010. Ci vogliono 35 ascensori ad alta velocità per raggiungere il piano più alto."},
 {q:"Quanti anni ci sono voluti a costruire la Muraglia Cinese?",min:0,max:2000,risposta:2000,unit:"anni (in fasi diverse)",curiosita:"La Grande Muraglia è stata costruita e ampliata nell'arco di circa 2.000 anni, dalle prime sezioni del VII secolo a.C. fino alla dinastia Ming (1368-1644). La sua lunghezza totale supera i 20.000 km."},
 {q:"Quante calorie ha una lattina di Coca-Cola (330ml)?",min:0,max:300,risposta:139,unit:"kcal",curiosita:"Una lattina da 330ml di Coca-Cola contiene circa 139 calorie e 35 grammi di zucchero. La variante Zero o Light ha circa 1-2 calorie. Gli italiani consumano circa 250 milioni di lattine di Coca-Cola all'anno."},
 {q:"A quanti km/h vola un falco pellegrino in picchiata?",min:0,max:500,risposta:389,unit:"km/h massimo",curiosita:"Il falco pellegrino raggiunge 389 km/h in picchiata — l'animale più veloce della Terra. In volo orizzontale non supera i 100 km/h. La sua struttura nasale riduce la pressione dell'aria a tali velocità."},
 {q:"Quanti milioni di persone usano Instagram ogni mese?",min:0,max:5000,risposta:2000,unit:"milioni",curiosita:"Instagram ha circa 2 miliardi di utenti attivi mensili nel 2024. Fu fondato nel 2010 da Kevin Systrom e Mike Krieger. Facebook la acquistò nel 2012 per 1 miliardo di dollari — uno degli acquisti più redditizi della storia tech."},
 {q:"Quanti anni ci ha messo Michelangelo a dipingere il soffitto della Cappella Sistina?",min:0,max:20,risposta:4,unit:"anni",curiosita:"Michelangelo dipinse il soffitto della Cappella Sistina dal 1508 al 1512 — circa 4 anni. Non era un pittore specializzato in affreschi: era principalmente scultore. Quasi sempre lavorava in posizione eretta, non sdraiato come si crede."},
 {q:"Quante specie di squali esistono nel mondo?",min:0,max:800,risposta:500,unit:"specie",curiosita:"Esistono circa 500 specie di squali. Il più grande è lo squalo balena (18 metri), che si nutre di plancton. Lo squalo bianco attacca raramente l'uomo — in media 5-10 attacchi mortali l'anno in tutto il mondo."},
 {q:"Quanti euro vale il PIL dell'Italia ogni anno?",min:0,max:5000,risposta:2085,unit:"miliardi di euro",curiosita:"Il PIL italiano è circa 2.085 miliardi di euro (2023) — la terza economia dell'eurozona. L'Italia rappresenta circa il 12% del PIL totale dell'UE. Il PIL pro capite è di circa 35.000 euro."},
 {q:"Quante ore di sonno raccomanda l'OMS per un adulto?",min:0,max:12,risposta:8,unit:"ore",curiosita:"L'OMS raccomanda 7-9 ore di sonno per gli adulti (8 come valore centrale). I neonati necessitano 14-17 ore. Dormire meno di 6 ore per notte aumenta il rischio di malattie cardiovascolari e diabete."},
 {q:"Quanti anni è durata la Guerra dei Cent'Anni?",min:0,max:200,risposta:116,unit:"anni",curiosita:"La Guerra dei Cent'Anni durò in realtà 116 anni (1337-1453) tra Francia e Inghilterra. Giovanna d'Arco vi giocò un ruolo decisivo prima di essere bruciata sul rogo nel 1431 a soli 19 anni."},
 {q:"Quanti km di pipeline del gas ci sono in Europa?",min:0,max:500000,risposta:200000,unit:"km",curiosita:"La rete europea di gasdotti supera i 200.000 km. L'Europa importa gas da Russia, Norvegia, Algeria e GNL americano. La crisi energetica del 2022 ha accelerato la diversificazione delle fonti."},
 {q:"Quante persone visitano il Louvre ogni anno?",min:0,max:20000000,risposta:9000000,unit:"visitatori",curiosita:"Il Louvre accoglie circa 9 milioni di visitatori l'anno — il museo più visitato del mondo. La Gioconda da sola attira il 70% dei visitatori. La piramide di vetro fu progettata da I.M. Pei e inaugurata nel 1989."},
 {q:"Quanti anni ha lo scacchi come gioco?",min:0,max:3000,risposta:1500,unit:"anni circa",curiosita:"Gli scacchi hanno circa 1.500 anni — nati in India come 'chaturanga' intorno al VI secolo d.C. Giunsero in Persia, poi nel mondo arabo e infine in Europa medievale. Le regole moderne si consolidarono nel XV secolo."},
 {q:"Quante squadre partecipano alla Serie A italiana?",min:0,max:30,risposta:20,unit:"squadre",curiosita:"La Serie A ha 20 squadre. Ogni stagione le ultime 3 retrocedono in Serie B. La Juventus è il club più titolato con 36 scudetti. Il campionato italiano è iniziato nel 1898."},
 {q:"Quanti gradi ha un angolo piatto?",min:0,max:360,risposta:180,unit:"gradi",curiosita:"Un angolo piatto misura 180 gradi. Un angolo retto è 90°, un angolo giro 360°. La suddivisione del cerchio in 360 gradi risale ai Babilonesi, che usavano una matematica base 60."},
 {q:"Quanti km di spiagge ha l'Italia?",min:0,max:20000,risposta:7500,unit:"km",curiosita:"L'Italia ha circa 7.500 km di coste. Le regioni con più chilometri di spiaggia sono Sardegna, Sicilia e Puglia. Circa il 60% delle coste italiane è balneabile, il 40% è roccioso o inaccessibile."},
 {q:"Quante persone muoiono ogni anno a causa del tabacco nel mondo?",min:0,max:20000000,risposta:8000000,unit:"persone",curiosita:"Il tabacco causa circa 8 milioni di morti l'anno nel mondo. 7 milioni sono fumatori diretti, 1 milione sono non fumatori esposti al fumo passivo. È la principale causa di morte prevenibile al mondo."},
 {q:"Quanti anni ci ha messo J.K. Rowling a scrivere il primo Harry Potter?",min:0,max:15,risposta:5,unit:"anni",curiosita:"J.K. Rowling impiegò circa 5 anni a scrivere 'Harry Potter e la Pietra Filosofale' (1990-1995). L'idea le venne durante un viaggio in treno. Il libro fu rifiutato da 12 editori prima della pubblicazione nel 1997."},
 {q:"Quanti litri di sangue pompa il cuore umano ogni giorno?",min:0,max:20000,risposta:7500,unit:"litri",curiosita:"Il cuore pompa circa 7.500 litri di sangue al giorno — oltre 2,5 milioni di litri nell'arco di una vita. A riposo pompa 4-5 litri al minuto; sotto sforzo intenso può arrivare a 20-25 litri al minuto."},
 {q:"Quanti anni fa nacque Gesù Cristo secondo il calendario gregoriano?",min:0,max:2100,risposta:2024,unit:"anni fa circa",curiosita:"Gesù Cristo è nato probabilmente tra il 4 e il 6 a.C. — paradossalmente prima di Cristo! Il monaco Dionigi il Piccolo nel VI secolo fece un calcolo errato quando istituì il calendario cristiano."},
 {q:"Quante ore impiega un volo diretto da Roma a New York?",min:0,max:20,risposta:10,unit:"ore circa",curiosita:"Un volo diretto Roma-New York dura circa 9-10 ore verso ovest (con il vento contrario). Il ritorno è di 8-9 ore grazie alle correnti a getto. La distanza è circa 7.000 km."},
 {q:"Quanti pesi ha un Boeing 747 in decollo?",min:0,max:600,risposta:412,unit:"tonnellate massimo",curiosita:"Il Boeing 747 ha un peso massimo al decollo di circa 412 tonnellate. Solo il carburante può pesare fino a 180 tonnellate. I motori generano una spinta di circa 30.000 kg ciascuno — 4 in totale."},
 {q:"Quante nazioni hanno mai partecipato alle Olimpiadi?",min:0,max:250,risposta:206,unit:"nazioni",curiosita:"206 comitati olimpici nazionali hanno partecipato alle Olimpiadi (più dei 195 paesi riconosciuti dall'ONU). I Giochi del 1896 ad Atene videro solo 14 nazioni partecipanti e 241 atleti."},
 {q:"Quante righe di codice contiene il sistema operativo Android?",min:0,max:50000000,risposta:12000000,unit:"righe di codice",curiosita:"Android contiene circa 12-15 milioni di righe di codice. Linux ha circa 27 milioni. Il software del rover marziano Curiosity ha circa 2,5 milioni di righe — scritte da circa 1.000 programmatori."},
 {q:"Quanti grammi pesa un pallone da calcio regolamentare?",min:0,max:1000,risposta:450,unit:"grammi",curiosita:"Un pallone da calcio deve pesare tra 410 e 450 grammi secondo le regole FIFA. La circonferenza deve essere tra 68 e 70 cm. Il pallone deve essere di cuoio o materiale sintetico adatto."},
 {q:"Quanti milioni di tonnellate di cemento produce la Cina ogni anno?",min:0,max:5000,risposta:2300,unit:"milioni di tonnellate",curiosita:"La Cina produce circa 2,3 miliardi di tonnellate di cemento l'anno — il 55% della produzione mondiale. Dal 2011 al 2013, la Cina ha usato più cemento che gli USA in tutto il XX secolo."},
 {q:"Quante ore al giorno guarda la TV in media un italiano?",min:0,max:10,risposta:4,unit:"ore",curiosita:"Gli italiani guardano la TV circa 4 ore al giorno in media — tra i più alti in Europa. Gli over 65 arrivano a 6-7 ore. La televisione è entrata nelle case italiane negli anni '50, con la RAI che iniziò le trasmissioni nel 1954."},
 {q:"Quanti anni ha impiegato Tolkien a scrivere Il Signore degli Anelli?",min:0,max:20,risposta:12,unit:"anni",curiosita:"Tolkien impiegò circa 12 anni a scrivere 'Il Signore degli Anelli' (1937-1949). Il libro fu pubblicato in tre volumi nel 1954-55. Lo Hobbit era stato scritto quasi per gioco nel 1937 come storia per i figli."},
 {q:"Quanti km di metropolitana ci sono a Parigi?",min:0,max:500,risposta:225,unit:"km",curiosita:"La metropolitana di Parigi ha circa 225 km di linee e 302 stazioni. È una delle più dense al mondo in rapporto alla superficie urbana. La prima linea aprì nel 1900 per l'Esposizione Universale."},
 {q:"Quante uova depone in media una gallina all'anno?",min:0,max:500,risposta:250,unit:"uova",curiosita:"Una gallina moderna da allevamento depone circa 250-300 uova l'anno. Le razze selvatiche ne depositano solo 12-15. L'Italia produce circa 13 miliardi di uova l'anno e ne importa circa 1,5 miliardi."},
 {q:"Quanti anni aveva Napoleone quando divenne imperatore?",min:0,max:50,risposta:35,unit:"anni",curiosita:"Napoleone fu incoronato imperatore il 2 dicembre 1804 a 35 anni. Si incoronò da solo — sfilando la corona dalle mani di Papa Pio VII. Morì nel 1821 a 51 anni, probabilmente di cancro allo stomaco."},
 {q:"Quanti miliardi di euro vale il mercato del calcio europeo?",min:0,max:50,risposta:29,unit:"miliardi di euro",curiosita:"Il mercato calcistico europeo vale circa 29 miliardi di euro di fatturato annuo. La Premier League inglese è la più ricca con 6-7 miliardi. Il calciatore più caro di sempre è Neymar: 222 milioni nel 2017."},
 {q:"Quante parole contiene in media un romanzo classico?",min:0,max:500000,risposta:90000,unit:"parole",curiosita:"Un romanzo medio contiene 70.000-90.000 parole. 'Guerra e Pace' di Tolstoy ne ha oltre 580.000. 'Il Vecchio e il Mare' di Hemingway solo 27.000. Harry Potter e la Pietra Filosofale ne ha 77.000."},
 {q:"Quanti anni aveva Leonardo da Vinci quando morì?",min:0,max:100,risposta:67,unit:"anni",curiosita:"Leonardo da Vinci morì il 2 maggio 1519 a 67 anni ad Amboise, in Francia. Visse gli ultimi anni alla corte del re Francesco I. Lasciò incompiuti molti progetti — pittore, scultore, ingegnere, anatomista, musicista."},
 {q:"Quante persone usano TikTok ogni mese nel mondo?",min:0,max:3000,risposta:1700,unit:"milioni",curiosita:"TikTok ha circa 1,7 miliardi di utenti attivi mensili. È l'app più scaricata al mondo nel 2020 e 2021. In media gli utenti trascorrono 52 minuti al giorno sulla piattaforma."},
 {q:"Quanti denti ha un adulto umano?",min:0,max:40,risposta:32,unit:"denti",curiosita:"Un adulto ha 32 denti, inclusi i 4 denti del giudizio. Se si estraggono i denti del giudizio (come spesso accade), si scende a 28. I bambini hanno 20 denti da latte."},
 {q:"Quanti km di rete ferroviaria ci sono in Italia?",min:0,max:50000,risposta:16700,unit:"km",curiosita:"L'Italia ha circa 16.700 km di rete ferroviaria. La prima ferrovia italiana fu la Napoli-Portici nel 1839. L'alta velocità (Frecciarossa) collega Roma e Milano in meno di 3 ore percorrendo 580 km."},
 {q:"Quante lingue ufficiali ha l'Unione Europea?",min:0,max:30,risposta:24,unit:"lingue",curiosita:"L'UE ha 24 lingue ufficiali — il più alto numero di lingue in qualsiasi organizzazione internazionale. Tutti i documenti ufficiali vengono tradotti in tutte le lingue. L'irlandese è l'ultima lingua aggiunta (2007)."},
 {q:"Quanti anni fa è stato fondato McDonald's?",min:0,max:100,risposta:84,unit:"anni fa",curiosita:"McDonald's fu fondato nel 1940 dai fratelli Richard e Maurice McDonald a San Bernardino, California. Ray Kroc acquistò l'azienda nel 1961 e la espanse globalmente. Oggi ha oltre 40.000 ristoranti in 100 paesi."},
 {q:"Quanti litri di latte produce una mucca al giorno?",min:0,max:100,risposta:25,unit:"litri",curiosita:"Una mucca da latte moderna produce circa 25-30 litri al giorno — oltre 8.000 litri l'anno. Le mucche selvatiche producono solo 3-4 litri. L'Italia è uno dei maggiori produttori di latte in Europa."},
 {q:"Quanti anni ha la città di Roma?",min:0,max:5000,risposta:2777,unit:"anni",curiosita:"Roma fu fondata tradizionalmente nel 753 a.C. — quindi ha circa 2.777 anni nel 2024. La frase 'Roma non è stata costruita in un giorno' è attribuita al cronista medievale Rimbaud de Vaqueiras, nel 1190."},
 {q:"Quanti milioni di persone vivono in condizioni di povertà estrema nel mondo?",min:0,max:2000,risposta:700,unit:"milioni",curiosita:"Circa 700 milioni di persone vivono con meno di 2,15 dollari al giorno (soglia di povertà estrema della Banca Mondiale). Nel 1990 erano 2 miliardi. Il progresso è stato enorme, ma ancora insufficiente."},
 {q:"Quante righe di testo ha la Bibbia?",min:0,max:50000,risposta:31000,unit:"versetti circa",curiosita:"La Bibbia contiene circa 31.000 versetti (31.102 nell'edizione King James). Il libro più lungo è i Salmi con 150 capitoli. Il versetto più corto è Giovanni 11:35: 'Gesù pianse' — due parole in italiano."},
 {q:"Quante stelle ha la bandiera americana?",min:0,max:60,risposta:50,unit:"stelle",curiosita:"La bandiera americana ha 50 stelle, una per ogni stato. Le 13 strisce rappresentano le colonie originali. L'ultima stella fu aggiunta nel 1960 dopo l'adesione delle Hawaii. La bandiera ha avuto 27 versioni diverse."},
 {q:"Quanti anni ha il whisky più vecchio mai venduto all'asta?",min:0,max:200,risposta:110,unit:"anni",curiosita:"Il whisky più vecchio venduto all'asta è un Glenlivet 1955 acquistato nel 2022 — 67 anni. Ma nel 2019 una bottiglia di Macallan 1926 fu venduta per 1,9 milioni di dollari — il record assoluto."},
 {q:"Quanti anni fa fu dipinta la Cappella Sistina (soffitto)?",min:0,max:600,risposta:512,unit:"anni fa",curiosita:"Michelangelo dipinse il soffitto della Cappella Sistina tra il 1508 e il 1512 — circa 512 anni fa. Il Giudizio Universale sulla parete dell'altare fu aggiunto tra il 1536 e il 1541."},
 {q:"Quanti grammi di zucchero ci sono in una Nutella (200g)?",min:0,max:200,risposta:108,unit:"grammi di zucchero",curiosita:"In un vasetto da 200g di Nutella ci sono circa 108 grammi di zucchero — il 54% del contenuto. La Nutella è stata inventata da Pietro Ferrero nel 1964 come alternativa economica al cacao scarso nel dopoguerra."},
 {q:"Quanti anni ha impiegato la costruzione del Duomo di Milano?",min:0,max:700,risposta:600,unit:"anni circa",curiosita:"Il Duomo di Milano fu iniziato nel 1386 e la sua costruzione — con interruzioni — durò quasi 600 anni, fino al 1965 quando furono completate le ultime porte. Ha 3.400 statue e 135 guglie."},
 {q:"Quanti anni fa fu inventata la stampa 3D?",min:0,max:60,risposta:42,unit:"anni fa",curiosita:"La stampa 3D fu inventata nel 1981 da Hideo Kodama in Giappone. Il primo brevetto commerciale fu di Chuck Hull nel 1984. Oggi si usano stampanti 3D per protesi mediche, componenti aerospaziali e persino case."},
 {q:"Quanti km è la distanza da Milano a Roma?",min:0,max:2000,risposta:572,unit:"km in linea d'aria",curiosita:"La distanza in linea d'aria tra Milano e Roma è circa 572 km. In auto sull'autostrada sono circa 575 km (5-6 ore). In treno ad alta velocità sono circa 580 km e meno di 3 ore."},
 {q:"Quante persone vivono nelle città (urbane) nel mondo?",min:0,max:100,risposta:57,unit:"% della popolazione mondiale",curiosita:"Il 57% della popolazione mondiale vive in aree urbane (2023) — circa 4,5 miliardi di persone. Nel 1950 era solo il 30%. Entro il 2050 si prevede che salga al 68%."},
 {q:"Quanti anni ci ha messo Picasso a dipingere Guernica?",min:0,max:10,risposta:1,unit:"mese circa",curiosita:"Guernica fu dipinta da Picasso in circa 5 settimane nel 1937, dopo il bombardamento della città basca di Guernica da parte delle forze naziste. Misura 3,49 × 7,76 metri ed è conservata al Reina Sofía di Madrid."},
 {q:"Quanti milioni di follower ha Chiara Ferragni al suo picco su Instagram?",min:0,max:50,risposta:29,unit:"milioni circa",curiosita:"Chiara Ferragni ha raggiunto circa 29 milioni di follower su Instagram al suo apice, diventando una delle influencer italiane più seguite al mondo. Ha iniziato con il blog 'The Blonde Salad' nel 2009."},
 {q:"Quanti anni vivono in media i camaleonti?",min:0,max:30,risposta:10,unit:"anni",curiosita:"I camaleonti vivono in media 5-10 anni, raramente di più. Il camaleonte di Labord (Madagascar) vive solo 4-5 mesi da adulto — la vita più corta di qualsiasi tetrapode. Cambiano colore per comunicare, non solo per mimetismo."},
 {q:"Quanti km/h raggiunge un razzo che va sulla Luna?",min:0,max:50000,risposta:39000,unit:"km/h",curiosita:"Un razzo che va sulla Luna raggiunge circa 39.000 km/h durante la fase di translunar injection. Per uscire dall'attrazione terrestre serve raggiungere la velocità di fuga: circa 40.000 km/h."},
 {q:"Quanti anni fa fu pubblicato il primo iPhone?",min:0,max:30,risposta:17,unit:"anni fa",curiosita:"Il primo iPhone fu presentato da Steve Jobs il 9 gennaio 2007 — 17 anni fa. Fu rivoluzionario: schermo multitouch, niente tastiera fisica, internet in tasca. Costava 499 o 599 dollari."},
 {q:"Quanti film ha diretto Alfred Hitchcock?",min:0,max:100,risposta:53,unit:"film",curiosita:"Alfred Hitchcock diresse 53 film tra il 1925 e il 1976. I più celebri: Psyco (1960), Gli Uccelli (1963), Vertigo (1958). Non vinse mai l'Oscar per la miglior regia, nonostante 5 nomination."},
 {q:"Quante volte è stato campione del mondo l'Italia di calcio?",min:0,max:10,risposta:4,unit:"volte",curiosita:"L'Italia ha vinto 4 Campionati del Mondo: 1934, 1938, 1982 e 2006. È la seconda nazione più titolata dopo il Brasile (5). Il gol di Grosso ai rigori contro la Francia nel 2006 resta iconico."}
];
